-- Cəmi: 6145 UPDATE (day-notifications İSTİSNA — ayrıca faylda)
-- ƏVVƏL sxem faylı (sütunlar) işlədilməlidir.
-- ============================================================

UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის თირკმელები განვითარებას განაგრძობს და უკვე იმდენად მომწიფებულია, რომ შარდის გამომუშავება შეუძლია. თუმცა ამ ეტაპზე ისინი ჯერ საკმარისად განვითარებული არ არის, რომ ორგანიზმიდან ნარჩენი ნივთიერებების გამოდევნის პროცესი სრულად შეასრულოს. მომდევნო კვირებში თირკმელების მიერ გამომუშავებული შარდი ჩაედინება ამნიონურ სითხეში, რომელშიც ბავშვი იმყოფება. შესაძლოა ეს უჩვეულოდ ჟღერდეს, მაგრამ ეს შარდი შარდოვანას არ შეიცავს და კვლევების თანახმად, სასმელ წყალზე უფრო სტერილურია. გარდა ამისა, მას ინფექციებისგან დამცავი ფუნქციაც აქვს.'), baby_message_ka = COALESCE(baby_message_ka, 'შეგიძლიათ მომიღუტუნოთ? (ვხუმრობ!) 😂 ნეტავ იცოდეთ, რამდენად მგრძნობიარე გახდა ჩემი კანი... თუ ვინმე, მაგალითად, ექიმი ულტრაბგერითი აპარატით თქვენს მუცელს შეეხება, მაშინვე ვრეაგირებ და უკან ვიხევ. ჩემი რეფლექსები იმდენად გამძაფრდა, რომ ყველაფერს ვგრძნობ. მე უკვე უბრალოდ უჯრედების გროვა კი არა, მგრძნობიარე ცოცხალი არსება ვარ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'მარწყვი'), body_changes_ka = COALESCE(body_changes_ka, 'ჰორმონების დაბალანსებისა და გულისრევის შემცირების გამო შესაძლოა მადა გაგეზარდოთ. ახლა უკვე როგორც საკუთარი თავისთვის, ისე ბავშვისთვის იკვებებით. ამიტომ მავნე საკვებს, სიგარეტსა და ალკოჰოლურ სასმელებს უნდა მოერიდოთ. ზედმეტი კალორიების შემცველი საკვების რაოდენობის კონტროლი ჭარბი წონის მომატების თავიდან აცილებაში დაგეხმარებათ. ღამით ჭამის სურვილი ბევრ მომავალ დედას უჩნდება. თუმცა ღამით ჭამამ შესაძლოა ხელი შეუშალოს სისხლში შაქრის დონის მარეგულირებელი ჰორმონის — ლეპტინის — გამოყოფას. ლეპტინის არასაკმარისმა გამოყოფამ შესაძლოა წონის სწრაფი მატება გამოიწვიოს. ამიტომ საღამოს 9 საათის შემდეგ, წყლის გარდა, არაფრის ჭამა და დალევა მნიშვნელოვანია როგორც კუჭის ჯანმრთელობისთვის, ისე წონის კონტროლისთვის.'), daily_tip_ka = COALESCE(daily_tip_ka, 'თუ გულისრევამ გაგიარათ, ახლა საუკეთესო დროა რაციონის გასამდიდრებლად; ყურადღება გაამახვილეთ ბევრი მწვანე ბოსტნეულისა და ხარისხიანი ცილის მიღებაზე. კანის დაჭიმულობის შესამცირებლად დამატენიანებელი ზეთების გამოყენება განაგრძეთ. თუ ენერგია დაგიბრუნდათ, დღის განმავლობაში 20-წუთიანი მშვიდი გასეირნება ჟანგბადით როგორც თქვენს, ისე ბავშვის მომარაგებას გააუმჯობესებს.') WHERE id = '726669c0-162f-4b1a-a70b-ca60baf4c509';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის სასა ფორმირებას იწყებს. სასა გუმბათისებრი სტრუქტურაა, რომელიც ბავშვის პირის ღრუს ზედა ნაწილს ქმნის და გარკვეული ბგერების წარმოქმნაში მონაწილეობს. სასის წინა ნაწილს, რომელიც მყარ ზედაპირს ქმნის, მაგარი სასა ეწოდება, ხოლო უკანა ნაწილს — რბილი სასა.;;;
სასა ორივე მხარეს განლაგებული ორი წყვილი კუნთით ბავშვის თავის ქალის ფუძეს უკავშირდება. ამასთანავე, სასა ერთმანეთისგან გამოყოფს ბავშვის პირისა და ცხვირის ღრუებს. მოძრავი რბილი სასა ყლაპვის დროს ზემოთ იწევა და ცხვირის ღრუს კეტავს, რითაც საკვების იქ მოხვედრას ხელს უშლის. რბილი სასის უკანა კიდის შუაში მდებარეობს ნაქი (უვულა), რომელიც მეტყველებისას ზოგიერთი ბგერის წარმოთქმაში მონაწილეობს. სასის უკანა ნაწილი ბავშვს ისეთი უკანაენისმიერი თანხმოვნების წარმოქმნაში ეხმარება, როგორებიცაა "q, k, ğ".'), baby_message_ka = COALESCE(baby_message_ka, 'მე უკვე შემიძლია სახე მოვმანჭო! 😝 ჩემი სახის კუნთები იმდენად განვითარდა, რომ უკვე სხვადასხვა გამომეტყველების მიღება შემიძლია. წარბებს ვკრავ, ტუჩებს ვბრიცავ, ვიღიმი ან გაკვირვებულ სახეს ვიღებ. ჩემთვის ეს თამაშია. უკვე ვვარჯიშობ, რომ დაბადების შემდეგ გაგაცინო. შენც მიღიმი?'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ლეღვი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის პერიოდში წონის დაკლება და დიეტის დაცვა ბავშვის განვითარების თვალსაზრისით რეკომენდებული არ არის. თუმცა წონის ჭარბმა მატებამაც შეიძლება ზოგჯერ ბავშვზე უარყოფითად იმოქმედოს. წონის სწრაფი მატების თავიდან ასაცილებლად და ორსულობის განმავლობაში წონის სათანადო მატების უზრუნველსაყოფად ყურადღება უნდა მიაქციოთ კვებას.;;;
გარდა ამისა, სასარგებლოა, მოერიდოთ შაქრის შემცველ მზა საკვებს, მყარ ცხიმებსა და დაბალი კვებითი ღირებულების მქონე, ცარიელი კალორიებით დატვირთულ პროდუქტებს. ნახშირწყლების ჭარბი მიღება და ღამით ჭამის ჩვევაც წონის მატების მიზეზებს მიეკუთვნება. ამასთანავე, ჰორმონების ზემოქმედებით ორსულობის დროს ნივთიერებათა ცვლა ნელდება და ფიზიკური აქტივობის შეზღუდვის შემთხვევაში წონის მატება შეიძლება გარდაუვალი გახდეს. დღის განმავლობაში მოულოდნელად გაჩენილი შიმშილის დასაძლევად ჯანსაღი წახემსება წონის მატების კონტროლში დაგეხმარებათ. თუ ჯანმრთელობის რაიმე პრობლემა არ გაქვთ, ორსულებისთვის სპეციალურად შემუშავებული ზოგიერთი ვარჯიშის შესრულებაც წონის სწრაფი მატების თავიდან აცილებაში დაგეხმარებათ.;;;
ამავდროულად, თავი უნდა შეიკავოთ ნებისმიერი სახის არაპასტერიზებული რძისა და რძის პროდუქტებისგან. გავრცელებული მცდარი მოსაზრების საპირისპიროდ, პასტერიზაცია საუკუნის ერთ-ერთ მნიშვნელოვან გამოგონებად მიიჩნევა; ის რძის კვებითი ღირებულების დაკარგვის გარეშე მასში არსებული მავნე მიკროორგანიზმებისა და, რაც მთავარია, სპოროვანი ბაქტერიების გაუვნებელყოფას უზრუნველყოფს. სახლში უმი რძის ადუღება მასში არსებულ როგორც სასარგებლო, ისე მავნე მიკროორგანიზმებს ანადგურებს, თუმცა განსაკუთრებით საშიში სპოროვანი ბაქტერიების სრულ გაუვნებელყოფას ვერ უზრუნველყოფს. ამიტომ უმი ან შეფუთული ხანგრძლივი შენახვის რძის ნაცვლად პასტერიზებული ყოველდღიური რძე უნდა მიიღოთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'თუ ღრძილების მგრძნობელობა კვლავ გაწუხებთ, მიირთვით C ვიტამინით მდიდარი ხილი. თუ მადა გაგეზარდათ, კვებაში ცილისა და კალციუმის ბალანსი დაიცავით. ჩვევად აქციეთ ყოველდღე სულ მცირე 2 ლიტრი წყლის დალევა. თუ წელის ტკივილი გაწუხებთ, ეცადეთ, კომფორტული ფეხსაცმელი ატაროთ და გამართული იჯდეთ. ყოველდღე დაუთმეთ დრო საკუთარ თავს და მოუსმინეთ მშვიდ მუსიკას — ეს დადებითი ენერგიით აგავსებთ როგორც თქვენ, ისე ბავშვს.') WHERE id = 'f769e4b1-414a-408e-8810-543b96add6b7';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'წოვის რეფლექსი ვითარდება. ნაყოფს თითები პირთან მიაქვს და წოვის მოძრაობებს ასრულებს. ეს დაბადების შემდგომი კვების ინსტინქტის საფუძველია. ამასთანავე, ნაყოფი ყლაპავს სანაყოფე სითხეს, რომელიც საჭმლის მომნელებელ სისტემაში გაივლის და თირკმლების საშუალებით იფილტრება.'), baby_message_ka = COALESCE(baby_message_ka, 'წოვის რეფლექსს ვსწავლობ! 🍼 ცერა თითი პირთან მიმაქვს და მის წოვას ვცდილობ. ეს ყველაზე მნიშვნელოვანი უნარია იმისთვის, რომ დაბადების შემდეგ შენი რძე ადვილად მოვწოვო. ზოგჯერ გამომდის, ზოგჯერ კი ხელი პირიდან მისხლტება. მაგრამ არ ვნებდები და ვარჯიშს ვაგრძელებ. შენც მოემზადე ჩემთვის, დედიკო!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ლეღვი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის პერიოდში თევზის მიღება, რომელიც ომეგა-3 და ომეგა-6 ცხიმოვანი მჟავებით უაღრესად მდიდარია, ბავშვის ტვინისა და თვალების განვითარებისთვის ძალიან მნიშვნელოვანია. ცილებითა და D ვიტამინით მდიდარი თევზი ბავშვის განვითარებაში მნიშვნელოვან წვლილს შეიტანს. ჯანსაღი ორსულობისთვის ექიმები თევზის ადვილად მონელების გამო მის მიღებას კვირაში ორჯერ გირჩევენ. თუმცა ეს არ ნიშნავს, რომ ნებისმიერი სახეობის თევზის ჭამა შეგიძლიათ. ზოგიერთი თევზი დიდი რაოდენობით ვერცხლისწყალს შეიცავს, რამაც შეიძლება ბავშვის განვითარებაზე უარყოფითად იმოქმედოს. ორაგული, თინუსი, სარდინი, კალმახი და სკუმბრია ის თევზებია, რომელთა მიღებაც ორსულობის პერიოდში უსაფრთხოდ შეგიძლიათ; მაღალი კვებითი ღირებულების გარდა, ისინი ფოლიუმის მჟავითაც საკმაოდ მდიდარია. ეს თევზები ომეგა-3 და ომეგა-6 ცხიმოვანი მჟავების მაღალი შემცველობითა და ვერცხლისწყლის დაბალი დონით გამოირჩევა. კვირაში დაახლოებით 300-400 გრამი მომზადებული თევზის მიღება საკმარისია. ორსულობის პერიოდში უნდა მოერიდოთ უმ თევზსა და საკვები დანამატების შემცველ კონსერვებს. შეწვისას თევზში არსებული ვიტამინები მთლიანად იკარგება, ამიტომ მის მოსამზადებლად უპირატესობა მიანიჭეთ ორთქლზე, გრილზე ან ღუმელში მომზადებას.'), daily_tip_ka = COALESCE(daily_tip_ka, 'თუ მადა გაგეზარდათ, სისხლში შაქრის დონის დასაბალანსებლად ხშირად და მცირე ულუფებით მიირთვით. კანზე სტრიების გაჩენის შესამცირებლად განაგრძეთ დამატენიანებელი ზეთების (ნუშის ან ქოქოსის ზეთის) გამოყენება. შეგიძლიათ ორსულებისთვის განკუთვნილი ტანსაცმლის შეძენა დაიწყოთ – ახლა ყველაზე მნიშვნელოვანი კომფორტია. დღის კარგ განწყობაზე გასატარებლად უყურეთ საყვარელ ფილმს.') WHERE id = '32fc4b43-9967-407f-bd27-ce27ec4287ad';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ახლა, როდესაც ორსულობის მე-11 კვირა დაასრულეთ, ულტრაბგერითი გამოკვლევისას ბავშვის უფრო მკაფიოდ დანახვა უკვე შეგიძლიათ. ამ ეტაპზე ბავშვის სასქესო ორგანოები ფორმირებას იწყებს. ნაწილი, რომელიც მანამდე მხოლოდ ქსოვილის პატარა ფრაგმენტი იყო, ახლა პენისად ან კლიტორად გარდაიქმნება. თუ ბავშვი საშვილოსნოში შესაბამის პოზიციაშია, მისი სქესი ულტრაბგერითი გამოკვლევისას შეიძლება გამოჩნდეს.;;;
ამავდროულად, ყურების განვითარება გრძელდება; ისინი თანდათან თავის გვერდებზე სათანადო ადგილს იკავებს. გარეთა და შუა ყურს შორის დაფის აპკი წარმოიქმნება. ეს აპკი ერთდროულად წარმოადგენს ბარიერს, რომელიც ბაქტერიების შიგნით შეღწევას აფერხებს, და ბავშვს გარე სამყაროს ხმებთან პირველ კონტაქტს უზრუნველყოფს. ბავშვს ხმები უკვე ესმის, თუმცა ჯერ მათი ერთმანეთისგან გარჩევა არ შეუძლია.;;;
პირველი ტრიმესტრის დასასრულის მოახლოებასთან ერთად ბავშვის პოზაც იცვლება. კისერი უგრძელდება, ნიკაპი მკერდს სცილდება და თავს უფრო სწორად იჭერს. ამგვარად, ის თანდათან ტოვებს ადრინდელ მოხრილ "C" ფორმას და სხეული უფრო სწორი უხდება.'), baby_message_ka = COALESCE(baby_message_ka, '12 კვირა შესრულდა! 🎉 დედიკო, პირველი ტრიმესტრი წარმატებით დავასრულეთ! ეს ორსულობის ყველაზე რთული და მნიშვნელოვანი ეტაპი იყო. ჩემი ყველა ორგანო წარმოიქმნა და ჩამოყალიბდა. ახლა უკვე ოფიციალურად "პატარა ადამიანი" ვარ. წინ უფრო მშვიდი და ენერგიული დღეები გველოდება. შენით ვამაყობ — შესანიშნავი გუნდი ვართ!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ლეღვი'), body_changes_ka = COALESCE(body_changes_ka, 'დღეიდან პლაცენტა სრულად იწყებს ფუნქციონირებას და ჰორმონების გამომუშავებას "ყვითელი სხეულისგან" გადაიბარებს. ამ გადასვლას, ჩვეულებრივ, გულისრევის შემცირება და ენერგიის მომატება მოჰყვება. შესაძლოა, თავი უფრო მხნედ იგრძნოთ. ორსულობის ყველაზე სარისკო პერიოდი უკვე უკან დარჩა!;;;
ორსულობის დროს ჰორმონული ცვლილებების გამო შეიძლება კანის გარკვეული პრობლემები წარმოიშვას. შესაძლოა განვითარდეს ეგზემა ან ფსორიაზი, ან უკვე არსებული მდგომარეობა გამწვავდეს. ეგზემისა და ფსორიაზის თავიდან ასაცილებლად კანის ტენიანობა შეძლებისდაგვარად უნდა გაზარდოთ, დალიოთ ბევრი წყალი და მიირთვათ ახალი ხილი და ბოსტნეული.;;;
ორსულობის ბოლო კვირებში მუცლის მნიშვნელოვნად გაზრდის შედეგად შეიძლება ზოგიერთი სახის გამონაყარი გაჩნდეს. ასეთი გამონაყარი განსაკუთრებით ხშირად პირველი ორსულობის დროს გვხვდება და ქავილის გამომწვევი ლაქები შეიძლება წარმოქმნას.'), daily_tip_ka = COALESCE(daily_tip_ka, 'პირველი ტრიმესტრის დასრულება საყვარელი რიტუალით აღნიშნეთ! ენერგიის დაბრუნების შემდეგ შეგიძლიათ აქტიურ ცხოვრებას დაუბრუნდეთ, თუმცა ერიდეთ მძიმე ნივთების აწევას. რადგან მადა გაგეხსნათ, ყურადღება გაამახვილეთ არა "ორის ნაცვლად", არამედ "ორისთვის ხარისხიანად" კვებაზე. თუ "ორმაგი ტესტი" ჯერ არ ჩაგიტარებიათ, მის ჩატარების ბოლო ვადა ექიმთან დააზუსტეთ. მოემზადეთ მეორე ტრიმესტრით (თაფლობის თვის პერიოდით) დასატკბობად!') WHERE id = '43e2ccf7-0f43-404f-b8d5-9a230d2fcf1f';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ორგანიზმის ერთ-ერთი ყველაზე მგრძნობიარე ნაწილი — ხმის იოგები — უკვე სრულად ჩამოყალიბებულია. მიუხედავად იმისა, რომ მათ პირველად მხოლოდ დაბადებისას (პირველი ტირილის დროს) გამოიყენებს, ყველაფერი უკვე მზადაა. ხმის იოგები ხორხში განლაგებულ ორ თხელ აპკს ჰგავს. ამ აპკების ვიბრაციისას მათ შორის არსებული ნაპრალი ვიწროვდება და ფართოვდება, რაც ხმის ტონს არეგულირებს. ვიწრო ნაპრალის შემთხვევაში ხმა მაღალია, ფართო ნაპრალისას კი — დაბალი. მშობიარობის დროს ფილტვებიდან ამოსული ჰაერი ამ იოგებს აამოძრავებს და თქვენი ბავშვის ხმას გაიგონებთ. საინტერესო ფაქტი: გოგონების ხმის იოგები უფრო მოკლე და თხელია, ბიჭების კი — უფრო გრძელი და სქელი. დაბადებისას თქვენი ბავშვის ხმის იოგების სიგრძე მხოლოდ 6 mm იქნება. გარდა ამისა, თქვენმა ბავშვმა უკვე დაიწყო თითის წოვა! ეს მისი ერთ-ერთი ყველაზე ადრეული და საყვარელი ჩვევაა, თუმცა ულტრაბგერით გამოკვლევაზე ამის დანახვა ჯერ ცოტათი ადრეა.'), baby_message_ka = COALESCE(baby_message_ka, 'მე საკვების გემოს ვგრძნობ! 🍲 რასაც თქვენ მიირთმევთ, იმის მიხედვით იცვლება სანაყოფე წყლების გემოც. ტკბილი, მჟავე, ნივრიანი... ყველაფერს ვყლაპავ და გემოს ვგრძნობ. უკვე ახლა ყალიბდება, მომავალში რომელი კერძები მეყვარება. ამიტომ, გთხოვთ, ბევრი ბოსტნეული მიირთვათ, რომ მეც შემიყვარდეს!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ლაიმი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობისას წარმოქმნილი ფიზიოლოგიური და ფსიქოლოგიური მიზეზების გამო, შესაძლოა, სქესობრივი კავშირისგან თავი შეიკავოთ იმის შიშით, რომ ბავშვს ზიანი მიადგება. თუმცა, თუ ორსულობა ნორმალურად მიმდინარეობს და ექიმი სხვაგვარად არ გირჩევთ, სქესობრივი კავშირის შეზღუდვის საჭიროება არ არსებობს. მეტიც, ორსულობის წინსვლასა და ჰორმონალური ფონის დარეგულირებასთან ერთად, შესაძლოა, სქესობრივი სურვილიც გაიზარდოს.;;;
ქალებს, რომლებსაც წარსულში განმეორებითი მუცლის მოშლა ან ნაადრევი მშობიარობა ჰქონიათ, ექიმის რეკომენდაციით პირველ ტრიმესტრში შესაძლოა სქესობრივი ცხოვრება შეეზღუდოთ. ასევე, ორსულობის ნებისმიერ ეტაპზე სქესობრივი კავშირი ექიმის მიერ მკაცრად იკრძალება, თუ არსებობს მუცლის მოშლის ან ნაადრევი მშობიარობის საფრთხე ან აღინიშნება ვაგინალური სისხლდენა. აკრძალვა ძალაში რჩება მანამდე, სანამ საფრთხის სრულად აღმოფხვრა არ დადასტურდება. სქესობრივი კავშირისგან თავის შეკავება საჭიროა მაღალი რისკის ორსულობის შემთხვევაშიც, როდესაც დიაგნოზირებულია "პლაცენტის წინამდებარეობა", ანუ პლაცენტა ბავშვზე ქვემოთ მდებარეობს და საშვილოსნოს ყელს ფარავს, რადგან ამ დროს სისხლდენის დაწყების რისკი არსებობს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'გულძმარვის თავიდან ასაცილებლად ჭამისთანავე ნუ დაწვებით და მოერიდეთ ცხარე და უხვად შეზავებულ საკვებს. მიირთვით მცირე ულუფებით, მაგრამ ხშირად. რკინის მიღების გასაზრდელად რაციონში შეიტანეთ წითელი ხორცი, ოსპი და მუქი მწვანე ბოსტნეული. რადგან ენერგიულად გრძნობთ თავს, შეგიძლიათ დრო დაუთმოთ ისეთ საქმიანობას, რომელიც გაბედნიერებთ, მაგალითად, თქვენი ბავშვისთვის პირველი საყიდლების დაგეგმვას.') WHERE id = '18d4758f-242c-49df-ab25-cc0a8449dd65';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ორგანიზმის ერთ-ერთი ყველაზე მგრძნობიარე ნაწილი — ხმის იოგები — უკვე სრულად ჩამოყალიბებულია. მიუხედავად იმისა, რომ მათ პირველად მხოლოდ დაბადებისას (პირველი ტირილის დროს) გამოიყენებს, ყველაფერი უკვე მზადაა. ხმის იოგები ხორხში განლაგებულ ორ თხელ აპკს ჰგავს. ამ აპკების ვიბრაციისას მათ შორის არსებული ნაპრალი ვიწროვდება და ფართოვდება, რაც ხმის ტონს არეგულირებს. ვიწრო ნაპრალის შემთხვევაში ხმა მაღალია, ფართო ნაპრალისას კი — დაბალი. მშობიარობის დროს ფილტვებიდან ამოსული ჰაერი ამ იოგებს აამოძრავებს და თქვენი ბავშვის ხმას გაიგონებთ. საინტერესო ფაქტი: გოგონების ხმის იოგები უფრო მოკლე და თხელია, ბიჭების კი — უფრო გრძელი და სქელი. დაბადებისას თქვენი ბავშვის ხმის იოგების სიგრძე მხოლოდ 6 mm იქნება. გარდა ამისა, თქვენმა ბავშვმა უკვე დაიწყო თითის წოვა! ეს მისი ერთ-ერთი ყველაზე ადრეული და საყვარელი ჩვევაა, თუმცა ულტრაბგერით გამოკვლევაზე ამის დანახვა ჯერ ცოტათი ადრეა.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი ძვლები მაგრდება! 🦴 ჩემი ჩონჩხი, რომელიც ადრე მხოლოდ ხრტილისგან შედგებოდა, ახლა ნამდვილ ძვლად გარდაიქმნება. ხელები და ფეხები მიგრძელდება. უკვე უფრო პროპორციულად გამოვიყურები. ჩემი თავი ჯერ კიდევ დიდია, მაგრამ სხეული ცდილობს, მას დაეწიოს. ძლიერი ბავშვი ვიქნები, დედიკო!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ქლიავი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის დროს პროგესტერონი, ესტროგენის დახმარებით, ასქელებს საშვილოსნოს კედელს და ბავშვის მიმაგრებას უწყობს ხელს. ის ამცირებს საშვილოსნოს კუნთების შესაძლო მგრძნობელობას ჰორმონ ოქსიტოცინის მიმართ და მათი შეკუმშვის თავიდან აცილებით ამცირებს მუცლის მოშლის რისკს, ხელს უწყობს ორსულობის შენარჩუნებას და კოლაგენის გამომუშავების ხელშეწყობით კანის ელასტიკურობას ზრდის. სისხლში პროგესტერონის დონის მატების შედეგად საყლაპავის ქვედა სფინქტერი დუნდება, რის გამოც კუჭის მჟავის ნაწილი საყლაპავში გადადის. ამის გამო შესაძლოა გულძმარვა და პირში მომჟავო გემო იგრძნოთ. გულძმარვის შესამცირებლად სითხე უნდა მიიღოთ არა ჭამის დროს, არამედ კვებებს შორის; მიირთვათ უფრო მცირე და ადვილად მოსანელებელი ულუფები და ყოველი ლუკმა კარგად დაღეჭოთ. ასევე უნდა მოერიდოთ ცხარე საკვებს, მჟავე ხილის წვენებს, ყავასა და შოკოლადს; ძილის დროს თავი და გულმკერდი სხეულზე მაღლა გქონდეთ, ხოლო ვახშამი ადრიანად მიირთვათ, რათა ორგანიზმმა საკვების მონელება მოასწროს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'სისხლის მოცულობის მატებასთან ერთად ორგანიზმის მოთხოვნილება სითხეზეც იზრდება; დარწმუნდით, რომ ყოველდღე სულ მცირე 2.5 ლიტრ წყალს სვამთ. თუ წელის არეში დაჭიმულობას გრძნობთ, მთლიანად უარი თქვით მაღალქუსლიან ფეხსაცმელზე და შეარჩიეთ ორთოპედიული, კომფორტული ფეხსაცმელი. გაზარდეთ კალციუმის მიღება, რათა ბავშვის ძვლები გამაგრდეს და თქვენი კბილები და ძვლებიც დაცული იყოს.') WHERE id = 'e16dc0a2-01a9-4a7e-990c-b0f97835b682';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'გილოცავთ! დღეს წარმატებით დაასრულეთ ორსულობის ერთ-ერთი ყველაზე მნიშვნელოვანი ეტაპი — პირველი ტრიმესტრი, ანუ პირველი სამი თვე. 😊 გასული 12 კვირის განმავლობაში თქვენი ბავშვის ყველა ორგანო სრულად ჩამოყალიბდა და თავისი ადგილი დაიკავა. თავისა და სხეულის პროპორციებითა და სახის ნაკვთებით ის უკვე მთლიანად ადამიანს ჰგავს. ეს ყველაზე მგრძნობიარე ეტაპიც იყო, რადგან პერიოდი, როდესაც ბავშვი ყველაზე მეტად იყო დაუცველი გარეგანი ზემოქმედების მიმართ და მუცლის მოშლის რისკიც მაღალი იყო, უკვე დასრულდა.;;;
ახლა იწყება პერიოდი, როდესაც ფიზიკურადაც უფრო კომფორტულად იგრძნობთ თავს. საშვილოსნო, რომელშიც თქვენი ბავშვი იზრდება, მენჯის ღრუში ვეღარ ეტევა და ზემოთ იწევს. ამის შედეგად შარდის ბუშტზე ზეწოლა მცირდება და ტუალეტში ხშირი სიარულის საჭიროებაც რამდენადმე იკლებს.'), baby_message_ka = COALESCE(baby_message_ka, '13-ე კვირა სრულდება! 👋 მოგესალმებით, სრული სიმშვიდე! უკვე ისეთი მოძრავი ვარ... ფეხებს ვიქნევ, ვტრიალდები, ხელებს ვშლი და ვკუმშავ. შესაძლოა, მუცელში პატარა "პეპლების ფარფატის" მსგავსი რამ იგრძნოთ (მაგრამ თუ ჯერ ვერაფერს გრძნობთ, ნუ ინერვიულებთ). აქ ვარ და ვიზრდები. ჩვენ ერთად შესანიშნავი გზა გამოვიარეთ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ქლიავი'), body_changes_ka = COALESCE(body_changes_ka, '13-ე კვირის დასასრული. თქვენ უკვე სრულად შეეგუეთ მეორე ტრიმესტრს. ძილი მოგიწესრიგდათ და მადაც დაგიბრუნდათ. თქვენი მუცელი უკვე პატარა "ორსულის მუცელს" ჰგავს. ტანსაცმლის შერჩევა შეიძლება უფრო სასიამოვნო გახდეს. შესაძლოა, თავი უფრო ქალურად და ლამაზად იგრძნოთ. დატკბით ამ პერიოდით — ეს ორსულობის "თაფლობის თვეა"! შესაძლოა, ძუძუებიდან "კოლოსტრუმის" (ხსენის) გამოყოფა გაგრძელდეს ან ახლა დაიწყოს. ეს სქელი, მოყვითალო სითხე ბავშვის პირველ ვაქცინად მიიჩნევა. თუ ის ტანსაცმელს გისვრით, შეგიძლიათ მკერდის სპეციალური საფენები გამოიყენოთ. სარძევე ჯირკვლები მშობიარობისთვის აქტიურად ემზადება.'), daily_tip_ka = COALESCE(daily_tip_ka, 'საწოლში წოლის ნაცვლად აქტიური ცხოვრების წესი აირჩიეთ. ორსულთა იოგა ან პილატესი თქვენს კუნთებს გააძლიერებს და მშობიარობისთვის მოგამზადებთ. ამ ჯგუფებში სხვა ორსულებსაც გაიცნობთ და გამოცდილებას გაუზიარებთ.') WHERE id = '451a1e44-829c-4f45-9442-ac30329fca22';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ორგანიზმში შარდგამომყოფი სისტემა სწრაფად ვითარდება. ეს სისტემა ორი თირკმლისგან, შარდსაწვეთებისა და შარდის ბუშტისგან შედგება. მისი მთავარი ფუნქციაა სისხლის მავნე ნივთიერებებისგან გაწმენდა და ორგანიზმში წყლისა და მარილების ბალანსის შენარჩუნება. ამ კვირიდან თქვენი ბავშვი უკვე იწყებს შარდის გამოყოფას და ეს სითხე მის გარშემო არსებულ ამნიონურ სითხეს ერევა. თირკმელებში ყალიბდება მილიონობით პატარა ფილტრი, რომელსაც ნეფრონი ეწოდება და რომელიც სისხლს ფილტრავს. ამჟამად თირკმელებში როგორც მოკლე, ისე გრძელი აგებულების ნეფრონები ფუნქციონირებს. როდესაც თქვენი ბავშვი სრულად განვითარდება, თითოეულ თირკმელში 1 მილიონზე მეტი ასეთი პატარა ფილტრი ექნება. ამ მილისებრი უჯრედების წყალობით თქვენი ბავშვის სისხლი მუდმივად იწმინდება და ნივთიერებათა ცვლა რეგულირდება.'), baby_message_ka = COALESCE(baby_message_ka, 'კეთილი იყოს შენი მობრძანება მეორე ტრიმესტრში! ☀️ მას „ოქროს პერიოდს“ უწოდებენ. იმიტომ, რომ შენ თავს უკეთ იგრძნობ, მე კი სწრაფად გავიზრდები. ახლა ლაიმის ზომის ვარ. ჩემი მოძრაობები უფრო კოორდინირებულია. უკვე შემთხვევით კი არ ვმოძრაობ, არამედ ისე, როგორც მინდა. მინდა, შეგეხო, დედიკო.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ლაიმი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის დროს წარმოქმნილ ნებისმიერ ჩივილს ყურადღება უნდა მიაქციოთ. მაგალითად, ალერგიული რეაქციის შედეგად თქვენს კანზე შესაძლოა გამონაყარი, წითელი ლაქები და ქავილი გაჩნდეს. ორსულობის პირველ თვეებში ასეთი გამონაყარი და ქავილი შესაძლოა ჰორმონ პროგესტერონის ზემოქმედებით იყოს გამოწვეული. თუმცა, თუ მოგვიანებითაც გაგრძელდება, აუცილებლად უნდა ჩატარდეს სისხლის ანალიზები. ამ ანალიზებით მოწმდება ღვიძლის ფერმენტები, ჰეპატიტის მაჩვენებლები, ნაღვლის მჟავები და ფარისებრი ჯირკვლის ჰორმონები. თუ ამ ანალიზების შედეგები ნორმისგან განსხვავდება, როგორც თქვენი, ისე თქვენი ბავშვის ჯანმრთელობის დასაცავად მკურნალობა აუცილებელია.;;;
გარდა ამისა, უმადობა, სისუსტე, დაღლილობა, თვალების სიწითლე ან გაყვითლება, შარდის სუნისა და ფერის ცვლილება შესაძლოა ღვიძლის მაჩვენებლების დარღვევაზე მიუთითებდეს. ამ მდგომარეობას ორსულთა ქოლესტაზი ეწოდება. ორსულთა ქოლესტაზის მქონე ქალებს სჭირდებათ გულდასმით მეთვალყურეობა და ხშირი შემოწმება NST-ის, დოპლეროგრაფიისა და ულტრაბგერითი კვლევის საშუალებით.;;;
ამ ჩივილების განვითარების ალბათობა განსაკუთრებით მაღალია, თუ ორსულობებს შორის დიდი შუალედი არ ყოფილა.'), daily_tip_ka = COALESCE(daily_tip_ka, 'სქესობრივ ცხოვრებასთან დაკავშირებით კონსულტაცია გაიარეთ თქვენს ექიმთან. თუ არ არსებობს რაიმე რისკი (სისხლდენა, მუცლის მოშლის საფრთხე), ორსულობის დროს სქესობრივი კავშირი სრულიად უსაფრთხოა და შესაძლოა სასარგებლოც კი იყოს (ჰორმონ ოქსიტოცინის წყალობით).') WHERE id = '931efc18-1bb9-41fb-bf51-8eb31fb5efd5';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ნაწლავები უკვე მნიშვნელოვნად განვითარდა. ნაწლავები, რომლებიც პირველ კვირებში მარტივ ქსოვილს წარმოადგენდა, ახლა იკეცება, წინა და შუა ნაწილებად იყოფა და გულსა და ფილტვებთან ერთად სწრაფად იზრდება სიგრძეში. ამ პერიოდში თქვენი ბავშვის გარშემო არსებული ამნიონური სითხის მოცულობა დაახლოებით 50 ml-ს აღწევს. ამავდროულად, ტვინში ფუნქციონირებას იწყებს ჰიპოფიზი, რომელსაც „მთავარ ჯირკვალსაც“ უწოდებენ. ეს პატარა ჯირკვალი გამოიმუშავებს მრავალ ჰორმონს, რომლებიც აუცილებელია სიმაღლეში ზრდისთვის, ნივთიერებათა ცვლისა და მომავალში რეპროდუქციული სისტემის ფუნქციონირებისთვის. ჰიპოფიზს ტვინის სხვა ნაწილი — ჰიპოთალამუსი მართავს. ისინი ერთად ორგანიზმის შინაგან წონასწორობას ინარჩუნებენ. ანუ, თუ ორგანიზმში რომელიმე პროცესი დაირღვევა, ეს ჯირკვლები ჰორმონების საშუალებით მდგომარეობას დაუყოვნებლივ აწესრიგებენ.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი თითის ანაბეჭდები მზადაა! 🧬 ჩემი სრულიად უნიკალური, მსოფლიოში განუმეორებელი თითის ანაბეჭდები სრულად ჩამოყალიბდა. ეს ჩემი პირადობის მოწმობაა. ტყუპისცალიც რომ მყავდეს, მისი თითის ანაბეჭდები ჩემისგან განსხვავებული იქნებოდა. მე ერთადერთი და განუმეორებელი ვარ!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ლაიმი'), body_changes_ka = COALESCE(body_changes_ka, 'თუ ორსულობის დროს გაქვთ ისეთი ნიშნები, როგორიცაა ჩვეულებრივზე მეტი წყლის დალევის სურვილი, ძალიან ხშირი შარდვა, ფეხების დაბუჟება და წონის უეცარი ცვლილებები, შესაძლოა შაქრიანი დიაბეტი განვითარებულიყო. თუ მანამდე შაქრიანი დიაბეტი არ გქონიათ, ორსულობის დროს წარმოქმნილ ამ მდგომარეობას „გესტაციური დიაბეტი“ ეწოდება. გესტაციური დიაბეტის მქონე ქალებს შესაძლოა აღენიშნებოდეთ მაღალი არტერიული წნევა, თავბრუსხვევა და თავის ტკივილი. გავრცელებული მოსაზრების საპირისპიროდ, ეს მდგომარეობა მხოლოდ ჭარბი წონის მქონე ორსულებს არ უვითარდებათ. უფრო მაღალი რისკის ქვეშ არიან ისინი, ვის ოჯახშიც შაქრიანი დიაბეტის შემთხვევებია. გესტაციური დიაბეტი ვითარდება იმის გამო, რომ ორსულობის განმავლობაში ბავშვის მხარდასაჭერად პლაცენტა იზრდება და მის მიერ გამოყოფილი ჰორმონები დედის ორგანიზმში ინსულინის მოქმედებას ამცირებს. ამ მდგომარეობას ინსულინრეზისტენტობა ეწოდება. თუ ინსულინი სათანადოდ ვერ მოქმედებს, სისხლში არსებული შაქარი ენერგიად ვერ გარდაიქმნება და სისხლში შაქრის დონე იმატებს. შედეგად ვითარდება გესტაციური დიაბეტი.;;;
მკურნალობის დროს ინიშნება დიეტა და, საჭიროების შემთხვევაში, ინსულინი. მთელი ორსულობის განმავლობაში მთავარია კვების სწორი რეჟიმის დაცვა. მკურნალობის გარეშე ამ მდგომარეობამ შესაძლოა გამოიწვიოს მუცლის მოშლა, ნაადრევი მშობიარობა, ბავშვის წონის ზედმეტად სწრაფი მატება და განვითარების გარკვეული დარღვევები. გესტაციური დიაბეტის არსებობა დგინდება ორსულობის 24-28-ე კვირებში ჩატარებული გლუკოზის დატვირთვის ტესტით.'), daily_tip_ka = COALESCE(daily_tip_ka, 'მეორე ტრიმესტრში მომატებული მადა სასარგებლო პროდუქტებით — თხილეულით, ახალი ხილითა და ხაჭოთი დაიკმაყოფილეთ. თუ წელის მსუბუქი ტკივილი დაგეწყოთ, ჯდომისას ზურგს უკან პატარა საყრდენი ბალიში მოათავსეთ. კანზე ორსულობის დროს პიგმენტური ლაქების წარმოქმნის თავიდან ასაცილებლად მოერიდეთ მზის პირდაპირ სხივებს და გამოიყენეთ მაღალი დამცავი ფაქტორის მქონე მზისგან დამცავი კრემი.') WHERE id = 'ec212007-cf13-4d3e-9523-fa6762234108';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის კუჭქვეშა ჯირკვალმა უკვე დაიწყო ინსულინის გამომუშავება. ამ ჯირკვლის 99% საჭმლის მონელების ხელშემწყობ ფერმენტებს წარმოქმნის, დარჩენილი 1%-ისგან შემდგარი მცირე უჯრედული ჯგუფები კი ინსულინს გამოყოფს. ინსულინი უზრუნველყოფს, რომ უჯრედებმა გამოიყენონ შაქარი (გლუკოზა), რომელიც ორგანიზმის ენერგიის მთავარი წყაროა. მისი ძირითადი ფუნქცია სისხლში შაქრის დონის ზედმეტად მატების თავიდან აცილებაა. ინსულინს შაქარი სისხლიდან გადააქვს კუნთისა და ცხიმის უჯრედებში, სადაც ის ენერგიის წყაროდ გამოიყენება. თუ სისხლში შაქრის დონე შემცირდება, ინსულინის გამომუშავება წყდება და შაქრის ნორმალური დონის შესანარჩუნებლად ორგანიზმი სხვა ჰორმონებს ააქტიურებს. ამგვარად, თქვენი ბავშვის ორგანიზმში შაქრის, ცხიმისა და ცილების ბალანსი შესანიშნავად რეგულირდება.'), baby_message_ka = COALESCE(baby_message_ka, 'ვიწყებ ხმების გაგონებას? 👂 ჩემი ყურების განვითარება გრძელდება და უკვე შემიძლია ვიბრაციების შეგრძნება. შენი გულისცემა, სისხლის მოძრაობა და კუჭის ხმები ჩემი იავნანაა. მალე შენი ხმის გარჩევასაც შევძლებ. მელაპარაკე, დედიკო, მე გისმენ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ლაიმი'), body_changes_ka = COALESCE(body_changes_ka, 'თქვენს კანზე სტრიების წარმოქმნის რისკი იზრდება. მუცლის, ბარძაყებისა და მკერდის ზრდასთან ერთად კანი იჭიმება. ამაში გენეტიკა დიდ როლს ასრულებს, თუმცა კანის დატენიანება მის ელასტიკურობას ზრდის და ქავილს ამცირებს. მშრალ კანზე სტრიები უფრო ადვილად ჩნდება. ამიტომ მნიშვნელოვანია კანის ყოველდღიურად დატენიანება და კვირაში 1-2-ჯერ მასაჟი.;;;
ორსულობის დროს არ დაგავიწყდეთ თქვენს კვების რაციონში თხილეულის დამატება. თხილეული ზეთოვანი თესლეულია და მაღალი კვებითი ღირებულება აქვს. მისი სასარგებლო თვისებების სრულად მისაღებად ის მოხალულის ნაცვლად უმი უნდა მიირთვათ. მათგან განსაკუთრებით მნიშვნელოვანია ნიგოზი, ნუში, ფისტა, კეშიუ, თხილი, ლეღვის ჩირი, გოგრის თესლი, გარგარის ჩირი და მიწის თხილი. ნიგოზი ხელს უწყობს ბავშვის ტვინის განვითარებას; თხილი მასში შემავალი კალციუმით — თქვენი ბავშვის ძვლების განვითარებას; ნუში ავსებს თუთიის ყოველდღიურ საჭიროებას; მიწის თხილი კი B და E ვიტამინების გარდა, კალიუმის, ფოსფორის, ნატრიუმისა და მაგნიუმის საჭიროებასაც აკმაყოფილებს. ასევე, ბუნებრივად გამომშრალი ლეღვი და გარგარი დაბალანსებულად უნდა მიირთვათ, რადგან ისინი შეიცავს მრავალ ვიტამინსა და მინერალს, რომლებიც ორსულობის დროს თქვენ და თქვენს ბავშვს გჭირდებათ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'მრგვალი იოგების ტკივილის შესამცირებლად ეცადეთ, უეცარი მოძრაობები არ გააკეთოთ; საწოლიდან ადგომისას ჯერ გვერდზე გადაბრუნდით. ღრძილების ჯანმრთელობისთვის გააგრძელეთ კალციუმით მდიდარი პროდუქტების მიღება და რბილი კბილის ჯაგრისის გამოყენება. თუ მადა მოგემატათ, ყურადღება მიაქციეთ საკვებში მაგნიუმის შემცველობას, რათა ფეხის კუნთების კრუნჩხვები თავიდან აიცილოთ.') WHERE id = '51726a4c-4dfd-4d8d-8fdf-a1b799174400';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ღვიძლმა უკვე დაიწყო ნაღვლის გამომუშავება. ეს სითხე უაღრესად მნიშვნელოვანია საჭმლის მომნელებელი სისტემისთვის, რადგან ორგანიზმს საკვებიდან მიღებული ცხიმებისა და მნიშვნელოვანი ვიტამინების (A, D, E, K) ათვისებაში ეხმარება. ნაღვლის წყალობით სისხლში გადადის ბავშვის ძვლების ჯანმრთელობისთვის (D ვიტამინი), მხედველობისთვის (A ვიტამინი), უჯრედების დაცვისა (E ვიტამინი) და სისხლის შედედებისთვის (K ვიტამინი) საჭირო ნივთიერებები. ამავდროულად, ეს სითხე ორგანიზმიდან ზოგიერთი მავნე ნივთიერების გამოდევნას უწყობს ხელს. ღვიძლში ყოველდღიურად წარმოქმნილი ნაღველი ძირითადი სადინრის საშუალებით თორმეტგოჯა ნაწლავში გადადის. ამ სითხის ნაწილი კი ღვიძლის ქვეშ მდებარე, მსხლის ფორმის ნაღვლის ბუშტში გროვდება. საჭიროებისას ნაღვლის ბუშტი ამ სითხეს წვრილ ნაწლავში გამოყოფს და მონელების პროცესს ხელს უწყობს.'), baby_message_ka = COALESCE(baby_message_ka, '13 კვირა! გამარჯობა, მე-2 ტრიმესტრო! 🎉 დედიკო, გილოცავ! ორსულობის ერთი მესამედი (1/3) უკვე გავიარეთ. ყველაზე რთული დღეები უკან დარჩა. ახლა იწყება პერიოდი, როცა ორივე უფრო თავისუფლად ამოვისუნთქებთ. უკვე ქლიავის ზომის ვარ. ჩემი ხმის იოგებიც განვითარდა. ჯერ ვერ გელაპარაკები, მაგრამ ჩემს ხმას ვამზადებ. ამ ახალ ეტაპზე კიდევ უფრო ლამაზი დღეები გველოდება.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ქლიავი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის დროს ერთ-ერთი ყველაზე ხშირი მოვლენა ვაგინალური გამონადენის მომატებაა. ორგანიზმში ესტროგენის დონის ზრდის გამო ვაგინალური გამონადენის მატება უმეტეს შემთხვევაში ნორმალურია. გამონადენი შეიძლება იყოს თეთრი, ყვითელი ან ოდნავ მუქი ფერის. ორსულობამდე პერიოდთან შედარებით, სისხლში ჰორმონების რაოდენობის მატების გამო გამონადენის გარეგნობისა და კონსისტენციის ცვლილება ბუნებრივია. ყურადღება უნდა მიაქციოთ შემდეგს: თუ ვაგინალური გამონადენი მუქი ყვითელი ან მომწვანო გახდება, ძალიან სქელი კონსისტენცია ექნება და, რაც მთავარია, გაფუჭებული თევზის მსგავსი უსიამოვნო სუნი ექნება, ეს შეიძლება ვაგინალური ინფექციის ნიშანი იყოს და მკურნალობას საჭიროებდეს. ვაგინალური გამონადენისა და ინფექციების თავიდან ასაცილებლად შხაპის მიღებისას წყლის ჭავლი საშოს შიგნით არ უნდა მიმართოთ, ინტიმური ზონის შიდა ან გარე ნაწილი სურნელოვანი ხელსახოცებითა და საპნებით არ უნდა გაიწმინდოთ და დეზოდორანტებსა და პარფიუმერულ საშუალებებს უნდა მოერიდოთ. ასეთი პრაქტიკა საზიანოა, რადგან საშოს ბუნებრივ მიკროფლორას არღვევს. ამ პერიოდში ბამბის შემცველი საცვლები უნდა გამოიყენოთ და საჭიროების შემთხვევაში დღეში 2-3-ჯერ გამოიცვალოთ. რადგან ჰაერის ცირკულაციას ხელს უშლის, ყოველდღიური საფენების გამოყენებას უნდა მოერიდოთ, ხოლო საცვლების ჰიგიენისთვის ისინი მაღალ ტემპერატურაზე უნდა გააუთოოთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ეს პერიოდი მოგზაურობისთვის ("Babymoon") ყველაზე უსაფრთხო და კომფორტული დროა. ენერგიით სავსე ხართ, მუცელი კი ჯერ ძალიან დიდი არ არის. ექიმთან კონსულტაციის შემდეგ შეგიძლიათ მცირე დასვენება დაგეგმოთ.') WHERE id = 'aae70b4b-3e99-462b-94d0-88716afa0dd4';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'პირველი ტრიმესტრის ბოლოსთვის თქვენი ბავშვის ყველაზე ახლო მეგობარი საშვილოსნოში — პლაცენტა — უკვე სრულად ჩამოყალიბებულია. ეს დროებითი ორგანო, რომელიც სულ რამდენიმე თვე არსებობს, ბავშვის გადარჩენასა და ზრდაში სასიცოცხლოდ მნიშვნელოვან როლს ასრულებს. თუ ამ ეტაპამდე ორსულობის შემანარჩუნებელ ჰორმონს — პროგესტერონს — თქვენს ორგანიზმში არსებული "ყვითელი სხეული" გამოიმუშავებდა, ახლა ამ საპასუხისმგებლო საქმეს პლაცენტა იღებს თავის თავზე. პლაცენტა დედის სისხლიდან ბავშვს ჟანგბადს, წყალსა და გლუკოზას გადასცემს, ბავშვის ორგანიზმში წარმოქმნილ ნარჩენ ნივთიერებებს გამოდევნის, დედის სისხლში არსებული ზოგიერთი ინფექციისგან დამცავ ბარიერს ქმნის და მხოლოდ ბავშვისთვის საჭირო ნივთიერებებს ატარებს. მოკლედ, პლაცენტა ბავშვისთვის ერთდროულად ფილტვების, თირკმელებისა და დამცავი სისტემის ფუნქციას ასრულებს.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი სხეული ბუსუსებით იფარება! 🐻 დედიკო, ჩემს კანზე ძალიან თხელი და რბილი ბუსუსები, სახელად "ლანუგო", იწყებს ზრდას. ახლა პატარა ატამს ვგავარ. ეს ბუსუსები სითხეში სიცივისგან მიცავს და სხეულის ტემპერატურის შენარჩუნებაში მეხმარება. დაბადებისას მათი უმეტესობა მომცილდება, მაგრამ ჯერ ეს "ქურქი" მჭირდება. შენ მე მათბობ, მე კი საკუთარ თავს.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'კივი'), body_changes_ka = COALESCE(body_changes_ka, 'ახლა, როდესაც მეორე ტრიმესტრში გადადიხართ, დროდადრო შეიძლება მუცლის ქვედა ნაწილში ან საზარდულის მიდამოში უეცარი, სპაზმის მსგავსი ტკივილი იგრძნოთ. ეს ტკივილი ბავშვის მატარებელი და მზარდი საშვილოსნოს გარშემო არსებული იოგების დაჭიმვითაა გამოწვეული. ერთ-ერთი მათგანია "round ligament" (მრგვალი იოგი). ასეთი ტკივილი განსაკუთრებით ხშირად ჩნდება წამოდგომისას, საწოლში ერთი გვერდიდან მეორეზე გადაბრუნებისას, უეცარი მოძრაობისას ან ხველის დროს. ეს მოძრაობები საშვილოსნოს გარშემო არსებულ იოგებს ჭიმავს და ტკივილს იწვევს. დასვენება, სხეულის პოზიციის შეცვლა, უეცარი მოძრაობებისგან თავის შეკავება, თბილი შხაპის მიღება და მტკივნეულ მიდამოზე თბილი კომპრესის დადება დისკომფორტის შემსუბუქებაში დაგეხმარებათ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'რადგან მადა მოგემატათ, რაციონი მრავალფეროვანი და ფერადი შეინარჩუნეთ; მიირთვით სხვადასხვა ბოსტნეული და ხილი, რათა თქვენი ბავშვი განსხვავებულ გემოებს გაეცნოს. გაზარდეთ რკინის შემცველი პროდუქტების (უცხიმო ხორცი, ოსპი, ისპანახი) მიღება, რათა ანემიისგან თავი დაიცვათ. რადგან ენერგიით სავსე ხართ, ყოველდღიური 15-20-წუთიანი მსუბუქი სეირნობა ძალიან სასარგებლო იქნება როგორც თქვენი განწყობისთვის, ისე საჭმლის მონელებისთვის.') WHERE id = '00f39406-c90d-4b7e-818d-3a2edbdeef33';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'მიუხედავად იმისა, რომ თქვენი ბავშვის ფილტვები სტრუქტურულად უკვე ჩამოყალიბებულია, ისინი განვითარებას ყველაზე გვიან ასრულებენ. ფილტვების სრულად მომწიფება ორსულობის 38-ე კვირამდე გრძელდება. რადგან ბავშვი ამჟამად ამნიონურ სითხეშია, ის ფილტვებით არ სუნთქავს. საჭირო ჟანგბადს პირდაპირ თქვენი სისხლიდან იღებს, ნახშირორჟანგს კი ისევ თქვენს სისხლს გადასცემს. ანუ თითქოს თქვენი ფილტვებით სუნთქავს.;;;
ამის მიუხედავად, ბავშვი უკვე ახლა ვარჯიშობს სუნთქვაში. ჰაერის ნაცვლად სითხეს ცხვირითა და პირით შეისუნთქავს და უკან გამოდევნის, რითაც სასუნთქ კუნთებს აძლიერებს. ამ პატარა მოძრაობების დანახვა ულტრაბგერითი გამოკვლევისას უკვე შესაძლებელია. ამ ვარჯიშების წყალობით დაბადებისთანავე პირველი ჩასუნთქვის გაკეთებას უფრო მარტივად შეძლებს.'), baby_message_ka = COALESCE(baby_message_ka, 'თითის ანაბეჭდების შემდეგ ახლა უკვე ფრჩხილებიც მაქვს! 💅 დედიკო, ჩემი თითების წვერებზე პატარა, თხელი ფრჩხილები იწყებს ჩამოყალიბებას. ჯერ ძალიან რბილია, მაგრამ დაბადებამდე გაიზრდება. ზოგჯერ შეიძლება საკუთარი სახე დავიკაწრო, ამიტომ დაბადებისას ხელთათმანების ჩაცმა დაგჭირდება. ყველაფერი შენ გგავს, ნეტავ ჩემი ფრჩხილებიც?'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'კივი'), body_changes_ka = COALESCE(body_changes_ka, 'ფოლატი წყალში ხსნადი B ჯგუფის ვიტამინია, რომელიც ბუნებრივად გვხვდება საკვებში, ხოლო მის სინთეზურ ფორმას ფოლიუმის მჟავა ეწოდება. ფოლიუმის მჟავა ადამიანების უმეტესობისთვის უსაფრთხოა პერორალურად მიღების ან ორგანიზმში ინექციის გზით შეყვანისას. განსაკუთრებით მნიშვნელოვანია მისი გამოყენება ორსულობის პერიოდში, რადგან ის ბავშვის ნერვული სისტემის განვითარებასა და ნერვული მილის დახურვას უწყობს ხელს. ორსულობის პირველ კვირებში ის მნიშვნელოვან როლს ასრულებს სისხლის წარმოქმნაში, ახალი უჯრედების ჩამოყალიბებასა და სიცოცხლისუნარიანობის შენარჩუნებაში, ასევე დნმ-ისა და რნმ-ის წარმოქმნაში.;;;
მისი მიღების დაწყება რეკომენდებულია ორსულობამდე სულ მცირე სამი თვით ადრე და გაგრძელება — ორსულობის შუა პერიოდამდე. თუ პრეპარატის მიღება შეუძლებელია, უხვად უნდა მიირთვათ ფოლატით მდიდარი პროდუქტები, როგორებიცაა ბამია, სატაცური, ლობიო, საფუარი, სოკო, ხორცი, ბანანი, ისპანახი, ბროკოლი და სალათის ფოთოლი.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ყურადღება მიაქციეთ სხეულის სწორ პოზას; გამართული დგომა სუნთქვას გაგიადვილებთ და წელის ტკივილსაც შეამცირებს. თუ ღრძილები მგრძნობიარე გაქვთ, მიირთვით C ვიტამინით მდიდარი საკვები. თუ მადა მოგემატათ, წასახემსებლად უპირატესობა ჯანსაღი ცხიმების შემცველ პროდუქტებს, მაგალითად, თხილეულს მიანიჭეთ. ყოველდღე რამდენიმე წუთი დაუთმეთ თქვენს ბავშვთან საუბარს.') WHERE id = 'aee96903-8ce9-4152-9673-4163944c634d';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის გარშემო არსებული ამნიონური სითხის მოცულობამ დაახლოებით 80 ml-ს მიაღწია. ამჟამად ბავშვის თავი მისი სხეულის დაახლოებით ნახევრის ზომისაა, რადგან ტვინი და ნერვული სისტემა ძალიან სწრაფად ვითარდება. არ ინერვიულოთ — მომდევნო კვირებში სხეული უფრო სწრაფად გაიზრდება და ეს თანაფარდობა დაბალანსდება. დაბადებისას თავი სხეულის ზომის მხოლოდ მეოთხედი იქნება. ნერვული სისტემის განვითარებასთან ერთად ბავშვის წოვისა და ყლაპვის რეფლექსები კიდევ უფრო ძლიერდება. გული კი ძალიან სწრაფად სცემს და სისხლის მიმოქცევას აჩქარებს, რათა მზარდი სხეულის ყველა ნაწილს სისხლი მიაწოდოს. მართალია, ჯერ ვერ გრძნობთ, მაგრამ თქვენი პატარა უკვე ძალიან აქტიურია: ამთქნარებს, ფეხებს იქნევს, ტრიალდება და თითებს ამოძრავებს. თუ ბავშვი საშვილოსნოს კედელს ერთ წამზე მეტხანს შეეხება, შესაძლოა ეს პატარა შეხებებიც ძალიან მალე იგრძნოთ.'), baby_message_ka = COALESCE(baby_message_ka, 'ბიჭი ვარ თუ გოგო? ეს უკვე განსაზღვრულია! 🩷💙 ჩემი სასქესო ორგანოები სრულად ჩამოყალიბდა. თუ გოგო ვარ, ჩემს საკვერცხეებში უკვე 2 მილიონი კვერცხუჯრედია. თუ ბიჭი ვარ, ჩემი წინამდებარე ჯირკვალი ყალიბდება. თუ ექიმები კარგი ულტრაბგერითი აპარატით დამაკვირდებიან, შესაძლოა ჩემი სქესიც დაინახონ. თქვენ რას გრძნობთ? დედის ინტუიცია ძლიერია!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'კივი'), body_changes_ka = COALESCE(body_changes_ka, 'თქვენი საშვილოსნო ჭიპიდან რამდენიმე სანტიმეტრით ქვემოთ ისინჯება. სისხლის მოცულობის გაზრდის გამო გული უფრო სწრაფად გიცემთ, რაც ნორმალურია. ჰორმონების ზემოქმედებით კანის პიგმენტაცია შეიძლება უფრო შესამჩნევი გახდეს, მაგალითად, ჭორფლები ან ხალები გამუქდეს. შესაძლოა მადა მკვეთრად გაგეზარდოთ. დილის გულისრევის დასრულების შემდეგ საკვების გემოს კვლავ უკეთ შეიგრძნობთ. თუმცა ფრთხილად იყავით — ტკბილეულისა და ცომეულის სურვილმა შეიძლება წონის ჭარბი მატება გამოიწვიოს. უპირატესობა ჯანსაღი საკვებიდან მიღებულ კალორიებს მიანიჭეთ.;;;
სარძევე ჯირკვლებზე სისხლძარღვები უფრო გამოკვეთილად ჩანს, ხოლო ძუძუსთავების გარშემო არეოლები კიდევ უფრო მუქდება და ფართოვდება. ეს ბუნებრივი „სამიზნე“ მექანიზმია, რომელიც დაბადების შემდეგ ბავშვს ძუძუს უფრო ადვილად პოვნაში ეხმარება. ძუძუებიდან მოყვითალო სითხის გამოყოფა ნორმალურია და ასევე ნორმალურია, თუ ასეთი გამონადენი არ გაქვთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'თუ ბავშვის სქესის გაგება ძალიან გსურთ, დაელოდეთ მომდევნო ულტრაბგერით გამოკვლევას. თუმცა გახსოვდეთ, რომ ბავშვის მდებარეობა ზოგჯერ სქესის დანახვის საშუალებას არ იძლევა. გამოკვლევის წინ რაიმე ტკბილის ჭამამ შეიძლება ბავშვი აამოძრაოს.') WHERE id = '35661bc0-afeb-48b5-9303-88d093e85d1a';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ახლად განვითარებად ორგანოებს შორის ელენთაცაა. რბილი და ღრუბლის მსგავსი აგებულების ელენთა უკვე იმდენად გაიზარდა, რომ ღვიძლის ზოგიერთი მნიშვნელოვანი ფუნქციის შესრულება შეუძლია. ელენთა ბავშვის ორგანიზმში ერთგვარი „დაცვისა და მარაგის“ ცენტრის როლს ასრულებს. ის მიკრობებთან მებრძოლ სისხლის თეთრ უჯრედებს წარმოქმნის, ხოლო მოძველებულ და ფუნქციადაკარგულ სისხლის წითელ უჯრედებს შლის. ამასთან, საჭიროების შემთხვევაში გამოსაყენებლად სისხლის წითელ უჯრედებს ინახავს. როდესაც ენერგიის ხარჯვა იზრდება, ელენთა იკუმშება და სისხლის ამ მარაგს სისხლის მიმოქცევის სისტემაში გამოყოფს. ამავე დროს, ბავშვის სხეულს ლანუგოდ წოდებული ძალიან თხელი, რბილი და უფერული ბუსუსები ფარავს. ეს ბუსუსები ბავშვისთვის სასიცოცხლოდ მნიშვნელოვანი დამცავი ფენაა. ვინაიდან ამ ეტაპზე ბავშვის სხეულზე ცხიმოვანი ფენა ჯერ სრულად არ ჩამოყალიბებულა, ლანუგო სხეულის ტემპერატურის სტაბილურად შენარჩუნებაში ეხმარება.'), baby_message_ka = COALESCE(baby_message_ka, 'თქვენს ხმას ვუსმენ! 👂 ჩემი ყურები კისრის ზემოდან თავის გვერდებზე — ანუ თავიანთ ნამდვილ ადგილებზე — გადავიდა. ახლა უკეთ მესმის თქვენი ხმა. მომიყევით ზღაპარი, მიმღერეთ. თქვენი ხმა მამშვიდებს. მამაც დამელაპარაკოს, მისი ხმის ცნობაც მინდა.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'მანდარინი'), body_changes_ka = COALESCE(body_changes_ka, 'ამ ეტაპამდე საშუალოდ 3-4 კილო უნდა გქონდეთ მომატებული. ორსულობის პერიოდში თითოეული ქალი სხეულის აგებულების შესაბამისად სხვადასხვა რაოდენობის წონას იმატებს. ორსულობისას საშუალოდ 8-12 კილოს მომატება ნორმად მიიჩნევა. თუმცა ყველა ქალმა შეიძლება ამდენი არ მოიმატოს. ეს სრულიად ბუნებრივი პროცესია.;;;
ორსულობის პერიოდში წელის გარშემოწერილობის გაზრდა ბუნებრივია, იმის მიუხედავად, წონაში ცოტა მოიმატეთ თუ ბევრი. მთელი ორსულობის განმავლობაში მოერიდეთ მუცელზე მომჭერ ტანსაცმელს, ფეხებზე მჭიდრო წინდებს, წელზე მომჭერ ქამრებსა და მაღალქუსლიან ფეხსაცმელს. ტანსაცმლის შერჩევისას უპირატესობა კომფორტს მიანიჭეთ. საცვლების სწორად შერჩევაც ძალიან მნიშვნელოვანია როგორც თქვენი კომფორტისთვის, ისე ჰიგიენისთვის. მოერიდეთ სინთეტიკური და ნეილონის ქსოვილისგან დამზადებულ საცვლებს და უპირატესობა ბამბისას მიანიჭეთ. ბიუსტჰალტერიც განსაკუთრებით კომფორტული და ელასტიკური შეარჩიეთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'მომატებული ენერგია შემოქმედებით საქმიანობას ან სამომავლო გეგმებს მოახმარეთ. თუ მუცელზე ქავილს გრძნობთ, ეს კანის გაჭიმვის ნიშანია; განაგრძეთ კანის რეგულარულად დატენიანება ბუნებრივი ზეთებით (ნუშის, ზეითუნის ზეთი). ყურადღება მიაქციეთ კალციუმისა და D ვიტამინის მიღებას, რათა ბავშვის ძვლები გამყარდეს. ყოველდღე 10 წუთის განმავლობაში მშვიდ გარემოში ბავშვისთვის წიგნის წაკითხვა ან მუსიკის მოსმენინება მასთან თქვენს კავშირს კიდევ უფრო გააძლიერებს.') WHERE id = 'a57894a0-cfe4-43ea-b3a3-609e569ae8e7';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის სასის ძვალი და პირის ღრუს ზედა ნაწილი უკვე სრულად ჩამოყალიბებულია. ლოყებში კი ვითარდება სპეციალური კუნთები, რომლებიც დაბადებისთანავე რძის წოვაში დაეხმარება. წოვა მხოლოდ მოძრაობა არ არის — ეს ბავშვის კვების, იმუნიტეტისა და უსაფრთხოების განცდისთვის ერთ-ერთი ყველაზე მნიშვნელოვანი უნარია. ის უკვე ვარჯიშობს და საშვილოსნოში თითს წოვს. ამ ვარჯიშების წყალობით დაბადებისთანავე ექნება ძუძუს წოვისთვის საჭირო ძალა და უნარი. წოვის პროცესი ასე მიმდინარეობს: ბავშვი ტუჩებით, ზედა სასითა და ენით ძუძუსთავს ეჭიდება და პირის ღრუში ძლიერ ვაკუუმს (ჰაერგაუმტარ სივრცეს) ქმნის. ენა უკან იწევს და რძისთვის ადგილს ათავისუფლებს, ხოლო პირი მჭიდროდ იკეტება, რათა სითხემ გარეთ არ გაჟონოს. ეს რეფლექსი იმდენად ძლიერია, რომ მომდევნო კვირებში ამ მოძრაობების შედეგად ბავშვის პირის ღრუში ნერწყვის გამომუშავება დაიწყება, რაც დაბადების შემდეგ საჭმლის მონელებას შეუწყობს ხელს.'), baby_message_ka = COALESCE(baby_message_ka, 'ვცურავ! 🏊‍♂️ შეიძლება არ დაიჯეროთ, მაგრამ ხელებს ვამოძრავებ და ფეხებს ვიქნევ. თითქოს აუზში მოცურავე პატარა ბაყაყი ვარ. ეს მოძრაობები ჩემი ტვინის განვითარებისთვის ძალიან მნიშვნელოვანია. ჯერ ვერ გრძნობთ ჩემს მოძრაობებს, რადგან ჩემ გარშემო არსებული წყალი ბიძგებს არბილებს, მაგრამ მე ძალიან ძლიერი ვარ!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'მანდარინი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის პირველივე კვირიდან საზარდულის ტკივილის დაწყება ნორმალურია. შეიძლება ისეთი შეგრძნებაც კი გქონდეთ, თითქოს მენსტრუაცია უნდა დაგეწყოთ. ასეთი ტკივილი ორსულობისას ჩვეულებრივი მოვლენაა. პირველ თვეებში ის შესაძლოა მზარდმა საშვილოსნომ და მისი კუნთების დაჭიმვამ გამოიწვიოს, ბოლო თვეებში კი — გაზრდილი ბავშვის ზეწოლამ საშვილოსნოსა და მუცლის ქვედა ნაწილზე. კვირების მატებასთან ერთად ტკივილი შეიძლება ბავშვის მოძრაობებსაც უკავშირდებოდეს. ექიმის მეთვალყურეობით მაგნიუმის მიღებამ შესაძლოა ეს ჩივილები შეამციროს. განსაკუთრებით ბოლო თვეებში ძლიერი საზარდულის ტკივილი, რომელიც დასვენების შემდეგაც არ გაივლის, შეიძლება მოახლოებული მშობიარობის ნიშანი იყოს. თუ ნაადრევი მშობიარობის რისკი გაქვთ, ასეთ შემთხვევაში შესაძლოა საავადმყოფოში მისვლა დაგჭირდეთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'არ დაგავიწყდეთ მზისგან დამცავი კრემის (SPF 50) გამოყენება. ზამთარშიც კი! ეს სახეზე მდგრადი ლაქების გაჩენის თავიდან აცილების საუკეთესო საშუალებაა. მზეზე ქუდის გარეშე ნუ გახვალთ.') WHERE id = 'f4ba8684-d553-4733-84cb-3f9f1059e979';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის სხეულის აღნაგობა თანდათან უფრო პროპორციული ხდება. ხელებმა უკვე მიაღწია იმ სიგრძეს, რაც უნდა ჰქონდეს და ამიერიდან სხეულთან ერთად იმავე ტემპით განაგრძობს ზრდას. თუმცა ფეხებს ამისთვის ცოტა მეტი დრო სჭირდება. ბავშვის სიგრძის შესაფასებლად მედიცინაში ერთ-ერთი უმნიშვნელოვანესი მაჩვენებელია ბარძაყის ძვალი — სხეულის ყველაზე გრძელი და ძლიერი ძვალი. ეს ძვალი კვლევებზე უკვე მკაფიოდ ჩანს და ბავშვის საერთო სიგრძის შესახებ ზუსტ ინფორმაციას გვაწვდის. ბოლო წლებში სიგრძის გამოსათვლელად კიდევ ერთ საინტერესო მეთოდსაც იყენებენ: ტერფის სიგრძის გაზომვას. განსაკუთრებით მე-20 კვირის შემდეგ, ბარძაყის ძვლის ან ტერფის სიგრძის 7-ზე გამრავლებით შესაძლებელია ბავშვის სავარაუდო სიგრძის დადგენა (მცირე ცდომილების გათვალისწინებით).'), baby_message_ka = COALESCE(baby_message_ka, 'მე სახის გამომეტყველებებს ვაკეთებ! 😜 ჩემი სახის კუნთები იმდენად განვითარდა, რომ შემიძლია წარბები შევკრა, თვალები მოვჭუტო ან გავიღიმო. ზოგჯერ პირს ვაღებ და ვამთქნარებ. ეს მხოლოდ გართობა არ არის — ასე ურთიერთობისთვის ვემზადები. როცა დამინახავ, ჩემს ყველაზე ტკბილ ღიმილს გაჩუქებ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'მანდარინი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის განმავლობაში თქვენი ძირითადი ნივთიერებათა ცვლის სიჩქარე ნორმასთან შედარებით საშუალოდ დაახლოებით 20 პროცენტით იზრდება. სხვა სიტყვებით რომ ვთქვათ, ორსულობის პერიოდში თქვენი ენერგეტიკული მოთხოვნილება დღეში დაახლოებით 300 კალორიით იმატებს. ცხიმოვან ცვლაშიც შესამჩნევი ცვლილებები ხდება. განსაკუთრებით მეორე ტრიმესტრში ცხიმის დაგროვება მატულობს, ხოლო მესამე ტრიმესტრში, ბავშვის ცხიმზე გაზრდილი მოთხოვნილების გამო, ამ ცხიმოვანი ქსოვილის ნაწილი ბავშვს გადაეცემა და დაგროვილი რაოდენობა მცირდება. გარდა ამისა, ორსულობის დასასრულამდე თქვენს ორგანიზმში ცილის საერთო რაოდენობა დაახლოებით 1 კგ-ით იმატებს. ორსულობის განმავლობაში ორგანიზმში დაახლოებით 6-7 ლიტრი წყალი გროვდება, ხოლო ფეხებში შეშუპების გამომწვევი დაახლოებით 1-2 ლიტრი სითხე შეიძლება დაგროვდეს. მოცირკულირე სისხლის მოცულობა 40-50 პროცენტით იზრდება. ეს მატება უკვე გავლილ პირველ ტრიმესტრში იწყება. სისხლის მოცულობის ზრდასთან ერთად გულისცემის სიხშირე დაახლოებით 10 პროცენტით იმატებს და არტერიული წნევაც მცირდება.'), daily_tip_ka = COALESCE(daily_tip_ka, 'იოგების ტკივილის შესამცირებლად მოერიდეთ უეცარ მოძრაობებს, ხოლო საწოლიდან ადგომისას ჯერ გვერდზე გადაბრუნდით. ღრძილების მგრძნობელობის შესამცირებლად განაგრძეთ კალციუმით მდიდარი საკვების (ყველი, იოგურტი, სეზამი) მიღება. მომდევნო კვირაში ბავშვი სიგრძეში კიდევ უფრო სწრაფად გაიზრდება, ამიტომ მიიღეთ საკმარისი სითხე და დაიცავით დაბალანსებული კვების რეჟიმი.') WHERE id = 'e561aed2-5768-4e9c-b71e-e052866b75f4';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამ კვირაში ულტრაბგერითი კვლევისას შეგიძლიათ მკაფიოდ დაინახოთ, როგორ აქტიურად ამოძრავებს თქვენი ბავშვი ხელის მტევნებს, მკლავებსა და ფეხებს. მიუხედავად იმისა, რომ ის საშვილოსნოში მუდმივად მოძრაობს, ამ „ცეკვის“ შესაგრძნობად კიდევ რამდენიმე კვირა დაგჭირდებათ. ჩვეულებრივ, ორსულობის მე-16-17 კვირისთვის მოძრაობები იმდენად ძლიერდება, რომ მათი შეგრძნება შესაძლებელია. თუმცა ეს პერიოდი ყველასთვის განსხვავებულია: პირველი ორსულობისას: მუცლის კუნთები უფრო მტკიცეა, ამიტომ მოძრაობების შეგრძნებას შესაძლოა 22-ე კვირამდე დასჭირდეს. განმეორებითი ორსულობისას: გამოცდილ დედებს ამ შეგრძნების ამოცნობა უფრო ადრე, ზოგჯერ მე-16 კვირიდან შეუძლიათ. პირველი მოძრაობები ძლიერი დარტყმები კი არა, უფრო „მსუბუქ ღიტინს“, „პეპლის ფარფატს“ ან „ფრინველის ფრთების ქნევას“ ჰგავს. მოძრაობები რეგულარული გახდება და ყოველდღიურად შეიგრძნობა საშუალოდ 24-26-ე კვირიდან.'), baby_message_ka = COALESCE(baby_message_ka, '14 კვირა! 📏 მე ატმის ზომის ვარ! ახლა ჩემი სხეული თავზე უფრო სწრაფად იზრდება, ამიტომ სულ უფრო მეტად ვემსგავსები პატარა ბავშვს. კისერი დამიგრძელდა, ნიკაპი კი ჩამომიყალიბდა. ყოველდღე ცოტათი უფრო ვიზრდები და ყოველდღე ცოტათი უფრო ვუახლოვდები შენთან შეხვედრას.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ატამი'), body_changes_ka = COALESCE(body_changes_ka, 'დილის გულისრევა და უეცარი ღებინება შესაძლოა კვლავ გაგრძელდეს. ეს ორსულობის დროს გავრცელებული მდგომარეობაა და უმეტეს შემთხვევაში მკურნალობას არ საჭიროებს.;;;
 სხვადასხვა სიმძიმით ის ორსულთა თითქმის ნახევარს აღენიშნება. თუმცა ტყუპებზე ორსულობისას ეს მდგომარეობა შეიძლება უფრო ხანგრძლივი და რთული იყოს. განსაკუთრებით ორსულობის პირველ კვირებში გამოვლენილი დილის გულისრევა იმის ნიშანია, რომ ჰორმონები თავის ფუნქციას ასრულებს. მიუხედავად ამისა, გულისრევისა და ღებინების ზუსტი მიზეზები უცნობია. დილის გულისრევის განსხვავებული ინტენსივობა შეიძლება დაკავშირებული იყოს ჰორმონების დონესთან, სტრესთან და დაღლილობასთან.;;;
ამ შემაწუხებელი მდგომარეობის შესამსუბუქებლად რამდენიმე ზომის მიღება შეგიძლიათ. მათ შორისაა ცილებითა და ნახშირწყლებით მდიდარი კვების რეჟიმის დაცვა, ღებინებით დაკარგული სითხის შესავსებად ბევრი სითხის მიღება, ვიტამინების რეგულარულად მიღება და ნებისმიერი ისეთი სუნის, გემოსა თუ სანახაობისგან თავის არიდება, რომელმაც შესაძლოა გულისრევა გამოიწვიოს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ტანსაცმლის საყიდლად შესანიშნავი დროა! შეიძინეთ ორსულებისთვის განკუთვნილი რამდენიმე სამოსი, რომლებშიც თავს კომფორტულად და ლამაზად იგრძნობთ. მჭიდრო ტანსაცმელმა შესაძლოა სისხლის მიმოქცევა დაარღვიოს და ვარიკოზული ვენების გაჩენას შეუწყოს ხელი.') WHERE id = 'a6400bac-f975-43dc-a8f8-6c0a5411246c';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის სახის პატარა კუნთები უკვე იმდენად განვითარებულია, რომ სხვადასხვა მიმიკური მოძრაობის შესრულება შეუძლია. ეს კუნთები პირის, თვალების, ცხვირისა და ყურების გარშემო მდებარეობს და მომავალში ემოციების გამოხატვას მოემსახურება. თქვენი ბავშვის სახის ზოგიერთი მნიშვნელოვანი კუნთია: თვალების გარშემო არსებული კუნთები: ხელს უწყობს ქუთუთოების გახსნა-დახურვასა და წარბების შეკვრას. პირის გარშემო არსებული კუნთები: უზრუნველყოფს ტუჩების მოკუმვასა და წინ გამოწევას. ეს კუნთები ხმის წარმოქმნისთვისაც მნიშვნელოვანია. „ჩაბერვის“ კუნთები (ლოყის კუნთები): ლოყებში მდებარეობს და მომავალში საკვების ღეჭვასა და ჩაბერვის მოძრაობაში მიიღებს მონაწილეობას. მართალია, თქვენი ბავშვი ამ მიმიკებს ჯერ გაცნობიერებულად არ აკეთებს (მაგალითად, განზრახ არ იღიმის), მაგრამ ტვინის განვითარებასთან ერთად სწორედ ამ კუნთების მეშვეობით გაჩვენებთ სიხარულს, ბრაზს, შიმშილსა თუ დაღლილობას.'), baby_message_ka = COALESCE(baby_message_ka, 'გემოს ვგრძნობ! 🍭 ჩემს ენაზე გემოვნების რეცეპტორები უკვე მუშაობს. იმ საკვების გემო, რომელსაც შენ მიირთმევ, ამნიონურ სითხეში გადადის. თუ ტკბილს შეჭამ, მეტ სითხეს გადავყლაპავ, რადგან ტკბილი მიყვარს! თუ მწარეს ან მჟავეს შეჭამ, შეიძლება სახე მოვმანჭო. შენ ჩემი პირველი მზარეული ხარ, დედიკო!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ატამი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულთა 30%-ს შესაძლოა აღენიშნებოდეს კვებითი დარღვევა, რომელსაც პიკას სინდრომი ეწოდება და საკვებად უვარგისი ნივთიერებების ჭამის სურვილით გამოიხატება. სიტყვა „პიკა“ ლათინურიდან მომდინარეობს და კაჭკაჭს ნიშნავს — ფრინველს, რომელიც ყველაფერს ჭამს, რასაც იპოვის. ამ სინდრომის მქონე ადამიანები ყველაზე ხშირად ჭამენ ყინულს, ნაცარს, თიხიან მიწას, საპონს, ქაღალდს, თმას, აგურის მტვერს, თეთრ ბათქაშს, ფოთლებსა და ფანქრის გრაფიტს. ორსულების მიერ ასეთი ნივთიერებების ჭამამ შეიძლება ბავშვს ჯანმრთელობის სერიოზული პრობლემები შეუქმნას. ქალებში პიკას ეპიზოდების გამომწვევი ზუსტი მიზეზი უცნობია. თუმცა სპეციალისტების აზრით, ეს შეიძლება რკინის დეფიციტს უკავშირდებოდეს, ან ორგანიზმი ამ გზით ცდილობდეს იმ ვიტამინებისა და მინერალების მიღებას, რომლებსაც ჩვეულებრივი კვებით საკმარისი რაოდენობით ვერ იღებს.;;;
შესაძლო მიზეზებს შორისაა ფსიქოლოგიური დისკომფორტი, სიყვარულის ნაკლებობა, დაუცველობის განცდა და ემოციური დეფიციტიც. რკინის დეფიციტით გამოწვეული ანემიის შემთხვევაში აუცილებელია მკურნალობა. როგორც დედის, ისე ბავშვის ჯანმრთელობისთვის ამ ნივთიერებების ჭამა უნდა შეწყდეს. ასევე საჭიროა ფსიქოლოგიური პრობლემის გამომწვევი ფაქტორების აღმოფხვრა.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ყაბზობის თავიდან ასაცილებლად მიირთვით ბოჭკოებით მდიდარი საკვები (გარგარი, ქლიავი, შვრია, ბოსტნეული). დილით უზმოზე ერთი ჭიქა თბილი წყლის დალევა ნაწლავების მუშაობას ააქტიურებს. უმოძრაობა ნაწლავების მოქმედებას კიდევ უფრო ანელებს, ამიტომ გაისეირნეთ.') WHERE id = '85f3613e-2010-4d4b-a7cf-efafd3875999';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის კანი სწრაფად ვითარდება, სქელდება და სხეულის ტემპერატურის შესანარჩუნებლად კვლავ ლანუგოს ბუსუსებით იფარება. კანი, რომელიც სხეულის ყველაზე დიდი ორგანოა, ჩამოყალიბებას ორსულობის ჯერ კიდევ მესამე კვირიდან იწყებს. კანის გარეთა შრეზე ბუსუსების ზრდა უკვე დაჩქარდა. ამ პერიოდში ისინი უფრო სწრაფად იზრდება და სქელდება. ამავდროულად, კანში წარმოიქმნება სპეციალური უჯრედები, რომლებსაც მელანოციტები ეწოდება. ეს უჯრედები გამოიმუშავებს მელანინის პიგმენტს, რომელიც კანისა და თმის ფერს განსაზღვრავს. მელანოციტები სხეულის ბუნებრივი „მზისგან დამცავი კრემივით“ მოქმედებს. ისინი მზის მავნე სხივებისგან გვიცავს:;;;
როდესაც მზის სხივები უხვადაა: მელანოციტები კანის ზედაპირისკენ გადაადგილდება, კანს ამუქებს და მავნე სხივების ღრმად შეღწევას უშლის ხელს.;;;
როდესაც მზის სხივები მცირეა: ეს უჯრედები კანის ქვედა შრეებში ინაცვლებს. შედეგად, კანი ღიავდება და სხეულს მზის სხივების გამოყენება უფრო მარტივად შეუძლია (მაგალითად, D ვიტამინის წარმოსაქმნელად).'), baby_message_ka = COALESCE(baby_message_ka, '100 დღე! 💯 დედიკო, დაუჯერებელია, უკვე 100 დღეა, რაც ერთად ვართ! ახლა ხელისგულის ზომის ვარ. ცერა თითის წოვას ვსწავლობ. ეს მამშვიდებს. როცა ღელავ ან იღლები, ამას ვგრძნობ და თავის დასამშვიდებლად თითს ვწოვ. ჩვენ ერთმანეთს ვგრძნობთ. ძალიან მიყვარხარ!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ლიმონი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის ზოგიერთ ეტაპზე ცხვირის გაჭედვა საკმაოდ შემაწუხებელი შეიძლება იყოს. ორსულთა დაახლოებით მესამედს ცხვირის გაჭედვა შეიძლება აღენიშნებოდეს მაშინაც კი, როდესაც ალერგია, ჩვეულებრივი გაციება ან გრიპი არ აქვს. ამ მდგომარეობას ორსულთა სურდო ან ორსულთა რინიტი ეწოდება.;;;
გარდა ამისა, ცხვირის გაჭედვას შეიძლება გამონადენიც ახლდეს. ღამით ცხვირის გაჭედვის გამო პირით სუნთქვამ შესაძლოა ყელის სიმშრალე გამოიწვიოს. ასევე, ღამით სუნთქვის გაძნელებისა და ხველის შედეგად შეიძლება უძილობა განვითარდეს. ლორწოვანი გარსის შეშუპებისა და ამის შედეგად სინუსების ვენტილაციის შემცირების გამო შესაძლოა თავის ტკივილიც განვითარდეს. ესტროგენი, რომლის დონეც ორსულობის დროს იმატებს და რომელიც დედობასთან დაკავშირებული ერთ-ერთი ჰორმონია, ცხვირის შიგნით ქსოვილების შეშუპებას იწვევს და გამონადენის მატებას უწყობს ხელს. ამასთანავე, ორსულობის პერიოდში ორგანიზმში მოცირკულირე სისხლის მოცულობის ზრდაც სისხლძარღვების გაფართოებასა და ცხვირის ლორწოვანი გარსის შეშუპებას იწვევს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'აღნიშნეთ ეს განსაკუთრებული დღე პატარა რიტუალით! იქნებ თქვენს ბავშვს პირველი წერილი მისწეროთ? რადგან კალციუმზე თქვენი მოთხოვნილება გაიზარდა, რაციონში ხაჭოს, ყველისა და იოგურტის რაოდენობა გაზარდეთ. თუ წელის ტკივილი გაწუხებთ, ძილის დროს ფეხებს შორის ბალიში მოათავსეთ — ეს ხერხემალზე დატვირთვას შეამცირებს. არ დაგავიწყდეთ ბევრი წყლის დალევა და სუფთა ჰაერზე სეირნობა.') WHERE id = '0cebfe33-ab23-4322-9649-a229de8418e8';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ორგანიზმში სისხლის წარმოქმნის საოცარი პროცესი მიმდინარეობს. თუ ორსულობის პირველ კვირებში სისხლს ჯერ ყვითრის პარკი, შემდეგ კი ღვიძლი წარმოქმნიდა, მე-12 კვირიდან ეს მნიშვნელოვანი ფუნქცია ძვლის ტვინმა გადაიბარა. დაბადებისას თქვენი ბავშვის ორგანიზმში დაახლოებით 350 ml სისხლი იქნება. ამჟამად თქვენი ბავშვი თითქოს „წყლისგან“ შედგება — მისი სხეულის დაახლოებით 94% წყალია. ძვლების გამკვრივებისა და კუნთების ზრდის კვალდაკვალ ეს მაჩვენებელი ოდნავ შემცირდება: მე-2 ტრიმესტრის შუა პერიოდში: 80-85% წყალი. მშობიარობის მოახლოებისას: 70% წყალი (რადგან ამ პერიოდში ცხიმოვანი შრე სწრაფად იზრდება). შედარებისთვის, ზრდასრული ადამიანის სხეულის მხოლოდ 60% შედგება წყლისგან.;;;
დაბადების მომენტიდან ბავშვის ორგანიზმში წყლის ბალანსის შესანარჩუნებლად თავის ტვინში მდებარე ჰიპოფიზი დაიწყებს ჰორმონ ვაზოპრესინის (ADH) გამოყოფას. ეს ჰორმონი თირკმელებში წყლის უკუშეწოვას უზრუნველყოფს, რითაც ბავშვს გაუწყლოებისგან დაიცავს და ორგანიზმში სითხის ბალანსს შეინარჩუნებს.'), baby_message_ka = COALESCE(baby_message_ka, 'გამარჯობა, დედიკო! 👋 დღეს წყალში ნამდვილ ტანვარჯიშს ვასრულებ. შენ ამას ჯერ ვერ გრძნობ, მაგრამ მე სალტოებს ვაკეთებ, ვტრიალებ და ფეხებს ვშლი. აქ ჯერ ძალიან დიდი სივრცე მაქვს და როგორც მინდა, ისე ვმოძრაობ. ეს მოძრაობები ჩემს კუნთებს აძლიერებს და ძვლებს ამაგრებს. შენ დაისვენე, მე კი ვარჯიშს გავაგრძელებ. ერთ დღეს ამ ბიძგებს შენც იგრძნობ!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ლიმონი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის გარკვეულ ეტაპზე თითქმის ყველა ქალს უწევს შეკრულობასთან გამკლავება. ორსულობის დროს შეკრულობის ერთ-ერთი მიზეზი ჰორმონი პროგესტერონია, რომლის დონეც პლაცენტის გავლენით სისხლში იმატებს და რომელიც გლუვ კუნთებს, მათ შორის საჭმლის მომნელებელი სისტემის კუნთებსაც, ადუნებს. შეკრულობა შეიძლება გაძლიერდეს მზარდი საშვილოსნოს მიერ ნაწლავებზე ზეწოლის გამოც. ნაწლავის კუნთების მოდუნების შედეგად საკვები და ნარჩენები საჭმლის მომნელებელ სისტემაში უფრო ნელა გადაადგილდება. რკინის დანამატებმა, განსაკუთრებით მაღალი დოზით მიღებისას, ორსულობის დროს შეკრულობა შეიძლება კიდევ უფრო გაამწვავოს. გარდა ამისა, დეფეკაციის დროს დაძაბვამ ან მაგარი განავლის გამოყოფამ შესაძლოა სწორი ნაწლავის სისხლძარღვების შეშუპება და ბუასილი (ჰემოროი) გამოიწვიოს. თუ შეკრულობა გაწუხებთ და რკინის დანამატებს იღებთ, დარწმუნდით, რომ საკმარისი რაოდენობის წყალს სვამთ. თუ ამის მიუხედავად ჩივილი არ მცირდება, შესაძლოა ექიმის რეკომენდაციით სხვა სახის რკინის პრეპარატზე გადასვლა დაგჭირდეთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'რადგან ბავშვის სმენა უმჯობესდება, მოასმენინეთ მას მშვიდი მუსიკა ან მოუყევით ზღაპარი. გულმავიწყობის თავიდან ასაცილებლად მნიშვნელოვანი საქმეები ბლოკნოტში ჩაიწერეთ. ნუ ინერვიულებთ კანზე პიგმენტაციის ცვლილებების გამო — ისინი მშობიარობის შემდეგ გაივლის. განაგრძეთ საკმარისი სითხის მიღება და კალციუმით მდიდარი საკვების (ნუში, ბროკოლი, რძის პროდუქტები) მიღება.') WHERE id = '4b92a6ac-df2b-4f98-b986-b23497226910';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის დაგრძელებულ და დაკლაკნილ ნაწლავებში მეკონიუმი (პირველი განავალი) იწყებს დაგროვებას. მეკონიუმი წებოვანი, უსუნო ნივთიერებაა, რომელიც ორსულობის განმავლობაში ბავშვის მიერ გადაყლაპული ამნიონური სითხის, ჩამოცვენილი ლანუგოს ბუსუსებისა და ნაწლავური სეკრეტის ნარევისგან წარმოიქმნება. ამ ნივთიერების 90% წყალია და ის ბავშვის ნაწლავებში დაბადებამდე გროვდება. ჩვეულებრივ, ბავშვი ამ განავალს დაბადებიდან პირველი 24 საათის განმავლობაში გამოყოფს. ვინაიდან ჰაერთან შეხება არ ჰქონია, ის სტერილურია და საშვილოსნოში ბავშვს არანაირ ზიანს არ აყენებს. მისი ფერი, როგორც წესი, მუქი მწვანე ან შავია, თუმცა მას შემდეგ, რაც ბავშვი კვებას დაიწყებს, თანდათან ღიავდება და ყვითელი ხდება. ზოგჯერ, განსაკუთრებით ვადაგადაცილებულ ბავშვებში, მეკონიუმი შესაძლოა ჯერ კიდევ საშვილოსნოში გამოიყოს. ასეთ შემთხვევებში ექიმები დაბადების შემდეგ ბავშვის სასუნთქ გზებს დაუყოვნებლივ წმენდენ, რათა ეს ნივთიერება ფილტვებში არ მოხვდეს და პრობლემა არ გამოიწვიოს.'), baby_message_ka = COALESCE(baby_message_ka, 'სინათლეს ვგრძნობ! 💡 დედიკო, ვერ დაიჯერებ, მაგრამ მიუხედავად იმისა, რომ ქუთუთოები დახუჭული მაქვს, ძლიერ სინათლეს მაინც ვგრძნობ. თუ მუცელზე კაშკაშა ფანარს მიანათებ, შეიძლება სახე მისკენ მივაბრუნო ან, თუ სინათლე თვალს მომჭრის, სახე ხელით დავიფარო. ჩემი სამყარო უკვე სრულიად ბნელი აღარ არის. ნეტავ, შენი სამყარო რამდენად ფერადია?'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ლიმონი'), body_changes_ka = COALESCE(body_changes_ka, 'ბავშვის საშვილოსნოში მიმაგრების შემდეგ სარძევე სადინარები და მკერდის მოცულობა განვითარებას იწყებს, რათა ორგანიზმი მშობიარობისთვის მოემზადოს და რძის წარმოქმნა უზრუნველყოს. ორსულობის მე-16 კვირიდან შესაძლოა შეამჩნიოთ, რომ მკერდიდან დროდადრო მოყვითალო სითხე გამოიყოფა. მკერდიდან გამოყოფილი ეს სითხე უსუნო, ყვითელი ან გამჭვირვალეა. ეს რძე ბევრ ანტისხეულს შეიცავს, რომლებიც ჯერ კიდევ განუვითარებელი იმუნური სისტემის მქონე ბავშვს სხვადასხვა ვირუსისა და მიკრობისგან იცავს. ამ სითხეში ჩვეულებრივ დედის რძესთან შედარებით უფრო მეტი ცილაა.'), daily_tip_ka = COALESCE(daily_tip_ka, 'მუცლის ზრდასთან ერთად დაიწყეთ ძილის პოზის შეცვლა. ზურგზე წოლამ შესაძლოა საშვილოსნოს მიერ მსხვილ სისხლძარღვებზე ზეწოლა გამოიწვიოს. მარცხენა გვერდზე წოლა როგორც თქვენი, ისე ბავშვის სისხლის მიმოქცევისთვის საუკეთესო პოზაა.') WHERE id = '6ada13a0-2697-47e7-9001-03b1698db1b4';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'მიუხედავად იმისა, რომ თქვენს ბავშვს დაბადების მომენტიდან შეუძლია ხმების გაგონება, ტირილი და ზოგიერთი რეფლექსის გამოვლენა, ისეთი უნარების განვითარებას, როგორებიცაა მხედველობა, მეტყველება და სიარული, ჯერ კიდევ დრო სჭირდება. ამის ძირითადი მიზეზი ისაა, რომ ნერვულ სისტემას გარე სტიმულებთან საკმარისი შეხება ჯერ არ ჰქონია. ტვინის განვითარება გარკვეულწილად „გამოცდილების დაგროვებით“ სრულდება. განსაკუთრებით მხედველობაა ის სისტემა, რომელიც ყველაზე გვიან ვითარდება. დაბადებისას არც თვალის ბადურა და არც ტვინში არსებული მხედველობის ცენტრი ჯერ ბოლომდე მომწიფებული არ არის. მუცლად ყოფნისას თქვენს ბავშვს სინათლის გარჩევა შეუძლია, თუმცა ეს სრულფასოვან მხედველობად არ ითვლება. პირველი 3 თვის განმავლობაში გამოსახულება ჯერ კიდევ ბუნდოვანია. თქვენს ბავშვს მხოლოდ 50-70 სმ-ის მანძილზე არსებული საგნების გარჩევა შეუძლია (დაახლოებით იმ მანძილზე, საიდანაც თქვენს სახეს ხედავს, როცა ხელში გიჭირავთ). ფოკუსირების უნარი ჯერ სუსტია. 5-6 თვის ასაკში, მოძრაობის უნარის გაუმჯობესებასთან ერთად, მხედველობაც უფრო მახვილი ხდება. მას უკვე შეუძლია მოძრავ საგნებს თვალით გააყოლოს და თვალისა და ხელის კოორდინაციის წყალობით ხელი იმ სათამაშოსკენ გაიწოდოს, რომელსაც ხედავს. თვალისა და მხედველობის ნერვების განვითარება სრულად 7 წლის ასაკში სრულდება.'), baby_message_ka = COALESCE(baby_message_ka, 'გემოებს ვარჩევ! 🍬 დედიკო, როცა შენ რაიმე ტკბილს ჭამ, სანაყოფე სითხეც ტკბილდება და მე უფრო მეტს ვყლაპავ. მჟავე ან მწარე გემოს დროს კი სახეს ვჭმუხნი. ჩემი გემოს შეგრძნების უნარი თითქმის ისეთივე ძლიერია, როგორიც ზრდასრული ადამიანის. ის, თუ მომავალში რომელი ბოსტნეული მეყვარება, უკვე ახლა შენს კვებაზეა დამოკიდებული. ჯანსაღად იკვებე, რომ მეც ჯანმრთელი ვიყო!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ყუბის ვაშლი'), body_changes_ka = COALESCE(body_changes_ka, 'შესაძლოა, ექიმმა გირჩიოთ, რომ მომავალ კვირას სამმაგი სკრინინგის ტესტი ჩაიტაროთ. სამმაგი სკრინინგი არის სისხლის ანალიზი, რომელიც ორსულობის მე-16 და მე-18 კვირებს შორის ყველა ორსულისთვისაა რეკომენდებული. მომავალი დედისგან აღებულ სისხლის ნიმუშში 3 სხვადასხვა ჰორმონის დონე იზომება. ამ ჰორმონების მაჩვენებლები, დედის ასაკთან, წონასთან, მოწევის სტატუსთან და ორსულობის ვადასთან ერთად, სპეციალურ კომპიუტერულ პროგრამაში მუშავდება. ეს ტესტი გამოიყენება ბავშვთან დაკავშირებული ქრომოსომული დარღვევების, განსაკუთრებით დაუნის სინდრომის სახელით ცნობილი ტრისომია 21-ისა და ედვარდსის სინდრომის სახელით ცნობილი ტრისომია 18-ის, ასევე ნერვული მილის დეფექტებად წოდებული ანომალიების სკრინინგისთვის.  ამ ტესტის ჩატარება განსაკუთრებით მნიშვნელოვანია მათთვის, ვის ოჯახურ ისტორიაშიც გვხვდება თანდაყოლილი დეფექტები, 35 წლისა და უფროსი ასაკის ქალებისთვის, მათთვის, ვინც ორსულობის დროს მავნე მედიკამენტები ან აბები მიიღო, ინსულინზე მყოფი ან დიაბეტის მქონე პირებისთვის, მათთვის, ვინც ორსულობისას ვირუსული ინფექცია გადაიტანა, და მათთვის, ვისაც ადრე თანდაყოლილი დეფექტის მქონე ბავშვი შეეძინა.'), daily_tip_ka = COALESCE(daily_tip_ka, 'მე-15 კვირის დასრულება საკუთარი თავის ცოტათი განებივრებით აღნიშნეთ! წელის ტკივილის თავიდან ასაცილებლად კომფორტული ფეხსაცმელი ატარეთ და მძიმე ტვირთს ნუ ასწევთ. ღრძილების ჯანმრთელობისთვის კალციუმის რეგულარულად მიღება არ დაგავიწყდეთ. მომავალ კვირას ბავშვის მოძრაობები კიდევ უფრო გაძლიერდება, ამიტომ ჩვევად აქციეთ, რომ ყოველდღე რამდენიმე წუთის განმავლობაში მშვიდად ესაუბროთ.') WHERE id = '7f759cae-0b0a-4f2e-8095-e125d4622671';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამ კვირიდან თქვენი ბავშვის ზრდის შესაფასებლად მხოლოდ სიმაღლის გაზომვა საკმარისი აღარ არის. ექიმები უფრო დეტალურ მაჩვენებლებზე — თავისა და მუცლის გარშემოწერილობაზე, ასევე ბარძაყის ძვლის სიგრძეზე — ამახვილებენ ყურადღებას. ეს მონაცემები ზუსტად აჩვენებს, შეესაბამება თუ არა ბავშვის განვითარება ორსულობის ვადას. თქვენს ბავშვს უკვე შეუძლია თავი და კისერი უფრო სწორად დაიჭიროს. ამას კისრის ორივე მხარეს არსებული ძლიერი კუნთები უზრუნველყოფს. ეს კუნთები თავის ქალას ამაგრებს და ბავშვს თავის თავისუფლად მოძრაობის საშუალებას აძლევს. იმისთვის, რომ ძვლები ერთმანეთზე ხახუნით არ გაცვდეს, მოძრავ სახსრებში სასახსრე სითხეა. ეს სითხე ძვლებს ისე ამოძრავებს თავისუფლად და უმტკივნეულოდ, თითქოს ისინი შეზეთილია.'), baby_message_ka = COALESCE(baby_message_ka, 'ფეხები მიგრძელდება! 🦵 აქამდე ჩემი ხელები და ფეხები ერთი ზომისა იყო, მაგრამ ახლა ფეხები სხეულის დანარჩენ ნაწილებთან შედარებით უფრო სწრაფად იზრდება. უკვე ნამდვილ მოდელს ვგავარ! ფეხებს ვხრავ და მუხლებს ჩემკენ ვწევ. ამ გრძელი ფეხებით შენთვის კარგი წიხლის მოსარტყმელად ვემზადები. ვხუმრობ, არ გატკენ, უბრალოდ „გამარჯობას“ გეტყვი.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ყუბის ვაშლი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის ამ ეტაპის შემდეგ, ბავშვის სწრაფი ზრდისა და საზარდულის მიდამოში სისხლძარღვებზე ზეწოლის გამო, ფეხების ვენებში სისხლის მიმოქცევა სუსტდება. თუ ამას ზაფხულის სიცხეც ემატება, შეშუპება შეიძლება სხეულის სხვადასხვა ნაწილში განვითარდეს, ყველაზე ხშირად კი ტერფებზე, კოჭებსა და წვივებზე. ჩივილების შესამცირებლად, ყოველი შესაძლებლობისას დაისვენეთ, კომფორტულ საწოლზე ან დივანზე წამოწექით, ფეხები ბალიშზე შემოდებით მაღლა ასწიეთ, საჭიროების შემთხვევაში მაჯებსა და კოჭებზე მსუბუქი მასაჟი გაიკეთეთ და კომფორტული ფეხსაცმელი ატარეთ.;;;
სხეულში შეშუპების კიდევ ერთი მიზეზია უმოძრაობასთან დაკავშირებული ჭარბი წონის მატება. კვების მოწესრიგება და ორსულობის დროს ნებადართული ვარჯიშების შესრულება წონის კონტროლში დაგეხმარებათ და მომდევნო თვეებში მოსალოდნელ წელისა და საზარდულის ტკივილებს შეამცირებს.;;;
ფეხით სიარული და ცურვა ორსულებისთვის ყველაზე შესაფერის ვარჯიშებად მიიჩნევა. ორივე ისეთი ფიზიკური აქტივობაა, რომლის შესრულებაც მომავალ დედას გულის, წონასწორობის, სახსრებისა და კუნთებისთვის ზედმეტი რისკის გარეშე შეუძლია. ვარჯიშისას მოკლე შესვენებები გააკეთეთ და სხეული ზედმეტად არ გადაღალოთ. ცურვისთვის, შეძლებისდაგვარად, აუზის ნაცვლად ზღვა აირჩიეთ. მოერიდეთ აუზებს, რომელთა სათანადო კონტროლსა და ჰიგიენაში დარწმუნებული არ ხართ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'სისხლის მოცულობის ზრდის გამო განსაკუთრებული ყურადღება მიაქციეთ რკინის მიღებას. იოგების ტკივილის შესამცირებლად ეცადეთ, უეცარი მოძრაობები არ გააკეთოთ. თუ მუცელზე ქავილს გრძნობთ, ყოველ საღამოს დამატენიანებელი ზეთებით მსუბუქი მასაჟი გაიკეთეთ. დღის სასიამოვნოდ გასატარებლად შეგიძლიათ ბავშვს თქვენი საყვარელი წიგნი ხმამაღლა წაუკითხოთ.') WHERE id = 'abd207ad-c924-457f-b115-c38d8e842b83';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'მიუხედავად იმისა, რომ ამ კვირაში თქვენი ბავშვის შიგნითა ყურის სტრუქტურა ფორმირებას იწყებს, სრულფასოვნად მოსმენის დაწყებამდე ჯერ კიდევ რამდენიმე კვირაა დარჩენილი. შიგნითა ყური საკმაოდ რთული სისტემაა, რომელიც პასუხისმგებელია როგორც ხმების გაგონებაზე, ისე სხეულის წონასწორობის შენარჩუნებაზე.;;;
როდესაც თქვენი ბავშვი სრულად განვითარდება, ამ სისტემის მეშვეობით 20-დან 20.000 ჰერცამდე დიაპაზონის ყველა ბგერის გაგონებას შეძლებს. ამჟამად ეს საოცარი „მოწყობილობა“ ეწყობა, თუმცა სრულად მუშაობას ორსულობის უფრო გვიან ეტაპზე (დაახლოებით 30-ე კვირისთვის) დაიწყებს.'), baby_message_ka = COALESCE(baby_message_ka, 'მე შენ გგრძნობ! 🤗 დედიკო, როცა მუცელზე ხელს მისვამ, ამ ზეწოლასა და სითბოს ვგრძნობ. ზოგჯერ იმ ადგილისკენ მოვცურავ, სადაც შენი ხელი დევს. ჩვენ შორის მხოლოდ კანი და წყალია, მაგრამ ჩვენი სულები ერთია. როცა სტრესს განიცდი, მეც ვნერვიულობ, ხოლო როცა იცინი, მეც ვმშვიდდები. გთხოვ, ყოველთვის გაიღიმე!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ფორთოხალი'), body_changes_ka = COALESCE(body_changes_ka, 'დროდადრო შესაძლოა ემოციურად, სტრესულად და ურთიერთსაწინააღმდეგო გრძნობებში ჩაფლულად იგრძნოთ თავი. ორსულობის პერიოდში თქვენს სხეულში გარკვეული ცვლილებები ხდება. ეს ფიზიკური და ჰორმონული ცვლილებები თქვენს ფსიქოლოგიურ მდგომარეობაზეც შეიძლება აისახოს. ემოციურობა, ადვილად წყენა და მგრძნობელობა ამ პერიოდში ყველაზე გავრცელებული განცდებია. გახსოვდეთ, რომ ორსულობისას წარმოქმნილი ეს სირთულეები დროებითია, ხოლო ამ საკითხში პარტნიორის მხარდაჭერა ორივე თქვენგანზე დადებითად იმოქმედებს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'როცა სუნთქვის გაძნელებას იგრძნობთ, გასწორდით და მხრები უკან გასწიეთ. ასე ფილტვებისთვის მეტი სივრცე იქმნება. ნელი და ღრმა სუნთქვა ჟანგბადით უზრუნველყოფს როგორც თქვენ, ისე ბავშვს.') WHERE id = '2da10eb1-918c-43c6-ad16-6306b072b4cb';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ნერვული სისტემა უკვე იმდენად განვითარდა, რომ მას ხელების, მკლავებისა და ფეხების უფრო გააზრებულად მართვა შეუძლია. ის უკვე უბრალოდ კი არ მოძრაობს, არამედ მუშტებს კრავს, თითებს სათითაოდ ამოძრავებს, მაჯებს ხრის და ისე იჭერს, თითქოს რაღაცის დაჭერას ცდილობს. თქვენი ბავშვის პირველი მოძრაობები ჯერ კიდევ 7-8-ე კვირებში, ხერხემლის მოძრაობით დაიწყო. მაშინ ის ძალიან პატარა იყო, ამიტომ წინ დახრისა და გვერდზე მოხრის ეს მოძრაობები შეუმჩნეველი რჩებოდა, ახლა კი ისინი უფრო ძლიერი და მიზანმიმართული გახდა. ამ საოცარი შეგრძნების განცდამდე სულ ცოტა დრო დარჩა! ჩვეულებრივ, დედები ბავშვის პირველ მოძრაობებს 16-ე და 20-ე კვირებს შორის გრძნობენ. თავდაპირველად იგრძნობთ მცირე ამობურცვებს, რომლებიც ბავშვის დარტყმებით, იდაყვის მიბჯენით ან სხეულის უკან გაჭიმვით იქნება გამოწვეული. თუ ეს თქვენი პირველი ორსულობაა ან შედარებით ჭარბი წონა გაქვთ, შესაძლოა ამ მოძრაობების შეგრძნებას 24-ე კვირამდე დასჭირდეს — ეს სრულიად ნორმალურია. ასეთ შემთხვევებში შეგიძლიათ პატარა ხრიკს მიმართოთ: ტკბილეულის მიღებამ შესაძლოა სისხლში შაქრის დონე გაზარდოს, ბავშვი გაააქტიუროს და მისი მოძრაობების უფრო მალე შეგრძნებაში დაგეხმაროთ.'), baby_message_ka = COALESCE(baby_message_ka, 'მე სუნთქვაში ვვარჯიშობ! 🌬️ რა თქმა უნდა, აქ ჰაერი არ არის, მხოლოდ წყალია. მაგრამ მე ამნიონურ სითხეს ფილტვებში ვისუნთქავ და უკან გამოვუშვებ. ეს ჩემს ფილტვის ბუშტუკებს ხსნის და მომავალში პირველი ჩასუნთქვისთვის ამზადებს. ზოგჯერ, როცა ეს სითხე ყელში გადამცდება, სლოკინი მეწყება. ამ რიტმულ სლოკინს თქვენ შესაძლოა რამდენიმე კვირის შემდეგ იგრძნოთ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ლიმონი'), body_changes_ka = COALESCE(body_changes_ka, 'უძილობა, ანუ ჩაძინებისა და ძილის შენარჩუნების გაძნელება, ორსულობის დროს საკმაოდ გავრცელებული პრობლემაა. უძილობა თითქმის ყველა ორსულს აწუხებს და უფრო მეტად ბოლო სამ თვეში იგრძნობა, როდესაც მუცელი მნიშვნელოვნად იზრდება და ორსულობა განსაკუთრებით შესამჩნევი ხდება. ორსულობის დასაწყისიდანვე, თქვენს სხეულში მიმდინარე ცვლილებების გამო, ტვინი იწყებს სიგნალის გამოგზავნას, რომ მეტი დასვენება გჭირდებათ. მთელი დღის განმავლობაში თავს დაღლილად გრძნობთ და დასვენებისა და ძილის მეტი მოთხოვნილება გაქვთ. თუმცა განსაკუთრებით ორსულობის ბოლო თვეებში წარმოქმნილმა ზოგიერთმა დისკომფორტმა შესაძლოა თქვენი ძილის რეჟიმი დაარღვიოს. ორსულობის პერიოდში უძილობის გამომწვევ მიზეზებს შორისაა გულძმარვა, ფეხების შეშუპება, ხშირი შარდვა, გულისცემის აჩქარება, ქოშინი, ფეხებზე დამატებითი დატვირთვით გამოწვეული კრუნჩხვები და ტკივილი, ასევე საჭმლის მომნელებელი სისტემის შენელებით გამოწვეული მჟავიანობა. გარდა ამისა, ძლიერმა სტრესმა და ცუდმა განწყობამაც შეიძლება ორსულობის დროს უძილობა გამოიწვიოს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ფეხებში დაღლილობის შესამცირებლად დღის განმავლობაში ხშირად შეიცვალეთ პოზიცია და დიდხანს ფეხზე ნუ იდგებით. საღამოს ფეხები გულის დონეზე მაღლა შემოაწყვეთ და 15 წუთის განმავლობაში დაისვენეთ. დაიცავით ჯანსაღი კვების რეჟიმი, რომელშიც ცილები და ბოჭკო ჭარბობს. თუ მაღალქუსლიან ფეხსაცმელს ატარებთ, უკვე დროა უფრო დაბალ და ორთოპედიულ მოდელებზე გადახვიდეთ.') WHERE id = 'ad6452f4-e2be-4e97-a304-4ef7692bd10b';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის გულმა ცემა ჯერ კიდევ მე-4 კვირაში დაიწყო, როდესაც სულ რამდენიმე უჯრედი სასწაულებრივად იკუმშებოდა და დუნდებოდა. ეს პატარა ძრავა სულ რაღაც 40 დღეში განვითარდა და სრულად ჩამოყალიბებულ, 4-კამერიან ორგანოდ იქცა. ახლა, ანუ მეოთხე თვეში, თქვენი ბავშვის გული მის პატარა სხეულში დღე-ღამეში დაახლოებით 20-25 ლიტრ სისხლს გადატუმბავს. დაბადებისას კი ეს მაჩვენებელი საოცრად გაიზრდება და დღე-ღამეში 250-300 ლიტრს მიაღწევს. თქვენი ბავშვის გული თქვენს გულზე დაახლოებით ორჯერ სწრაფად ცემს (წუთში 140-160-ჯერ). მთელი ორსულობის განმავლობაში ეს პატარა გული 1.5 მილიონზე მეტჯერ სცემს და თქვენი ბავშვის თითოეულ უჯრედს სისხლითა და სიცოცხლით უზრუნველყოფს.'), baby_message_ka = COALESCE(baby_message_ka, 'მე თქვენს გულს ვუსმენ! ❤️ ჩემი სმენა ყოველდღიურად სულ უფრო უმჯობესდება. თქვენი გულისცემა, სისხლძარღვებში სისხლის მოძრაობისა და მუცელში ბუყბუყის ხმები ჩემთვის მუდმივი მუსიკაა. ეს ხმები მამშვიდებს. დაბადების შემდეგაც, როცა გულში ჩამიკრავთ, თქვენს გულისცემას გავიგონებ და დავმშვიდდები, რადგან ეს ხმა "სახლს" გამახსენებს.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ყუბის ვაშლი'), body_changes_ka = COALESCE(body_changes_ka, 'ჩვეულებრივ, ადამიანმა დღე-ღამეში დაახლოებით 2 ლიტრი წყალი უნდა მიიღოს. თუმცა ორსულობის დროს ეს რაოდენობა შესაძლოა 3-3.5 ლიტრამდე გაიზარდოს. ამის მიზეზი ისაა, რომ ორსულობის პერიოდში ქალის ორგანიზმში მიმდინარე ფიზიოლოგიურ ცვლილებებს ბავშვის ზრდაც ემატება, ამიტომ სხეულს დიდი რაოდენობით წყალი სჭირდება. ორსულობის დასაწყისიდან ბოლომდე სისხლის მოცულობა დაახლოებით 1-1.5 ლიტრით იზრდება, ხოლო საშვილოსნოში, სადაც თქვენი ბავშვი იმყოფება, ამნიონური სითხე წარმოიქმნება. ამ სითხეს დღე-ღამის განმავლობაში განახლება სჭირდება. ამნიონური სითხე გარკვეული პერიოდულობით დედის ორგანიზმიდან მიღებული წყლით იცვლება და იწმინდება. ბავშვის გარშემო საკმარისი რაოდენობის ამნიონური სითხის არსებობას დიდი მნიშვნელობა აქვს მისი მოძრაობებისა და ფილტვების განვითარებისთვის. ამასთან, ბავშვის უჯრედების სტრუქტურის დაახლოებით 80%-ს წყალი შეადგენს, ამიტომ დედის მიერ მიღებული წყლის რაოდენობა ბავშვზე პირდაპირ მოქმედებს. ამ პერიოდში წყალს ასევე დიდი მნიშვნელობა აქვს სხეულის ტემპერატურის რეგულირებისთვის, სახსრების კომფორტისთვის, კანის სილამაზისა და საჭმლის მომნელებელი სისტემის სათანადო მუშაობისთვის.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ატარეთ ბამბის საცვლები და მოერიდეთ ვიწრო შარვლებს. თუ ყოველდღიურ საფენებს იყენებთ, ისინი ყოველ 3-4 საათში ერთხელ გამოცვალეთ, რათა ნესტიანმა გარემომ ბაქტერიების გამრავლება არ გამოიწვიოს. მნიშვნელოვანია, რომ ინტიმური ზონა მშრალად შეინარჩუნოთ.') WHERE id = '170cfd85-3741-42d0-81e6-fb29eb61eb4e';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამ კვირაში თქვენი ბავშვი დაახლოებით 50 გრამს იწონის და მისი სიგრძე 11-12 სმ-ია. ის უკვე მინიატიურულ ადამიანს ჰგავს: თავის კანიდან წარბებამდე ხშირი ლანუგოთია დაფარული, პატარა ყურები აქვს და დახუჭული ქუთუთოებით ისვენებს. მიუხედავად იმისა, რომ თქვენი ბავშვის თვალების სტრუქტურა უკვე სრულად ჩამოყალიბებულია, ფუნქციურად ისინი ყველაზე გვიან განვითარებული ორგანო იქნება. ამას საინტერესო მიზეზი აქვს: მიუხედავად იმისა, რომ ნერვული უჯრედები (ნეირონები) მრავლადაა, მათ გარშემო მიელინის გარსი ჯერ არ ჩამოყალიბებულა. მიელინის გარსი სპეციალური ცხიმოვანი შრეა, რომელიც ნერვებს ფარავს. ის შეიძლება ელექტროსადენების გარშემო არსებულ საიზოლაციო ფენას შევადაროთ. ამ შრის გარეშე ელექტრული სიგნალები ნეირონებს შორის სწრაფად ვერ გადაიცემა. მიელინის გარსის ჩამოყალიბებასთან ერთად თქვენი ბავშვი გარედან მიღებულ გამოსახულებებსა და სიგნალებს უფრო სწრაფად აღიქვამს და გააანალიზებს.'), baby_message_ka = COALESCE(baby_message_ka, 'დედიკო, ჩემი კანი ჯერ კიდევ ძალიან თხელია, მაგრამ სხეულზე არსებული ბუსუსები, რომლებსაც "ლანუგო" ეწოდება, სითბოს მინარჩუნებს. ჩემი ფეხები უკვე ხელებზე გრძელი ხდება. ახლა უფრო პროპორციულად გამოვიყურები. ზრდა ძალიან დამღლელია, მაგრამ მე ამას ვუმკლავდები!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ყუბის ვაშლი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის განმავლობაში, თქვენი ბავშვისა და საკუთარი ჯანმრთელობისთვის, უხვად უნდა მიიღოთ წყალი. ამ პერიოდში მიღებული წყლის რაოდენობა თქვენს ბავშვზეც ისევე მოქმედებს, როგორც თქვენზე. ორსულობის დროს საკმარისი წყლის მიღება არა მხოლოდ მრავალი პრობლემის მოგვარებაში გეხმარებათ, არამედ ზოგიერთ შემთხვევაში მათ სრულად თავიდან აცილებასაც უწყობს ხელს. ორსულობის დროს საკმარისი წყლის მიღება საშვილოსნოს შეკუმშვებს უშლის ხელს და ნაადრევი მშობიარობის რისკს ამცირებს. ის კანს უფრო ბზინვარესა და ჯანსაღ იერს ანიჭებს და სტრიების წარმოქმნასაც ამცირებს. ხელს უშლის საშარდე გზების ინფექციებს, შეკრულობასა და ბუასილს. ასევე ამცირებს ისეთი პრობლემების რისკს, როგორიცაა ბავშვის გარშემო ამნიონური სითხის შემცირება და არასაკმარისი განახლება. განსაკუთრებით ზაფხულის ცხელ თვეებში ავსებს ოფლიანობით დაკარგულ სითხეს. ამცირებს გულისრევას, გულძმარვასა და სხეულში წარმოქმნილ შეშუპებას.'), daily_tip_ka = COALESCE(daily_tip_ka, 'გულძმარვის დროს ნუშის ჭამას ან ერთი ჭიქა თბილი რძის დალევას ბუნებრივი დამამშვიდებელი ეფექტი აქვს.') WHERE id = '6bfad434-2bc6-4bb0-9834-16dd77e6fbe8';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამ კვირიდან თქვენი ბავშვის თავის ზრდის ტემპი ოდნავ შენელდება, რათა სხეულმა მის ზომას მიაღწიოს. ამავდროულად, ფილტვებში უკვე ჩამოყალიბებულია ყველაზე მნიშვნელოვანი სტრუქტურები — ალვეოლები, რომლებიც მომავალში სუნთქვას უზრუნველყოფს. ალვეოლები ფილტვების ყველაზე ბოლო ნაწილებში განლაგებული პატარა ტომსიკებია, რომლებიც ჰაერით ივსება. მათი მთავარი ფუნქცია აირთა ცვლაა: სისხლიდან ნახშირორჟანგის მიღება და გამოდევნა, ხოლო ორგანიზმისთვის საჭირო ჟანგბადის სისხლში გადატანა. ამჟამად თქვენი ბავშვი ამ სისტემას ჰაერის ნაცვლად ამნიონური სითხით "ავარჯიშებს". ეს ვარჯიში ძალიან მნიშვნელოვანია, რათა დაბადებისთანავე პირველი ჩასუნთქვა შეძლოს.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი ყურები უკვე თავის ადგილზეა! 👂 ჩემი ყურები ახლა ზუსტად თავის გვერდებზე, ანუ საბოლოო ადგილას მდებარეობს. უკვე უფრო მკაფიოდ მესმის შენი. შენი ნაწლავებისა და სუნთქვის ხმა ჩემთვის სიმფონიასავითაა. თუმცა ყველაზე მეტად შენი საუბარი და სიცილი მიყვარს. ხშირად მიმღერე იავნანა — მე მათ ვიმახსოვრებ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ფორთოხალი'), body_changes_ka = COALESCE(body_changes_ka, 'მომდევნო დღეებში შესაძლოა ცხვირიდან სისხლდენა დაგეწყოთ. ორსულობის გარკვეულ ეტაპზე ეს ჩივილი ბევრ ქალს უჩნდება და, ჩვეულებრივ, შეშფოთების მიზეზი არ არის. ცხვირიდან სისხლდენას შეიძლება ხელი შეუწყოს ორგანიზმში სისხლის მოცულობისა და სისხლძარღვებზე ზეწოლის მატებამ, რაც ბავშვის საშვილოსნოში ზრდას უკავშირდება. მომატებული წნევა განსაკუთრებით თხელ და ზედაპირულ სისხლძარღვებზე მოქმედებს და შესაძლოა ცხვირიდან სისხლდენა გამოიწვიოს. ამ ზეწოლის შედეგად ცხვირის შიდა ზედაპირზე არსებული წვრილი სისხლძარღვები სკდება და სისხლდენა იწყება. სისხლდენის დროს დაწოლა ან თავის უკან გადაწევა რეკომენდებული არ არის. ამ შემთხვევაში სისხლი შეიძლება ყელში გადავიდეს, გადაყლაპოთ და გულისრევა გამოიწვიოს. ამის ნაცვლად, დაჯექით ან დადექით, თავი ოდნავ წინ დახარეთ და ცხვირზე თითები მოუჭირეთ, სანამ სისხლდენა არ შეჩერდება. გარდა ამისა, სისხლძარღვების გასამაგრებლად, ექიმის რეკომენდაციით, შეგიძლიათ C ვიტამინის დანამატი მიიღოთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ღრძილებიდან სისხლდენის თავიდან ასაცილებლად რბილი კბილის ჯაგრისი გამოიყენეთ. მომატებული მადა ჯანსაღი საკვებით დაიკმაყოფილეთ. წელის ტკივილის თავიდან ასაცილებლად დიდხანს ნუ დარჩებით ერთსა და იმავე პოზაში. დღის სასიამოვნო განწყობით გასატარებლად შეადგინეთ საყვარელი სიმღერების სია და მას თქვენს ბავშვთან ერთად მოუსმინეთ.') WHERE id = '785f2466-b995-4db8-a286-7f765b7f2877';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვი უკვე ავოკადოს ზომისაა!  ამ კვირის ყველაზე საინტერესო სიახლე ბავშვის გემოს შეგრძნების განვითარებაა.;;;
თქვენი ბავშვის ენის ზედაპირზე გემოვნების კვირტები უკვე ჩამოყალიბებულია. გემოს აღქმის მექანიზმი საკმაოდ რთული და საინტერესოა: საკვები პირის ღრუში არსებულ ნერწყვში იხსნება, შემდეგ კი ენის ზედაპირზე განლაგებული რეცეპტორები გემოს აღიქვამს და ამ ინფორმაციას თავის ტვინის შესაბამის სენსორულ ცენტრს გადასცემს.;;;
როგორც ყველა ცოცხალი არსება, თქვენი ბავშვიც სწავლობს გარემომცველ გამღიზიანებლებზე რეაგირებას — ამ შემთხვევაში, მის მიერ გადაყლაპული ამნიონური სითხის გემოზე. საინტერესოა, რომ ენის ყველა ნაწილი თითოეულ გემოს ერთნაირი ინტენსივობით ვერ აღიქვამს:;;;
რადგან თქვენ მიერ მიღებული საკვების გემო ამნიონურ სითხეში გადადის, ბავშვი უკვე ახლა ეცნობა სხვადასხვა გემოს. ამან შესაძლოა მომავალში მის საკვებ არჩევანზეც კი იმოქმედოს.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი გული ძლიერია! 💪 ჩემი პატარა გული დღეში დაახლოებით 25 ლიტრ სისხლს გადატუმბავს! ასეთი პატარა სხეულისთვის ეს უზარმაზარი სამუშაოა. სისხლი მთელ ჩემს სხეულში მოძრაობს და ჟანგბადსა და საკვებ ნივთიერებებს მაწვდის. შენი დამსახურებით ძლიერი გული მაქვს. ეს გული მთელი ჩემი ცხოვრების განმავლობაში მხოლოდ შენს სიყვარულში იფეთქებს.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ავოკადო'), body_changes_ka = COALESCE(body_changes_ka, 'ზოგჯერ შესაძლოა თავი ძალიან დაღლილად იგრძნოთ, ზოგ დღეებში კი ჩვეულებრივზე მეტი ენერგია გქონდეთ. პირველ სამ თვეში პროგესტერონის დონის სწრაფმა მატებამ შესაძლოა ძილიანობა გამოიწვიოს. თქვენი მეტაბოლიზმიც აჩქარებულია და მეტ ენერგიას ხარჯავს, რაც ორსულობის ადრეულ ეტაპზე დაღლილობას აძლიერებს. ამასთანავე, შედარებით დაბალი არტერიული წნევა და სისხლის წარმოების მატებაც ენერგიის მარაგს ამცირებს. ორსულობის მე-2 ტრიმესტრს ხშირად ორსულობის "თაფლობის თვეს" უწოდებენ. თქვენი ორგანიზმი უკვე შეეგუა ორსულობის ჰორმონების ცვლილებას, ამიტომ პირველ ტრიმესტრთან შედარებით შესაძლოა ნაკლებად დაიღალოთ და სრულად დაიწყოთ მომზადება იმისთვის, რომ მალე ბავშვი გეყოლებათ. დაღლილობის პერიოდში მასთან გასამკლავებლად არ დაგავიწყდეთ ჯანსაღად კვება, ბევრი წყლის დალევა, ძილის რეჟიმის დაცვა და ფიზიკური აქტივობა.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ეცადეთ, გამართულად იჯდეთ და სიარულისას მხრები უკან გაშალოთ — ეს წელის ტკივილს შეამცირებს. კანის ელასტიკურობის შესანარჩუნებლად კვლავ გამოიყენეთ დამატენიანებელი საშუალებები. უპირატესობა მიანიჭეთ კალციუმითა და მაგნიუმით მდიდარ საკვებს (ნუში, მწვანე ბოსტნეული), რათა ბავშვის ძვლები გამაგრდეს და ფეხის კუნთების კრუნჩხვებიც თავიდან აიცილოთ.') WHERE id = '6a2c14a8-03ef-4ac3-8457-485f9afcbef3';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ულტრაბგერითი გამოკვლევისას თქვენი ბავშვის ჩონჩხი უკვე იმდენად განვითარებულია, რომ მკაფიოდ ჩანს. ჩონჩხის სისტემა შედგება ძვლებისა და მათი დამაკავშირებელი სახსრებისგან. ეს ძვლები კუნთებთან ერთად მუშაობს და ბავშვს თქვენს საშვილოსნოში მოქნილი მოძრაობების შესრულების საშუალებას აძლევს.;;;
ახალშობილის სხეულში 270 ძვალია, ხოლო ზრდასრულ ადამიანს 206 ძვალი აქვს. ამის მიზეზი ისაა, რომ ბავშვის ძვლები ჯერ კიდევ ხრტილოვანია და ერთმანეთისგან განცალკევებულია. ასეთი მოქნილობა ბავშვს სამშობიარო არხში გავლისას დაზიანებისგან იცავს. დაბადების შემდეგ ეს პატარა ძვლები (მაგალითად, თავის ქალის ნაწილები) დროთა განმავლობაში ერთმანეთს შეეზრდება და უფრო დიდ და მტკიცე ძვლებს წარმოქმნის.'), baby_message_ka = COALESCE(baby_message_ka, 'თავს უკვე სწორად ვიჭერ! 🦒 დედიკო, ჩემი კისრის კუნთები იმდენად გამაგრდა, რომ უკვე შემიძლია თავი სწორად დავიჭირო. ადრე თავი მკერდისკენ მქონდა დახრილი, ახლა კი ირგვლივ უფრო თავისუფლად შემიძლია ყურება (მიუხედავად იმისა, რომ აქ ბნელა). ჩემი სხეული იზრდება, უფრო მოხდენილი ვხდები და ტანიც უფრო გამართული მაქვს. შენს მუცელში ვარჯიში ძალიან სასიამოვნოა!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ავოკადო'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის დროს ჰორმონული ბალანსის ცვლილების გამო თქვენი ორგანიზმი ჩვეულებრივისგან განსხვავებულ პროცესებს გადის. გულისრევა, ღებინება, თვალთ დაბნელება, თავბრუსხვევა და გულის წასვლა განსაკუთრებით ხშირად გვხვდება ორსულობის პირველ სამ თვეში, თუმცა ეს მდგომარეობები ორსულობის ნებისმიერ ეტაპზე შეიძლება დროდადრო გამოვლინდეს. ორსულობისას საშვილოსნო ჩვეულებრივზე ბევრად მეტად იზრდება, ამიტომ სისხლის დიდი ნაწილი იმ საშვილოსნოსკენ მიემართება, სადაც თქვენი ბავშვია მოთავსებული. ამის გამო სხვა ორგანოებს, მათ შორის თავის ტვინს, დროდადრო შესაძლოა საჭირო რაოდენობის სისხლი არ მიეწოდოს. ასეთ მდგომარეობაში ორგანიზმი სისხლზე უეცარ მოთხოვნილებას ვერ აკმაყოფილებს, რამაც შეიძლება თავბრუსხვევა და გულის წასვლა გამოიწვიოს. ამ პერიოდში შესაძლო თავბრუსხვევისა და გულის წასვლის თავიდან ასაცილებლად ძალიან სწრაფად და მოულოდნელად ნუ წამოდგებით, მოერიდეთ ზურგზე წოლას, არ დარჩეთ მშიერი ან გაუწყლოებული და, თუ ანემია გაქვთ, ჩაიტარეთ შესაბამისი მკურნალობა.'), daily_tip_ka = COALESCE(daily_tip_ka, 'მუცლის არეში ქავილის შესამცირებლად არ დაგავიწყდეთ ბუნებრივი ზეთებით მასაჟი. წელის ტკივილის თავიდან ასაცილებლად ეცადეთ, დიდხანს არ იჯდეთ ერთსა და იმავე პოზაში. საკმარისი სითხის მიღება ძალიან მნიშვნელოვანია როგორც თქვენი, ისე თქვენი ბავშვის ნივთიერებათა ცვლისთვის. მომავალ კვირას კიდევ უფრო დიდი სიურპრიზები გველოდება!') WHERE id = 'b6a34159-6856-4473-a35e-81785fe0fc0e';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'პლაცენტა, რომელსაც ბავშვის თანამგზავრსაც უწოდებენ, თქვენს ბავშვთან ერთად განაგრძობს ზრდას. ორსულობის პირველ კვირებში, როდესაც უჯრედთა ჯგუფები გაყოფას იწყებს ბავშვის ჩამოსაყალიბებლად, ზოგიერთი მათგანი პლაცენტის წარმომქმნელ უჯრედებად გარდაიქმნება. სანამ ბავშვი სანაყოფე პარკში იზრდება, განვითარებას განაგრძობს პლაცენტაც, რომელსაც იგი ჩამოყალიბებული ჭიპლარით უკავშირდება. ორსულობის მე-4 კვირისთვის ორგანიზმში მატებას იწყებს ორსულობის ჰორმონების დონე, რომლებიც ხელს უწყობს როგორც ბავშვის, ისე პლაცენტის განვითარებას. ამგვარად, სანაყოფე პარკში ბავშვი და პლაცენტა ერთდროულად განაგრძობენ ზრდას. პლაცენტა დროებითი ორგანოა, რომელიც მთელი ორსულობის განმავლობაში უზრუნველყოფს თქვენსა და ბავშვს შორის საკვები ნივთიერებების გაცვლას, საშვილოსნოში ბავშვთან ერთად იზრდება, ხოლო ბავშვის დაბადების შემდეგ ორგანიზმიდან გამოიდევნება და თავის ფუნქციას ასრულებს. ორსულობის მნიშვნელოვანი ნაწილის განმავლობაში ეს ორგანო დაახლოებით თქვენი ბავშვის ზომისაა, ბოლო კვირებში კი საშუალოდ 20-25 სმ ზომას, 2-3 სმ სისქესა და 500 გრამ წონას აღწევს.'), baby_message_ka = COALESCE(baby_message_ka, 'პეპლის ფარფატი! 🦋 დედიკო, გრძნობ ჩემს მოძრაობას? აქ შიგნით სალტოებს ვაკეთებ! ზოგი დედა ამას აღწერს, როგორც „მუცელში პეპელა დაფარფატებს“ ან „თევზი დაცურავს“. თუ ჯერ ვერაფერს გრძნობ, ნუ მოიწყენ — ჯერ ძალიან პატარა ვარ და ჩემი ბიძგებიც სუსტია. მაგრამ სულ მალე ისე ძლიერად დაგარტყამ ფეხს, რომ მაშინვე მიხვდები!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'მსხალი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის პერიოდში გულ-სისხლძარღვთა, ანუ გულისა და სისხლძარღვების ჯანმრთელობა მნიშვნელოვანია. ამიტომ, თუ ექიმმა რაიმე უკუჩვენება არ აღმოაჩინა, სპეციალისტები ორსულობისას ფიზიკურ აქტივობას დაჟინებით გირჩევენ. ორსულობის პერიოდში ვარჯიში ამსუბუქებს ისეთ გავრცელებულ ჩივილებს, როგორიცაა წელის ტკივილი, ფეხის კრუნჩხვები და დაღლილობა, ასევე ზრდის ენერგიის დონეს. ვარჯიში ამცირებს ორსულობასთან დაკავშირებული დიაბეტისა და მაღალი არტერიული წნევის რისკსაც. ის მნიშვნელოვნად ამცირებს მშობიარობის შემდგომი დეპრესიის განვითარების ალბათობას. გამძლეობისა და კუნთების ძალის ზრდით ვარჯიში მშობიარობის პროცესსაც უწყობს ხელს. ვარჯიშით გაძლიერებული მუცლისა და ზურგის კუნთები ორსულობის პერიოდში ტკივილის წარმოქმნის ალბათობას ამცირებს. სხეულის რეგულარული გაჭიმვა (stretching) დაგეხმარებათ დაძაბულობის კერების აღმოჩენასა და მტკივნეული კუნთების მოდუნებაში.'), daily_tip_ka = COALESCE(daily_tip_ka, 'საღამოს წყნარ ოთახში დაწექით, ხელი მუცელზე დაიდეთ და ყურადღება მოიკრიბეთ. ზოგჯერ მოძრაობის შესაგრძნობად მხოლოდ სიმშვიდე და კონცენტრაციაა საჭირო. რაიმე ტკბილის ჭამამ შესაძლოა ბავშვი აამოძრაოს.') WHERE id = '6f4082a3-2c0c-4302-bc06-2af671b9e9b3';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'მიუხედავად იმისა, რომ თქვენი ბავშვის კანი გასქელებას განაგრძობს, ამ ეტაპზე ის ჯერ კიდევ გამჭვირვალედ გამოიყურება. ამ გამჭვირვალობის წყალობით, ბავშვის დანახვა რომ შეგძლებოდათ, თხელი კანის ქვეშ სისხლძარღვებს, ჩონჩხსა და ორგანოებს დაინახავდით. ბავშვის თვალის ხამხამის რეფლექსი განვითარებას განაგრძობს. ქუთუთოები წუთში საშუალოდ 15-20-ჯერ იხამხამებს, რაც დღეში დაახლოებით 30 ათასს აღწევს. თვალის ხამხამი არა მხოლოდ თვალის კაკალს იცავს, არამედ თვალის შიგნითა ნაწილსა და რქოვანას მუდმივად ტენიანობის სათანადო დონეს უნარჩუნებს. ქუთუთოები ასევე კვებავს თვალის გარეთა შრეს, რომელიც ძილის დროს ჟანგბადს ვერ იღებს. ეს მოძრაობა უნებლიედ სრულდება და მისი წყალობით თვალები ინტენსიური სინათლისა და უცხო სხეულებისგან არის დაცული. ქუთუთოს დახურვისას ცრემლის ჯირკვლებიდან გამოყოფილი სითხე მთელ თვალის კაკალს ატენიანებს. ამგვარად თავიდან არის აცილებული როგორც თვალის გამოშრობა, ისე გამაღიზიანებელი ნივთიერებებით მისი დაზიანება. ხამხამი მოძრაობის დროს მზერის ერთ წერტილზე ფოკუსირებასაც უწყობს ხელს.'), baby_message_ka = COALESCE(baby_message_ka, 'საოფლე ჯირკვლები მიყალიბდება! 💦 ჩემი კანი ჯერ კიდევ ვითარდება და ახლა საოფლე ჯირკვლების ჩამოყალიბება იწყება. რა თქმა უნდა, წყალში ყოფნისას არ ვოფლიანობ, მაგრამ დაბადების შემდეგ ისინი სხეულის ტემპერატურის დასარეგულირებლად ძალიან დამჭირდება. ყველაფერი ჩემი მომავალი ცხოვრებისთვის მზადებაა. რა საოცარი სკოლაა შენი სხეული!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'მსხალი'), body_changes_ka = COALESCE(body_changes_ka, 'მუცლის ზრდასთან ერთად შესაძლოა მუცლის არეში ქავილი იგრძნოთ და თხელი ხაზების მსგავსი სტრიებიც შენიშნოთ. ორსულობის გარკვეულ პერიოდში მკერდზე, თეძოებსა და მუცელზე შეიძლება გაჩნდეს ვარდისფერი, იისფერი ან წითელი, ოდნავ ჩაღრმავებული და ქავილის გამომწვევი ხაზები. ეს ხაზები კანის ქვეშ მდებარე შემაერთებელი ქსოვილის შრეების გადაჭარბებული დაჭიმვით გამოწვეული მცირე დაზიანებებია. სტრიების წარმოქმნაზე მოქმედი ყველაზე მნიშვნელოვანი ფაქტორი გენეტიკური მიდრეკილებაა. გენეტიკის გარდა, მუცელზე სტრიების გაჩენის კიდევ ერთი რისკფაქტორი წონის უეცარი და ჭარბი მატებაა. სწრაფად მზარდი მუცელი კანის დაჭიმვასა და ელასტიკურობის დაკარგვას იწვევს, რის გამოც შეიძლება სტრიები წარმოიქმნას. ამიტომ სტრიების თავიდან ასაცილებლად დიდი მნიშვნელობა აქვს წონის დაბალანსებულად და რეკომენდებულ ფარგლებში მატებას. სტრიების წარმოქმნის თავიდან ასაცილებლად ან მათი რაოდენობის შესამცირებლად უნდა შეინარჩუნოთ კანის ტენიანობა, წონა დაბალანსებულად მოიმატოთ, ბევრი წყალი დალიოთ, ჯანსაღად იკვებოთ და რეგულარულად ივარჯიშოთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'თავბრუსხვევის თავიდან ასაცილებლად მჯდომარე ან მწოლიარე მდგომარეობიდან ნელა წამოდექით. საკმარისი სითხის მიღება დაგეხმარებათ როგორც ენერგიის შენარჩუნებაში, ისე სანაყოფე სითხის განახლებაში. რადგან კალციუმზე თქვენი მოთხოვნილება გაიზარდა, რაციონში უპირატესობა მიანიჭეთ ისეთ პროდუქტებს, როგორიცაა ხაჭო და იოგურტი. დღის მშვიდი გასეირნებით დასრულება როგორც თქვენს, ისე თქვენი ბავშვის კომფორტს შეუწყობს ხელს.') WHERE id = '011238e0-e01a-4bb0-b882-82b96d90dc82';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'დროდადრო მუცელში მსუბუქ მოძრაობებს ხომ არ გრძნობთ? დიდი ალბათობით, ეს თქვენი ბავშვია! 😊თქვენ უკვე შეგიძლიათ იგრძნოთ თქვენი ბავშვის მოძრაობები, რადგან მისი ძვლები და კუნთები საკმარისად განვითარდა და საგრძნობლად გაძლიერდა. ამ ეტაპიდან ბავშვი უფრო მკვეთრად იმოძრავებს და მისი მოძრაობების შეგრძნებას შეძლებთ. ამასთან, საშვილოსნოს ზრდისა და სანაყოფე სითხის მოცულობის მატების წყალობით, მას გადასაადგილებლად საკმაოდ დიდი სივრცე აქვს. ორსულობის ამ ეტაპზე შეგიძლიათ იგრძნოთ ბავშვის ის მოძრაობები, რომელთა დროსაც იგი საშვილოსნოს კედელს ერთ წამზე მეტხანს ეხება. საკმაოდ განვითარებული ძვლებისა და კუნთების წყალობით ბავშვი ახლა უფრო აქტიურია, ვიდრე ოდესმე, და ყველა კუნთს იყენებს, რითაც მათ შემდგომ განვითარებას უწყობს ხელს. თუ ბავშვს ჯერ ვერ გრძნობთ, შეშფოთება საჭირო არ არის. მის მოძრაობებს სულ მალე იგრძნობთ. ბავშვის მოძრაობების გვიან შეგრძნების მიზეზებს შორის შეიძლება იყოს პირველი ორსულობისას მუცლის კუნთების სიმკვრივე, ჭიპის მიდამოში ცხიმოვანი შრის დამცავი ბარიერის როლი და ბავშვის გარშემო სანაყოფე სითხის ჭარბი რაოდენობა. ორსულთა 90% ბავშვის მოძრაობებს მე-16-22-ე კვირებს შორის გრძნობს.'), baby_message_ka = COALESCE(baby_message_ka, '„ყველში“ ვეხვევი! 🧀 სასაცილოდ ჟღერს, მაგრამ ჩემს კანზე თეთრი, კრემისებრი ნივთიერება წარმოიქმნება. მას „ვერნიქსი“ (Vernix Caseosa) ეწოდება. ეს ნივთიერება ჩემს თხელ კანს წყალში ზედმეტად დარბილებისგან იცავს. ვერნიქსი რომ არ ყოფილიყო, წყალში დიდხანს ყოფნის გამო კანი სულ დამინაოჭდებოდა. ეს ჩემი ბუნებრივი დამატენიანებელია.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'მსხალი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის პერიოდში პლაცენტა და საშვილოსნო დიდი რაოდენობით პროგესტერონს გამოიმუშავებს. ამის გამო სისხლში პროგესტერონის მაღალი დონე ანელებს კუჭის პერისტალტიკასა და შეკუმშვით მოძრაობებს და საყლაპავის ქვედა სფინქტერის მოდუნებას იწვევს. შედეგად, კუჭის მჟავა საყლაპავში გადადის და გულძმარვა ვითარდება. ცხიმიანი ან ცხარე საკვების, კოფეინის შემცველი სასმელების მიღებისგან თავის შეკავება, გაზიანი სასმელების ნაცვლად წყლის დალევა და მზა კერძების, კეტჩუპისა და მწნილის მსგავსი გადამუშავებული პროდუქტებისგან თავის არიდება გულძმარვის თავიდან აცილებაში დაგეხმარებათ. ასევე ეცადეთ, კვება დაძინებამდე სამი საათით ადრე დაასრულოთ. მწოლიარე მდგომარეობაში კუჭის მჟავა მოდუნებული სფინქტერიდან საყლაპავში უფრო ადვილად გადადის. თუ გვიან ივახშმეთ, ეცადეთ, სულ მცირე ერთი საათის განმავლობაში არ დაწვეთ. ამასთან, გულძმარვის შესამსუბუქებლად შეიძლება სასარგებლო იყოს ცივი რძისა და იოგურტის მიღება, გვირილის, პიტნისა და ჯანჯაფილის ჩაის დალევა, მცირე ულუფებითა და ხშირად კვება და თითოეული ლუკმის კარგად დაღეჭვა.'), daily_tip_ka = COALESCE(daily_tip_ka, 'საჯდომი ნერვის ტკივილის შესამსუბუქებლად სპეციალური გაჭიმვის ვარჯიშები შეასრულეთ. დიდხანს ერთსა და იმავე პოზაში ნუ იჯდებით. თბილი შხაპი ან მტკივნეულ ადგილზე თბილი კომპრესის დადება კუნთების მოდუნებაში დაგეხმარებათ.') WHERE id = '3902a1df-6463-4c00-82b6-0534aaec9c0a';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ნანატრი კვირაც დადგა! ამ კვირიდან მზად იყავით, რომ ექიმთან ვიზიტისას თქვენი ბავშვის სქესი გაიგოთ. ორსულობის მე-16 კვირაში კარგი ულტრაბგერითი აპარატითა და გამოცდილი ექიმის დახმარებით, თუ ბავშვი ხელსაყრელ პოზაშია, მისი სქესის განსაზღვრა 90%-იანი სიზუსტით არის შესაძლებელი. ამ ეტაპზე გოგონებისა და ბიჭების სასქესო ორგანოები უკვე იმდენად განვითარებულია, რომ ულტრაბგერით კვლევაზე ერთმანეთისგან განსხვავდება. ბიჭების შემთხვევაში ამ პერიოდის მთავარი სიახლე ის არის, რომ სათესლე ჯირკვლები, რომლებიც აქამდე მუცლის ღრუში მდებარეობდა, სათესლე პარკისკენ დაშვებას იწყებს.;;;
ზოგჯერ დიაგნოსტირებისას შეცდომაც შეიძლება მოხდეს. მაგალითად: გოგონების შემთხვევაში ჭიპლარი ზოგიერთი კუთხიდან ბიჭის სასქესო ორგანოს შეიძლება ჰგავდეს. ბიჭების შემთხვევაში, თუ სათესლე ჯირკვლები სათესლე პარკში ჯერ სრულად არ არის დაშვებული, ბავშვი შეიძლება შეცდომით გოგოდ მიიჩნიონ. სწორედ ამიტომ ექიმები ცდილობენ, ბავშვს რამდენიმე სხვადასხვა პოზიციიდან დააკვირდნენ. თუ თქვენი ექიმი დარწმუნებით არ საუბრობს და მხოლოდ ვარაუდს გამოთქვამს, დიდი შენაძენების გაკეთებამდე უმჯობესია დაელოდოთ დეტალურ ულტრაბგერით კვლევას, რომელიც ჩვეულებრივ 18-22-ე კვირებში ტარდება.'), baby_message_ka = COALESCE(baby_message_ka, '16 კვირა დასრულდა! 🥑 მე ავოკადოს ზომის ვარ! ჩემთვის ყველაზე მნიშვნელოვანი ამბავი ის არის, რომ ჩემი სისხლის მიმოქცევა შესანიშნავად მუშაობს. ჩემი პატარა გული ყოველდღე ლიტრობით სისხლს გადატუმბავს. ვიზრდები, ვძლიერდები და მოუთმენლად ველი შენთან შეხვედრის დღეს. შენ ჩემი სამყარო ხარ!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ავოკადო'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობისას შეიძლება ხშირად მოშარდვის სურვილი გაგიჩნდეთ, რადგან საშვილოსნო შარდის ბუშტზე ზეწოლას ახდენს და ჰორმონული დონეც იცვლება. თუმცა, თუ ამასთან ერთად შარდვისას წვას ან ჩხვლეტას, საზარდულის არეში ზეწოლის შეგრძნებასა და ტკივილს გრძნობთ, ხოლო შარდი მუქი ფერისაა, შესაძლოა საშარდე გზების ინფექცია გქონდეთ. საშარდე გზების ინფექციას უმეტესად ნაწლავებიდან მოხვედრილი ბაქტერიები იწვევს. ორსულობისას ამ პრობლემის განვითარების სიხშირე შეიძლება გაზარდოს სასქესო ორგანოების არასათანადო ჰიგიენამ, დაუცველმა სქესობრივმა კავშირმა, იმუნური სისტემის დამასუსტებელმა დაავადებებმა, შაქრიანმა დიაბეტმა, თირკმელების სტრუქტურულმა დაავადებებმა, თირკმლის კენჭებმა და წარსულში ჩატარებულმა შარდსასქესო სისტემის ოპერაციებმა. საშარდე გზების ინფექციის დროს მნიშვნელოვანია ადრეული დიაგნოსტიკა, რადგან ინფექციის პროგრესირებამ შესაძლოა თირკმელების მხრივ გართულებები გამოიწვიოს. მაღალმა სიცხემ შეიძლება საშვილოსნოს შეკუმშვები ნაადრევად დაიწყოს და შედეგად მუცლის მოშლა ან ნაადრევი მშობიარობაც კი გამოიწვიოს. ორსულობისას დღეში სულ მცირე 2 ლიტრი წყლის დალევა და სითხის მიღების გაზრდა აძლიერებს საშარდე გზებში ნაკადს და მათ გაწმენდას უწყობს ხელს. ამასთან, პრობიოტიკებით მდიდარი საკვები, როგორიცაა იოგურტი და კეფირი, აძლიერებს როგორც მიკროფლორას, ისე იმუნურ სისტემას და ინფექციებისადმი მიდრეკილებას ამცირებს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ორსულობის ერთ-ერთ ყველაზე სასიამოვნო ეტაპზე ხართ, ამიტომ ყოველი წამით დატკბით. განაგრძეთ გვერდზე ძილი და ანემიის თავიდან ასაცილებლად რაციონში რკინით მდიდარი საკვები შეიტანეთ. კანის დაჭიმვისა და სტრიების შესამცირებლად არ დაგავიწყდეთ მისი რეგულარულად დატენიანება. მომავალ კვირას ბავშვის სმენა კიდევ უფრო გაუმჯობესდება!') WHERE id = '4db5e35d-0bef-4624-aa7c-2dbb50189eef';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვი უკვე ავოკადოს ზომისაა. მომდევნო რამდენიმე კვირა მისთვის სწრაფი განვითარების პერიოდი იქნება — მისი წონაც და სიგრძეც დაახლოებით გაორმაგდება. ;;;
ამ კვირაში ულტრაბგერითი კვლევისას დიდი ალბათობით ბავშვს ზურგზე მწოლიარეს დაინახავთ. მისი ხერხემალი და ზურგის კუნთები უკვე მნიშვნელოვნად გაძლიერდა, რაც საშუალებას აძლევს, თავი და კისერი უფრო სწორად დაიჭიროს. ფეხები კი წინა კვირებთან შედარებით კიდევ უფრო დაგრძელდა და სხეულის პროპორციული გახდა.;;;
თქვენი ბავშვის სახის მიმიკებიც უფრო მრავალფეროვანი ხდება: მას უკვე შეუძლია წარბების შეკვრა და, მიუხედავად იმისა, რომ ქუთუთოები დახუჭული აქვს, თვალის კაკლების მოძრაობაც.;;;
ერთ-ერთი ყველაზე ამაღელვებელი სიახლე კი ის არის, რომ თქვენი ბავშვი ბგერების აღქმას იწყებს. შიგნითა ყურის სტრუქტურის განვითარების წყალობით მას უკვე ესმის ხმები. პირველი ხმები, რომლებსაც ის ისმენს, თქვენი სხეულიდან მოდის: გულისცემა, სუნთქვა და ნაწლავების მოძრაობა. მალე მისი ტვინი ამ ხმების უფრო ღრმად გაანალიზებას დაიწყებს და ბავშვი თქვენი ხმის სხვა გარე ხმებისგან გარჩევას ისწავლის. ამიტომ უკვე შეგიძლიათ ესაუბროთ და უმღეროთ.'), baby_message_ka = COALESCE(baby_message_ka, 'ცხიმის ფენას ვაგროვებ! 🧈 აქამდე ძალიან გამხდარი ვიყავი და კანი ძვლებზე თავისუფლად მქონდა გადაკრული. ახლა კი განსაკუთრებული ცხიმის ფენის დაგროვებას ვიწყებ, რომელსაც "ყავისფერ ცხიმს" უწოდებენ. ეს ცხიმი სითბოს შემინარჩუნებს და ენერგიას მომცემს. თანდათან იმ საყვარელ, ფუმფულა ბავშვს ვემსგავსები. მინდა, როცა შენს მკლავებში აღმოვჩნდები, რბილი და ფუმფულა ვიყო.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ავოკადო'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის პერიოდში თქვენი ჯანმრთელობის, ბავშვის განვითარებისა და კანის პრობლემების შესამცირებლად უნდა დარწმუნდეთ, რომ C ვიტამინის დღიურ მოთხოვნილებას იკმაყოფილებთ. C ვიტამინის ანტიოქსიდანტური თვისებები ინფექციებთან ბრძოლას უწყობს ხელს და ორსულობის პერიოდში, როდესაც იმუნური სისტემა უფრო მგრძნობიარეა, თქვენს ორგანიზმს ტოქსინებისგან იცავს. ის სასიცოცხლოდ მნიშვნელოვანია ქსოვილების აღდგენის, ჭრილობების შეხორცების, კანის ელასტიკურობის გაზრდისა და სტრიების პრევენციისთვის, ძვლების ზრდისა და აღდგენისთვის, ასევე კოლაგენის წარმოსაქმნელად — ეს არის სტრუქტურული ცილა, რომელიც ხრტილში, ძვლებში, მყესებსა და კანში გვხვდება და ჯანსაღი კანისთვის აუცილებელია. C ვიტამინი ასევე მნიშვნელოვანია, რადგან ხელს უწყობს ორგანიზმისთვის საჭირო რკინის შეწოვას. ამის წყალობით ჰემოგლობინის დონე ნორმის ფარგლებში ნარჩუნდება და ანემიისგან გიცავთ. გარდა ამისა, C ვიტამინი ბავშვის ქსოვილების ჩამოყალიბებას უწყობს ხელს და პლაცენტის სისხლძარღვებს აძლიერებს; შედეგად, ნაყოფს მეტი ჟანგბადი მიეწოდება და პლაცენტის ნაადრევი აშრევების რისკი მცირდება. C ვიტამინი შეკრულობის დროსაც შესანიშნავი დამხმარეა და ნაწლავების თავისუფალ მოქმედებას უწყობს ხელს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'კანის მოვლისას მოერიდეთ კრემებს, რომლებიც შეიცავს "რეტინოიდებს" (A ვიტამინის წარმოებულებს) ან "სალიცილის მჟავას". ამ ნივთიერებებმა შეიძლება ბავშვს ზიანი მიაყენოს. აირჩიეთ ბუნებრივი ზეთები ან ორსულებისთვის განკუთვნილი კოსმეტიკა.') WHERE id = '15cf9597-2ec2-4fe2-8400-f9a4938a8ee5';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ორსულობის მე-16 კვირაში თქვენი ბავშვის თვალები უკვე იმდენად არის განვითარებული, რომ სიბნელისა და მკვეთრი სინათლის გარჩევა შეუძლია. თუმცა განსხვავების შესაგრძნობად სინათლე ძალიან კაშკაშა უნდა იყოს, რადგან საშვილოსნოს კედელი სინათლისგან ძლიერ დამცავ ბარიერს ქმნის. ამჟამად გარედან შემომავალი სინათლის მხოლოდ 1% აღწევს ბავშვამდე. სხვა საინტერესო დეტალებია: ქუთუთოები: ამ ეტაპზე ბავშვის ქუთუთოები ჯერ კიდევ ერთმანეთთან არის შეწებებული. მათი გახსნა-დახურვა მხოლოდ მე-20 კვირის შუა პერიოდიდან დაიწყება. დღისა და ღამის განსხვავება: მომდევნო კვირებში, მუცლის კანის დაჭიმვასა და გათხელებასთან ერთად, შიგნით უფრო მეტი სინათლე შეაღწევს. ეს ბავშვს დღისა და ღამის გარჩევასა და სინათლის წყაროსკენ მიბრუნებაშიც კი დაეხმარება. გუგის სინათლის რეფლექსი: 30-ე კვირიდან ბავშვს გუგის რეფლექსი უვითარდება. თვალის ფერად ნაწილში — ფერად გარსში — არსებული კუნთები სინათლეზე რეაგირებს: კაშკაშა სინათლეზე გუგა ვიწროვდება, სუსტ განათებაზე კი ფართოვდება. ეს თვალის დაცვისა და გამოსახულების რეგულირების შესანიშნავი მექანიზმია.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი ჭიპლარი სქელდება! 🔌 ეს ჩემი სიცოცხლის ხაზია. საკვები ნივთიერებები და ჟანგბადი შენგან ჩემამდე ამ "კაბელის" გავლით მოდის. ახლა ის უფრო სქელი და მტკიცეა და მასში დიდი რაოდენობით სისხლი მიედინება. ზოგჯერ ხელით ვეჭიდები და ვეთამაშები, მაგრამ არ ინერვიულო — იმდენად ელასტიკური და სრიალაა, რომ ვერ მოვუჭერ და სისხლის ნაკადს ვერ შევაჩერებ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'მსხალი'), body_changes_ka = COALESCE(body_changes_ka, 'საშვილოსნოში მზარდი ბავშვის განვითარებისთვის სასარგებლოა, თუ ამიერიდან ზურგზე აღარ დაიძინებთ. ბავშვისთვის სისხლის უკეთ მისაწოდებლად უმჯობესია, მარცხენა გვერდზე იძინოთ. ზურგზე წოლისას სხეულის მთელი წონა ხერხემალსა და ზურგის კუნთებს აწვება. ეს მდგომარეობა სისხლძარღვებზე დამატებით ზეწოლას ქმნის და ბავშვისკენ მიმავალ სისხლის ნაკადს ამცირებს. ორსულობის განმავლობაში ბავშვისთვის საუკეთესო პოზაა მარცხენა გვერდზე წოლა, მუხლების მოხრა და ფეხებს შორის ბალიშის მოთავსება. ეს პოზა თირკმელებს მუშაობას უადვილებს და ამცირებს შეშუპებას, რომელიც სხეულში, განსაკუთრებით ხელებსა და მუხლებთან შეიძლება განვითარდეს. ამ პერიოდში უფრო კომფორტული ძილისთვის შეიძლება ორსულობის ბალიშის გამოყენებაც გამოგადგეთ. ჯანსაღი და ხანგრძლივი ძილისთვის რაციონიდან უნდა ამოიღოთ კოფეინის შემცველი სასმელები, როგორიცაა ყავა, ჩაი და კოლა. დღის განმავლობაში მიიღეთ ბევრი სითხე, თუმცა დაძინებამდე 2-3 საათით ადრე შეწყვიტეთ მისი მიღება და მოერიდეთ მძიმე საკვებს. გარდა ამისა, რეგულარული ვარჯიში, დაძინებამდე თბილი შხაპის მიღება და რძის დალევა მშვიდად დაძინებაში დაგეხმარებათ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'თუ თვალების სიმშრალე გაწუხებთ, დღის განმავლობაში ხშირად შეისვენეთ და ეკრანთან ნაკლები დრო გაატარეთ. ვინაიდან კალციუმზე მოთხოვნილება გაიზარდა, თქვენს რაციონში აუცილებლად შეიტანეთ სეზამი, ყველი და მწვანე ფოთლოვანი ბოსტნეული. თუ წელის არეში მსუბუქ დაჭიმულობას გრძნობთ, მჯდომარე მდგომარეობაში მხრები უკან გასწიეთ და მსუბუქი მოძრაობები შეასრულეთ. ჩვენ ყოველდღე ცოტათი უფრო ვიზრდებით!') WHERE id = 'c27b671d-4d70-44eb-80ea-7aedfd97f434';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი საშვილოსნო, რომელიც ბავშვს 9 თვის განმავლობაში მასპინძლობს, ამ კვირიდან ჭიპის ზუსტად ქვემოთ მდებარეობს. ორსულობის დასაწყისში თქვენი საშვილოსნო საშუალოდ 60 გრამს იწონიდა, ამ ეტაპზე კი მისი წონა უკვე 250 გრამს აღწევს. ამ კვირაში საშვილოსნოში, სანაყოფე პარკში, სადაც თქვენი ბავშვი იმყოფება, საშუალოდ 100 ml ამნიონური სითხეა. ეს რაოდენობა დაახლოებით 10 სუფრის კოვზ წყალს უდრის. ეს სითხე ბავშვისთვის სტაბილურ ტემპერატურულ გარემოს ქმნის და ერთგვარი დამცავი ბალიშის როლს ასრულებს, რომელიც მას მექანიკური ტრავმებისა და გარეგანი ზემოქმედებისგან იცავს. ამასთან, ანტიბაქტერიული თვისებების წყალობით, ბავშვის გარშემო სტერილურ გარემოს ქმნის და ინფექციებისგან იცავს.'), baby_message_ka = COALESCE(baby_message_ka, 'მესმის შენი, დედა! 🗣️ ახლა ჩემი ყურები სრულფასოვნად იწყებს ფუნქციონირებას. მესმის შენი საუბარი, სიცილი და ის სიმღერებიც კი, რომლებსაც მღერი. მართალია, ხმა დახშულად აღწევს ჩემამდე (თითქოს წყლის ქვეშ ვიყო), მაგრამ ინტონაციას ვარჩევ. ხშირად მითხარი „მიყვარხარ“, მინდა, ეს სიტყვა დავიმახსოვრო.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'მსხალი'), body_changes_ka = COALESCE(body_changes_ka, 'საზარდულის ტკივილი, რომელიც ორსულობის პირველ კვირებში საშვილოსნოს ზრდისა და სისხლის მიმოქცევის გაძლიერების გამო შეიძლება გაჩნდეს, მომდევნო კვირებში შესაძლოა წონის მატებამ და საშვილოსნოს დამჭერი იოგების დაჭიმვამ გამოიწვიოს. გარდა ამისა, ორსულობისას თქვენი ორგანიზმი გამოიმუშავებს ჰორმონს, რომელსაც რელაქსინი ეწოდება. რელაქსინი არბილებს მყარ ქსოვილებს, რომლებიც იოგებს ერთმანეთთან აკავშირებს. ეს ნიშნავს, რომ ორსულობისას მენჯისა და საზარდულის სახსრები შეიძლება უფრო მოძრავი გახდეს. მეორე ტრიმესტრში, ბავშვის ზრდასთან ერთად, საშვილოსნოს დამჭერი მრგვალი იოგებიც იწყებს დაჭიმვას, რამაც ასევე შეიძლება საზარდულის ტკივილი გამოიწვიოს. საზარდულის ტკივილის თავიდან ასაცილებლად შეძლებისდაგვარად აქტიური უნდა იყოთ, თუმცა ზედმეტად არ გადაიღალოთ და ყოველდღიური საქმიანობისას უეცარ მოძრაობებს მოერიდოთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ესაუბრეთ თქვენს ბავშვს! წაუკითხეთ წიგნი და მოუყევით, როგორ ჩაიარა თქვენმა დღემ. ეს თქვენ შორის ემოციურ კავშირს აძლიერებს. კვლევები აჩვენებს, რომ დაბადების შემდეგ ბავშვები ცნობენ იმ ხმებსა და სიმღერებს, რომლებიც დედის მუცელში ყოფნისას ესმოდათ.') WHERE id = '16510ace-04bb-4c83-9c44-82e27d7b140c';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვი ამ კვირაშიც აგრძელებს დაბადების დღისთვის მზადებას. ამჟამად ყველაზე მნიშვნელოვანი მოძრაობები, რომლებზეც ის მუშაობს, წოვისა და ყლაპვის რეფლექსებია! ის ემზადება პირველი ყლუპებისთვის, რომლებითაც თქვენ გამოკვებავთ. ყლაპვა ერთ-ერთი პირველი რეფლექსური მექანიზმია, რომელსაც ბავშვი ივითარებს. ეს პროცესი იწყება მას შემდეგ, რაც ზედა ტუჩის ჩამოყალიბება სრულდება, ტუჩი ფუნქციონირებას იწყებს და ბავშვს პირის დახურვის საშუალებას აძლევს.;;;
ყლაპვის დაწყების შედეგად წოვის უნარიც ინსტინქტურად ვითარდება. ანუ ფუნქციურად ეს ორი რეფლექსი ერთმანეთს მიჰყვება. ბავშვის მიერ უკვე დაწყებული ეს ინტენსიური ვარჯიში სრულყოფილად მხოლოდ 32-ე კვირისთვის შეიძლება განვითარდეს.;;;
ამავე პერიოდში თქვენი ბავშვი ამნიონური სითხის ყლაპვასაც სწავლობს და ამ გზით, ისევე როგორც სუნთქვის ფუნქციის შემთხვევაში, ემზადება იმისთვის, რომ დაბადებისას ყველაფერი მზად ჰქონდეს. შედეგად, დაბადების შემდეგ მას უკვე ექნება იმდენად განვითარებული ყლაპვის უნარი, რომ თქვენი ძუძუდან რძის წოვას შეძლებს. ნერწყვის რაოდენობის მიხედვით, ყლაპვის რეფლექსი სიფხიზლისას დაახლოებით წუთში ორჯერ, ხოლო ძილის დროს დაახლოებით წუთში ერთხელ ვლინდება.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი ხელები უსაქმოდ არ ჩერდება! ✊ ჩავლების რეფლექსი ძალიან ძლიერი მაქვს. ხელებს მუშტებად ვკრავ და თითებს ვამოძრავებ. ზოგჯერ ჭიპლარს ვეჭიდები, ზოგჯერ კი მეორე ხელს. ეს მოძრაობები ჩემს თითებს აძლიერებს. როცა დავიბადები, შენს თითს ისე მაგრად ჩავეჭიდები, რომ გაგიკვირდება!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'მსხალი'), body_changes_ka = COALESCE(body_changes_ka, 'თქვენი საშვილოსნო თითქმის ჭიპის დონემდეა ასული და ამას უკვე ხელითაც იგრძნობთ. რადგან ამ კვირიდან ბავშვი წინა კვირებთან შედარებით უფრო სწრაფად იწყებს წონის მატებასა და განვითარებას, დიდი ალბათობით, თქვენი წონაც ოდნავ უფრო სწრაფად მოიმატებს. ამ პერიოდისთვის საშუალოდ 2.5-5 kq უნდა გქონდეთ მომატებული. ზოგიერთი მომავალი დედის მუცელი ორსულობის ვადასთან შედარებით უფრო დიდი ან პატარა შეიძლება იყოს. ამის ყველაზე სავარაუდო მიზეზებია ნაწლავებში დაგროვილი აირები ან კანის სიმკვრივე.;;;
ამ კვირის ბოლომდე სამმაგი ტესტი უნდა ჩაიტაროთ. მიუხედავად იმისა, რომ ზოგიერთი ლაბორატორია გამოყენებული კომპიუტერული პროგრამების დახმარებით სამმაგი ტესტის შეფასებას მე-20 კვირამდე ან უფრო გვიანაც ახორციელებს, სასარგებლოა რისკის უფრო ადრე გამოვლენა. ზოგიერთი ექიმი მიიჩნევს, რომ თუ 11-14-ე კვირებს შორის ჩატარებული ორმაგი ტესტის შედეგები დაბალ რისკზე მიუთითებს, სამმაგი ტესტი აუცილებელი არ არის, სხვებმა კი შესაძლოა როგორც ორმაგი, ისე სამმაგი ტესტის ჩატარება გირჩიონ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ორსულობის ერთ-ერთ ყველაზე კომფორტულ პერიოდში ხართ, ამიტომ საკუთარ თავს დრო დაუთმეთ. მარცხენა გვერდზე ძილი ჩვევად აქციეთ, რათა სისხლის მიმოქცევა ოპტიმალური იყოს როგორც თქვენთვის, ისე ბავშვისთვის. განაგრძეთ ბევრი სითხის მიღება და კალციუმით მდიდარი საკვების მიღება. მომავალ კვირას ბავშვის მოძრაობების უფრო მკაფიოდ შეგრძნების ალბათობა გაიზრდება!') WHERE id = '0f424a2a-4630-431c-9be8-af0ad1977c5a';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ფილტვები ყველა მიმართულებით აგრძელებს განვითარებასა და ფუნქციონირების დაწყებას. მართალია, ფილტვებს ჯერ არ შეუძლია ნახშირორჟანგისა და ჟანგბადის მიმოცვლა, თუმცა უკვე შეძენილი აქვს ფუნქცია, რომელიც დაბადების შემდეგ სუნთქვას უზრუნველყოფს. ამ ეტაპზე სუნთქვითი მოძრაობები ამნიონური სითხის გარემოში მიმდინარეობს.;;;
პირველი ჩასუნთქვა, რომელსაც თქვენი ბავშვი დაბადებისას გააკეთებს, მის ცხოვრებაში ყველაზე რთული იქნება. ამის მიზეზი ისაა, რომ წყლით სავსე სასუნთქ სისტემაში წყალი ჰაერმა უნდა ჩაანაცვლოს.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი ძვლები მაგრდება! 🦴 ადრე ჩემი ჩონჩხი რეზინივით რბილი ხრტილისგან შედგებოდა, ახლა კი ის ნამდვილ ძვლად გარდაიქმნება (ოსიფიკაცია). უკვე უფრო ძლიერი ვარ. ჩემი ნეკნები, ხერხემალი და ფეხის ძვლები მაგრდება. მე უკვე აღარ ვარ პატარა ჟელესავით რბილი არსება — ძლიერი ბიჭი ვარ (ან გოგო)!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'მსხალი'), body_changes_ka = COALESCE(body_changes_ka, 'თუ შაქრიანი დიაბეტი ორსულობამდეც გქონდათ, ორსულობის პერიოდში განსაკუთრებული სიფრთხილე გმართებთ. ორსულობისას სისხლში შაქრის დონის კონტროლი შეიძლება უფრო რთული იყოს, ვიდრე ორსულობამდე. ასევე შესაძლოა ინსულინის დოზის შეცვლა გახდეს საჭირო. ასეთ შემთხვევაში ექიმთან შემოწმებაც უფრო ხშირად დაგჭირდებათ.;;;
შაქრიანი დიაბეტი დაავადებაა, რომელიც სისხლში შაქრის დონის მატებას იწვევს. მაშინაც კი, თუ ჩვეულებრივ შაქრიანი დიაბეტი არ გაქვთ, შესაძლოა განვითარდეს ორსულობის დიაბეტი, რომელსაც გესტაციურ დიაბეტსაც უწოდებენ. ორსულობის 24-28-ე კვირებს შორის სკრინინგი ტარდება გლუკოზის დატვირთვის ტესტით, რომელიც შაქრის ტესტის სახელითაცაა ცნობილი. შედეგები ზუსტდება 50-75-100 qramlıq ორალური გლუკოზის ტესტით და ისმება საბოლოო დიაგნოზი. ორსულობასთან დაკავშირებული შაქრიანი დიაბეტი დაახლოებით ყოველი 150 ორსულობიდან ერთ შემთხვევაში შეიძლება განვითარდეს. თუ გაქვთ ისეთი სიმპტომები, როგორიცაა წყურვილი, წონის კლება, ჭარბი ჭამის მოთხოვნილება, ჩვეულებრივზე მეტი წყლის მიღება და შარდვა ან მუდმივი დაღლილობა, ექიმს უნდა მიმართოთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'უეცარი თავბრუსხვევის თავიდან ასაცილებლად, წოლიდან წამოდგომისას ჯერ დაჯექით, შემდეგ კი ნელა ადექით. წელის ტკივილის დროს მსუბუქი პრენატალური იოგა ან სეირნობა ძალიან სასარგებლოა. განსაკუთრებული ყურადღება მიაქციეთ რკინისა და კალციუმის მიღებას. რას იტყვით, დღეს თქვენს ბავშვს ზღაპარი რომ წაუკითხოთ ან სამომავლო გეგმებზე ესაუბროთ?') WHERE id = 'ae23805e-1ec4-470c-a370-e36eb29268eb';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ცხიმოვანი ქსოვილი (ცხიმის ფენა) კანის ქვეშ და შინაგანი ორგანოების გარშემო გროვდება. ეს ცხიმოვანი ფენა ენერგიის მარაგის როლს ასრულებს. ნაყოფის გულისცემა თავის ტვინის მიერ რეგულირდება და უფრო რიტმული ხდება (წუთში 140-150 დარტყმა). სისხლის მიმოქცევის სისტემა სრული დატვირთვით მუშაობს.'), baby_message_ka = COALESCE(baby_message_ka, 'მე „ვიმატებ წონაში“, დედიკო! 🧸 ჩემს სხეულში ცხიმოვანი ქსოვილის დაგროვება გრძელდება. ადრე ძალიან გამხდარი ვიყავი, ახლა კი ხელები და ფეხები მევსება. ეს ცხიმოვანი ფენა ძალიან მჭირდება, რადგან დაბადების შემდეგ სხეულის ტემპერატურის რეგულირებაში დამეხმარება. ჩემზე ნუ ინერვიულებ, აქ თბილად ვარ და არ მშია. შენ უბრალოდ ჯანსაღად იკვებე, დანარჩენს მე მივხედავ!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'დიდი ხახვი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის ამ ეტაპზე შესაძლოა მრავალი ფიზიკური და ემოციური ცვლილება იგრძნოთ. სისხლის მიმოქცევის გაძლიერების გამო იმატებს ვაგინალური გამონადენის, ოფლის, ლორწოსა და სხვა სითხეების რაოდენობა. უჩვეულო სიზმრები შესაძლოა თქვენი ჰორმონების, ემოციური მდგომარეობისა და მოლოდინების შედეგიც იყოს. ორსულობის დროს შეიძლება ვარჯიშს ერიდებოდეთ, რადგან გეშინიათ, რომ საკუთარ სხეულს ან ბავშვს ზიანი არ მიაყენოთ. თუმცა სათანადო ვარჯიში მშობიარობას ამარტივებს და ბავშვის ჯანმრთელობაზეც დადებითად მოქმედებს. ამ პერიოდში შეგიძლიათ რეგულარულად შეასრულოთ წელის ვარჯიშები, რომლებიც ხერხემალს გაგიძლიერებთ. ორსულებისთვის განკუთვნილი იოგა და პილატესი ორსულობის პირველივე კვირებიდან არის რეკომენდებული. კვირაში 3-5 დღე, 30 წუთის განმავლობაში სწრაფი ტემპით სიარული ორსულობისას ძალიან სასარგებლო იქნება თქვენთვის. თუმცა ეს ყველაფერი ისე უნდა გააკეთოთ, რომ არ გადაიღალოთ. თუ ვარჯიში არ გიყვართ, მოძრაობისთვის შეგიძლიათ იცეკვოთ. ორსულობის დროს ცეკვა გაძლიერებთ, მოქნილობას გიმატებთ და სტრესის დონის შემცირებით განწყობასაც გიუმჯობესებთ. ამასთანავე, ეს შესანიშნავი იდეაა, რათა ბავშვთან ერთად გართობა უკვე ახლა დაიწყოთ!'), daily_tip_ka = COALESCE(daily_tip_ka, 'თქვენს მენიუში ყოველთვის შეიტანეთ კალციუმით მდიდარი საკვები. მიირთვით რძის პროდუქტები, ბროკოლი, ნუში და სეზამი. თუ საკმარის კალციუმს ვერ მიიღებთ, ბავშვი მისთვის საჭირო კალციუმს თქვენი ძვლებიდან და კბილებიდან მიიღებს.') WHERE id = 'c7911f10-1eb8-49da-80ba-c909457132da';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ხელისა და ფეხის თითებზე, რომლებიც დღითი დღე გრძელდება, თითის ანაბეჭდების ჩამოყალიბება გრძელდება. ბავშვის სხეულის შემადგენელი და მისი ფორმირების პროცესში მონაწილე თითოეული უჯრედი დნმ-ის მოლეკულას შეიცავს. ადამიანების დნმ 99%-ით მსგავსია, ხოლო დარჩენილი 1% თქვენს ბავშვს უნიკალურს ხდის.;;;
თითის წვერების კანზე სხვადასხვა მოხაზულობის თვალით ხილული რელიეფური ხაზები წარმოიქმნება, ხოლო კანის გარეთა შრეზე არსებულ ამ ამობურცულობებს პაპილები ეწოდება. ამ სტრუქტურის წყალობით თითოეულ ადამიანს უნიკალური თითის ანაბეჭდები აქვს. არავის, მათ შორის ერთკვერცხუჯრედიან ტყუპებსაც კი, არ აქვს ერთმანეთის იდენტური თითის ანაბეჭდები. სხვაგვარად რომ ვთქვათ, თითის ანაბეჭდი მხოლოდ ჩვენთვის დამახასიათებელი კვალია, რომელსაც ყველაფერზე ვტოვებთ, რასაც ვეხებით. თუ სერიოზული ჭრილობა ან დაზიანება არ განვითარდა, თითის ანაბეჭდის ხაზები მთელი სიცოცხლის განმავლობაში უცვლელი რჩება.'), baby_message_ka = COALESCE(baby_message_ka, 'სიზმრებს ვხედავ! 💤 დედიკო, მეცნიერები ამბობენ, რომ უკვე შემიძლია „REM ძილის“, ანუ Rapid Eye Movement -თვალების სწრაფი მოძრაობის ფაზაში გადასვლა. ეს ნიშნავს, რომ სიზმრების ნახვა შემიძლია! ნეტავ, რას ვხედავ სიზმარში? ალბათ შენი ხმა მესმის ან შენს სახეს წარმოვიდგენ. დღის უმეტეს ნაწილს ძილში ვატარებ, მაგრამ როცა მღვიძავს, ძალიან აქტიური ვარ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'დიდი ხახვი'), body_changes_ka = COALESCE(body_changes_ka, 'ბოლო წლებში პილატესი მომავალი დედების მიერ ყველაზე ხშირად არჩეული ვარჯიშის ერთ-ერთი სახეა. პილატესი სხეულს ადუნებს, გონებას განტვირთავს, ზურგისა და წელის ტკივილს ხელს უშლის და მომავალ დედას საკუთარი სხეულის უკეთ შეცნობაში ეხმარება. მნიშვნელოვანია, ივარჯიშოთ ამ სფეროს სპეციალისტთან. განსაკუთრებული ყურადღება უნდა მიექცეს იმას, რომ შესრულებული პილატესის მოძრაობები ორსულობის პერიოდისთვის შესაფერისი იყოს.;;;
რაც შეეხება იოგას, ორსულობის დროს ზოგიერთი პოზის შესრულება კატეგორიულად დაუშვებელია. ამიტომ გაკვეთილები მხოლოდ გამოცდილი ინსტრუქტორისგან უნდა მიიღოთ, რომელიც სპეციალურად ორსულებისთვის განკუთვნილ იოგას ასწავლის. მოიძიეთ ორსულთა იოგის ჯგუფები და თქვენთვის ყველაზე შესაფერისი შეარჩიეთ. ;;;
ერთი მუხლი იატაკზე დადეთ, მეორე ფეხი წინ გადადგით და ჩაიმუხლეთ. იგრძნობთ, როგორ იჭიმება ფეხებისა და თეძოების კუნთები. შემდეგ ფეხები შეცვალეთ. ეს სავარჯიშო ფეხებს გაგიძლიერებთ. ასე ისინი თქვენი მუცლის სიმძიმეს უფრო მარტივად გაუმკლავდებიან.'), daily_tip_ka = COALESCE(daily_tip_ka, 'უჩვეულო სიზმრების ნუ შეგეშინდებათ — ეს ორსულობის ნორმალური ნაწილია. დაძინებამდე დამამშვიდებელი მუსიკის მოსმენა ან წიგნის კითხვა გონების მოდუნებაში დაგეხმარებათ. იზრუნეთ, რომ საძინებელში სიგრილე იყოს.') WHERE id = '109a3421-ce4d-45f2-89cf-6db2482011b0';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის კბილის მინანქარმა ფორმირება დაიწყო. კბილი შედგება მინანქრისგან, დენტინისგან, ცემენტისგან და კბილის რბილობისგან, რომელსაც პულპა ეწოდება. მინანქარი ორგანიზმში ყველაზე მყარი ნივთიერებაა. ის კბილს გარედან დამცავი ფენის მსგავსად ფარავს.;;;
ამ ეტაპზე კალციუმის მარილები ბავშვის კბილის ორგანულ ჩანასახზე ნელ-ნელა ილექება, გროვდება და კრისტალდება. ეს პროცესი ბავშვის კბილების ამოჭრამდე გრძელდება. ორსულობის დროს ზოგიერთი მედიკამენტის მიღებამ შესაძლოა კბილის მინანქრის ფორმირების პროცესი შეანელოს. შედეგად კბილებზე შეიძლება ყვითელი, ნაცრისფერი ან ყავისფერი პიგმენტაცია წარმოიქმნას. ზოგჯერ შესაძლოა განვითარდეს კბილის განუვითარებლობა ან ზრდის შეფერხება, რასაც ჰიპოპლაზია ეწოდება.'), baby_message_ka = COALESCE(baby_message_ka, 'ხმებზე ვკრთები! 🔊 თუ მოულოდნელად დააცემინებ, კარი ძლიერად გაიჯახუნებს ან ხმამაღალი მუსიკა ჩაირთვება, მე ადგილზე შევხტები. ამას „მოროს რეფლექსს“ უწოდებენ. ხელებსა და ფეხებს უეცრად ვშლი და ისევ ვკეცავ. ჩემი სმენა ძალიან მგრძნობიარე გახდა. გთხოვ, მშვიდ გარემოში იყავი — ხმამაღალი ბგერები მაწუხებს.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'დიდი ხახვი'), body_changes_ka = COALESCE(body_changes_ka, 'სუნთქვითი ვარჯიშები ორსულობის პერიოდში სხეულის არასწორი პოზის გამოსწორებასა და წელის ტკივილის შემცირებაში გეხმარებათ. ისინი გასწავლით სუნთქვისა და მოდუნების ტექნიკას, რომელიც მშობიარობის დროს დაგჭირდებათ, ასევე ზრდის მუცლისა და საზარდულის კუნთების მოქნილობასა და ძალას. ეს ვარჯიშები მშობიარობისთვის ემოციურად გამზადებთ, შეკუმშვების დროს სუნთქვის კონტროლსა და ეფექტურად გაჭინთვაში გეხმარებათ და საშუალებას გაძლევთ, მშობიარობისას ენერგია გონივრულად გამოიყენოთ.;;;
სწორი სუნთქვა ზრდის სისხლში ჟანგბადის დონეს და ხელს უწყობს ორგანიზმიდან ტოქსინების გამოდევნას, ნერვული სისტემისა და ჰორმონების რეგულირებას, იმუნიტეტის გაძლიერებას, უჯრედების ეფექტიანობის გაზრდით კანის გამოცოცხლებას, ყურადღების უფრო მარტივად მოკრებას, მეხსიერების გაუმჯობესებას, გაგებისა და აღქმის უნარის დაჩქარებას, შემოქმედებითი და სწრაფი აზროვნების განვითარებას, ძილის მოწესრიგებასა და მისი ხარისხის გაუმჯობესებას, ასევე გონებრივ სიმშვიდეს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'თუ ჯერ კიდევ არ გიგრძნიათ, ამ დღეებში ბავშვის პირველი მსუბუქი მოძრაობების შესაგრძნობად შეგიძლიათ მშვიდ გარემოში წამოწვეთ და ყურადღება მუცელზე გადაიტანოთ. წელის ტკივილის შესამცირებლად დაბალქუსლიანი ფეხსაცმელი ჩაიცვით. რადგან კალციუმზე თქვენი მოთხოვნილება გაიზარდა, რაციონში მეტი რძის პროდუქტი და მწვანე ბოსტნეული შეიტანეთ. დღეს საკუთარ თავს პატარა საჩუქარი გაუკეთეთ!') WHERE id = '5dba3d5c-bb87-4502-8385-7f27405dc9b2';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის სხეული უკვე უფრო პროპორციულად იზრდება. ამიტომ გული ცდილობს, სხეულში გადატუმბული სისხლის რაოდენობა გარკვეულ დონეზე სტაბილურად შეინარჩუნოს. უჯრედების დიფერენცირებისა და განვითარების შედეგად სპეციფიკური ფორმის მიმღები გულის განვითარება განაყოფიერებიდან ორ თვეში სრულდება. 60 დღის განმავლობაში ის 4 სარქვლისა და 4 კამერის მქონე ორგანოდ ყალიბდება და თქვენი ბავშვის მთელი ცხოვრების განმავლობაში აგრძელებს მუშაობას.;;;
ამ ეტაპზე თქვენი ბავშვის გული წუთში 140-160-ჯერ ცემს. 3 თვის ასაკში ეს მაჩვენებელი წუთში 135-140-მდე, 6 თვის ასაკში 130-მდე, 9 თვის ასაკში 120-125-მდე, 12 თვის ასაკში 115-120-მდე, 24 თვის ასაკში 115-მდე, 4 წლის ასაკში 100-მდე, ხოლო 15 წლის ასაკში დაახლოებით 75-80-მდე დასტაბილურდება.;;;
ამ პერიოდში ულტრაბგერითი გამოკვლევისას ბავშვის გულში შესაძლოა ხვრელებიც გამოჩნდეს. თუ არ არსებობს ნათესაური ქორწინების შემთხვევა ან ახლო ნათესავებში გულის ანომალიების მქონე პირი, ორსულობის დროს ექიმის დანიშნულების გარეშე მედიკამენტები არ გამოგიყენებიათ, არ გადაგიტანიათ ისეთი მძიმე ინფექცია, როგორიცაა წითურა, არ არის დასმული დაუნის ან ტერნერის სინდრომის დიაგნოზი და არ იღებთ ალკოჰოლს, ეს ხვრელები ბავშვის დაბადებამდე 80% ალბათობით დაიხურება.'), baby_message_ka = COALESCE(baby_message_ka, 'ჭიპლარით ვთამაშობ! ➰ ჩემი ყველაზე საყვარელი სათამაშო ჭიპლარია. ხელს ვკიდებ, ვუჭერ და ვატრიალებ. მაგრამ ნუ გეშინია, ის ძალიან სრიალა და გამძლეა, ამიტომ ვერ დავაზიანებ. ეს თამაში ჩემს ჩაჭიდების რეფლექსსა და ხელისა და თვალის კოორდინაციას ავითარებს. შენ რას აკეთებ? მე აქ სულაც არ ვიწყენ!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'დიდი ხახვი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობა ვარიკოზული ვენების განვითარებას უწყობს ხელს. ბავშვის საჭიროებების დასაკმაყოფილებლად სისხლის მოცულობა საგრძნობლად იზრდება. ამის გამო სისხლძარღვებში მეტი სისხლი მოძრაობს, რაც განსაკუთრებით ფეხებში მის დაგროვებას აძლიერებს. ორსულობის დროს განვითარებული ვარიკოზული ვენები, ჩვეულებრივ, მზარდი ბავშვის მიერ საზარდულის მიდამოში ვენებზე ზეწოლის შედეგად ჩნდება.;;;
ვარიკოზული ვენები კანზე იისფერი ან ლურჯი, გამსხვილებული და ობობის ქსელის მსგავსი სისხლძარღვების სახით ვლინდება. მდგომარეობის პროგრესირებასთან ერთად სიმპტომებს შეიძლება დაემატოს ძლიერი ტკივილი, კრუნჩხვები, ფეხების დაღლილობა, სიმხურვალისა და სიმძიმის შეგრძნება. რამდენიმე მარტივი, მაგრამ მნიშვნელოვანი რეკომენდაციის დაცვა და მათი ჩვევად ქცევა ვარიკოზული ვენების წარმოქმნის თავიდან აცილებაში დაგეხმარებათ.;;;
ეცადეთ, დიდხანს არ იჯდეთ ფეხი ფეხზე გადადებული. ჯდომისას სისხლის მიმოქცევის გასააქტიურებლად ფეხები ამოძრავეთ. დასვენებისას ფეხები სხეულის დონეზე მაღლა მოათავსეთ. ნუ ასწევთ სიმძიმეებს. დალიეთ ბევრი წყალი და მოერიდეთ ზედმეტად მარილიან საკვებს. დიდხანს ნუ მართავთ ავტომობილს. მოერიდეთ მაღალქუსლიან ფეხსაცმელს. გამოიყენეთ სპეციალური კომპრესიული წინდები. ზურგზე ძილის ნაცვლად მარცხენა გვერდზე დაიძინეთ. ნუ იბანავებთ ზედმეტად ცხელი წყლით და ნუ ჩაიცვამთ ძალიან მჭიდრო ტანსაცმელს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'წელის დატვირთვის შესამცირებლად ეცადეთ, გამართულად იჯდეთ და დიდხანს ფეხზე არ იდგეთ. საღამოს ფეხების გულის დონეზე ოდნავ მაღლა მოთავსებით 15 წუთით დასვენება შეშუპებასაც შეამცირებს და მოგადუნებთ. რადგან კალციუმზე თქვენი მოთხოვნილება გაიზარდა, რაციონში შეიტანეთ ხაჭო, ყველი ან ნუში. დღე საყვარელი ჰობით დაასრულეთ.') WHERE id = '1282e899-e7f6-47fc-b213-e93601a67a84';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'მიუხედავად იმისა, რომ ექიმის მიერ ჩატარებული გამოკვლევისას თქვენი ბავშვის ძვლებს ერთიან სტრუქტურად ხედავთ, ჩონჩხის სისტემა საკმაოდ რთული აგებულებისაა. ის შედგება ცოცხალი ძვლის უჯრედებისგან — ოსტეოციტებისგან — და უჯრედშორისი ნივთიერებისგან, რომელიც ამ უჯრედებს შორის სივრცეს ავსებს და თავად უჯრედების მიერ გამოიყოფა. ეს ნივთიერება შეიცავს ძვლის სიმტკიცის განმსაზღვრელ კალციუმის ფოსფატს, კალციუმის კარბონატს, მაგნიუმის ფოსფატს, ასევე მცირე რაოდენობით ისეთ მინერალებს, როგორებიცაა რკინა და ნატრიუმი.;;;
ყვითელი ძვლის ტვინი, კომპაქტური ძვალი, ღრუბლისებრი ძვალი, ძვლისაზრდელა, ხრტილი და სისხლძარღვები ძვლის შემადგენელი სტრუქტურებია. ხრტილი ძვლების შეერთების ადგილებში მდებარეობს. რბილი სტრუქტურის წყალობით ის ხელს უშლის ძვლების ერთმანეთზე ხახუნსა და ცვეთას. ის ასევე უზრუნველყოფს ძვლის სიგრძეში ზრდას. სისხლძარღვები კი სისხლს ძვლის უჯრედებამდე მიაწვდის.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი ძვლები მაგრდება! 🦴 ჩემი ჩონჩხი ყოველდღე უფრო მტკიცე ხდება. კალციუმი ჩემს ძვლებში გროვდება და მათ ამაგრებს. უკვე პატარა რეზინის კაცუნა აღარ ვარ. ჩემი ნეკნები, ხერხემალი, ფეხის ძვლები... ყველაფერი ნამდვილ ძვლად იქცევა. რძე, რომელსაც სვამ, და ყველი, რომელსაც მიირთმევ, ჩემამდე სამშენებლო მასალასავით აღწევს. გმადლობ, დედიკო!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'დიდი ხახვი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის განმავლობაში ზოგიერთი სახის ტკივილის არსებობა ნორმალურია. მათ შორისაა ფეხების ტკივილიც. ფეხების ტკივილის ყველაზე თვალსაჩინო ნიშანი შეშუპებაა. შეიძლება შეშუპდეს როგორც წვივები, ისე ტერფები. ტერფების შეშუპება ტკივილსა და დისკომფორტს იწვევს. შეშუპების შესამოწმებლად თითი კოჭის მიდამოზე უნდა დააჭიროთ. კალციუმისა და მაგნიუმის დეფიციტმა, წონის გადაჭარბებულმა მატებამ, უმოძრაობამ, გულისკენ სისხლის დაბრუნების გაძნელებამ და კალიუმის, მაგნიუმისა და კალციუმის დაბალმა დონემ შეიძლება ტკივილი გააძლიეროს. თუ ფეხების ტკივილი გაწუხებთ, შეძლებისდაგვარად უნდა დაასვენოთ ისინი. ღამის ძილისას გვერდზე წოლა გაცილებით შესაფერისი პოზაა. აკონტროლეთ წონის მატება. ძილისას ფეხების მაღლა მოთავსება შვებას მოგიტანთ. ცივი წყალი შეშუპებულ კუნთებს ამშვიდებს და სისხლძარღვების შევიწროებას უწყობს ხელს. ამიტომ ცივი შხაპი და ყინულის კომპრესი შეიძლება ეფექტური იყოს. ამასთანავე, ტკივილის შემსუბუქებაში მასაჟი და ვარჯიშიც დაგეხმარებათ. სხეულში შეშუპების შესამცირებლად არ დაგავიწყდეთ ბევრი სითხის მიღება.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ფეხის კრუნჩხვების თავიდან ასაცილებლად მიირთვით მაგნიუმით მდიდარი საკვები. ძილის წინ ფეხის კუნთების გაჭიმვა და თბილი შხაპის მიღება შეიძლება დაგეხმაროთ.') WHERE id = '79568d36-35e8-4a60-8ad2-b99e6d2f45e1';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ორსულობის მე-18 კვირაში სრულად ფუნქციონირებს პლაცენტა — ამ ეტაპზე დედასა და ბავშვს შორის არსებული უმნიშვნელოვანესი კავშირი. ის ბავშვის განვითარებისთვის საჭირო საკვებ ნივთიერებებსა და ჟანგბადს უშუალოდ თქვენი სისხლიდან იღებს და მას გადასცემს. პლაცენტას კიდევ ერთი ძალიან საინტერესო და კრიტიკულად მნიშვნელოვანი მოვალეობა აქვს — დამცავი ფუნქცია. ჩვეულებრივ, თქვენმა ორგანიზმმა შეიძლება ბავშვი "უცხო სხეულად" აღიქვას და შეუტიოს, თუმცა პლაცენტა ბარიერის როლს ასრულებს და ხელს უშლის თქვენი იმუნური უჯრედების მიერ ბავშვის დაზიანებას.;;;
ექიმის მიერ ჩატარებული გამოკვლევისას უკვე მკაფიოდ ხილული პლაცენტა მე-18 კვირაში თითქმის თქვენი ბავშვის ზომისაა. ამ პერიოდის შემდეგ ორივე განაგრძობს ზრდას, თუმცა ბავშვი პლაცენტაზე უფრო სწრაფად გაიზრდება.'), baby_message_ka = COALESCE(baby_message_ka, 'მე ვამთქნარებ და ვასლოკინებ! 🥱 ჩემი დიაფრაგმა ძალიან აქტიურად მუშაობს. ხშირად ვასლოკინებ. ეს შეიძლება უცნაურად მოგეჩვენოს, მაგრამ ჩემთვის ძალიან სასარგებლოა. ასე ფილტვებსა და სასუნთქ გზებს ვიწმენდ. როცა ვიღლები, ტკბილადაც ვამთქნარებ. შენც დაისვენე ჩემთან ერთად, კარგი?'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ტკბილი წიწაკა'), body_changes_ka = COALESCE(body_changes_ka, 'ეს კვირა ბევრი დედისთვის გარდამტეხია ბავშვის მოძრაობების შეგრძნების მხრივ. თუ ჯერ არ გიგრძნიათ, ყურადღებით იყავით — მუცელში შეიძლება მსუბუქი შეგრძნება გქონდეთ, თითქოს "გაზის ბუშტუკი" მოძრაობს ან "ფრთები ფარფატებს". თქვენი არტერიული წნევა შესაძლოა კვლავ დაბალი იყოს, რამაც შეიძლება სისუსტე გამოიწვიოს. მადა შესაძლოა პიკს აღწევდეს. თქვენი მეტაბოლიზმი აჩქარებულია და ორგანიზმი ბავშვისთვის დამატებით ენერგიას საჭიროებს. თუმცა ჭამის შემდეგ შეიძლება გულძმარვამ შეგაწუხოთ. ვინაიდან საშვილოსნო კუჭზე ზეწოლას ახდენს, დიდი ულუფების მიღება რთულდება.'), daily_tip_ka = COALESCE(daily_tip_ka, 'აკონტროლეთ არტერიული წნევა. თუ თავბრუსხვევა ხშირად გაწუხებთ, დღის განმავლობაში მიიღეთ ბევრი სითხე და შეგიძლიათ მცირე რაოდენობით მიირთვათ მარილიანი პროდუქტები (აირანი, მარილიანი კრეკერი), თუ ექიმს სხვა მითითება არ მოუცია.') WHERE id = '1343d008-0806-4770-8e2d-0452ed215751';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის სხეულში ცხიმოვანი შრის ჩამოყალიბება დაიწყო, რაც მისი ზრდის დამაჩქარებელი ერთ-ერთი უმნიშვნელოვანესი ფაქტორია. ცხიმები სამ ძირითად კლასად იყოფა: მარტივ, რთულ და წარმოებულ ცხიმებად.;;;
ცხიმის ყველაზე ცნობილი სახეობა — ქოლესტერინი — საკვებიდან მიიღება ან უჯრედებში სინთეზირდება. ამ პროცესში ყველაზე აქტიურ როლს ღვიძლი ასრულებს. ცხიმებს ორგანიზმში ძალიან მნიშვნელოვანი ფუნქციები აქვს: ისინი ენერგიის უდიდესი წყაროა, იცავს შინაგან ორგანოებს და სითბოს წარმოქმნით ორგანიზმს სიცივისგან იცავს.;;;
ცხიმები ასევე ხელს უწყობს ორგანიზმის მიერ A, D, E და K ვიტამინების შეწოვას. როდესაც თქვენი ბავშვის ცხიმოვანი შრის ჩამოყალიბება დასრულდება, ცხიმების 90% კანქვეშ დაგროვდება. დარჩენილი ნაწილი კი მუცლის ღრუში, კუნთოვან ბოჭკოებს შორის და ისეთი სასიცოცხლოდ მნიშვნელოვანი ორგანოების გარშემო განთავსდება, როგორიცაა თირკმელები, გული და ღვიძლი, რათა ისინი დაიცვას.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი თითები და თითის ანაბეჭდები! 🧬 დედიკო, ჩემი თითის ანაბეჭდები უკვე სრულად ჩამოყალიბებულია. ეს მოხაზულობები მთელი ჩემი ცხოვრების განმავლობაში არ შეიცვლება. მე უნიკალური ვარ! ხელებისა და ფეხების თავისუფლად მოძრაობაც უკვე შემიძლია. ხან ფეხებს გადავაჯვარედინებ და ისე ვზივარ, ხან კი "ვცურავ". ჩემთვის ეს ყველაზე მყუდრო ადგილია.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ტკბილი წიწაკა'), body_changes_ka = COALESCE(body_changes_ka, 'ნუ შეშფოთდებით, თუ გეჩვენებათ, რომ თქვენი მუცელი ერთ დღეს დიდია, მეორე დღეს კი — პატარა. იმ დღეებში, როდესაც მუცლის არე ჩვეულებრივზე დიდი გეჩვენებათ, მიზეზი შესაძლოა ნაწლავების მუშაობის შენელებასთან დაკავშირებული აირების დაგროვება ან შებერილობა იყოს. თუ ულტრაბგერითი გამოკვლევის (USM) მაჩვენებლები ორსულობის ვადას შეესაბამება, მუცლის ზომას მნიშვნელობა არ აქვს. ეს მთლიანად მუცლის კუნთების აგებულებას, სხეულის ანატომიურ თავისებურებებსა და ორსულობით გამოწვეულ ცვლილებებზე ორგანიზმის რეაქციას უკავშირდება.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ეცადეთ, დიდხანს ფეხზე არ იდგეთ, რადგან ამან შეიძლება წელის ტკივილი გააძლიეროს. თუ მჯდომარე სამუშაო გაქვთ, ყოველ საათში ერთხელ ადექით და 5 წუთის განმავლობაში გაიარეთ. თუ თვალების მსუბუქ სიმშრალეს გრძნობთ, ექიმთან კონსულტაციის შემდეგ შეგიძლიათ ხელოვნური ცრემლი გამოიყენოთ. თქვენი ბავშვი უკვე უფრო მკაფიოდ გრძნობს თქვენს მოძრაობებს, ამიტომ განაგრძეთ მასთან კავშირის დამყარება.') WHERE id = 'e537dc02-2a8f-44e4-8520-858b44bd2d69';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის გრძნობათა ორგანოები უკვე საკმაოდ მგრძნობიარეა. კვლევები აჩვენებს, რომ ბავშვს ჯერ კიდევ საშვილოსნოში ყოფნისას შეუძლია თქვენი ხმის ყველა სხვა ხმისგან გარჩევა. ბავშვები ქალის ხმებსა და მაღალ ტონებზე უფრო მეტად რეაგირებენ, ვიდრე მამაკაცის ხმებზე. ამის მიზეზი ისაა, რომ საშვილოსნოს კედელი სხვადასხვა სიხშირის ბგერით ტალღებს განსხვავებულად ატარებს; ამ ეტაპზე ბავშვს მაღალი ტონები უფრო მკაფიოდ ესმის. პირველი ხმები კი, რომლებიც თქვენს ბავშვს ესმის, თქვენი სხეულიდან მომდინარე გულისცემა, სისხლის მიმოქცევისა და ორგანოების მუშაობის ხმებია. გრძნობათა ორგანოების განვითარებასთან ერთად ბავშვი გარე ხმების აღქმასა და დამახსოვრებას იწყებს. საინტერესოა, რომ დაბადების შემდეგ მტვერსასრუტის, ფენის ან ჭურჭლის სარეცხი მანქანის ხმაზე მშვიდდება, რადგან ეს ხმები საშვილოსნოში არსებულ გარემოს ახსენებს. ეს ხმები, რომლებსაც "თეთრ ხმაურს" (white noise) უწოდებენ, განსაკუთრებით კოლიკის მქონე ბავშვების დასამშვიდებლად გამოყენებული ერთ-ერთი ყველაზე ეფექტური საშუალებაა.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი სქესი უკვე განსაზღვრულია! 🩷💙 თუ გოგო ვარ, ჩემი საშვილოსნო და ფალოპის მილები უკვე ჩამოყალიბებულია და თავის ადგილასაა. თუ ბიჭი ვარ, ჩემი სასქესო ორგანოები მკაფიოდ ჩანს. იცი, ვინ ვარ? თუ გინდა, რომ სიურპრიზად შეინახო? ნებისმიერ შემთხვევაში, მე შენი პატარა ვარ და ძალიან მიყვარხარ!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ტკბილი წიწაკა'), body_changes_ka = COALESCE(body_changes_ka, 'ახლა, როდესაც ორსულობის თითქმის ნახევარი გაიარეთ, თუ საჭიროზე მეტი წონა მოიმატეთ ან ფიქრობთ, რომ წონას სწრაფად იმატებთ, როგორც თქვენი, ისე ბავშვის ჯანმრთელობისთვის ყურადღება უნდა გამოიჩინოთ. ნორმალური წონის მქონე ქალებისთვის ორსულობისას ყოველდღიური კალორიული საჭიროება მხოლოდ 300 კკალ-ით იზრდება. ეს საშუალოდ 1900-დან 2500 კკალ-მდე შეადგენს. ეს მაჩვენებელი ყველა ქალისთვის განსხვავებულია, ხოლო საჭირო ზღვარზე მეტი კალორიის მიღება წონის არაჯანსაღ მატებას იწვევს. ორსულობის განმავლობაში წონის გასაკონტროლებლად ყოველთვის უმჯობესია მცირე ულუფებით და ხშირად კვება. ძირითად კვებებს შორის წახემსება დაგეხმარებათ, რომ ძირითადი კვებისას ზედმეტი არ მიირთვათ. რკინით მდიდარი საკვები ორსულობასთან დაკავშირებული სისუსტის შემცირებას უწყობს ხელს. ლობიოს, თევზისა და მჭლე ხორცის მიღება არა მხოლოდ წონის ჭარბ მატებას უშლის ხელს, არამედ ამცირებს ჰიპერტენზიისა და პრეეკლამფსიის რისკსაც.'), daily_tip_ka = COALESCE(daily_tip_ka, 'წელის ტკივილის შესამსუბუქებლად შეასრულეთ "მენჯის საათის" ვარჯიში. დაწექით ზურგზე და მენჯი წინ და უკან ამოძრავეთ. ეს წელის კუნთებს მოადუნებს. ასევე, ორსულებისთვის განკუთვნილი დამჭერი ქამრის ტარებამ შეიძლება წელზე დატვირთვა შეამციროს.') WHERE id = '10652607-2e60-42fd-8695-4db1781a35b4';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თუ თქვენი ბავშვი გოგოა, ამ ეტაპზე მის საკვერცხეებში კვერცხუჯრედების წარმოქმნა უკვე დაწყებულია. განვითარების ადრეულ პერიოდში როგორც მამრობით, ისე მდედრობით ემბრიონებს სასქესო სადინრების ორი წყვილი აქვთ. ბიჭებში „მეზონეფრული“ სადინრები მამაკაცის რეპროდუქციულ სისტემას აყალიბებს, ხოლო გოგოებში „პარამეზონეფრული“ სადინრები ქალის რეპროდუქციული სისტემის განვითარებას უზრუნველყოფს. სასქესო ორგანოების დიფერენცირებისას გოგო ბავშვებში ეს სადინრები საშვილოსნოდ და საშოდ (ვაგინად) გარდაიქმნება. საინტერესოა, რომ გოგო ბავშვის საკვერცხეებში დაბადებამდე 2 მილიონზე მეტი კვერცხუჯრედი წარმოიქმნება. ეს კვერცხუჯრედების ყველაზე დიდი რაოდენობაა, რომელიც მას მთელი ცხოვრების განმავლობაში ექნება.;;;
მოზარდობის ასაკამდე ეს რიცხვი დაახლოებით 400,000–500,000-მდე მცირდება. რეპროდუქციული პერიოდის დაწყების შემდეგ კი ყოველთვიურად დაახლოებით 1000 კვერცხუჯრედი იკარგება. ასაკის მატებასთან ერთად მცირდება არა მხოლოდ კვერცხუჯრედების რაოდენობა, არამედ იცვლება მათი ხარისხიც: მაგალითად, 30 წლის ქალში ყოველი 2-3 კვერცხუჯრედიდან ერთი ქრომოსომულად ნორმალურია, ხოლო 40 წლის ასაკში ეს მაჩვენებელი ყოველ 5-6 კვერცხუჯრედში ერთამდე მცირდება.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი ნერვული სისტემა ჩქარდება! ⚡ ჩემი ტვინიდან სხეულისკენ მიმავალი სიგნალები უკვე „სუპერსწრაფი“ გზით გადაეცემა. მიელინის შრის წყალობით მოძრაობების უკეთ მართვა შემიძლია. უკვე შემთხვევით კი არ ვმოძრაობ, არამედ მიზანმიმართულად ვეხები და ვბრუნდები. ჩემი ტვინი უზარმაზარი კომპიუტერივით პროგრამდება. შეგიძლიათ, ჩემით იამაყოთ!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ტკბილი წიწაკა'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის ისე დასრულება, რომ წონა საერთოდ არ მოიმატოთ ან მხოლოდ რამდენიმე კილოგრამი მოიმატოთ, არც რეალურია და არც სწორი მიზანი. თუ ორსულად ხართ, წონაც, რა თქმა უნდა, მოიმატებს. ორსულობის მეორე ტრიმესტრი, რომელშიც ახლა ხართ, ის პერიოდია, როდესაც თქვენი ბავშვი სწრაფ ზრდასა და განვითარებას იწყებს. ამიტომ შესამჩნევი წონის მატებაც სწორედ ამ პერიოდში იწყება. ბავშვის ზრდასთან ერთად იმატებს საკვებისა და ენერგიის რაოდენობა, რომელსაც ის თქვენგან იღებს, ამიტომ თქვენც მეტი კვება გჭირდებათ. შესაბამისად, ორსულობის ამ პერიოდში კვირაში დაახლოებით 500 გრამის მომატება ნორმად ითვლება.;;;
სოსისის, სალამისა და სუჯუკის მსგავსი გადამუშავებული ხორცპროდუქტების დამზადებისას გამოყენებულმა დანამატებმა, მათ შორის ნიტრიტებმა და ნიტრატებმა, შესაძლოა ბავშვის ჯანმრთელობას ზიანი მიაყენოს. ;;;
ნახშირწყლებით მდიდარი საკვები გულისრევას ამცირებს. თუმცა სახამებლის შემცველი პროდუქტები, როგორიცაა თეთრი ბრინჯი და მაკარონი, სისხლში შაქრის დონის მატებას იწვევს. ორსულობის პერიოდში საკმარისი ვიტამინების მისაღებად უაღრესად მნიშვნელოვანია ხილის მოხმარების გაზრდა.'), daily_tip_ka = COALESCE(daily_tip_ka, 'თუ მხედველობა მნიშვნელოვნად დაგიბინდათ ან თვალწინ „სინათლის გაელვებები“ შენიშნეთ, დაუყოვნებლივ მიმართეთ ექიმს. ეს შესაძლოა მაღალი არტერიული წნევის ნიშანი იყოს. მსუბუქი დაბინდვა კი ჩვეულებრივი მოვლენაა.') WHERE id = '29db8583-08d7-4065-8fa7-18665ece5422';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'მომდევნო ერთი თვის განმავლობაში თქვენი ბავშვის სხეული დაიწყებს დაფარვას განსაკუთრებული შრით, რომელსაც ვერნიქს კაზეოზა ეწოდება. ეს თეთრი, კრემისებრი ნივთიერება თქვენი ბავშვის პირველი დამცავი ფარია დედის საშვილოსნოში და მას პირველ დაბანამდე იცავს.;;;
კვლევები აჩვენებს, რომ ვერნიქსი იმუნიტეტის ხელშემწყობ დაახლოებით 40 სხვადასხვა ცილას შეიცავს. საინტერესოა, რომ ამ ცილების ნახევარი ბუნებაში, ვერნიქსის გარდა, სხვაგან არსად გვხვდება. ამ უნიკალურ ნივთიერებებს მიკრობების განადგურების უნარი აქვს და ბავშვი ინფექციებისგან საიმედოდ იცავს.;;;
ვერნიქსის შრე თქვენი ბავშვისთვის ერთდროულად ბუნებრივი დამატენიანებლისა და ტემპერატურის მარეგულირებლის როლს ასრულებს. ის ხელს უშლის ბავშვის სხეულიდან სითხის დაკარგვას, ხელს უწყობს კანის ახალი უჯრედების წარმოქმნას და თავისი სრიალა სტრუქტურის წყალობით მშობიარობის პროცესს ამარტივებს.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემს ტვინში სინათლეები ინთება! 🧠 დედიკო, ჩემი ტვინი ახლა უზარმაზარი კომპიუტერივით მუშაობს. მხედველობის, სმენის, გემოს, ყნოსვისა და შეხებისთვის სპეციალური ცენტრები იქმნება. მე უბრალოდ კი არ ვიზრდები, არამედ სამყაროს აღსაქმელად ვემზადები. როცა თქვენს ხმას ვისმენ, ჩემი ტვინის „სმენის ცენტრი“ აქტიურდება. ჩვენი კავშირი უკვე მეცნიერულ დონეზეა!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'პომიდორი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის დროს კანი უფრო მგრძნობიარეა და მზის სხივების ზემოქმედებას მეტად განიცდის. ჰიპოფიზიდან გამოყოფილი მელანოციტების მასტიმულირებელი ჰორმონის დონის მატება, რომელიც კანის ფერის განმსაზღვრელ, მელანინის გამომყოფ უჯრედებზე მოქმედებს, კანს გამუქებისადმი განსაკუთრებით მგრძნობიარეს ხდის.;;;
მზის სხივების გამო ორსულობისთვის დამახასიათებელი ლაქების გაჩენა ან უკვე არსებული ლაქების გამუქება საკმაოდ ხშირია. გარდა ამისა, მზეზე დიდხანს ყოფნამ შესაძლოა გამოიწვიოს როგორც სხეულის ტემპერატურის გადაჭარბებული მატება, ისე ორგანიზმში სითხის შემცირება. ორივე მდგომარეობამ შეიძლება ორსულობაზე უარყოფითად იმოქმედოს. ყველა ამ მიზეზის გამო ორსულობისას მზეზე დიდხანს ყოფნა რეკომენდებული არ არის.'), daily_tip_ka = COALESCE(daily_tip_ka, 'წელის ტკივილის შესამცირებლად მაღალქუსლიან ფეხსაცმელზე სრულად თქვით უარი. ჯდომისას წელის უკან პატარა ბალიში მოათავსეთ. მუცლის შუა ნაწილის კუნთები ზედმეტად არ დაძაბოთ, საწოლიდან ადგომისას კი ჯერ გვერდზე გადაბრუნდით და შემდეგ წამოდექით.') WHERE id = 'bc3702e9-c9f0-4b15-a3b9-8dd5c0a6dd34';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენს ბავშვს უკვე სიზმრების ნახვა შეუძლია! განვითარებადი ტვინის წყალობით თქვენს ბავშვს უკვე შეუძლია REM ძილის ფაზაში გადასვლა. REM ძილი ძილის ის ნაწილია, რომლის დროსაც ტვინში სიზმრები ფორმირდება. ის ძილის მე-4 ფაზაში გვხვდება და ძილის საერთო ხანგრძლივობის საშუალოდ 15-20%-ს შეადგენს. ეს ჩაძინებიდან 30-90 წუთის შემდეგ ხდება.;;;
ძილს 4 სხვადასხვა ფაზა აქვს. პირველ ფაზაში შესაძლოა ბოლომდე ვერ ჩაგეძინოთ და სიმაღლიდან ვარდნის შეგრძნება გაგიჩნდეთ. მე-2 ფაზაში სხეული ნამდვილი ძილისთვის ემზადება. გულისცემის სიხშირე და სხეულის ტემპერატურა კლებას იწყებს. მე-3 და მე-4 ფაზები ღრმა ძილის ეტაპებია და სწორედ ამ დროს შეიძლება გამოვლინდეს ძილში სიარული. ღრმა ძილად წოდებული ამ ფაზების განმავლობაში სხეული აღდგება, ქსოვილები ხორცდება, აღარ საჭირო უჯრედებს ორგანიზმი იშორებს და იმუნური სისტემა არასაჭირო ნივთიერებებისგან თავისუფლდება. ბავშვები ძილის ამ ფაზებში იზრდებიან და ვითარდებიან.;;;
როდესაც ტვინი REM ძილის ფაზაშია, სუნთქვა ჩქარდება, თვალები კი შემთხვევით და სწრაფ მოძრაობას იწყებს. ამის წყალობით სიზმრები თითქმის რეალურივით შთამბეჭდავი ხდება. მთავარი კი ისაა, რომ ამ ფაზაში ტვინი ისეთივე აქტიურია, როგორც სიფხიზლის დროს. ჯერ კიდევ დედის საშვილოსნოდან მოყოლებული, ახალშობილი ბავშვები დროის დიდ ნაწილს REM ძილში ატარებენ. ეს ეხმარება მათ, განვითარების ყველაზე მნიშვნელოვან პერიოდში მიღებული გამოცდილება უკეთ გააერთიანონ. REM ძილი ბავშვების ძილის ციკლის დაახლოებით 50%-ს შეადგენს. ზრდასთან ერთად ეს ფაზა თანდათან მოკლდება, ასაკის მატებასთან ერთად კი მისი წილი სწრაფად მცირდება.'), baby_message_ka = COALESCE(baby_message_ka, 'მე თქვენ გიცავთ! 🥚 თუ გოგო ვარ, ჩემს პატარა საკვერცხეებში უკვე 6 მილიონი კვერცხუჯრედია! ეს ნიშნავს, რომ თქვენი მომავალი შვილიშვილები უკვე ახლა ჩემში არიან. თუ ბიჭი ვარ, ჩემი სასქესო ორგანოები ვითარდება. შთამომავლობა გრძელდება, დედიკო. თქვენ ისტორიას ქმნით.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'პომიდორი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის პერიოდში თქვენი ფიზიკური და ფსიქიკური ჯანმრთელობის შესანარჩუნებლად ვიტამინების სწორად და შესაბამისი დოზებით მიღებას დიდი მნიშვნელობა აქვს. ვიტამინების არასაკმარისმა მიღებამ შესაძლოა გარკვეული პრობლემები გამოიწვიოს, რადგან ისინი ორგანიზმის ყველა ორგანოსა და სისტემაზე მოქმედებს. ვიტამინები ბუნებრივ საკვებში არსებული მარეგულირებელი და ორგანიზმის გამძლეობის გამაძლიერებელი ნივთიერებებია, რომლებიც უჯრედების განახლებასა და ენერგიის გამომუშავებას უწყობს ხელს. ორგანიზმს ისინი ყოველდღიურად განსაზღვრული რაოდენობით სჭირდება, დეფიციტის შემთხვევაში კი დამატებების სახით უნდა მიიღოთ.;;;
ორსულობის პერიოდში ვიტამინების არასაკმარისმა მიღებამ შესაძლოა გამოიწვიოს მხედველობის პრობლემები, მუდმივი დაღლილობის შეგრძნება, ენისა და კანის ნახეთქები, ანემია, გონებრივი გადაღლა და დეპრესიული სიმპტომები, კანზე სისხლჩაქცევებისა და ლაქების გაჩენა, ძვლების ტკივილი და კუნთოვანი მასის დაკარგვა.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ძილის დროს ეცადეთ, აუცილებლად მარცხენა გვერდზე დაწვეთ; ეს მაქსიმალურად ზრდის სისხლის მიწოდებას როგორც ბავშვისთვის, ისე საშვილოსნოსთვის. წელის ტკივილის შესამსუბუქებლად მსუბუქი გაჭიმვის ვარჯიშები შეასრულეთ. მომატებული მადა ხილითა და ბოსტნეულით დააბალანსეთ. თქვენს ბავშვს უკვე უფრო მკაფიოდ ესმის თქვენი, ამიტომ დღეს მშვიდ ტემპში მოასმენინეთ მუსიკა, რომელიც მას მოსწონს.') WHERE id = '695bdf70-cf7b-4ed0-9ff8-c4418720fc60';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის პირველი მოძრაობა, რომელსაც იგრძნობთ, შეიძლება სლოკინი იყოს! სლოკინი უეცარი ჩასუნთქვაა, რომელიც მუცლისა და გულმკერდის ღრუების გამყოფი დიაფრაგმის კუნთის მოულოდნელი შეკუმშვისა და ხმის იოგებს შორის არსებული ნაპრალის დახურვის შედეგად წარმოიქმნება. მართალია, ახალშობილებში ის ხშირად გვხვდება, მაგრამ სინამდვილეში ეს პროცესი ჯერ კიდევ დედის მუცელში იწყება.;;;
თქვენი ბავშვი სლოკინებს, რადგან საშვილოსნოში ამნიონურ სითხეს ყლაპავს. მიუხედავად იმისა, რომ ეს ზოგიერთ დედას აშფოთებს, სინამდვილეში ბავშვის განვითარებისთვის ძალიან სასარგებლოა. სლოკინის წყალობით ბავშვის წოვის რეფლექსი ძლიერდება, რაც დაბადებისთანავე კვებაში ეხმარება.;;;
ამნიონური სითხის ყლაპვისას დიაფრაგმის კუნთის შეკუმშვა და მოდუნება ბავშვის ფილტვებს ავარჯიშებს. წოვის, ყლაპვისა და სლოკინის დროს ფილტვებში მოხვედრილი სითხე მათ სუნთქვისთვის მომზადებასა და განვითარებაში ეხმარება. მშობიარობის მოახლოებასთან ერთად ბავშვი უფრო მეტ სითხეს ყლაპავს, ამიტომ სლოკინის ეპიზოდებიც შეიძლება გახშირდეს.'), baby_message_ka = COALESCE(baby_message_ka, 'გამარჯობა, დედიკო! მე მანგოს ზომის ვარ. ჩემი ხელები და ფეხები უკვე სხეულის პროპორციულია. მე პატარა ადამიანი ვარ! ახლა უკვე უფრო ძლიერად შემიძლია დაგარტყა ფეხები. მზად იყავი!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'მანგო'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის პერიოდში კვებას ძალიან დიდი ყურადღება უნდა მიაქციოთ. თუთია ერთ-ერთი ძირითადი საკვები ელემენტია, რომელიც აუცილებლად უნდა შედიოდეს თქვენს კვების რაციონში. ის ერთ-ერთი უმნიშვნელოვანესი მინერალია, რომელიც ცილებისა და უჯრედის მემბრანის სტრუქტურაში მონაწილეობს. ამასთანავე, თუთია გენებით განსაზღვრული ცილების წარმოქმნის პროცესშიც არის ჩართული. ორგანიზმში თუთიის საკმარისი რაოდენობა ასევე 100-ზე მეტი ფერმენტის ჯანსაღ და გამართულ ფუნქციონირებას უზრუნველყოფს.;;;
ორსულობის პერიოდში ორგანიზმის მოთხოვნილება თუთიაზე იზრდება. ამ დროს თუთიის საკმარისი რაოდენობით მიღება მნიშვნელოვან როლს ასრულებს დნმ-ისა და ცილების სტრუქტურის ჩამოყალიბებაში. ამიტომ ორსულობისას, როდესაც უჯრედები განსაკუთრებით სწრაფად წარმოიქმნება, თუთიის მიღება ძალიან მნიშვნელოვანია. არაორსული ქალის თუთიის დღიური მოთხოვნილება 8 mq-ია, ორსული ქალისთვის კი ეს მაჩვენებელი 11 mq-მდე იზრდება. მეძუძურმა დედამ დღეში 12 mq თუთია უნდა მიიღოს. თუთია ყველაზე დიდი რაოდენობით ხორცსა და ზღვის პროდუქტებში გვხვდება.'), daily_tip_ka = COALESCE(daily_tip_ka, 'გზის ნახევრამდე მოსვლა პატარა სიხარულით აღნიშნეთ! ზურგის ტკივილის შესამცირებლად ეცადეთ, გამართულად იჯდეთ და მძიმე საგნები არ ასწიოთ. თუ ფეხები შეშუპებული გაქვთ, დღის ბოლოს ოდნავ მაღლა შემოაწყვეთ და დაისვენეთ. განაგრძეთ ბევრი წყლის სმა და რაციონში ბოჭკოვანი საკვების ჩართვა. ხვალ დიდი „ეკვატორის“ დღე გველოდება!') WHERE id = 'c0a11fee-73af-4684-98a2-4425bd830ba9';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'გილოცავთ! ორსულობის ნახევარი უკვე გაიარეთ.;;;
თუ თქვენი ბავშვი გოგოა, მის საკვერცხეებში კვერცხუჯრედების წარმოქმნა სწრაფად გრძელდება. ბიჭებში კი სათესლე ჯირკვლები ყალიბდება და საკუთარი ადგილისკენ დაშვებას განაგრძობს. სათესლე ჯირკვლები მამაკაცის რეპროდუქციული სისტემის ძირითადი ნაწილია და სპერმატოზოიდების ჯანსაღი განვითარებისთვის სხეულის ტემპერატურაზე დაახლოებით 2 გრადუსით უფრო გრილი გარემო სჭირდება. სწორედ ამიტომ მდებარეობს სათესლე პარკი სხეულის გარეთ — დაბალი ტემპერატურა სპერმის უჯრედების დაშლას უშლის ხელს.;;;
სათესლე ჯირკვლებს რამდენიმე მნიშვნელოვანი ფუნქცია აქვს: ტესტოსტერონის ჰორმონის გამოყოფა, მამაკაცისთვის დამახასიათებელი ფიზიკური ნიშნების განვითარება და სპერმის წარმოქმნა. განვითარების სრულად დასრულების შემდეგ ამ სისტემას დღეში 200 მილიონამდე სპერმატოზოიდის წარმოქმნა შეუძლია.'), baby_message_ka = COALESCE(baby_message_ka, 'თმა მეზრდება! 💇‍♂️ ჩემს თავის კანზე ნამდვილი თმა იწყებს ამოსვლას. ჯერ ძალიან თხელი და უფერულია, მაგრამ დაბადებისას შეიძლება თმიანი ბავშვი ვიყო. როცა გულძმარვა გაწუხებს, ბებიები ხომ ამბობენ, „ბავშვს თმა ამოსდისო“ — იქნებ მართლაც მართლები არიან?'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'მანგო'), body_changes_ka = COALESCE(body_changes_ka, 'ამ ეტაპზე თქვენი საშვილოსნო ორსულობამდელ მდებარეობასთან შედარებით სამჯერ უფრო მაღლაა. ამ კვირიდან მშობიარობამდე ის ყოველ კვირას დაახლოებით 1 sm-ით ზემოთ აიწევს. საშვილოსნოს ზემოთ გადაადგილება შინაგანი ორგანოების მდებარეობას შეცვლის. ერთ-ერთი ასეთი ორგანოა კუჭი: მისი სარქველების მოდუნების შედეგად მჟავე pH-ის მქონე შიგთავსი შეიძლება საყლაპავში გადავიდეს და გულძმარვა გამოიწვიოს.;;;
გულძმარვა და მჟავიანობა ორსულობისას ხშირად გვხვდება. მის თავიდან ასაცილებლად მოერიდეთ ისეთ პროდუქტებს, როგორებიცაა პომიდორი, ხახვი, ნიორი, გაზიანი და მჟავე სასმელები, სიგარეტი, ნაყინი, სიროფიანი ტკბილეული, შოკოლადი, შემწვარი კერძები, ტომატის პასტა, ცხარე საკვები, მწნილი, ფორთოხალი და ცხარე წიწაკა. გულძმარვის დროს პირველ რიგში შეგიძლიათ თბილი რძე სცადოთ. თბილი რძე გულძმარვას ამცირებს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ორსულობის ნახევრის გასავლელად საკუთარ თავს სასიამოვნო დღე აჩუქეთ! ზურგის ტკივილის თავიდან ასაცილებლად ეცადეთ, გამართულად იჯდეთ და დასვენებისას აუცილებლად მარცხენა გვერდზე დაწვეთ. განსაკუთრებული ყურადღება მიაქციეთ რკინის მიღებას, რადგან ბავშვის სისხლის წარმოქმნისთვის მასზე მოთხოვნილება იზრდება. ყოველდღიურად 20-30-წუთიანი მსუბუქი სეირნობა მხნეობის შენარჩუნებაში დაგეხმარებათ.') WHERE id = 'ac85f07b-25b5-4dda-969a-4a8dfc9a2528';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'მართალია, ამ კვირებში თქვენი ბავშვის სხეული მთლიანად ლანუგოთია დაფარული, მაგრამ წარბებისა და თავის არეში თმა უფრო ხშირია და უკვე მკაფიოდ შესამჩნევი ხდება. წარბები მხოლოდ გარეგნობისთვის არ არის — ისინი თვალებს ზემოდან ჩამოსული ოფლის წვეთებისგან, წყლისა და სხვა მავნე ნივთიერებებისგანაც იცავს. საინტერესოა, რომ წარბების სიგრძე გოგო და ბიჭ ბავშვებში ერთნაირია (დაახლოებით 10 mm), თუმცა მათი სისქე განსხვავდება. თქვენი ბავშვის წარბების არეში საშუალოდ 200-300 ღერი წარმოიქმნება. თუ თქვენი ბავშვი ბიჭია, მისი წარბების სტრუქტურა მომავალში ამოსული ულვაშისა და წვერის სტრუქტურის მსგავსი იქნება. წარბისა და წამწამის ღერები სხეულზე ყველაზე გამძლეა — ისინი ყველაზე გვიან ჭაღარავდება და, თუ ჯანმრთელობის განსაკუთრებული პრობლემა არ არსებობს, ყველაზე ნაკლებად ცვივა.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი თირკმელები შესანიშნავად მუშაობს! 💧 მე ამნიონურ სითხეს ვყლაპავ, ჩემი თირკმელები კი მას ფილტრავს და სუფთა შარდის სახით უკან აბრუნებს. ეს სითხე მიცავს, სითბოს მინარჩუნებს და მოძრაობაში მეხმარება. ჩემს აუზს თავად ვასუფთავებ. თქვენც ბევრი წყალი დალიეთ, რომ ჩემი წყალი სუფთა და უხვი იყოს.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'მანგო'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის პერიოდში თქვენი მენჯის ჩვეულებრივ მყარი სახსრები ფართოვდება, რათა მშობიარობისას ბავშვმა თავისუფლად გაიაროს. ამის გამო ამ პერიოდში შეიძლება წონასწორობის გარკვეული დარღვევები იგრძნოთ. მენჯის გამოსასვლელი ოვალური ფორმისაა — წინა-უკანა მიმართულებით გრძელი, ხოლო მარჯვნიდან მარცხნივ მოკლე. ამ გზის ყველაზე ვიწრო ნაწილი შუა მონაკვეთია, სადაც რამდენიმე ძვლოვანი შვერილია. ბავშვის თავსა და მენჯის ძვლის ოვალურ ნაწილს შორის მხოლოდ 20 sm-მდე სივრცეა. დედის მუცელში ყოფნისას ბავშვს თავი წინ აქვს დახრილი ისე, რომ ნიკაპი მკერდს ეხება. ამის წყალობით თავი მენჯში უმცირესი შესაძლო დიამეტრით შედის. არც ბავშვის თავი და არც მენჯის ძვალი არ არის სრულიად მყარი და უცვლელი. ორსულობის განმავლობაში ორივე ისე იცვლება, რომ ერთმანეთს მოერგოს. ბავშვის თავის ქალის შემადგენელ ძვლებს ერთმანეთზე გადაადგილება შეუძლია და ისინი ზრდასრული ადამიანის ძვლებზე უფრო რბილია. ამის წყალობით ბავშვს სამშობიარო არხში გავლა შეუძლია.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ფეხების დაღლილობისა და შეშუპების შესამცირებლად დღის განმავლობაში ხშირად შეიცვალეთ მდგომარეობა და დიდხანს უმოძრაოდ ნუ დარჩებით. რკინის მიღების გასაზრდელად რაციონში დაამატეთ წითელი ხორცი, ოსპი და მუქი მწვანე ბოსტნეული. თქვენს ბავშვს უკვე ყველაფერი ესმის, ამიტომ დღეს შეგიძლიათ თქვენი საყვარელი წიგნი ხმამაღლა წაუკითხოთ.') WHERE id = '34d9ab3e-6f7e-4354-93cc-e6f91180c7df';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამ ეტაპზე თქვენი ბავშვი დროის 90%-ს ძილში ატარებს. სანაყოფე წყლებში მოტივტივე ბავშვი მთელი დღის განმავლობაში თქვენი მოძრაობების რიტმში ირწევა და მშვიდად იძინებს. ღამით კი, როცა თქვენ აღარ მოძრაობთ და სითხეც მშვიდდება, ის გაღვიძებას იწყებს. მიიჩნევა, რომ ახალშობილების ღამით ხშირი გაღვიძების ერთ-ერთი მიზეზი სწორედ ეს ჩვევაა.;;;
ვინაიდან საშვილოსნოს კედელი დედის მუცელსა და გარე სამყაროს შორის დღისა და ღამის განსხვავებას ფარავს, ბავშვს ამ რიტმთან შესაგუებლად დაბადებიდან 1-2 თვე შეიძლება დასჭირდეს. ხოლო ყველაზე მნიშვნელოვანი მიზეზი, რის გამოც თქვენი ბავშვი თითქმის მთელ დღეს ძილში ატარებს, ზრდის ჰორმონია.;;;
ეს ჰორმონი ჰიპოფიზის წინა წილის უჯრედებში წარმოიქმნება, ცილოვანი სტრუქტურა აქვს და ორგანიზმში სიმაღლეში ზრდასა და ქსოვილების განვითარებას უზრუნველყოფს. ყველაზე მნიშვნელოვანი ისაა, რომ ეს ჰორმონი უმთავრესად ბავშვის ძილის დროს სინთეზდება. ანუ, რაც უფრო მეტხანს სძინავს თქვენს ბავშვს, მით უფრო ჯანსაღად და სწრაფად იზრდება.'), baby_message_ka = COALESCE(baby_message_ka, 'მე ძილის რეჟიმი მაქვს! 🌙 დედიკო, მთელი დღე ფხიზლად არ ვარ. მეც მაქვს ძილისა და სიფხიზლის პერიოდები. ჩვეულებრივ, როცა დადიხარ ან მოძრაობ, ვირწევი და ვიძინებ. როცა შენ დაწოლა და დასვენება გინდა, მე ვიღვიძებ და დისკოთეკას ვაწყობ. ჩვენი რეჟიმები ცოტათი განსხვავდება, მაპატიე!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'მანგო'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობამდე თითოეული სარძევე ჯირკვლის წონა საშუალოდ 230-250 გრამია. ორსულობისას რძის სადინრების გაფართოების შედეგად სარძევე ჯირკვლების მოცულობა იმატებს, ისინი იზრდება და მგრძნობიარე ხდება. შესაძლოა სიმძიმის შეგრძნებაც გაჩნდეს. მარჯვენა და მარცხენა სარძევე ჯირკვლების ზომებს შორის შეიძლება განსხვავება წარმოიქმნას. მათ გარშემო კანის ქვეშ სისხლძარღვები შესაძლოა უფრო შესამჩნევი გახდეს. ამის გამო სარძევე ჯირკვლები ჩვეულებრივზე ორჯერ მძიმე შეიძლება გახდეს. საშვილოსნო, რომლის წონაც ჩვეულებრივ დაახლოებით 60 გრამია, ამ ეტაპზე დაახლოებით 300 გრამს იწონის. მშობიარობის დღისთვის კი მისი წონა 1000 გრამს მიაღწევს. სანაყოფე წყლების წონა, რომლებშიც თქვენი ბავშვი იმყოფება, ამ ეტაპზე დაახლოებით 350-400 გრამია, ორსულობის ბოლოს კი 800 გრამამდე გაიზრდება. ამ კვირიდან პლაცენტა ზომითა და წონით თითქმის თქვენი ბავშვის ტოლია, ორსულობის ბოლოს კი დაახლოებით 600-650 გრამს მიაღწევს. გარდა ამისა, ქსოვილთაშორისი სითხის რაოდენობა ორსულობამდელ პერიოდთან შედარებით 1500-2000 გრამით გაიზრდება. მშობიარობის შემდგომ რძის წარმოსაქმნელად ორგანიზმის მიერ დაგროვებული ცხიმის წონა კი ამ ეტაპზე 400-500 გრამს უახლოვდება, ორსულობის ბოლოს კი 3500-4000 გრამს მიაღწევს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ხელებზე სიწითლისა და სიცხის შეგრძნების შესამცირებლად ისინი გრილი წყლით დაიბანეთ. ქიმიურ საწმენდ საშუალებებს ნუ შეეხებით. სახის მზისგან დასაცავად აუცილებლად გამოიყენეთ ქუდი და SPF კრემი.') WHERE id = 'd0d5f1e7-e726-4e8b-9248-bacff687b744';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის თავის კანზე სხვა ღინღლისგან განსხვავებული, ნამდვილი თმის ძირები განვითარებას იწყებს. თმა გამძლე ცილისგან — კერატინისგან წარმოიქმნება. მის შიდა სტრუქტურაში არსებული განსაკუთრებული ბმები თმის სიმტკიცეს უზრუნველყოფს. თუ თმის დამცავი გარე შრე დაზიანდა, თმა მტვრევადი ხდება.;;;
თმის ძირი კანის ქვედა შრეში მდებარე ფოლიკულში წარმოიქმნება, შემდეგ იზრდება, კანის ზედა შრეს გაივლის და გარეთ გამოდის. თქვენი ბავშვის თმის ფერს თქვენსა და თქვენი პარტნიორის დნმ-ში არსებული პიგმენტი მელანინი განსაზღვრავს. ამ პიგმენტის რაოდენობის მიხედვით თმა ღია ან მუქი ფერისაა.;;;
თმის ტიპს კი დისულფიდური ბმების სიმჭიდროვე განსაზღვრავს; ხვეულ თმაში ეს ბმები უფრო ინტენსიურია. მიუხედავად იმისა, რომ თმის ღერი ძალიან თხელი ჩანს, სინამდვილეში ის რამდენიმე შრისა და მრავალი ბოჭკოსგან შედგება. თმის ბოლოების გაყოფაც სწორედ ამ ბოჭკოვანი სტრუქტურების ერთმანეთისგან განცალკევების შედეგად ხდება.'), baby_message_ka = COALESCE(baby_message_ka, 'მე ვერნიქსით ვარ დაფარული! 🧼 ჩემს სხეულზე არსებული თეთრი, კრემის მსგავსი ნივთიერება ახლა უფრო სქელია. ის წყალში ზედმეტად დალბობისგან მიცავს. დაბადებისას კი სამშობიარო არხში გასრიალებასა და გამოსვლაშიც დამეხმარება. ბუნებამ ყველაფერზე იზრუნა, ასე არ არის? ყველა სახის დაცვა მაქვს, რომ შენთან ჯანმრთელი მოვიდე.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'მანგო'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის პერიოდში ქალების ორგანიზმში მიმდინარე ჰორმონულმა ცვლილებებმა შესაძლოა ცხვირის ლორწოვანი გარსის შეშუპება და გაჭედვა გამოიწვიოს. ამის შედეგად ცხვირიდან გამონადენის რაოდენობა იმატებს. სინუსიტის მსგავსად, ამ მდგომარეობამ სინუსების ღრუების დახშობის გამო შესაძლოა ცხვირის გაჭედვა გამოიწვიოს. ეს ხვრინვის ხელშემწყობი ერთ-ერთი პრობლემაა. ამასთანავე, ბავშვის ზრდის დაწყებასთან ერთად წონაც სწრაფად იმატებს. გარდა ამისა, კვების რეჟიმის შეცვლის გამო შესაძლოა ჭარბი წონაც მოიმატოთ. ეს ჭარბი წონა სხეულის სხვადასხვა უბანზე ნაწილდება. ცხიმის სახით დაგროვების გამო სხეულის სხვადასხვა ნაწილში ქსოვილების მოცულობა იზრდება. ქალები, რომლებიც ორსულობისას ჭარბ წონას იმატებენ, ხვრინვისკენ უფრო მეტად არიან მიდრეკილნი. ამიტომ საჭიროა ზომების მიღება, რათა ორსულობის ნორმალური მიმდინარეობისთვის რეკომენდებულზე მეტი წონა არ მოიმატოთ. კვების რეჟიმი ჯანსაღად უნდა დაგეგმოთ და წონის მატება აკონტროლოთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'გულძმარვის თავიდან ასაცილებლად ჭამისთანავე ნუ დაწვებით და უპირატესობა მიანიჭეთ მცირე ულუფებით ხშირ კვებას. წელის ტკივილის დროს ჯდომისას ზურგს უკან პატარა ბალიში მოათავსეთ და გამართულად იჯექით. არ დაგავიწყდეთ რკინის მიღება, რათა სისხლზე როგორც თქვენი, ისე ბავშვის ორგანიზმის მოთხოვნილება სრულად დაკმაყოფილდეს. ამ საღამოს საკუთარ თავს ცოტა დრო დაუთმეთ და მშვიდ მუსიკას მოუსმინეთ.') WHERE id = '481d4a59-0854-49d1-ad3d-0f418a6738b5';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამ კვირაში თქვენი ბავშვის წონა დაახლოებით 300 გრამს უახლოვდება. სრულიად ბუნებრივია, თუ ექიმის გამოკვლევების მიხედვით ბავშვის განვითარება კალენდარულ ვადას ცოტათი უსწრებს ან ჩამორჩება. 2 კვირის სხვაობა ნორმად მიიჩნევა.;;;
განვითარების პირველ თვეებში ბავშვების 60%-ის განვითარება შეიძლება ბოლო მენსტრუაციის თარიღით განსაზღვრულ ვადას უსწრებდეს. მეორე ტრიმესტრის ბოლოს ეს სხვაობა, ჩვეულებრივ, მცირდება და ზომები ორსულობის ვადას შეესაბამება. თუ სხვაობა 2 კვირას გადააჭარბებს, ექიმმა შესაძლოა პერინატოლოგთან გამოკვლევაზე ან დამატებით კვლევებზე გადაგამისამართოთ, რათა მდგომარეობას უფრო ყურადღებით დააკვირდეს.;;;
თუ თქვენი ბავშვი თავის ვადას ცოტათი „ჩამორჩება“, ეს განვითარების შეფერხებას ავტომატურად არ ნიშნავს. ულტრაბგერითი აპარატით გაზომვები ძალიან მგრძნობიარეა; შედეგზე გავლენას ახდენს ბავშვის მდებარეობა, ექიმის მიერ გაზომვის მეთოდი და აპარატის ტექნიკური დონე. რამდენიმე წუთის შუალედით ჩატარებულმა გაზომვებმაც კი შეიძლება მცირე სხვაობა აჩვენოს, ამიტომ 2 კვირამდე განსხვავების შემთხვევაში შეშფოთების საფუძველი არ არსებობს.'), baby_message_ka = COALESCE(baby_message_ka, 'მზად ვართ მნიშვნელოვანი გამოკვლევისთვის? 🩺 უახლოეს დღეებში „ანატომიური სკანირება“ (დოპლერი) ჩატარდება. ექიმი ჩემს თითოეულ ორგანოს — გულს, ტვინსა და თითებს — სათითაოდ შეამოწმებს. მე ხელს დაგიქნევ! თუ გაგვიმართლებს, ჩემს სქესსაც ზუსტად დაინახავ. (თუ არ დავმალე).'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'მანგო'), body_changes_ka = COALESCE(body_changes_ka, 'ამ კვირიდან სარძევე ჯირკვლებზე ყავისფერი უბანი თანდათან გაიზრდება. ამ არეს არეოლა ეწოდება და მან შესაძლოა სარძევე ჯირკვლის თითქმის ნახევარი მოიცვას. სარძევე ჯირკვლის ზრდასთან ერთად დვრილისა და არეოლის მდებარეობაც იცვლება. ეს ნორმალური მოვლენაა და შესაძლოა მშობიარობიდან მე-12 თვემდე გაგრძელდეს. არეოლა დვრილის გარშემო არსებული მუქი ფერის რგოლია. მისი ფორმა, ფერი და ზომა ყველა ადამიანში განსხვავებულია და კანის ფერზეცაა დამოკიდებული. პირველი ორსულობის შემდეგ არეოლის ფერი უფრო მუქი ხდება და ასეთად რჩება. არეოლის შიგნით მდებარეობს პატარა ცხიმოვანი ჯირკვლები, რომლებსაც მონტგომერის ჯირკვლები ეწოდება.'), daily_tip_ka = COALESCE(daily_tip_ka, 'წელის დატვირთვის შესამცირებლად ეცადეთ გამართულად იჯდეთ და დიდხანს ფეხზე ნუ იდგებით. საღამოს ფეხები გულის დონეზე ოდნავ მაღლა მოათავსეთ და 15 წუთის განმავლობაში დაისვენეთ — ეს შეშუპებასაც შეამცირებს და სისხლძარღვებსაც განტვირთავს. განსაკუთრებული ყურადღება მიაქციეთ რკინისა და კალციუმის მიღებას. დღე დაასრულეთ თქვენი საყვარელი წიგნიდან რამდენიმე გვერდის ბავშვისთვის ხმამაღლა წაკითხვით.') WHERE id = '6ad08d05-7381-4d47-abac-7c50836b90a0';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენს ბავშვს უკვე შეუძლია თქვენი ხმის გაგონება!;;;
ორსულობის მე-20 კვირისთვის ბავშვის ყურის ჩამოყალიბება მეტწილად დასრულებულია. თუმცა მისი განვითარება 24-ე კვირამდე გრძელდება. თქვენს ბავშვს, რომელსაც გარე ხმების აღქმა შიდა ყურის მეშვეობით შეუძლია, საუბრისას უკვე ესმის თქვენი ხმა.;;;
რამდენიმე კვირაში ბავშვის სმენა იმდენად მგრძნობიარე გახდება თქვენი ხმის, ემოციური მდგომარეობისა და ქცევის მიმართ, რომ მისი გულისცემისა და მოძრაობების შეცვლასაც გამოიწვევს. როდესაც მშვიდად საუბრობთ, ბავშვიც მშვიდდება და გულისცემა უნელდება. განსაკუთრებით 24 კვირის შემდეგ ძლიერმა ხმაურმა შეიძლება ბავშვი შეაკრთოს და ზოგჯერ ამის შემდეგ სლოკინიც დაეწყოს.;;;
ამ პერიოდში დაბალი ტონალობის, არცთუ ხმამაღალი მუსიკის მოსმენა ბავშვს ამშვიდებს. შეგიძლიათ მუსიკა ჩვეულებრივად ჩართოთ ან მუცლისთვის განკუთვნილი სპეციალური ყურსასმენები გამოიყენოთ.'), baby_message_ka = COALESCE(baby_message_ka, 'წარბები და წამწამები მაქვს! 👁️ დედიკო, ჩემი სახე უკვე მთლიანად ადამიანისას ჰგავს. თვალების ზემოთ თხელი წარბები გამეზარდა, ქუთუთოებზე კი — გრძელი წამწამები. ახლა უფრო ლამაზი (ან სიმპათიური) ვარ. თვალების დახამხამებისთვის ვემზადები, თუმცა მათ გახსნამდე ჯერ კიდევ რამდენიმე კვირაა დარჩენილი. ჩემზე ოცნებობ? მე შენზე ვოცნებობ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'სტაფილო'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის განმავლობაში შესაძლოა კანის გარკვეული პრობლემები შეგექმნათ. მაგალითად, კანის მომატებულმა ცხიმიანობამ შეიძლება აკნე გამოიწვიოს. თუ ასეთი პრობლემა გაქვთ, კანი დღეში ორჯერ ბუნებრივი გამწმენდი საშუალებით გაიწმინდეთ. ყურადღება მიაქციეთ, რომ თქვენ მიერ გამოყენებული კრემები უცხიმო იყოს. არ მიიღოთ აკნეს სამკურნალო პერორალური პრეპარატები. ამ მედიკამენტებმა ბავშვებში შეიძლება მძიმე ანომალიები გამოიწვიოს. ბავშვის განვითარებისთვის, ექიმთან კონსულტაციის შემდეგ, შეგიძლიათ ომეგას შემცველი დანამატების მიღება დაიწყოთ. ომეგა მიეკუთვნება აუცილებელ ცხიმებს, რომლებიც ორგანიზმმა უნდა მიიღოს. ომეგა ცხიმოვანი მჟავების ერთ-ერთი სახეობაა და განსაკუთრებით მნიშვნელოვანია ბავშვის ტვინისა და თვალების განვითარებისთვის. კვლევები აჩვენებს, რომ ომეგა ნაადრევი მშობიარობის რისკს ამცირებს და ხელს უწყობს ბავშვის უფრო მაღალი წონით დაბადებას.'), daily_tip_ka = COALESCE(daily_tip_ka, 'მაცივარი ჯანსაღი საკვებით შეავსეთ. თუ ხელთ გექნებათ გარეცხილი ხილი, ბოსტნეული, იოგურტი ან ხაჭო, ნაკლებად გაგიჩნდებათ მავნე „წასახემსებლების“ მიღების სურვილი.') WHERE id = '11b2d6de-75e4-4639-b4fc-0a1a64a49ebf';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენს ბავშვს უკვე ეწყება ძილის ინდივიდუალური რეჟიმის ჩამოყალიბება, თუმცა ის ჯერ სრულად რეგულარული არ არის. ბუნებრივია, რომ ექიმთან გამოკვლევისას ბავშვი ხშირად მძინარე ნახოთ. დღის განმავლობაში თქვენი მოძრაობა ამნიონურ სითხეს არწევს, რაც ბავშვისთვის იავნანასავით მოქმედებს, ამშვიდებს და აძინებს.;;;
ბავშვი ყველაზე აქტიური ღამითაა, როცა თქვენ დასასვენებლად წვებით, არტერიული წნევა გიქვეითდებათ და გარემო მშვიდდება. პატარას, რომელსაც დღის განმავლობაში კარგად ეძინა, ღამის სიჩუმეში „თამაში“ სიამოვნებს. ამ პერიოდში ძილის რეჟიმის ჩამოყალიბება საფუძველს ქმნის როგორც საშვილოსნოში განვითარებისთვის, ისე დაბადების შემდეგ ძილის ჯანსაღი ჩვევებისთვის.;;;
კვლევები აჩვენებს, რომ ორსულობის დროს მავნე ჩვევები (ალკოჰოლი, ნარკოტიკული ნივთიერებები და სხვ.) ბავშვის ძილის ხარისხს მკვეთრად აუარესებს. ასეთ შემთხვევებში ბავშვებს „არაეფექტური ძილის“ პრობლემა ექმნებათ; ისინი ჯანმრთელ ბავშვებთან შედარებით 5-ჯერ უფრო ხშირად იღვიძებენ და მათი ძილის საერთო ხანგრძლივობაც მნიშვნელოვნად ნაკლებია.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი სისხლი წითლდება! 🩸 ძვლებში არსებული ძვლის ტვინი ახლა სისხლის უჯრედებს წარმოქმნის. ეს ძალიან მნიშვნელოვანია ჩემი მომავალი იმუნიტეტისთვის და ჟანგბადის გადასატანად. ჩემი სისხლის ჯგუფი უკვე განსაზღვრულია. შენსას ემთხვევა თუ მამასას? ამას ჩემი დაბადების შემდეგ გაიგებ. ყოველდღე უფრო დამოუკიდებელი ვხდები.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'სტაფილო'), body_changes_ka = COALESCE(body_changes_ka, 'თუ მაჯებსა და თითებში მუდმივ დაბუჟებას გრძნობთ, ეს ჩივილი შესაძლოა კარპალური გვირაბის სინდრომს უკავშირდებოდეს. კარპალური გვირაბის სინდრომი ვითარდება მაშინ, როდესაც მედიანური ნერვი მაჯის გვირაბში გავლისას იჭყლიტება. საწყის ეტაპზე ის დაბუჟებით ვლინდება. ორსულობისას მაჯებსა და ფეხებში ხშირად განვითარებული შეშუპება მაჯის ნერვებზე ზეწოლას ახდენს. ეს იწვევს მაჯებისა და თითების დაბუჟებას, ჩხვლეტის შეგრძნებასა და ტკივილს. თუ ნერვის მოჭერის ეს სინდრომი მხოლოდ ორსულობას უკავშირდება, მშობიარობის შემდეგ მოკლე ხანში, მკურნალობის გარეშე, თავისთავად გაივლის.'), daily_tip_ka = COALESCE(daily_tip_ka, 'მუცლის ქავილის შესამცირებლად, შხაპის შემდეგ კანი არ შეიმშრალოთ და ნესტიან კანზე ბუნებრივი ზეთებით მასაჟი გაიკეთეთ. ფეხებზე დატვირთვის შესამცირებლად ჯდომისას ისინი ოდნავ მაღლა შემოაწყვეთ. უპირატესობა მიანიჭეთ მაგნიუმით მდიდარ საკვებს — ეს ფეხის კრუნჩხვების თავიდან აცილებაში დაგეხმარებათ.') WHERE id = '374d8324-b6d6-473c-83ac-7fb12f83f44c';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამ კვირაში, როცა ლანუგოს ღინღლი კვლავ ფარავს თქვენი ბავშვის სხეულს, სქესის მიუხედავად, მას ძუძუსთავები უყალიბდება. ძუძუსთავების ძირითადი ფუნქცია ძუძუთი კვების უზრუნველყოფაა. საინტერესოა, რომ ძუძუსთავზე არა ერთი ხვრელი, არამედ რძის გამომყოფი 20-მდე პატარა სადინარი (ხვრელი) მდებარეობს. ამას უფრო ნათლად მშობიარობის შემდეგ დაინახავთ, როდესაც რძე ჩაგიდგებათ.;;;
ჯერ კიდევ ემბრიონულ ეტაპზე, ანუ მანამდე, სანამ სასქესო ორგანოები განსხვავებას დაიწყებს, ძუძუსთავების წარმომქმნელი უჯრედები უკვე გაერთიანებულია. სასქესო მიდამოსთვის დამახასიათებელი თავისებურებების ჩამოყალიბება კი მე-8 კვირამდე ვერ იწყება. როდესაც ბიჭებში მამაკაცის სასქესო სისტემის წარმომქმნელი SRY გენი აქტიურდება, ძუძუსთავები უკვე ჩამოყალიბებულია, ამიტომ ეს გენი მათ განვითარებას სრულად ვეღარ აჩერებს. სწორედ ამიტომ აქვთ ძუძუსთავები ორივე სქესის წარმომადგენლებს.'), baby_message_ka = COALESCE(baby_message_ka, '🥕 ერთი დიდი სტაფილოს ზომის ვარ! ახლა უფრო მეტხანს მძინავს და უფრო ძლიერად ვურტყამ ფეხებს. ჩემი ძილის რეჟიმი შეიძლება შენს რეჟიმს არ დაემთხვეს. როცა შენ გძინავს, მე ვიღვიძებ, რადგან როცა აღარ მოძრაობ, მგონია, რომ ჩემი „საქანელა“ გაჩერდა, და მეღვიძება.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'სტაფილო'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის მეორე ტრიმესტრში, რომელშიც ახლა იმყოფებით, დროდადრო შესაძლოა შეშუპება გაგივითარდეთ. შეშუპება უმეტესად სისხლის მიმოქცევის დარღვევის შედეგია. მშობიარობისთვის მოსამზადებლად გადიდებული საშვილოსნო და მენჯის მიდამო ფეხების სისხლძარღვებზე ზეწოლას ახდენს. ეს ზეწოლა ანელებს სისხლის მიმოქცევას და შეშუპებას იწვევს. შეშუპების კიდევ ერთი მიზეზი კვების ჩვევებია. დადგენილია, რომ ადამიანების მნიშვნელოვანი ნაწილი, ვისაც ძლიერი შეშუპება აწუხებს, საკმარის ცილას არ იღებს. საჭირო ცილა შეგიძლიათ მიიღოთ ხორცისა და მსგავსი საკვებისგან, თუმცა შესაძლოა საკმარისი იყოს დღეში სულ მცირე სამი ულუფა რძის ან რძის პროდუქტის მიღებაც. კვებასთან დაკავშირებული კიდევ ერთი მნიშვნელოვანი საკითხი მარილის სათანადო რაოდენობით მიღებაა. ბევრს მიაჩნია, რომ ჭარბი მარილი ორგანიზმში წყლის შეკავებას და, შესაბამისად, შეშუპებას იწვევს. მართალია, თუმცა მარილის არასაკმარისმა მიღებამაც შეიძლება შეშუპება გამოიწვიოს. მთავარია, მარილი საკმარისი რაოდენობით მიიღოთ და ყოველთვის დაბალანსებულად და ჯანსაღად იკვებოთ. თუ შეშუპება გაწუხებთ, უნდა წამოწვეთ, ფეხები მაღლა შემოაწყოთ, ბევრი სითხე მიიღოთ, ხანმოკლე გასეირნებები მოიწყოთ, ჩაიცვათ ტანსაცმელი, რომელიც სხეულზე არ მოგიჭერთ, და ყურადღება მიაქციოთ კვებას.'), daily_tip_ka = COALESCE(daily_tip_ka, 'წელზე დატვირთვის შესამცირებლად ეცადეთ გამართული იჯდეთ და დიდხანს ფეხზე არ იდგეთ. საღამოს ფეხების გულის დონეზე ოდნავ მაღლა აწევით 15 წუთით დასვენება შეშუპებასაც შეამცირებს და მოდუნებაშიც დაგეხმარებათ. რადგან კალციუმის საჭიროება გაზრდილია, რაციონში შეიტანეთ ხაჭო, ყველი ან ნუში. დღე თქვენი საყვარელი მუსიკით დაასრულეთ.') WHERE id = '4291c964-97b5-4aa4-a48e-b3cb8e0fe5cb';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის საჭმლის მომნელებელმა სისტემამ უკვე განვითარების მნიშვნელოვან ეტაპს მიაღწია. მისი კუჭი სრულად მზადაა გამოიმუშაოს რძის მოსანელებლად განკუთვნილი სპეციალური ნივთიერება — ფერმენტი რენინი (ქიმოზინი).;;;
რძის მონელება მის შემადგენლობაში არსებული ცილის, კაზეინის, შედედებით იწყება. დაბადების შემდეგ, როდესაც ბავშვი რძეს წოვს, კუჭში არსებული ფერმენტი რენინი მას მაშინვე ადედებს. შემდეგ მოქმედებას იწყებს ფერმენტი პეპსინი, რომელიც ამ ნივთიერებას ამინომჟავებად შლის, რათა ბავშვის უჯრედებმა მათი ათვისება შეძლონ. რენინის ზემოქმედების შემდეგ რძე იოგურტის ან ყველის მსგავს არაერთგვაროვან სტრუქტურას იძენს. პეპსინი კი ამ ცილებს შლის და ხელს უწყობს მათი სისხლის მეშვეობით სხეულის ყველა ნაწილში გადატანას.;;;
დაბადების შემდეგ ბავშვები ზოგჯერ ჭარბ რძეს ამოანთხევენ. თუ ბავშვის პირიდან ამოსული რძე უკვე თხევადი კი არა, უფრო მკვრივი და სქელია, ეს იმის ნიშანია, რომ კუჭში არსებული ფერმენტები რძის სწრაფად და ჯანსაღად მონელებას შეუდგნენ.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემს ხმას ვამზადებ! 🎤 ჩემი ხორხი და სახმო იოგები უკვე სრულად მზადაა. ახლა მხოლოდ ჰაერი მაკლია. როგორც კი დავიბადები, პირველივე ჩასუნთქვასთან ერთად გეტყვით: "გამარჯობა, დედა!" (ანუ "უააა!"). წარმოგიდგენიათ ეს წამი? ყოველდღე სწორედ ამ მომენტისთვის ვვარჯიშობ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ბანანი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობისას განსაკუთრებული სიფრთხილეა საჭირო იმის განსაზღვრისას, თუ რომელი მცენარეული ჩაის დალევა შეიძლება. ექიმის თანხმობის მიღების შემდეგ მელისას და ჯანჯაფილის ჩაის მიღება შეგიძლიათ. ცნობილია, რომ დამამშვიდებელი მოქმედების მქონე მელისას ჩაის ორსულობის პერიოდში გამოყენება მავნე ზემოქმედებას არ იწვევს. განსაკუთრებით ქალებს, რომლებსაც ჩაძინება უჭირთ ან უძილობა აწუხებთ, შეუძლიათ ძილის წინ ერთი ფინჯანი მელისას ჩაი დალიონ. ანტიოქსიდანტებით მდიდარი ჯანჯაფილი სასარგებლოა ჩაის სახითაც. პირველ ტრიმესტრში, როდესაც გულისრევა და ღებინება ხშირია, ჯანჯაფილის ჩაი ამ ჩივილების შემცირებას შეიძლება დაეხმაროს. ჟოლოს ფოთლებისგან მომზადებულმა ჩაიმ კუნთებზე სხვადასხვა გავლენა შეიძლება მოახდინოს. ჟოლოს ჩაის, რომელსაც მშობიარობის ტკივილების შემსუბუქება შეუძლია, ორსულობის ბოლო კვირებში მიღება შესაძლოა სარისკო იყოს. მწვანე ჩაი ანტიოქსიდანტების მაღალი შემცველობის გამო საკმაოდ სასარგებლოა. ის ორგანიზმიდან ტოქსინების გამოდევნასაც უწყობს ხელს. თუმცა, რადგან ფოლიუმის მჟავის შეწოვას ამცირებს, ბავშვზე უარყოფითად შეიძლება იმოქმედოს. ამიტომ ორსულობისას მწვანე ჩაის მიღება, როგორც წესი, რეკომენდებული არ არის. ორსულობისას სალბის ჩაის დალევამ შესაძლოა შეკუმშვები გამოიწვიოს ან სისხლდენის რისკი გაზარდოს. ამიტომ არ უნდა მიიღოთ მცენარეული ჩაი, რომელიც სისხლის გათხელებას უწყობს ხელს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'შეკრულობის თავიდან ასაცილებლად მიირთვით ბოჭკოებით მდიდარი საკვები და დალიეთ ბევრი წყალი. დიდხანს ნუ იდგებით და ნუ იჯდებით ერთ მდგომარეობაში. კეგელის ვარჯიშები მენჯის ფსკერის მიდამოში სისხლის მიმოქცევას აუმჯობესებს და ბუასილის დროსაც შეიძლება დაგეხმაროთ.') WHERE id = '0c65c176-54fc-4e82-af61-c7b6cff2d77a';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ორსულთა დაახლოებით 70% ამ კვირიდან ბავშვის პირველი მოძრაობების შეგრძნებას იწყებს. ეს თქვენს ბავშვთან პირველი ფიზიკური კონტაქტია და ორსულობის ერთ-ერთი ყველაზე ამაღელვებელი მომენტია.;;;
თქვენი ბავშვი ჯერ იმდენად დიდი არ არის, რომ მისი მოძრაობები ყოველდღე, რეგულარულად იგრძნოთ. სრულიად ბუნებრივია, ერთ დღეს აქტივობა იგრძნოთ, მომდევნო რამდენიმე დღის განმავლობაში კი — ვერაფერი. მოძრაობები, ჩვეულებრივ, 20-იანი კვირების შუა პერიოდის შემდეგ ხდება რეგულარული. თუ ჯერ არცერთი მოძრაობა არ გიგრძნიათ, ნუ ინერვიულებთ — 24-ე კვირამდე ეს ნორმად ითვლება. ეს შეიძლება მუცლის იოგების დაჭიმულობას, ბავშვის მდებარეობას ან მუცლის მიდამოში ცხიმოვან ქსოვილს უკავშირდებოდეს.;;;
საშვილოსნო ზრდასთან ერთად ნაწლავებს გვერდებისკენ სწევს. ამ ზეწოლით გამოწვეული ნაწლავების მოძრაობა, აირები ან საჭმლის მონელების პროცესები ზოგჯერ ბავშვის მოძრაობებში შეიძლება აგერიოთ. დროთა განმავლობაში ამ ორი განსხვავებული შეგრძნების ერთმანეთისგან გარჩევას ისწავლით.'), baby_message_ka = COALESCE(baby_message_ka, 'გზის ნახევარი გავიარეთ! 🏁 გილოცავთ, დედიკო! 40-კვირიანი მარათონის ზუსტად ნახევარი (50%) დავასრულეთ. უკვე ბანანის ზომის ვარ! დაუჯერებელია, არა? შეხედეთ, აქამდე რამდენად გავიზარდე. თქვენი მუცელი უკვე ჭიპის დონემდეა გაზრდილი. ფინიშისკენ მივიწევთ!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ბანანი'), body_changes_ka = COALESCE(body_changes_ka, 'მინერალებს დიდი მნიშვნელობა აქვს უჯრედების დაცვისა და კბილების, ძვლებისა და კანის ჯანსაღი სტრუქტურისთვის. გარდა ამისა, ისინი მნიშვნელოვან როლს ასრულებს არტერიული წნევის, გულის რიტმისა და კუნთების ფუნქციების რეგულირებაში, ორგანიზმში სითხის ბალანსის შენარჩუნებაში, რეპროდუქციასა და მრავალ სხვა პროცესში. ამ მინერალებს შორის ორსულობის მთელი პერიოდის განმავლობაში ყველაზე მნიშვნელოვანი კალციუმია. ორგანიზმში კალციუმის რაოდენობა მხოლოდ ძვლებისთვის არ არის მნიშვნელოვანი — ის ორგანიზმში მიმდინარე ყველა პროცესშიც მონაწილეობს. ამასთანავე, კალციუმი ჯანმრთელი და ძლიერი კბილებისთვის აუცილებელი მინერალია და კუნთების მუშაობაშიც დიდ როლს ასრულებს. ის განსაკუთრებით საჭიროა ორგანიზმის მიერ რკინის გამოსაყენებლად და საკვებიდან მიღებული ნივთიერებების უჯრედის მემბრანაში გასატარებლად.'), daily_tip_ka = COALESCE(daily_tip_ka, 'გზის ნახევრის გავლა იმით აღნიშნეთ, რაც გიყვართ! წელის ტკივილის შესამცირებლად ეცადეთ, ფეხზე ფეხგადადებული არ იჯდეთ. ღამით აუცილებლად მარცხენა გვერდზე დაწექით და მუხლებს შორის ბალიში მოათავსეთ. განაგრძეთ რკინით მდიდარი საკვების (ოსპი, წითელი ხორცი, ისპანახი) მიღება, რათა როგორც თქვენი, ისე ბავშვის სისხლის წარმოქმნის საჭიროება სრულად დაკმაყოფილდეს.') WHERE id = 'ce6d14e2-2cef-47b0-bf61-c80d97194d99';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის წონა 250–280 გრამია. რა სწრაფად იზრდება, არა? წარმოუდგენელი სისწრაფით მზარდი ბავშვის სხეულისთვის მეტი სისხლის მისაწოდებლად მისი გული წამითაც არ ჩერდება და მუშაობას განაგრძობს. ამის წყალობით გულის კუნთები კვლავ ვითარდება და ძლიერდება.;;;
გულის კუნთის შეკუმშვების მეშვეობით ჟანგბადი და საკვები ნივთიერებები ბავშვის სხეულის თითოეულ უჯრედამდე აღწევს. ეს მოძრაობები სიცოცხლისთვის აუცილებელი ფუნქციების შესრულებას უზრუნველყოფს.'), baby_message_ka = COALESCE(baby_message_ka, 'მე "საჭმელს" ვჭამ! 🍽️ დედიკო, ჩემი საჭმლის მომნელებელი სისტემა უკვე ამუშავდა. სანაყოფე სითხეს ვყლაპავ, ჩემი ნაწლავები კი მისგან შაქარსა და წყალს იწოვს. ამ სითხის გემო ყოველდღე იცვლება — გუშინ თქვენ მიერ მირთმეული ნივრიანი კერძის გემოც ვიგრძენი! ჩემს ნაწლავებში პირველი განავალი, რომელსაც "მეკონიუმი" ეწოდება, გროვდება. ნუ ღელავთ, მას ჩემი საფენისთვის ვინახავ და აქ არაფერს ვსვრი!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'სტაფილო'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის პერიოდში საკუთარი ჯანმრთელობისთვის რკინის მიღებას განსაკუთრებული ყურადღება მიაქციეთ. ორსულობისას რკინაზე თქვენი მოთხოვნილება თითქმის ორჯერ იზრდება. ამ პერიოდში ორგანიზმში, არაორსულ მდგომარეობასთან შედარებით, 50%-ით მეტი სისხლია. სისხლის უჯრედების წარმოქმნისთვის კი რკინა აუცილებელია.;;;
რკინას ასევე მნიშვნელოვანი როლი აქვს იმ სტრუქტურების ფუნქციონირებაში, რომლებიც კუნთებსა და შემაერთებელ ქსოვილებს ჟანგბადით ამარაგებს, აგრეთვე იმუნური სისტემის მხარდაჭერაში. სისხლში რკინის დონეზე თქვენ მიერ მიღებული სხვა ნივთიერებებიც მოქმედებს. კალციუმმა, ასევე კოფეინის შემცველმა სასმელებმა, მაგალითად ჩაიმ და ყავამ, შეიძლება ორგანიზმის მიერ რკინის ათვისებას ხელი შეუშალოს.;;;
C ვიტამინი კი რკინის შეწოვას უწყობს ხელს. ამიტომ რკინით მდიდარი საკვების მიღების შემდეგ ერთი ჭიქა ხილის წვენის დალევა ან ხილის მირთმევა შეიძლება სასარგებლო იყოს.;;;
განსაკუთრებით მეორე და მესამე ტრიმესტრებში რკინა სასიცოცხლოდ მნიშვნელოვანია თქვენი ბავშვის განვითარებისა და პლაცენტისთვის. სისხლისთვის საჭირო რკინის მიღება დაბალანსებული კვებით შეგიძლიათ. ანემიის რისკის შესამცირებლად ნუ უგულებელყოფთ რეგულარულ გამოკვლევებს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'თუ ფეხების შეშუპებას გრძნობთ, დღის განმავლობაში ხშირად შეიცვალეთ პოზიცია, საღამოს კი ფეხები ბალიშზე შემოაწყვეთ და დაისვენეთ. კანის ელასტიკურობის შესანარჩუნებლად დალიეთ ბევრი წყალი და გამოიყენეთ დამატენიანებელი ზეთები. ყურადღება მიაქციეთ კალციუმისა და მაგნიუმის მიღებას, რათა ფეხის კრუნჩხვები თავიდან აიცილოთ.') WHERE id = '2f4c880c-7bdd-4dec-acbd-cd0e6c8859e0';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'უკვე შესაძლებელია თქვენი ბავშვის გულისცემის სტეტოსკოპით მოსმენა! ექიმთან ვიზიტისას ამ მოწყობილობით შესაძლებელია თქვენი ბავშვის გულისცემის შემოწმება. თქვენი და ბავშვის გულისცემის ერთმანეთისგან გარჩევა საკმაოდ მარტივია: ბავშვის გული თქვენსაზე დაახლოებით 2-ჯერ უფრო სწრაფად ცემს.;;;
თქვენი ბავშვის სწრაფ განვითარებაში ერთ-ერთი მთავარი როლი ჭიპლარს (umbilical cord) ეკისრება. მთელი ორსულობის განმავლობაში ის ბავშვს სასიცოცხლოდ მნიშვნელოვან საკვებ ნივთიერებებსა და ჟანგბადს აწვდის. ჭიპლარის სიგრძე საშუალოდ 50-55 სანტიმეტრია და მას სპირალური ფორმა აქვს.'), baby_message_ka = COALESCE(baby_message_ka, 'მე შენს სტრესს ვგრძნობ. 😟 დედიკო, როცა დაძაბული ხარ, შენს ორგანიზმში წარმოქმნილი ჰორმონები (კორტიზოლი) ჩემამდეც აღწევს და მეც ვღელავ. გული უფრო სწრაფად მიცემს. მაგრამ როცა მშვიდად და ბედნიერად ხარ, მეც „ბედნიერების ჰორმონებით“ ვიკვებები. გთხოვ, ნუ ინერვიულებ. ჩვენ ერთად ვართ, ყველაფერი კარგად იქნება.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'სტაფილო'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის დროს შესაძლოა ჰემოროი განვითარდეს ან უკვე არსებული ჰემოროით გამოწვეული ჩივილები გაძლიერდეს.;;;
ზედაპირთან ახლოს მდებარე სისხლძარღვები ფართოვდება, რაც ვარიკოზისა და ჰემოროის განვითარებას უწყობს ხელს. გარდა ამისა, ამ პერიოდში მომატებულმა ჰორმონმა პროგესტერონმა შესაძლოა სისხლძარღვების გარშემო არსებული გლუვი კუნთები მოადუნოს და სისხლძარღვების ადვილად გაფართოება გამოიწვიოს. ჰემოროის პირველი ნიშანი, ჩვეულებრივ, დეფეკაციის (განავლის გამოყოფის) დროს შემჩნეული სისხლის ლაქებია. სისხლდენის გარდა, სხვა სიმპტომები შეიძლება იყოს ანუსის მიდამოში სისავსის შეგრძნება, ტუალეტის შემდეგ გაწმენდისას ხელით შესაგრძნობი შეშუპება და დეფეკაციისას დაწყებული ხანგრძლივი ტკივილი. ჰემოროის თავიდან ასაცილებლად ყველაზე მნიშვნელოვანია შეკრულობის პრევენცია. უპირატესობა მიანიჭეთ ბოჭკოვანი და ცელულოზით მდიდარი საკვების მიღებას, გაზარდეთ წყლის, ბოსტნეულისა და ხილის მოხმარება, რათა ნაწლავთა მოქმედება თავისუფლად, დაძაბვის გარეშე მოხდეს. თუ ამ გზებით პრობლემა არ მოგვარდება, შეიძლება ექიმის მიერ დანიშნული შესაბამისი განავლის დამარბილებელი საშუალების გამოყენება.'), daily_tip_ka = COALESCE(daily_tip_ka, 'თუ ფეხებზე მსუბუქ შეშუპებას გრძნობთ, დღის ბოლოს ოდნავ მაღლა შემოაწყვეთ და დაასვენეთ. წელის ტკივილის შესამცირებლად ჩაიცვით დაბალქუსლიანი და კომფორტული ფეხსაცმელი. რადგან კალციუმზე მოთხოვნილება გაზრდილია, რაციონში რძის პროდუქტებისა და მწვანე ბოსტნეულის რაოდენობა გაზარდეთ. რას იტყვით, დღეს თქვენს ბავშვს იავნანა რომ უმღეროთ?') WHERE id = '39505edc-cdd2-40ac-b9cb-aa04fd0c51af';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის კუჭქვეშა ჯირკვალმა უკვე დაიწყო ინსულინისა და გლუკაგონის რეგულარულად გამომუშავება. ინსულინი ბავშვის კუჭქვეშა ჯირკვალში, ლანგერჰანსის კუნძულების ბეტა უჯრედების მიერ გამოიყოფა. როდესაც სისხლში საჭიროზე მეტი შაქარია, ინსულინი ხელს უწყობს მის ღვიძლში გლიკოგენის სახით დაგროვებას. ამგვარად, ის სისხლში შაქრის დონეს ამცირებს.;;;
ინსულინი ასევე ხელს უწყობს სისხლში არსებული გლუკოზის, საჭიროებისას კი ამინომჟავებისა და თავისუფალი ცხიმოვანი მჟავების უჯრედებში შეღწევას, რითაც უჯრედები საჭირო დროს აუცილებელ ენერგიას იღებენ. როდესაც ინსულინი საკმარისი რაოდენობით არ გამოიყოფა, სისხლში შაქრის დონე იმატებს და შარდთან ერთად გამოიყოფა. ეს მდგომარეობა იწვევს დიაბეტს, რომელიც ხალხში შაქრიანი დიაბეტის სახელითაა ცნობილი. გლუკაგონი კი კუჭქვეშა ჯირკვლის ალფა უჯრედების მიერ გამოიყოფა. ის ინსულინის სრულიად საპირისპირო ფუნქციას ასრულებს. საჭიროებისას ღვიძლსა და კუნთებში დაგროვილი გლიკოგენის სისხლში გადასვლას უწყობს ხელს და სისხლში შაქრის დონეს ზრდის. ეს წონასწორობა აუცილებელია, რათა ხანგრძლივი შიმშილის დროს ორგანიზმი ენერგიის გარეშე არ დარჩეს.'), baby_message_ka = COALESCE(baby_message_ka, 'მე გემოების მცოდნე გურმანი ვარ! 😋 ჩემს ენაზე გემოვნების რეცეპტორები სრულად მუშაობს. როცა ცხარე წიწაკას ჭამ, მე სლოკინი მეწყება, ხოლო როცა შოკოლადს მიირთმევ, უფრო აქტიური ვხდები. მეცნიერები ამბობენ, რომ რაც უფრო მრავალფეროვან საკვებს მიირთმევ ახლა, მით უფრო ნაკლებად პრეტენზიული ვიქნები საკვების მიმართ, როცა გავიზრდები. მოდი, ერთად ვიკვებოთ ჯანსაღად!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'სტაფილო'), body_changes_ka = COALESCE(body_changes_ka, 'თუ ამ პერიოდში გაქვთ ისეთი ჩივილები, როგორიცაა თმის ცვენა, ფრჩხილების მტვრევა, სისუსტე, მადის დაქვეითება, თავის ტკივილი, თავბრუსხვევა, ქოშინი, გულის ფრიალი, სწრაფად დაღლა და გაღიზიანება, სისხლის ანალიზები უნდა ჩაიტაროთ. ორსულობის დროს ანემია, როგორც წესი, მეორე ტრიმესტრში აღინიშნება, როდესაც ბავშვი მისთვის საჭირო რკინას დედის ორგანიზმიდან იღებს. ორსულობა ანემიის რისკს ზრდის, ხოლო დედის ანემია არა მხოლოდ დედის ჯანმრთელობას უქმნის საფრთხეს, არამედ ბავშვზეც უარყოფითად მოქმედებს. ყოველდღიურ რაციონში რკინის მიღების გასაზრდელად უნდა მოერიდოთ კოფეინის მაღალი შემცველობის მქონე სითხეებს, როგორიცაა ჩაი, ყავა და კოლას ტიპის სასმელები, რადგან ისინი რკინის შეწოვას აფერხებს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'წელის ტკივილის შესამცირებლად ჯდომისას აუცილებლად დაიდეთ ზურგს უკან ბალიში და ეცადეთ, სწორად იჯდეთ. კანის ქავილის დროს შხაპის შემდეგ გამოიყენეთ ბუნებრივი დამატენიანებლები. არ დაგავიწყდეთ ბევრი წყლის დალევა — ეს მნიშვნელოვანია როგორც თქვენთვის, ასევე სანაყოფე წყლების განახლებისთვის. დღე თქვენი საყვარელი ჰობით დაასრულეთ.') WHERE id = 'f309c326-d1e8-4059-8ac7-ab4a84a92059';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვისთვის სასიცოცხლოდ მნიშვნელოვანი ამნიონური სითხე, რომელშიც ის იმყოფება, ამ ეტაპზე ყოველ სამ საათში ერთხელ განახლდება. ამიტომ თქვენი ორგანიზმის გაუწყლოების თავიდან აცილება ბავშვის ჯანმრთელობისთვის უაღრესად მნიშვნელოვანია. ეს სითხე 99%-ით წყლისგან შედგება და ასევე შეიცავს არაორგანულ მარილებს, ორგანულ ნივთიერებებსა და ბავშვის ორგანიზმიდან გამოყოფილ ნივთიერებებს.;;;
ამასთან, სასუნთქი სისტემის გასავითარებლად თქვენი ბავშვი ყოველდღე თავისი წონის მეოთხედის ოდენობის სითხეს ფილტვებში შეისუნთქავს და ამგვარად ვარჯიშობს. იგივე ეხება საჭმლის მომნელებელ სისტემასაც. ამ სასიცოცხლო სითხის ფუნქციებია ბავშვის შესაძლო ტრავმებისგან დაცვა, სასუნთქი სისტემის განვითარება, თავისუფალი მოძრაობის შესაძლებლობის მიცემით ჩონჩხისა და კუნთების განვითარების ხელშეწყობა, სითხეში ელექტროლიტური ბალანსის შენარჩუნება, იმუნური სისტემის გაძლიერება და ბავშვისთვის ანტიბაქტერიული გარემოს შექმნა, ასევე მშობიარობამდე სანაყოფე გარსის გახეთქვისა და სითხის დაღვრისას ბავშვის დაბადებისთვის მოსამზადებლად სამშობიარო გზების გაწმენდა.;;;
თუ ამნიონური სითხე საჭიროზე ნაკლებია, ამ მდგომარეობას ოლიგოჰიდრამნიონი ეწოდება, ხოლო თუ საჭიროზე მეტია — პოლიჰიდრამნიონი. ამნიონური სითხის სიმცირის ან სიჭარბის შემთხვევაში ექიმის მეთვალყურეობა უფრო ხშირად დაგჭირდებათ.'), baby_message_ka = COALESCE(baby_message_ka, 'მე შეხებით ვსწავლობ! 🖐️ ხელებით ვეხები სახეს, ფეხებს, ჭიპლარსა და საშვილოსნოს კედელს. ეს ჩემი სხეულის საზღვრების გაგებაში მეხმარება. მე საკუთარ თავს აღმოვაჩენ. ზოგჯერ ცერა თითს ვწოვ. ეს მამშვიდებს. როცა შენც მუცელზე მეხები, მე ამ სითბოს ვგრძნობ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'სტაფილო'), body_changes_ka = COALESCE(body_changes_ka, 'თუ სახეზე, თვალების ირგვლივ, სახსრების მიდამოებსა და ფეხებზე ძლიერი შეშუპება გაქვთ, წონას უეცრად და სწრაფად იმატებთ, ძლიერი და მუდმივი თავის ტკივილი გაწუხებთ, მხედველობის დაბინდვა გაქვთ ან მუცლის არეში მწვავე ტკივილი და ღებინება აღგენიშნებათ, შესაძლოა პრეეკლამფსია გქონდეთ. პრეეკლამფსია, რომელსაც ხალხში ორსულობის ტოქსიკოზსაც უწოდებენ, სერიოზული მდგომარეობაა და ორსულთა 5%-ს აღენიშნება. დიაგნოზი ორსულობის მე-20 კვირიდან ისმება, თუ მაღალი არტერიული წნევის გარდა კიდევ სულ მცირე ერთი ნიშანი არსებობს. ასეთი ნიშნებია შარდში ცილის არსებობა, ღვიძლის ან თირკმლის ფუნქციის დარღვევები. ზოგჯერ პრეეკლამფსია ყოველგვარი სიმპტომის გარეშეც შეიძლება განვითარდეს. მაღალი არტერიული წნევა შესაძლოა თანდათან განვითარდეს ან უეცრად დაიწყოს. არტერიული წნევის კონტროლი პრენატალური მეთვალყურეობის მნიშვნელოვანი ნაწილია, რადგან პრეეკლამფსიის პირველი ნიშანი, ჩვეულებრივ, წნევის მატებაა. ორსულობის ტოქსიკოზის განვითარების ალბათობა უფრო მაღალია 18 წლამდე და 35 წელზე უფროსი ასაკის ორსულებში, ჭარბი ან ძალიან დაბალი წონის შემთხვევაში, ნათესაურ ქორწინებაში მყოფ წყვილებში, პაციენტებში, რომლებსაც ადრე მნიშვნელოვანი ქირურგიული ოპერაცია აქვთ ჩატარებული, ასევე ქალებში, რომლებსაც ორსულობამდე ჰქონდათ გულის დაავადება, დიაბეტი, მაღალი არტერიული წნევა, ეპილეფსია, ფარისებრი ჯირკვლის ან სხვა დაავადება.'), daily_tip_ka = COALESCE(daily_tip_ka, 'აღნიშნეთ 21-ე კვირის დასრულება მცირე გასეირნებით! წელის ტკივილის შესამცირებლად ჩაიცვით დაბალქუსლიანი და კომფორტული ფეხსაცმელი. ძილისას აუცილებლად დაწექით მარცხენა გვერდზე და ფეხების ქვეშ ბალიში დაიდეთ — ეს სისხლის მიმოქცევას გააუმჯობესებს. განაგრძეთ ბევრი წყლის სმა და რაციონში ბოჭკოვანი საკვების ჩართვა.') WHERE id = '925057a2-a250-49b9-bcfa-f9f914c5c38f';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ეს კვირა ნიშნავს, რომ ორსულობის 4 თვისა და 3 კვირის ხართ. ანუ მე-5 თვის დასრულებამდე სულ რაღაც 1 კვირა დაგრჩათ! ;;;
ორსულობის მონიტორინგისას ერთ-ერთი საკითხი, რომელიც ყველაზე მეტად გაინტერესებთ, თქვენი ბავშვის განვითარება და ორსულობის შესაბამის კვირაში მისი წონა და სიგრძეა. ულტრაბგერითი გამოკვლევით განსაზღვრული პარამეტრების შეფასების საფუძველზე წონისა და სიგრძის გამოთვლას დიდი სამედიცინო მნიშვნელობა აქვს; ეს მაჩვენებლები განსაკუთრებით მნიშვნელოვანია ბავშვის წონის მატების, განვითარების და მშობიარობის მეთოდის განსაზღვრისთვის.;;;
დაბალი წონით ან ზედმეტად დიდი წონით დაბადებულ ბავშვებს მშობიარობისას ან მის შემდეგ შესაძლოა გარკვეული გართულებები და რისკები შეექმნათ. ჯანმოს მონაცემებით, 4500 გრამისა და მეტი წონის ბავშვები ბუნებრივი მშობიარობისთვის შესაფერისად არ მიიჩნევიან. აზერბაიჯანში არსებული პრაქტიკით კი, მიუხედავად იმისა, რომ ეს საკითხი თქვენი და თქვენი ექიმის გადაწყვეტილებაზეა დამოკიდებული, ზოგადად 4 კგ და მეტი წონის ბავშვების შემთხვევაში საკეისრო კვეთაა რეკომენდებული.'), baby_message_ka = COALESCE(baby_message_ka, 'მამას ხმა მესმის! 👨 ახლა უკვე არა მხოლოდ თქვენი ხმა, არამედ გარედან შემოსული დაბალი ტონალობის ხმებიც უკეთ მესმის. თუ მამა თქვენს მუცელთან ახლოს მოვა და დამელაპარაკება, მის ხმას ვიცნობ. უთხარით, ზღაპარი მომიყვეს ან უბრალოდ "გამარჯობა" მითხრას. მეც ძალიან მიყვარს!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ქოქოსი'), body_changes_ka = COALESCE(body_changes_ka, 'პირველ თვეებში გამოვლენილი ისეთი სიმპტომები, როგორებიცაა გულისრევა, სისუსტე, თავის ტკივილი და კრუნჩხვები, თანდათან ქრება და ფიზიკურად თავს უფრო მხნედ გრძნობთ. გარდა ამისა, მეორე ტრიმესტრი ის პერიოდიცაა, როდესაც ორსულობასთან ემოციური შეგუება იწყება.;;;
ორსულობის ამ ეტაპზე სასქესო ორგანოებში სისხლძარღვების რაოდენობის მატებისა და სისხლის მიმოქცევის აჩქარების გამო შესაძლოა სექსუალური სურვილი გაძლიერდეს. ამასთანავე, სქესობრივი კავშირის დროს ქალის ორგაზმი ბავშვს არანაირ ზიანს არ აყენებს. პირიქით, ზოგიერთი კვლევის თანახმად, ორგაზმის დროს საშვილოსნოს შეკუმშვები ბავშვის გულისცემაზე დადებითად მოქმედებს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'თუ მუცლის ქვედა ნაწილში მსუბუქ გამაგრებას იგრძნობთ, ცოტა ხნით წამოწექით, დაისვენეთ და ბევრი წყალი დალიეთ. განაგრძეთ რკინისა და მაგნიუმის მიღება, რათა ენერგიის დონე სტაბილური დარჩეს.') WHERE id = 'f395dae9-427a-4c8d-8ba3-bfb8922cadf2';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'მიუხედავად იმისა, რომ თქვენს ბავშვს თმა უკვე ამოსული აქვს, თმის ღერები ჯერ კიდევ უფერულია, რადგან პიგმენტურ ნივთიერებას არ შეიცავს. თმა ძირითადად სხვადასხვა ცილისგან შედგება და ბუნებრივ ფერს პიგმენტ მელანინისგან იღებს. მელანინი როგორც ღია, ისე მუქი ფერის თმაში გვხვდება. თმის ფერის სიმუქე ან სიღიავე მელანინის პიგმენტების რაოდენობის პროპორციულია. სხვა სიტყვებით რომ ვთქვათ, მეტი მელანინის შემცველი თმა უფრო მუქად გამოიყურება, ვიდრე ნაკლები პიგმენტის შემცველი. გარდა ამისა, თმა სხეულის სხვა ტიპის ბეწვთან შედარებით უფრო სწრაფად იზრდება. თმის ზრდის საშუალო სიჩქარე დღეში 0.3 mm-დან 0.5 mm-მდეა. დაბადებისას ბიჭებისა და გოგონების თმის ღერებს ერთნაირი სისქე აქვს.'), baby_message_ka = COALESCE(baby_message_ka, 'რიტმს ვყვები! 🥁 როდესაც მუსიკას უსმენთ ან ცეკვავთ, ამ რიტმს მეც ვგრძნობ. ზოგჯერ მუსიკის ტემპის შესაბამისად მოძრაობაც კი შემიძლია. მშვიდი მუსიკა მაძინებს, სწრაფი კი მაღვიძებს. ჩემი მუსიკალური გემოვნება უკვე ყალიბდება.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ქოქოსი'), body_changes_ka = COALESCE(body_changes_ka, 'მადის მატება ყველაზე ხშირად ორსულობის მეორე ტრიმესტრში, ანუ მე-3 თვის დასაწყისიდან მე-6 თვის ბოლომდე შეინიშნება. პირველი 3 თვის განმავლობაში ჰორმონების დონის ინტენსიური მატება სუნებისადმი მგრძნობელობასა და გულისრევას იწვევს. მეორე ტრიმესტრში ორგანიზმი ამ ჰორმონულ ბალანსს ეჩვევა, გულისრევა მცირდება და მადა იმატებს. ამიტომ ორსულობისას წონის ყველაზე დიდი მატება სწორედ ამ პერიოდში ხდება. რაც უნდა გაგეზარდოთ მადა, ამ პერიოდში ჯანსაღად უნდა იკვებოთ და ცხიმიან, მარილიან და შაქრის მაღალი შემცველობის საკვებს მოერიდოთ. ამასთანავე, ხშირი და მცირე ულუფებით კვება სისხლში შაქრის დონეს მუდმივად დაბალანსებულად შეინარჩუნებს და ერთ ჯერზე ზედმეტად ბევრი კალორიის მიღებას აგაცილებთ თავიდან. ვარჯიში და სეირნობაც ამ პერიოდში მადის გაკონტროლებაში დაგეხმარებათ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'თუ ღამით ფეხის კუნთი გაგეკვანძებათ, დაუყოვნებლივ მოქაჩეთ ფეხის თითები თქვენკენ (მუხლის მიმართულებით), ხოლო ქუსლი წინ გასწიეთ. ეს მოძრაობა წვივის კუნთს ჭიმავს და ტკივილს ამცირებს. მასაჟიც სასარგებლოა.') WHERE id = '68f0e92d-9dd8-4759-acc2-0054a8f6a53a';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის მოძრაობა მისი კუნთების განვითარების ერთ-ერთი უმნიშვნელოვანესი ფაქტორია. ბავშვის დაბადებისას კუნთების წონა სხეულის მთლიანი წონის დაახლოებით ერთ მეხუთედს შეადგენს. მოზარდობის ასაკში კუნთების წონა სხეულის მთლიანი წონის ერთ მესამედს, ხოლო ზრდასრულ ასაკში ორ მეხუთედს შეადგენს. კუნთების ზრდა, ზოგადად, სხეულის ზრდის პარალელურად მიმდინარეობს. დაბადებისას ბავშვებს თვალისა და სუნთქვის კუნთები კარგად აქვთ განვითარებული. ხელის კუნთები კი ფეხის კუნთებთან შედარებით უფრო განვითარებულია. მოზარდობის ასაკამდე დიდი კუნთები მცირე კუნთებზე უკეთ მუშაობს. ამიტომ ბავშვები ფართო და დიდი მოძრაობების შესრულებას უფრო კარგად ახერხებენ, ვიდრე მცირე და ზუსტ მოძრაობებს.'), baby_message_ka = COALESCE(baby_message_ka, '🥥 მე ქოქოსის ზომის ვარ! ახლა უკვე მინიატიურული ბავშვი ვარ. წარბები, წამწამები, ფრჩხილები – ყველაფერი მაქვს. ახლა ჩემი მთავარი მიზანი წონის მომატება და ფილტვების მომზადებაა. ჯერ კიდევ ძალიან გამხდარი ვარ, მაგრამ თქვენ კარგად მკვებავთ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ქოქოსი'), body_changes_ka = COALESCE(body_changes_ka, 'სისხლის მოცულობის მატება აუცილებელია როგორც თქვენი ბავშვისთვის, ისე თქვენი ჯანმრთელობისთვის. თუმცა ამის გამო ფეხებზე შესაძლოა ვენების ვარიკოზული გაგანიერება განვითარდეს. პირველ წლებში ვარიკოზი ხშირად მხოლოდ ვიზუალურ დისკომფორტს იწვევს, მოგვიანებით კი შესაძლოა ტკივილის მიზეზიც გახდეს. ვარიკოზის განვითარების მექანიზმში მრავალი ფაქტორი მონაწილეობს. ის შეიძლება განვითარდეს ორსულობის, ჭარბი წონის, დიდხანს ფეხზე დგომის, ჩასახვის საწინააღმდეგო აბებისა და ჰორმონული მკურნალობის, ვიწრო ტანსაცმლის ტარების, ყაბზობის, ასაკისა და გენეტიკური ფაქტორების გამო. ვარიკოზის პრევენციისთვის სასარგებლოა რეგულარული ვარჯიში, დიდხანს ფეხზე დგომისგან თავის შეკავება, ფეხზე ფეხგადადებული ჯდომის თავიდან აცილება, ზედმეტად მოჭერილი და ვიწრო ტანსაცმლის არჩაცმა, მაღალქუსლიანი ფეხსაცმლის ნაცვლად კომფორტული ფეხსაცმლის არჩევა, ყაბზობის პრევენცია და ბოჭკოთი მდიდარი საკვების მიღება.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ღამით უმჯობესია მარცხენა გვერდზე იწვეთ და არა მარჯვენაზე, რადგან ეს აუმჯობესებს საშვილოსნოსკენ სისხლის მიწოდებასა და თირკმელების მუშაობას. ფეხებზე მსუბუქი შეშუპების შესამცირებლად აკონტროლეთ მარილის მიღება და ბევრი წყალი დალიეთ. თუ ქოშინი გაქვთ, მოძრაობა შეანელეთ, ზურგი და მკერდი გამართული გქონდეთ და ღრმად ისუნთქეთ.') WHERE id = '0192bd32-2239-497b-af81-dc9dc504732a';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ორგანიზმში სისხლის წითელი უჯრედების რაოდენობა თანდათან იზრდება. ეს უჯრედები ორგანიზმში ჟანგბადისა და ნახშირორჟანგის გადამტანი ძირითადი ნაწილაკებია. ისინი სისხლის ყველა უჯრედის 99%-ს შეადგენენ და მკვეთრი წითელი შეფერილობით გამოირჩევიან.;;;
ამ უჯრედების წარმოქმნას თირკმელების მიერ გამოყოფილი ჰორმონი ერითროპოეტინი არეგულირებს. პროცესი ძვლის ტვინში იწყება და დაახლოებით ერთი კვირის განმავლობაში მომწიფებული უჯრედები სისხლის მიმოქცევაში ერთვებიან. მომწიფებულ სისხლის წითელ უჯრედებს ბირთვი არ აქვთ, ამიტომ ისინი ძალიან მოქნილები არიან. სწორედ ამ მოქნილობის წყალობით, ისინი ყველაზე ვიწრო სისხლძარღვებშიც კი ადვილად გადაადგილდებიან და ჟანგბადს ორგანიზმის ყველა ნაწილს აწვდიან. სისხლის წითელი უჯრედების სიცოცხლის ხანგრძლივობა მხოლოდ 3 თვეა. დროთა განმავლობაში გაცვეთილი და დაზიანებული უჯრედები ელენთაში, ღვიძლსა და ძვლის ტვინში ფაგოციტოზად წოდებული პროცესის შედეგად იშლება და ორგანიზმიდან გამოიდევნება.'), baby_message_ka = COALESCE(baby_message_ka, 'შენს ხმას ვცნობ! 🗣️ დედიკო, უკვე შემიძლია შენი ხმა სხვების ხმებისგან გავარჩიო. როცა ლაპარაკობ, ვმშვიდდები და ჩემი გულისცემა ნელდება. ჩემთვის ეს მსოფლიოში ყველაზე უსაფრთხო ხმაა. განაგრძე ჩემთვის სიმღერა, მე მათ ჩემს „მეხსიერების ყუთში“ ვინახავ. როცა დავიბადები და იმ სიმღერას გავიგონებ, გავჩუმდები.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ქოქოსი'), body_changes_ka = COALESCE(body_changes_ka, 'ზოგიერთ ქალს ორსულობის დროს საერთოდ არ უჩნდება აკნე, ზოგიერთთან კი მისი გაძლიერება შეინიშნება. ამის მიზეზი, ჩვეულებრივ, სისხლში ჰორმონების დონის მნიშვნელოვანი მატებაა. ჰორმონების მატებასთან ერთად კანის ცხიმიანობაც პროპორციულად იზრდება. ამგვარად, კანის ზედაპირზე ცხიმის ჭარბი დაგროვება აკნეს წარმოქმნის ერთ-ერთი მთავარი მიზეზია. ორსულობის პერიოდში თავი უნდა შეიკავოთ მძიმე მაკიაჟისგან, არ გამოიყენოთ სათანადოდ გაუვნებელყოფილი მაკიაჟის საშუალებები და ფუნჯები, მოერიდოთ არაჯანსაღ საკვებს, განსაკუთრებით შემწვარ კერძებს, ჩვეულებრივზე მეტად იზრუნოთ კანის სისუფთავეზე და გამოიყენოთ ორსულობისთვის შესაფერისი, წყლის ბაზაზე დამზადებული დამატენიანებლები. ასევე გახსოვდეთ, რომ გამონაყარის მოჭყლეტამ ან ხელით შეხებამ შესაძლოა მასში არსებული ჩირქი კანის ზედაპირზე გაავრცელოს და ახალი გამონაყარის წარმოქმნა გამოიწვიოს. ამიტომ სახის კანს ზედმეტად არ უნდა შეეხოთ და უნდა გახსოვდეთ, რომ ეს დროებითი პროცესია.'), daily_tip_ka = COALESCE(daily_tip_ka, 'საღამოობით ფეხებზე „ცივი შხაპით“ მასაჟი გაიკეთეთ. წყლის ნაკადი ქვემოდან ზემოთ მიმართეთ, რათა სისხლის მიმოქცევა გააუმჯობესოთ. მოერიდეთ მარილიან საკვებს, რადგან მარილი ორგანიზმში წყალს აკავებს.') WHERE id = '47e98235-5632-4780-b011-1fba5afdb56a';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის რეპროდუქციული სისტემა მომწიფებასა და განვითარებას განაგრძობს. თუ თქვენი ბავშვი ბიჭია, ამ პერიოდში მის სათესლე ჯირკვლებში სპერმატოზოიდების წარმოქმნა დაიწყება. ჯერ კიდევ საშვილოსნოში მყოფი ბავშვის სათესლე ჯირკვლების მილაკებში განლაგებული სპერმატოგონიური უჯრედები 2n ქრომოსომულ ნაკრებს შეიცავს. ანუ მათ ჯერ არ აქვთ მომწიფებული სპერმატოზოიდის აგებულება; ისინი სასქესო უჯრედების ნაცვლად სხეულის უჯრედების მსგავსად ფუნქციონირებენ. ამის მიზეზი ისაა, რომ სასქესო უჯრედები n ქრომოსომულ ნაკრებს, ხოლო სხეულის უჯრედები 2n ქრომოსომულ ნაკრებს შეიცავს.;;;
სქესობრივ მომწიფებამდე ბიჭებში სპერმატოგონიური უჯრედები 2n ქრომოსომულ ნაკრებს შეიცავს, ამიტომ ისინი მიტოზური გაყოფით მრავლდებიან. სქესობრივი მომწიფების დაწყებისას კი ეს უჯრედები მომწიფების გარკვეულ საფეხურს აღწევენ და მეიოზური გაყოფისთვის შესაფერის აგებულებას იძენენ. ამის შედეგად ისინი მათთვის დამახასიათებელ n ქრომოსომულ ნაკრებს იღებენ.'), baby_message_ka = COALESCE(baby_message_ka, 'სახეზე ვეხები! 🤲 ხელებით ჩემს სახეს ვიკვლევ. ცხვირს, ნიკაპსა და თვალებს ვეხები. ჩემი კანი ჯერ ძალიან თხელია, მაგრამ შეხებას კარგად ვგრძნობ. ეს მოძრაობები ჩემს ტვინში სხეულის რუკას ქმნის. საკუთარი თავის შეცნობას ვიწყებ. როცა შენც მუცელზე მეხები, ამას ვგრძნობ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ქოქოსი'), body_changes_ka = COALESCE(body_changes_ka, 'დღის ბოლოს ფეხების შეშუპებამ შესაძლოა მოიმატოს. ამის მიზეზია ორგანიზმში სითხის შეკავება, სისხლის მოცულობის ზრდა და ცხელი ამინდი. შესაძლოა ისიც იგრძნოთ, რომ ბეჭედი თითზე გიჭერთ. ორსულობის ამ ეტაპზე ეს ნორმალური ფიზიოლოგიური მდგომარეობაა. ამასთან, ღამით შესაძლოა ფეხების კრუნჩხვებმაც შეგაწუხოთ. ეს შეიძლება სისხლის მიმოქცევის შენელებას ან კალციუმის/მაგნიუმის/კალიუმის დეფიციტს უკავშირდებოდეს. შესაძლოა ასევე განვითარდეს „მოუსვენარი ფეხების სინდრომი“.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ქავილის დროს კანი ფრჩხილებით არ მოიქავოთ. ამის ნაცვლად წაისვით დამატენიანებელი ზეთი ან კრემი და ხელისგულით ნაზად მოეფერეთ. ცივი კომპრესიც დაგეხმარებათ ქავილის შემსუბუქებაში.') WHERE id = 'da8c9afd-1f7d-4478-b2fc-5b192ee0259f';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამ კვირაში, ძვლოვანი ქსოვილის წარმოქმნის დაჩქარებასთან ერთად, თქვენი ბავშვის თავის ქალა ფორმირებას განაგრძობს. თავის ქალა ქვედა და უკანა ნაწილში ხერხემალს უერთდება, წინა ნაწილში კი სახის ძვლებს აკავებს. ამ ეტაპზე თქვენი ბავშვის თავის ქალა ჯერ სათანადოდ განვითარებული არ არის, თუმცა ზრდასრულ ასაკში მისი ზომები დაახლოებით 18 სმ სიგრძე, 13 სმ სიმაღლე და 14 სმ დიამეტრი იქნება.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი გული მღერის! ❤️ ექიმს უკვე შეუძლია ჩემი გულისცემა სპეციალური აპარატების გარეშე, მხოლოდ სტეტოსკოპით მოისმინოს. ჩემი გული წუთში 140-150-ჯერ ცემს. შენთვის ეს ხმა სიცოცხლის რიტმია, ასე არ არის? ჩემი გული შენი წყალობით ასე ძლიერად ცემს.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ქოქოსი'), body_changes_ka = COALESCE(body_changes_ka, 'სწრაფად მზარდი ბავშვის ჭიპის დონემდე აწევის გამო, ამ მიდამოში კანი შესაძლოა დაიჭიმოს და სტრიები გაჩნდეს. ისინი, ჩვეულებრივ, მუცლის ქვედა ნაწილში ჩნდება, თუმცა შესაძლოა ბარძაყებზე, დუნდულებზე, მკერდსა და მკლავებზეც გამოჩნდეს. სტრიებს მოვარდისფრო-თეთრი შეფერილობა და კანის დაზიანების მსგავსი იერი აქვს. ისინი კანის ზედაპირზე მცირე ზომის, არაღრმა ჩაღრმავებების სახით ჩანს. თუ თქვენი კანი ელასტიკურია, შეშფოთების მიზეზი არ გაქვთ, რადგან ელასტიკური კანი სტრიების წარმოქმნისკენ ნაკლებად არის მიდრეკილი. ამიტომ რაიმე პროდუქტის ან დამცავი საშუალების გამოყენება აუცილებელი არ არის. სტრიების მოსაშორებლად ყველაზე სასურველი მეთოდია სპეციალური დამატენიანებელი კრემების ან ისეთი ბუნებრივი გარეგანი საშუალებების გამოყენება, როგორებიცაა ნუშისა და გარგარის კურკის ზეთი.'), daily_tip_ka = COALESCE(daily_tip_ka, 'დღეს მუცელზე ნაზი მასაჟის გაკეთებისას თქვენს ბავშვს ესაუბრეთ — ის უკვე ძალიან კარგად გრძნობს თქვენი ხელის ზეწოლასა და სითბოს.') WHERE id = 'aa1f1ed4-15e9-4574-a163-232172e516be';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის სმენის სრულად ჩამოყალიბებასთან ერთად, თავის ტვინის ნეირონებს შორის კავშირების დამყარების პროცესიც ჩქარდება. ბავშვის ტვინი უკვე, ზრდასრული ადამიანის ტვინის მსგავსად, ხუთი ძირითადი წილისგან შედგება და თითოეულ მათგანს საკუთარი ფუნქცია აქვს:;;;
ფრონტალური (შუბლის) წილი: პასუხისმგებელია ცნობიერ აზროვნებასა და ემოციების მართვაზე.;;;
პარიეტალური (თხემის) წილი: აერთიანებს გრძნობის ორგანოებიდან მიღებულ ინფორმაციას და უზრუნველყოფს სივრცის აღქმას.;;;
ოქციპიტალური (კეფის) წილი: მხედველობასთან დაკავშირებული ინფორმაციის დამუშავების ცენტრია.;;;
ტემპორალური (საფეთქლის) წილი: უზრუნველყოფს ბგერებისა და სუნების აღქმას, სახეებისა და ადგილების ამოცნობას.;;;
ცერებელუმი (ნათხემი): ინარჩუნებს წონასწორობას და მოძრაობებს შეგრძნებებთან აკავშირებს.'), baby_message_ka = COALESCE(baby_message_ka, 'მე გრეიპფრუტის ზომის ვარ! დაახლოებით 370 გრამს ვიწონი, ჩემი სიგრძე კი 27.1 სმ-ია. ჩემი კანი ჯერ კიდევ დანაოჭებულია, რადგან ძალიან სწრაფად ვიზრდები და ცხიმოვანი შრე კანს ჯერ ბოლომდე არ ავსებს. მაგრამ ნუ ღელავთ, დაბადებამდე საყვარელი, ფუმფულა ბავშვი გავხდები. ახლა ჩემი მთავარი საქმე წონის მომატებაა!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'გრეიპფრუტი'), body_changes_ka = COALESCE(body_changes_ka, 'სისხლში პროგესტერონის ჰორმონის კონცენტრაციის მომატების გამო კუჭის დაცლა ფერხდება, ხოლო ნაწლავების მოძრაობა ნელდება. შედეგად შესაძლოა შეკრულობამ შეგაწუხოთ.;;;
ამ პერიოდში საჭმლის მომნელებელი სისტემაც ერთ-ერთი ყველაზე მეტად დაზარალებული სისტემაა. ჰორმონული ცვლილებების გამო კუჭის მჟავას გამოყოფის გაძლიერება, საყლაპავის ტალღისებური მოძრაობების შემცირება, კუჭის სარქველების მოდუნების შედეგად რეფლუქსის განვითარება და, განსაკუთრებით ორსულობის ბოლო 3 თვის განმავლობაში, გაზრდილი საშვილოსნოს მიერ კუჭის ზემოთ აწევის გამო საკვების მონელების შენელება ამ ცვლილებების ნაწილია.;;;
ამ პროცესში, სხეულის მოცულობის ზრდის გამო, შესაძლოა თირკმელებიც გადიდდეს. მომატებული წონის მქონე თირკმლებში შარდის ნაკადი ნელდება, ხოლო არხები, რომლებსაც შარდი თირკმლებიდან შარდის ბუშტში გადააქვთ, ფართოვდება. ამიტომ ორსულობის პერიოდში საშარდე გზების ინფექციები საკმაოდ ხშირია.'), daily_tip_ka = COALESCE(daily_tip_ka, 'რადგან შაბათ-კვირაა, მეტი დრო დაუთმეთ საკუთარ თავს. ქოშინის თავიდან ასაცილებლად ეცადეთ, გამართული იჯდეთ, ხოლო ძილისას ზურგს უკან დამატებითი ბალიში დაიდოთ. მომატებული მადა სასარგებლო თხილეულით აკონტროლეთ. ხვალ ახალი კვირა იწყება — ამ საღამოს თქვენი ბავშვისთვის დამამშვიდებელი მუსიკის სია შეადგინეთ.') WHERE id = 'dcc1b63f-cc53-4d60-9050-ad76c211d2c4';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ეს კვირა მეორე ტრიმესტრის ბოლო თვის პირველი კვირაა. უფრო მარტივად რომ ვთქვათ, მეორე ტრიმესტრის დასრულებამდე მხოლოდ 1 თვე დარჩა.;;;
ამ კვირიდან ცხიმოვანი შრის ფორმირება ჩქარდება, თუმცა შედარებით ნაკლებად, ვიდრე ბოლო ტრიმესტრში. ამიტომ ბავშვის კანი წინანდელთან შედარებით ნაკლებად დანაოჭებული ჩანს. თქვენი ბავშვის ცხიმოვანი ქსოვილის სწრაფ ზრდასთან ერთად კანის ნაოჭებიც თანდათან შემცირდება. ცხიმოვანი უჯრედების რაოდენობა, რომლებსაც საკუთარ ზომაზე 6-ჯერ მეტად გაზრდა შეუძლიათ, ბავშვის მოზარდობის პერიოდამდე 40 მილიარდიდან 100 მილიარდამდე მერყეობს. ეს უჯრედები, რომლებიც უკვე იწყებენ ჩამოყალიბებას, სიცოცხლისთვის აუცილებელია და ორგანიზმის ენერგეტიკულ სისტემას უწყობს ხელს. ცხიმების წყალობით ორგანიზმი ასევე ითვისებს ცხიმში ხსნად A, D, E და K ვიტამინებს. გარდა ამისა, ცხიმები ორგანიზმში კალციუმის შენარჩუნებასაც უზრუნველყოფს.'), baby_message_ka = COALESCE(baby_message_ka, 'ვვარჯიშობ! 🏋️‍♂️ დედიკო, ჩემი მოძრაობები ახლა უფრო ძლიერია. ზოგჯერ შეიძლება შეამჩნიოთ, რომ თქვენი მუცლის ერთი მხარე იბერება ან მოძრაობს. ეს მე იდაყვს ან მუხლს თქვენსკენ ვაწვები. ასე გეუბნებით: "აქ ვარ!" როდესაც ხელს მადებთ, მეც ვმშვიდდები.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'გრეიპფრუტი'), body_changes_ka = COALESCE(body_changes_ka, 'განსაკუთრებით საღამოს საათებში შეიძლება შეამჩნიოთ, რომ თქვენი ტერფები ჩვეულებრივზე უფრო დიდია. ორსულობისას ტერფების ზომის მატება, როგორც წესი, დროებითი პროცესია. ამის ერთ-ერთი მთავარი მიზეზი ორგანიზმში სითხის დაგროვებით გამოწვეული შეშუპებაა. განსაკუთრებით ბოლო თვეებში, ორგანიზმში წყლის შეკავების შედეგად ხელები და ფეხები შუპდება. ამის გამო ფეხსაცმელი, რომელსაც ადრე თავისუფლად იცვამდით, შეიძლება მოგიჭიროთ. კიდევ ერთი მიზეზია ორსულობის პერიოდში საჭიროზე მეტი ან ძალიან სწრაფი წონის მატება. ასეთ შემთხვევაში ტერფების მიდამოში დაგროვილი ცხიმის გამო ფეხები უფრო შეშუპებულად გეჩვენებათ. ტერფების ზომის მატების კიდევ ერთი მიზეზი ჰორმონი რელაქსინია. ეს ჰორმონი მენჯის ძვლებსა და ორგანიზმში არსებულ შემაერთებელ ქსოვილებს არბილებს და ადუნებს, რათა მშობიარობისას ბავშვმა სამშობიარო არხში გავლა შეძლოს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'შესანიშნავი დროა მუცლისთვის ფოტოს გადასაღებად! "Before/After" (მანამდე/შემდეგ) კოლაჟებისთვის ეს კვირები ძალიან შესაფერისია, რადგან თქვენს მუცელს უკვე ლამაზი, მომრგვალებული ფორმა აქვს.') WHERE id = 'a3ddbe51-ede9-4765-9b27-d3fb41ca5df3';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ფილტვებში დაიწყო ნივთიერება სურფაქტანტის გამოყოფა. მარტივად რომ ვთქვათ, სურფაქტანტი ნივთიერებაა, რომელიც სითხის ზედაპირულ დაჭიმულობას ამცირებს. ამიტომ იგი ძალიან მნიშვნელოვანია, რათა ფილტვებმა სუნთქვის ფუნქციის შესრულება შეძლოს.;;;
ფილტვებში სურფაქტანტის გამომუშავების დაწყების წყალობით თქვენი ბავშვი სიცოცხლისუნარიანობის ზღვარს მნიშვნელოვნად მიუახლოვდა. ფილტვებში სურფაქტანტის გამომუშავება თანდათან იზრდება და 37-ე კვირისთვის ბავშვის ფილტვების განვითარების დასრულებას უზრუნველყოფს.;;;
ნაადრევად დაბადებული, დღენაკლული ბავშვების ფილტვებში სურფაქტანტი საკმარისი რაოდენობით არ არის. სურფაქტანტის დეფიციტის გამო ფილტვები სუნთქვის ფუნქციას სრულად ვერ ასრულებს და ხელოვნური სუნთქვის აპარატი ხდება საჭირო.'), baby_message_ka = COALESCE(baby_message_ka, 'სამყაროს ვუსმენ! 🌍 ახლა უკვე არა მხოლოდ თქვენი ხმა, არამედ გარედან შემოსული ხმამაღალი ხმებიც მესმის. თუ ძაღლი ყეფს, მანქანა უსიგნალებს ან მტვერსასრუტი მუშაობს, ყველაფერს ვგრძნობ. ზოგჯერ ამ ხმების მეშინია და ვკრთები. როცა თქვენ მშვიდად ხართ, მეც მშვიდად ვარ. ჩვენი სამყარო საერთოა.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'გრეიპფრუტი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის მე-20 კვირების შუა პერიოდთან მიახლოებისას შესაძლოა ბრექსტონ-ჰიქსის ე.წ. ცრუ შეკუმშვები დაიწყოს. ბრექსტონ-ჰიქსის შეკუმშვები საშვილოსნოს კუნთების დაჭიმვის შედეგად ვითარდება და ორსულობის მეორე ტრიმესტრის ნებისმიერ ეტაპზე შეიძლება დაიწყოს. მშობიარობის ნამდვილი შეკუმშვებისგან განსხვავებით, მათი ინტენსივობა და სიხშირე ცვალებადია. ისინი შესაძლოა უფრო ხშირად გამოვლინდეს განსაკუთრებით საღამოს საათებში და დაღლილობისას. ნამდვილი და ცრუ შეკუმშვების განმასხვავებელი სხვა ნიშნებია: ცრუ შეკუმშვები არარეგულარულია, დროთა განმავლობაში არ ხშირდება, თანდათან სუსტდება, სხეულის პოზიციის შეცვლისას გაივლის და უმეტესად მუცლის წინა ნაწილში იგრძნობა. ამ შეკუმშვების შესამსუბუქებლად უნდა დაისვენოთ, გაისეირნოთ, მიიღოთ საკმარისი სითხე და წელის მიდამო დაიმასაჟოთ. თბილი შხაპიც შეიძლება დაგეხმაროთ შეკუმშვებით გამოწვეული დისკომფორტის შემცირებაში. თუ ფიქრობთ, რომ შეკუმშვები განსაზღვრული ინტერვალებით მეორდება და მათი სიხშირე და ინტენსივობა თანდათან იზრდება, შესაძლოა უახლოეს სამედიცინო დაწესებულებას უნდა მიმართოთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'თუ ცრუ შეკუმშვები გაწუხებთ, დალიეთ ერთი ჭიქა წყალი, დაწექით მარცხენა გვერდზე და დაისვენეთ. ხშირად გაუწყლოება ან დაღლილობა ამ შეკუმშვებს აძლიერებს.') WHERE id = '97aa8d6c-1084-4919-a563-80230748cb6e';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ორგანიზმმა, ჯერ ძალიან მცირე რაოდენობით, ანტისხეულების გამომუშავება დაიწყო. ეს ნიშნავს, რომ მიუხედავად იმისა, რომ იმუნური სისტემა ჯერ სრულად არ ჩამოყალიბებულა, მის საფუძველს უკვე ეყრება. ანტისხეული სასარგებლო ნივთიერებაა, რომელსაც ორგანიზმი მავნე ბაქტერიების, მიკრობებისა და უცხო ნივთიერებების საპასუხოდ გამოიმუშავებს. ანტისხეულები ორგანიზმის ბუნებრივი დამცავი მექანიზმია და იმუნური სისტემის ძირითად სტრუქტურულ ერთეულს წარმოადგენს.;;;
ძალიან მნიშვნელოვანია, რომ ბავშვი დაბადებისთანავე თქვენი პირველი რძით — ხსენით (კოლოსტრუმით) გამოკვებოთ. ხსენი შეიცავს ანტისხეულებს, რომელთა გამომუშავებაც ბავშვს ჯერ არ შეუძლია. კვებისას ეს ანტისხეულები წვრილი ნაწლავიდან შეიწოვება, ბავშვის სისხლში ხვდება, ხელს უწყობს მისი იმუნური სისტემის განვითარებას და გარედან შემოჭრილი მავნე მიკროორგანიზმებისგან იცავს.'), baby_message_ka = COALESCE(baby_message_ka, 'სიზმარს ვხედავ? 💤 ჩემი ტვინის ტალღები აჩვენებს, რომ მე "REM ძილის" ფაზაში ვარ. ამ დროს, მიუხედავად იმისა, რომ თვალები დახუჭული მაქვს, თვალის კაკლები სწრაფად მოძრაობს. მეცნიერები ამბობენ, რომ ეს სიზმრის ნახვას ნიშნავს. რას ვხედავ სიზმარში? იქნებ შენს ხმას, ან იქნებ ამნიონური სითხის გემოს.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'გრეიპფრუტი'), body_changes_ka = COALESCE(body_changes_ka, 'დეტალური ულტრაბგერითი გამოკვლევა ორსულობის მე-19 და 23-ე კვირებს შორის ტარდება. ამ პერიოდში ბავშვის ორგანოები უკვე ჩამოყალიბებულია, ხოლო სანაყოფე წყლების მომატებული რაოდენობა უფრო დეტალური გამოსახულებების მიღების შესაძლებლობას იძლევა. დეტალური ულტრაბგერითი გამოკვლევის მიზანია ბავშვის განვითარების შეფასება და შესაძლო ანომალიების გამოვლენა. თანამედროვე ულტრაბგერითი აპარატებით შესაძლებელია ზოგიერთი ანომალიისა და ქრომოსომული დარღვევის ნიშნების დანახვა. ამ სკრინინგის დროს ცალ-ცალკე და დეტალურად მოწმდება ბავშვის თავის ქალა და ტვინი, ხერხემალი, გულმკერდის ღრუს სტრუქტურები, მუცლის ღრუს ორგანოები, კუჭ-ნაწლავის სისტემა, გული, ხელები და ფეხები, ასევე პლაცენტა.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ფეხები კედელს მიაყრდენით, მაღლა ასწიეთ და 15 წუთის განმავლობაში წამოწექით. ეს სისხლის უკან დაბრუნებას უწყობს ხელს და შეშუპებას ამცირებს. შეამცირეთ მარილიანი საკვების მიღება, მაგრამ არა წყლის!') WHERE id = 'aebe9763-3910-4530-99d7-d5c87283c426';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის შიდა ყურის სტრუქტურის განვითარებისა და სმენის ფუნქციის ჩამოყალიბების შედეგად, ტვინის სმენაზე პასუხისმგებელი ნაწილი სხვა უბნებთან შედარებით უფრო მეტად არის განვითარებული.;;;
ჩონჩხი და კუნთები იმდენად გაძლიერდა, რომ მოძრაობები მუცლის კედლიდან იგრძნობა და ზოგჯერ შეიძლება თვალითაც კი დაინახოთ. ნაყოფის ხერხემალი მტკიცდება. სისხლძარღვები, განსაკუთრებით ფილტვებში, განვითარებას განაგრძობს.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი დარტყმები ძლიერდება! 🥋 დედიკო, გრძნობ? მე უკვე უბრალოდ კი არ "დავცურავ", არამედ ნამდვილ დარტყმებს ვასრულებ. ზოგჯერ შეიძლება მოგეჩვენოს, რომ კარატეში ვვარჯიშობ. ეს მოძრაობები აჩვენებს, რომ ჯანმრთელი ვარ. უკვე შეგიძლია ჩემი მოძრაობების დათვლა დაიწყო.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'გრეიპფრუტი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის 24-ე და 28-ე კვირებს შორის ჩატარებული გლუკოზის დატვირთვის ტესტი სისხლში გლუკოზის დონის შეფასებით დიაბეტის რისკის დადგენაში გვეხმარება. ორსულობის დროს ინსულინის ბალანსის დარღვევის გამო დიაბეტი შეიძლება განუვითარდეს ქალსაც კი, რომელსაც ორსულობამდე დიაბეტი არ ჰქონია და მისი სიმპტომები არ აღენიშნებოდა. ეს მდგომარეობა, რომელსაც გესტაციური დიაბეტი ეწოდება, ორსულთა დაახლოებით 10%-ში გვხვდება.;;;
გარდა ამისა, ქალებისთვის, რომლებსაც დიაბეტი ჯერ კიდევ დაორსულებამდე ჰქონდათ, ორსულობისას სისხლში გლუკოზის დონის კონტროლი შეიძლება კიდევ უფრო გართულდეს. ამიტომ დიაბეტის მქონე ორსულებისთვის აუცილებელია რეგულარული შემოწმება, შესაბამისი კვების რეჟიმის დაცვა და სათანადო მკურნალობა.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ჯანსაღი წასახემსებელი: ნიგოზი, ქიშმიში, გარგრის ჩირი ან ერთი ჯამი იოგურტი. ეს პროდუქტები დაგანაყრებთ და ბავშვს საჭირო ვიტამინებითაც უზრუნველყოფს. მოერიდეთ სწრაფ კვებას — ის მხოლოდ არაჯანსაღი წონის მატებას იწვევს.') WHERE id = '846475dc-14c4-4c7d-ac51-e75ce4438f24';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ცხიმოვანი ქსოვილი, რომლის ჩამოყალიბებაც თქვენი ბავშვის სხეულში დაიწყო, ზრდასრული ადამიანის ორგანიზმში არსებული ცხიმისგან განსხვავდება. მართალია, ეს ბევრმა არ იცის, მაგრამ ცხიმოვანი უჯრედების ორი ტიპი არსებობს: თეთრი და ყავისფერი ცხიმი. თეთრ და ყავისფერ ცხიმოვან უჯრედებს შორის მთავარი განსხვავება მათი ფერია. თეთრი ცხიმოვანი უჯრედის შიგნით ერთი დიდი ლიპიდური, ანუ ცხიმოვანი წვეთის გარდა სხვა ნივთიერება თითქმის არ არის. ეს ცხიმოვანი შრე უჯრედს მის დამახასიათებელ ფერს აძლევს. თეთრი ცხიმი ენერგიის მარაგს ქმნის და შინაგან ორგანოებს რბილ საყრდენს უზრუნველყოფს. ამასთან, ეს უჯრედები მრავალ ჰორმონს, მათ შორის ესტროგენსა და ლეპტინს გამოიმუშავებს და სხვა ჰორმონების, მაგალითად ინსულინის, მოქმედებაშიც მონაწილეობს. ამ ეტაპზე თქვენი ბავშვის ორგანიზმი ძირითადად ყავისფერ ცხიმოვან უჯრედებს წარმოქმნის. ერთი დიდი ცხიმოვანი წვეთის ნაცვლად, ამ უჯრედებში მცირე ზომის ცხიმოვანი წვეთები და დიდი რაოდენობით მიტოქონდრიაა. მათი განსხვავებული ფერის კიდევ ერთი მიზეზი უჯრედის სტრუქტურაში რკინის არსებობაა, რაც მას უფრო მუქ შეფერილობას აძლევს. თეთრი ცხიმოვანი უჯრედებისგან განსხვავებით, ყავისფერი ცხიმოვანი უჯრედები სხეულის გასათბობად აქტიურად წარმოქმნის სითბოს. ეს განსაკუთრებით მნიშვნელოვანია ჩვილებისთვის, რომლებსაც საკუთარი თავის გასათბობად საჭირო მოძრაობების შესრულება ჯერ არ შეუძლიათ.'), baby_message_ka = COALESCE(baby_message_ka, 'წონასწორობას ვინარჩუნებ! ⚖️ ჩემს ყურში არსებული "ვესტიბულური აპარატი" სრულად მუშაობს. უკვე ვგრძნობ, თავით ქვემოთ ვარ თუ ზემოთ. როცა შენ მოძრაობ, მეც ვცდილობ წონასწორობა შევინარჩუნო. შეგვიძლია ერთად ვიცეკვოთ!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'გრეიპფრუტი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის დასაწყისიდან ბოლომდე თქვენი ორგანიზმის ჰორმონული ბალანსი მთლიანად იცვლება, რაც მნიშვნელოვანია როგორც თქვენთვის, ისე თქვენი ბავშვისთვის. ამ პროცესში მონაწილეობს hCG, ესტროგენი, პროგესტერონი, რელაქსინი, ოქსიტოცინი და LH.;;;
ესტროგენი მნიშვნელოვან როლს ასრულებს ორგანიზმის ბავშვის ტარებისა და ძუძუთი კვებისთვის მომზადებაში. ამავდროულად, ის ხელს უწყობს ემბრიონის საშვილოსნოს შიდა ზედაპირზე საიმედოდ მიმაგრებას. ორსულობის დროს ამ ჰორმონის დონე ნორმალურ მაჩვენებელთან შედარებით შესაძლოა 50-ჯერ გაიზარდოს. ის ხელს უწყობს საშვილოსნოს კუნთებისა და სარძევე ჯირკვლების სადინრების ზრდას, ასევე საშვილოსნოსთვის საკმარისი სისხლის მიწოდებას. ესტროგენი აგრეთვე ზრდის მელანოციტების — კანის შეფერილობის განმსაზღვრელი პიგმენტის წარმომქმნელი უჯრედების — აქტივობას. ამიტომ ორსულობისას ძუძუს დვრილები და ვაგინა შეიძლება გამუქდეს, სახეზე კი გაჩნდეს ჭორფლები ან ე.წ. "ორსულობის ნიღაბი". ესტროგენთან დაკავშირებულმა ცვლილებებმა შეიძლება გავლენა მოახდინოს არტერიულ წნევაზე და სექსუალური აქტივობის სურვილიც გააძლიეროს.;;;
ორსულობისას კიდევ ერთი უმნიშვნელოვანესი ჰორმონია პროგესტერონი. მისი მთავარი ფუნქცია საშვილოსნოს შიდა ქსოვილის მომზადება და რეგულირებაა, სადაც თქვენი ბავშვი ვითარდება. ამ ფუნქციას ის ესტროგენთან ერთად ასრულებს. პროგესტერონი ორსულობის დროს კუნთებსაც ადუნებს, განსაკუთრებით კი საშვილოსნოს კუნთებს, რითაც ხელს უშლის მათ არასაჭირო შეკუმშვას და ორსულობის ნაადრევად დასრულებას.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ქოშინის შეგრძნებისას ხელები თავს უკან მოათავსეთ და ღრმად ჩაისუნთქეთ — ეს გულმკერდის მოცულობას დროებით გაზრდის. ღამით უფრო კომფორტულად ძილისა და მენჯის ტკივილის შესამცირებლად მუხლებს შორის ბალიში მოათავსეთ. დალიეთ ბევრი წყალი და რაციონში გაზარდეთ კალიუმით მდიდარი პროდუქტების რაოდენობა, რათა კუნთების დაძაბულობა შემცირდეს.') WHERE id = 'b80a4824-be4e-45cc-b6d6-5d38c928227c';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'სისხლძარღვთა სისტემა, რომელიც თქვენი ბავშვის სხეულს ქსელივით ფარავს, უკვე სრული სისწრაფით ვითარდება. წარმოიდგინეთ, ადამიანის სხეულში სისხლძარღვების საერთო სიგრძე დაახლოებით 100 000 km-ია — ეს წარმოუდგენელი მანძილი დედამიწისთვის ორჯერ მეტჯერ შემოვლასაც კი ეყოფა! ეს საოცარი სატრანსპორტო სისტემა სამი ტიპის „გზისგან“ შედგება: არტერიები სხეულის „ჩქაროსნული მაგისტრალებია“. მათ გულიდან ჟანგბადით მდიდარი სისხლი სხეულის სხვადასხვა ნაწილში გადააქვთ. ყველაზე დიდი და ძლიერი არტერია — აორტა — გულიდან გამოდის და სისხლს უფრო მცირე განშტოებებში ანაწილებს. არტერიები კუნთოვანიცაა და ელასტიკურიც, რათა გულის ყოველი შეკუმშვისას წარმოქმნილ წნევას გაუძლოს. ვენები „შემკრები გზებია“, რომლებსაც ჟანგბადით ღარიბი სისხლი ისევ გულისკენ მიაქვთ. ვენებს ერთი ძალიან საინტერესო საიდუმლო აქვთ: მათ შიგნით მცირე, მგრძნობიარე სარქვლებია განლაგებული. ეს სარქვლები ხელს უშლის სისხლს, მიზიდულობის ძალის გავლენით, უკან დაბრუნებაში და უზრუნველყოფს მის მოძრაობას მხოლოდ გულისკენ. კაპილარები არტერიებისა და ვენების დამაკავშირებელი, თმის ღერზეც კი წვრილი მიკროსკოპული სისხლძარღვებია. ისინი იმდენად გამტარი და ნაზია, რომ სწორედ მათი მეშვეობით იღებენ უჯრედები საკვებ ნივთიერებებს და თავისუფლდებიან ნარჩენი ნივთიერებებისგან. კაპილარები ჩვენი სხეულის ყველა ქსოვილში გვხვდება და ნივთიერებათა ცვლის ნამდვილი ცენტრია.'), baby_message_ka = COALESCE(baby_message_ka, 'ფრჩხილები მეზრდება! 💅 ხელის ფრჩხილები უკვე თითქმის თითების წვერებამდე აღწევს. ისინი ძალიან თხელი და ბასრია. ზოგჯერ შემთხვევით სახეს ვიკაწრავ. თუმცა ჩემი კანი სწრაფად ხორცდება. ყოველდღე უფრო მეტად გემსგავსებით, დედიკო.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'გრეიპფრუტი'), body_changes_ka = COALESCE(body_changes_ka, 'თქვენი ბავშვის უჩვეულოდ სწრაფი ზრდისა და საშვილოსნოს ზემოთ გადაადგილების გამო თქვენი სხეულის სიმძიმის ცენტრი იცვლება.;;;
ფეხის კრუნჩხვები განსაკუთრებით ხშირად გვხვდება ორსულობის მეორე და მესამე ტრიმესტრებში. ისინი შეიძლება განვითარდეს ფეხებში სისხლძარღვების ან ნერვების ზეწოლის გამო. ფეხის კრუნჩხვების მიზეზი შესაძლოა ასევე იყოს საკვებით მაგნიუმის დღიური მოთხოვნილების დაუკმაყოფილებლობა.;;;
წელის ტკივილი კი ორსული ქალების დაახლოებით ორ მესამედს აწუხებს. ჩვეულებრივ, ის წარმოიქმნება იმის გამო, რომ მზარდი მუცელი წელის კუნთებს ძაბავს და სხეულის პოზას ცვლის. ტკივილის შესამცირებლად მიიღეთ თბილი შხაპი, გამოიყენეთ წელის დამჭერი ქამარი, დაჯექით წელის საყრდენის მქონე სკამზე, მოერიდეთ დიდხანს ფეხზე დგომასა და ერთ პოზაში გაჩერებას, მარჯვენა ან მარცხენა გვერდზე წოლისას ფეხებს შორის ბალიში მოათავსეთ და თავი აარიდეთ უეცარ მოძრაობებს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ჩაიცვით რამდენიმე ფენად. როცა დაგცხებათ, ზედა ფენის გახდა შეგეძლებათ. ატარეთ ბუნებრივი ქსოვილებისგან (ბამბა, სელი) დამზადებული ტანსაცმელი, რათა კანმა ისუნთქოს. სხეულის ტემპერატურის დასარეგულირებლად დალიეთ ბევრი წყალი.') WHERE id = '2970a789-ae12-4a5d-81be-71d79963f650';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვი იბადება ტვინის მიერ მართული უნებლიე რეფლექსური მოძრაობებით. ამ რეფლექსებს მიეკუთვნება მოროს რეფლექსი, ჩაჭიდების რეფლექსი, შეკრთომის რეფლექსი, ტერფის რეფლექსი, ნაბიჯის გადადგმის რეფლექსი, წოვისა და ძებნის რეფლექსები.;;;
როდესაც ბავშვს ეჩვენება, რომ ვარდება, ხელებს წინ იშვერს, მტევნებს შლის და თითებს შეძლებისდაგვარად ფართოდ შლის. შემდეგ ხელებს ისე აერთებს, თითქოს რაღაცას ეხვევა. თუ ფეხები თავისუფლად აქვს, მათაც ანალოგიურად ამოძრავებს. ამას მოროს რეფლექსი ეწოდება და ის დაბადებიდან მცირე ხნის შემდეგ ქრება.;;;
შეკრთომის რეფლექსი მაშინ ვლინდება, როდესაც ბავშვს ახლოს ძლიერი ან მოულოდნელი ხმა ესმის. შედეგად ბავშვის სხეული იჭიმება, მხრები იკეცება, ხელები კი ზემოთ იწევა, თითქოს შესაძლო თავდასხმისგან თავის დაცვას ცდილობს. თავდაცვისკენ მიმართული ეს რეფლექსი სხვა რეფლექსების მსგავსად არ ქრება — პირიქით, ის მთელი ცხოვრების განმავლობაში ძლიერდება და ვითარდება.;;;
წოვის რეფლექსი დაბადების შემდეგ ბავშვის პირის ზედა ნაწილთან რაიმეს შეხებით აქტიურდება. მისი წყალობით ბავშვი ძუძუს თავს საკმარისად ძლიერად ეჭიდება, რათა დედის რძით იკვებოს. ეს რეფლექსი 3-4 თვის განმავლობაში ნებელობით მოძრაობად გარდაიქმნება.;;;
ამ რეფლექსებიდან ზოგიერთი გარკვეული დროის შემდეგ შეიძლება გაქრეს. დარჩენილ უნებლიე მოძრაობებს კი ტვინის განვითარების შედეგად თანდათან გააზრებული, ნებელობითი მოძრაობები ანაცვლებს.'), baby_message_ka = COALESCE(baby_message_ka, 'მუცელი რატომ გიხტით? 🐇 დედიკო, იგრძენით? ახლახან სლოკინი მქონდა! ჩემი დიაფრაგმა ვარჯიშობს და ამიტომ სხეული რიტმულად მითრთის. ეს შეიძლება უცნაურად მოგეჩვენოთ, თითქოს მუცელში საათი წიკწიკებს. არ ინერვიულოთ, ეს არ მტკივა — პირიქით, ფილტვებს მიმაგრებს.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'დიდი გრეიპფრუტი'), body_changes_ka = COALESCE(body_changes_ka, 'ამ პერიოდში თქვენს ბავშვს განსაკუთრებით ბევრი რკინა სჭირდება. ამან თქვენს ორგანიზმში რკინის დეფიციტი შეიძლება გამოიწვიოს. თუ სისუსტე, დაღლილობა ან სიფერმკრთალე გაწუხებთ, ექიმმა შეიძლება რკინის დონის შესამოწმებლად ანალიზების ჩატარება გირჩიოთ. თქვენს მზარდ ბავშვსა და პლაცენტას დამატებითი რკინა სჭირდება. ქალების უმეტესობა ორსულობას ამ მოთხოვნილების დასაკმაყოფილებლად საკმარისი რკინის მარაგით არ იწყებს. რკინაზე მოთხოვნილება განსაკუთრებით მეორე და მესამე ტრიმესტრებში იზრდება და მისი მხოლოდ საკვებით დაკმაყოფილება შეუძლებელი ხდება. ექიმის მიერ რეკომენდებული რკინის პრეპარატის მიღებასთან ერთად, ხორციან კერძებს მიაყოლეთ ლიმონის წვენით შეზავებული სალათი, ხოლო ბოსტნეულის კერძები C ვიტამინით მდიდარ სალათებთან ერთად მიირთვით — ეს რკინის შეწოვას გააუმჯობესებს.'), daily_tip_ka = COALESCE(daily_tip_ka, '23-ე კვირის წარმატებით დასრულება საკუთარი თავის განებივრებით აღნიშნეთ! წელის ტკივილის შესამცირებლად ატარეთ დაბალქუსლიანი ფეხსაცმელი და დიდხანს ნუ დარჩებით ერთსა და იმავე პოზაში. ყურადღება მიაქციეთ კალციუმისა და D ვიტამინის მიღებას, რათა ბავშვის ძვლების განვითარება ჯანსაღად გაგრძელდეს. ხვალ ახალ კვირას — 24-ე კვირას ვიწყებთ!') WHERE id = 'c1de12f1-7759-492c-b277-e01fb2d857c9';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'გილოცავთ! თქვენმა ბავშვმა უკვე სიცოცხლისუნარიანობის ზღვარს მიაღწია. ეს კვირა ითვლება პერიოდად, როდესაც ნაადრევად დაბადებულ ბავშვს, საავადმყოფოს ახალშობილთა ინტენსიური თერაპიის შესაძლებლობების შესაბამისად, გადარჩენის შანსი უჩნდება.;;;
ამ კვირიდან თქვენი ბავშვის სიცოცხლისუნარიანობის ზღვართან მიღწევის უმთავრესი მიზეზი ფილტვების განვითარების მნიშვნელოვანი ეტაპის დაწყებაა. ფილტვებში უკვე ჩამოყალიბებული სასუნთქი გზების განშტოებები საჰაერო ტომსიკებს უკავშირდება. ამასთანავე, დაწყებულია საჰაერო ტომსიკების შიდა ზედაპირის დამფარავი სურფაქტანტის გამომუშავება. სურფაქტანტი სუნთქვისას ფილტვებში ზედაპირულ დაჭიმულობას ამცირებს და საჰაერო ტომსიკებს ჩაფუშვისგან იცავს. მიუხედავად იმისა, რომ სურფაქტანტის გამომუშავება ამ კვირაში იწყება, ნორმალური პროცესის დროს ის 38-ე კვირისთვის სრულდება. ამიტომ 24-34 კვირის ორსულებში, რომლებსაც ნაადრევი მშობიარობის საფრთხე აქვთ, დროის მოსაგებად სხვადასხვა მეთოდით ცდილობენ მშობიარობის შეჩერებას და უკეთებენ კორტიკოსტეროიდების შემცველ ინიექციებს, რომლებიც სურფაქტანტის გამომუშავებას ზრდის და ამგვარად ფილტვების განვითარებას აჩქარებს.'), baby_message_ka = COALESCE(baby_message_ka, 'გისმენთ! 👂 დედიკო, სახლში მტვერსასრუტის ხმა ძალიან ხმამაღალია, არა? ძლიერ ხმებზე უკვე ვკრთები. თუმცა თქვენი მშვიდი ხმა მამშვიდებს. როცა მელაპარაკებით, შეიძლება მოძრაობა შევწყვიტო, რათა მოგისმინოთ. ჩვენი პირველი დიალოგები იწყება.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'დიდი გრეიპფრუტი'), body_changes_ka = COALESCE(body_changes_ka, 'თქვენი მუცლის ზედაპირზე ბავშვის მოძრაობები უკვე გარედანაც შესამჩნევია. კანის პიგმენტაცია შეიძლება უფრო გამუქდეს. ასევე, ჭიპი (umbilicus) შესაძლოა ჩაღრმავების ნაცვლად გარეთ გამოიბეროს და „ღილივით“ გამოჩნდეს. ეს საშვილოსნოს ზეწოლითაა გამოწვეული. თქვენი სხეულის ტემპერატურა შეიძლება ჩვეულებრივზე მაღალი იყოს. ძალიან ადვილად ოფლიანდებით. შესაძლოა „წამოხურება“ იგრძნოთ. ეს ნივთიერებათა ცვლის აჩქარებასა და სისხლის მიმოქცევის გაზრდას უკავშირდება. გრილ ადგილებს ეძებთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ამ კვირაში ექიმთან დაგეგმეთ გლუკოზის ტოლერანტობის ტესტის (OGTT) ჩატარება. მუცლის კანის ქავილისა და სტრიების შესამცირებლად რეგულარულად გამოიყენეთ დამატენიანებელი კრემები. დღეს ზედმეტად ნუ გადაიღლებით — ყოველ 1 საათში ერთხელ ფეხები გაშალეთ და 10 წუთი დაისვენეთ.') WHERE id = '372f913d-c4b6-4616-837e-127ec92b9515';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენ ორსულობის მე-6 თვეში ხართ. ბავშვის ორგანოები, რომელიც ახლა წონის სწრაფად მატების ეტაპზე გადადის, უკვე იმდენადაა განვითარებული, რომ გარე სამყაროსთან შეგუებას შეძლებს, ხოლო მისი პაწაწინა ტერფები დაბადების დღემდე თითქმის ორჯერ გაიზრდება.;;;
თქვენი ბავშვი რეფლექსური მოძრაობების განვითარებას განაგრძობს. ამასთანავე, მან უკვე ზოგიერთი გააზრებული მოძრაობის შესრულებაც დაიწყო. რეფლექსი განისაზღვრება, როგორც გარეგანი გამღიზიანებლის შედეგად წარმოქმნილი უნებლიე ფიზიკური რეაქცია. დაბადებისას თქვენს ბავშვს მრავალი რეფლექსური მოძრაობა ექნება. თავდაპირველად ის ამ მოძრაობებს უნებლიეთ ასრულებს და მათ კონტროლს ვერ ახერხებს.'), baby_message_ka = COALESCE(baby_message_ka, 'მე წონას ვიმატებ! ⚖️ ჩემი კანი ჯერ კიდევ ოდნავ დანაოჭებულია, თითქოს დიდი მაქვს. მაგრამ სწრაფად ვიმატებ წონას და ამ სიცარიელეებს ვავსებ. მალე საყვარელი, ფუმფულა ბავშვი გავხდები. თქვენ კარგად მკვებავთ, გმადლობთ!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'დიდი გრეიპფრუტი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის პერიოდში თქვენს გულ-სისხლძარღვთა სისტემაში საკმაოდ ბევრი ცვლილება ხდება. კერძოდ, ორსულობის პირველი კვირებიდანვე სისხლში მომატებული ჰორმონი პროგესტერონი სისტემურ სისხლძარღვოვან წინააღმდეგობას ამცირებს, რის გამოც არტერიული წნევა იკლებს. პირველ კვირებში თვალთ დაბნელების, თავბრუსხვევისა და გონების დაკარგვის მიზეზი შესაძლოა სწორედ არტერიული წნევის დაქვეითება იყოს. გულის დარტყმითი მოცულობა, ანუ სისხლის რაოდენობა, რომელსაც გული თითოეული შეკუმშვისას სისხლის მიმოქცევაში გადაისვრის, დაახლოებით 50%-ით იზრდება. წუთში სისხლის მიმოქცევაში გადასროლილი სისხლის მოცულობა 4,5 ლიტრიდან 6 ლიტრამდე იმატებს. გულისცემის სიხშირე, რომელსაც პულსს ვუწოდებთ, შესაძლოა წუთში 70-დან 90-მდე გაიზარდოს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'C ვიტამინი ღრძილებს ამაგრებს. მიირთვით ისეთი საკვები, როგორიცაა კივი, წითელი წიწაკა და ფორთოხალი. კბილის ძაფის გამოყენებისას ძალიან ფრთხილად იყავით.') WHERE id = '5f95650f-570c-4da1-a06d-ada1c9adbe04';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ბავშვის მოძრაობები არაუგვიანეს ამ კვირისა უკვე უნდა გეგრძნოთ. ორსულობის პროგრესირებასთან ერთად ბავშვის მოძრაობები შეიძლება შეიცვალოს. თავდაპირველად შედარებით სუსტი მოძრაობები ამ ეტაპზე უკვე უფრო შესამჩნევი ხდება.;;;
ამ ეტაპზე ბავშვი ხშირად მის გარშემო მიმდინარე მოვლენებზე საპასუხოდ მოძრაობს. ძლიერმა ხმაურმა, მკვეთრმა სინათლემ ან ზოგიერთმა მასტიმულირებელმა საკვებმა შესაძლოა ბავშვი აამოძრაოს და ბიძგებისკენ უბიძგოს. ამ კვირებში ბავშვისგან რეგულარული მოძრაობების მოლოდინი ჯერ ნაადრევია. თუმცა, თუ მოძრაობებს დიდი ხნის განმავლობაში ვერ იგრძნობთ, სისხლში შაქრის დონის ამწევი საკვების მიღება და მშვიდ გარემოში მარცხენა გვერდზე დაწოლა შეიძლება დაგეხმაროთ.'), baby_message_ka = COALESCE(baby_message_ka, 'მე წონასწორობის ოსტატი ვარ! 🤸‍♂️ ჩემს ყურში არსებული წონასწორობის ორგანო სრულად ფუნქციონირებს. როცა თქვენ მოძრაობთ, მეც შიგნით ვირწევი. ჩემთვის ეს ნამდვილი ატრაქციონია!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'დიდი გრეიპფრუტი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის პერიოდში საკმაოდ მაღალია რკინადეფიციტური ანემიის, იგივე სისხლნაკლებობის, განვითარების ალბათობა. ჰემოგლობინის დონის შემცირება ზოგჯერ ყოველგვარი სიმპტომის გარეშე მიმდინარეობს. გავრცელებულ სიმპტომებს შორისაა კანის სიფერმკრთალე, სისუსტე, დაღლილობა, კონცენტრაციის დარღვევა, თავის ტკივილი, ხელებისა და ფეხების დაბუჟება, გაღიზიანებადობა, ყურებში ხმაური, ტუჩების დასკდომა და პირის კუთხეებში წყლულები, თმის ცვენა, ფრჩხილების გათხელება და ადვილად მტვრევა. რკინის დეფიციტის გაღრმავებისას შესაძლოა განვითარდეს გულის ფრიალი, მიწის ან ყინულის ჭამის სურვილი, ფარისებრი ჯირკვლის ფუნქციის შენელება და „მოუსვენარი ფეხების“ სინდრომი.;;;
ანემიის თავიდან ასაცილებლად ეცადეთ, დღის განმავლობაში რკინის შემცველი საკვების სულ მცირე 2-3 პორცია მიიღოთ. რკინის მაღალი შემცველობით გამოირჩევა სუბპროდუქტები (ღვიძლი და სხვ.), ხორცი, მწვანე ბოსტნეული, ქიშმიში, ბექმეზი, თხილი, არაქისი, კვერცხი და ხმელი პარკოსნები. რკინის პრეპარატებთან ან რკინის შემცველ საკვებთან ერთად მიღებული ფორთოხლის წვენი, პომიდვრის წვენი და სალათი ორგანიზმის მიერ რკინის ათვისებას აუმჯობესებს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'მენჯის ტკივილის შესამცირებლად შეასრულეთ კეგელის ვარჯიშები — ეს კუნთებს მშობიარობისთვისაც მოამზადებს. თუ მუცელში დაჭიმულობას იგრძნობთ, მიიღეთ თბილი შხაპი — ეს თქვენც დაგამშვიდებთ და ბავშვსაც.') WHERE id = '3837da99-9708-4d97-b55a-0f688693e446';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამ კვირიდან თქვენი ბავშვი ზრდის ნახტომის ეტაპზე გადადის. ეს ნიშნავს, რომ მხოლოდ ამ კვირაში ბავშვი დაახლოებით 150 გრამს მოიმატებს. კვირის ბოლოს, კუნთების გაძლიერების, საშვილოსნოს გაზრდისა და მასში ამნიონური სითხის მატების გამო, თქვენი ბავშვი აქამდე არნახულად აქტიური გახდება. თუ ხანგრძლივ ღამის ძილს გეგმავთ, შესაძლოა ეს გეგმა ვერ განახორციელოთ. 😊 ამ ეტაპზე ბავშვი დღე-ღამეში დაახლოებით 18 საათს სძინავს, თუმცა ღამით უფრო აქტიურია. ამის მიზეზი ისაა, რომ დღის განმავლობაში თქვენი მოძრაობების გამო ამნიონური სითხე ირხევა და ბავშვს უფრო ადვილად ეძინება.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი თვალები მოძრაობს! 👀 მიუხედავად იმისა, რომ ქუთუთოები ჯერ კიდევ დახუჭული მაქვს, თვალები მათ ქვეშ სწრაფად მოძრაობს მარჯვნივ და მარცხნივ. ეს ნიშნავს, რომ სიზმრებს ვხედავ. ალბათ სიზმარში თქვენ გხედავთ. ფერადი სიზმრების სამყაროში ვარ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'სიმინდი'), body_changes_ka = COALESCE(body_changes_ka, 'ამ კვირებიდან შესაძლოა ქოშინი და ჰაერის უკმარისობის შეგრძნება დაგეწყოთ. ამის მიზეზია მზარდი საშვილოსნო და ჰორმონულ სისტემაში მიმდინარე ცვლილებები. ორსულობის პერიოდში ბავშვის ზრდასთან ერთად გაფართოებული საშვილოსნო დიაფრაგმას აწვება. ამასთანავე, განსაკუთრებით ორსულობის ბოლო პერიოდში, დიაფრაგმა დაახლოებით 4 სმ-ით ზემოთ იწევს. ეს ფილტვებზე ზეწოლას ახდენს და ჩასუნთქული ჰაერის მოცულობას ცვლის, რაც ქოშინს იწვევს.;;;
პროგესტერონის მიერ გააქტიურებული თავის ტვინის სუნთქვის ცენტრი ორსულობის განმავლობაში უფრო ხშირ და ღრმა სუნთქვას უზრუნველყოფს. ამის მიზანია პლაცენტისთვის დიდი რაოდენობით ჟანგბადის მიწოდება და ნახშირორჟანგის უფრო ინტენსიურად გამოდევნა. ყოველი ჩასუნთქვისას ფილტვებში ჩვეულებრივზე %30-40-ით მეტი ჰაერის შესვლა და გამოსვლა შეიძლება სუნთქვის გაძნელებისა და ქოშინის მიზეზი გახდეს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ფეხების შეშუპების შესამცირებლად დიდხანს ნუ დარჩებით ერთსა და იმავე პოზაში, ხოლო ჯდომისას ფეხები მაღლა შემოაწყვეთ. წელის ტკივილის დროს დაწექით მარცხენა გვერდზე და მუხლებს შორის ბალიში მოათავსეთ. განაგრძეთ ბევრი წყლის სმა, რადგან ეს შეშუპების თავიდან აცილებასაც უწყობს ხელს და სანაყოფე წყლების სისუფთავესაც უზრუნველყოფს. დღეს ცოტა დრო საკუთარ თავს დაუთმეთ და დამამშვიდებელ მუსიკას მოუსმინეთ.') WHERE id = 'fd7b3482-d799-4c13-953a-cf2d0bbea122';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ფორმირებადი კაპილარული სისხლძარღვებისა და ჯერ კიდევ არასაკმარისად გასქელებული კანის გამო, მისი სხეული მოვარდისფრო შეფერილობას იძენს. ამ დღეებში ბავშვს აქამდე დახშული ნესტოებიც გაეხსნება. ცხვირი არა მხოლოდ სუნთქვის უმნიშვნელოვანესი ნაწილია, არამედ მასში მდებარეობს ხუთი გრძნობიდან ერთ-ერთი — ყნოსვა. ყნოსვა გემოს შეგრძნებასთან ერთად ფუნქციონირებს. სწორედ ამიტომ, ორგანიზმში ინფექციის არსებობისას საკვების გემოს შეგრძნება შეიძლება დაქვეითდეს.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი კანი უკვე გამჭვირვალე აღარ არის! 🎨 დედიკო, ადრე რომ მიყურებდი, ჩემი ყველა სისხლძარღვი ჩანდა, ახლა კი კანი მისქელდება და ფერს იძენს. ცხიმოვანი შრის მატებასთან ერთად ჩემი კანი გაუმჭვირვალე ხდება. უკვე აღარ ვგავარ „უცხოპლანეტელს“ და ნამდვილ საყვარელ ბავშვს ვემსგავსები. როცა დამინახავ, მაშინვე შეგიყვარდები!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'სიმინდი'), body_changes_ka = COALESCE(body_changes_ka, 'დაახლოებით 1 თვის შემდეგ საშვილოსნოს ყელის სიგრძე ნელ-ნელა დაიწყებს შემცირებას. ორსულობის დროს საშვილოსნოს ყელის სიგრძე 14-28-ე კვირებს შორის სტაბილური რჩება, ხოლო 28-ე კვირის შემდეგ თანდათან მოკლებასა და გათხელებას იწყებს.;;;
ერთ-ერთი კვლევის თანახმად, იმ ქალების დაახლოებით ნახევარმა, რომელთაც 24-ე კვირაზე საშვილოსნოს ყელის სიგრძე 25 mm ან ნაკლები ჰქონდათ, 35-ე კვირამდე იმშობიარა.'), daily_tip_ka = COALESCE(daily_tip_ka, 'წელის ტკივილის შესამცირებლად დიდხანს ნუ იჯდებით ერთსა და იმავე პოზაში; ყოველ 30 წუთში ერთხელ ადექით და მსუბუქად გაიარ-გამოიარეთ. ღამით კომფორტულად დასაძინებლად მთლიანად მარცხენა გვერდზე დაწოლა გააუმჯობესებს როგორც თქვენს, ისე ბავშვის ჟანგბადით მომარაგებას. თუ წელის არეში მწვავე ტკივილი გაქვთ, აუცილებლად მიმართეთ ექიმს და განიხილეთ ორთოპედიული ქამრის გამოყენება.') WHERE id = '525f7e7c-0bea-4071-90df-5a46dae136d6';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ამოქმედებულმა ხმის იოგებმა შეიძლება დღის განმავლობაში დროდადრო სლოკინი გამოიწვიოს. შესაძლოა, ამას უკვე თავადაც გრძნობთ. თუ ბავშვი თანაბარი ინტერვალებით, გულისცემის მსგავს რიტმულ მოძრაობებს აკეთებს, ეს ნიშნავს, რომ მას ასლოკინებს. ბევრი ორსული ფიქრობს, რომ სლოკინი ბავშვს ზიანს აყენებს, თუმცა სინამდვილეში მას ბავშვის განვითარებისთვის დიდი მნიშვნელობა აქვს. სლოკინი შეიძლება რამდენიმე წუთში დასრულდეს, თუმცა ზოგჯერ ნახევარი საათიც გაგრძელდეს. ორგანოების ზრდისა და განვითარების გაგრძელების გამო დიაფრაგმა დროდადრო იკუმშება და სლოკინს იწვევს. შეიძლება ითქვას, რომ სლოკინი დიაფრაგმის ვარჯიშის ერთგვარი ფორმაა. ამგვარად დიაფრაგმა ბავშვის დაბადების შემდეგ საშვილოსნოს გარეთ სუნთქვისთვის ემზადება.'), baby_message_ka = COALESCE(baby_message_ka, 'ნესტოები მეხსნება! 👃 აქამდე ნესტოები დახშული მქონდა, დღეს კი იხსნება. ახლა უკვე შემიძლია ამნიონური სითხე ცხვირით უფრო თავისუფლად „ჩავისუნთქო“. ასე ჩემს სასუნთქ კუნთებს ვავარჯიშებ. ზოგჯერ, როცა სითხე ყელში გადამცდება, სლოკინი მეწყება. გრძნობ ამ „ტუკ-ტუკ“ მოძრაობებს?'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ყვავილოვანი კომბოსტო'), body_changes_ka = COALESCE(body_changes_ka, 'წელის ტკივილი შეიძლება გაძლიერდეს. მუცლის წინ წამოწევასთან ერთად წონასწორობის შესანარჩუნებლად უნებლიეთ წელს უკან ხრით. ეს ხერხემლის კუნთებს ძაბავს. დიდხანს ფეხზე დგომა ტკივილს აძლიერებს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'სუნთქვის გაძნელების შესამცირებლად ეცადეთ, გამართულად იჯდეთ, მხრები უკან გაშალოთ და გულმკერდი გახსნათ. კალციუმზე მოთხოვნილების დასაკმაყოფილებლად დღის განმავლობაში უპირატესობა მიანიჭეთ რძის პროდუქტებს ან მწვანეფოთლოვან ბოსტნეულს. თუ მუცლის კანი გექავებათ, დაიტენიანეთ ნატურალური ნუშის ან კაკაოს ზეთით. დღეს ცოტა დაისვენეთ და თქვენს ბავშვთან ერთად მომავალ ლამაზ დღეებზე იოცნებეთ.') WHERE id = '637acaae-ce43-494a-a7b1-a90cc43779c0';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ფილტვებში ფორმირებული სისხლძარღვების საშუალებით სისხლის მიმოქცევის მცირე წრე ვითარდება. თავდაპირველად მარჯვენა პარკუჭში დაგროვილი, ჟანგბადით ღარიბი და ნახშირორჟანგით მდიდარი სისხლი ფილტვის არტერიის საშუალებით ფილტვებს მიეწოდება. მარჯვენა და მარცხენა ფილტვებში მოხვედრილი სისხლი ნივთიერებათა ცვლის შედეგად ნახშირორჟანგს გამოყოფს, ჟანგბადს იღებს და იწმინდება. სისხლის მიმოქცევის მცირე წრე სრულდება, როდესაც გაწმენდილი სისხლი ფილტვის ვენით გულის მარცხენა წინაგულში ჩაედინება, შემდეგ კი აორტის საშუალებით მთელ სხეულში გადაიტუმბება.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი ხერხემალი ძალიან ძლიერია! 🦴 ჩემი ძვლები, სახსრები და იოგები იმდენად გამაგრდა, რომ უკვე შემიძლია სხეული სრულიად გამართულად დავიჭირო. წელს ვასწორებ და ვიჭიმები. ჩემი ხერხემალი მთავარი საყრდენია, რომელიც მომავალში გამართულად დამიჭერს. განაგრძე კალციუმის მიღება, ის ჯერ კიდევ ძალიან მჭირდება!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ყვავილოვანი კომბოსტო'), body_changes_ka = COALESCE(body_changes_ka, 'შეიძლება თვალების სიმშრალე ან მხედველობის დაბინდვა იგრძნოთ. ორსულობის ჰორმონები ცრემლის გამოყოფას ამცირებს. ამასთან, ორგანიზმში სითხის დაგროვებამ შეიძლება რქოვანას ფორმა ოდნავ შეცვალოს. სათვალის დიოპტრი შესაძლოა დროებით შეიცვალოს, ამიტომ ახალი სათვალის შეძენას ნუ იჩქარებთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ძილის დროს მუხლებს შორის ბალიშის მოთავსება წელის ტკივილს მნიშვნელოვნად ამცირებს. ეს ხერხემალს სწორ მდგომარეობაში ინარჩუნებს. ამასთან, ორსულობისას შედარებით მყარ ლეიბზე ძილი შეიძლება უფრო კომფორტული იყოს.') WHERE id = 'a0633b87-cd3d-42be-95e2-2574a37bda58';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამ კვირაში ექიმის მიერ ჩატარებული გამოკვლევის დროს შეიძლება დაინახოთ, როგორ იღიმება თქვენი ბავშვი. 😊 ისეთი მიმიკური მოძრაობები, როგორიცაა ენის გამოყოფა, სახის მოჭმუხვნა და გაღიმება, შეიძლება ჩაითვალოს ერთ-ერთ ნიშნად იმისა, რომ საშვილოსნოში ბავშვის ტვინის ქსოვილი საკმაოდ კარგად არის განვითარებული.;;;
ძლიერი სტრესის, ტრავმული მოვლენების ან თავს უბედურად გრძნობის დროს თქვენი ორგანიზმის მიერ გამოყოფილმა ჰორმონებმა შეიძლება ბავშვზე იმოქმედოს და მისი მოძრაობის შემცირება გამოიწვიოს.;;;
ასევე, როცა იცინით, ბედნიერი ან აღელვებული ხართ, თქვენს ორგანიზმში გამოყოფილი ჰორმონები სისხლის მეშვეობით, პლაცენტის გავლით, პირდაპირ ბავშვს აღწევს; ამან შეიძლება მისი გულისცემის აჩქარება, მოძრაობის გააქტიურება და თქვენზე რეაგირება გამოიწვიოს.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი ფილტვები ემზადება! 🌬️ ჩემს ფილტვებში დაიწყო სპეციალური ნივთიერების წარმოქმნა, რომელსაც "სურფაქტანტი" ეწოდება. ის დამეხმარება, რომ პირველი ჩასუნთქვისას ფილტვები გაიშალოს და ერთმანეთს არ მიეწებოს. ჯერ კიდევ წყალში ვარ, მაგრამ ეს მომავლისთვის ყველაზე მნიშვნელოვანი მომზადებაა. სუნთქვა თავისუფლებაა!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'სიმინდი'), body_changes_ka = COALESCE(body_changes_ka, 'შესაძლოა, დროდადრო თქვენი ძუძუებიდან სითხის გამოყოფა უკვე დაიწყო. ეს ნორმალურ მდგომარეობად მიიჩნევა და სანერვიულო არაფერია. ჰორმონებმა, რომლებიც ძუძუებს მშობიარობის შემდეგ რძის გამომუშავებისთვის ამზადებს, ორსულობის პერიოდში შეიძლება სითხის გამოყოფა და ძუძუებიდან რძის დენა გამოიწვიოს. წვეთების სახით გამოყოფილ ამ სითხეს, ჩვეულებრივი რძისგან განსხვავებით, ხსენი ეწოდება. ხსენი ჩვეულებრივ რძესთან შედარებით მეტ ცილას, ცხიმსა და ანტისხეულს შეიცავს.'), daily_tip_ka = COALESCE(daily_tip_ka, '24-ე კვირის დასრულება საკუთარი თავისთვის დროის დათმობით აღნიშნეთ! წელის ტკივილის შესამცირებლად უპირატესობა დაბალქუსლიან, ორთოპედიულ ფეხსაცმელს მიანიჭეთ. თუ ჯერ არ გაგიკეთებიათ, გლუკოზის დატვირთვის ტესტის შესახებ ექიმს გაესაუბრეთ. ღამით მარცხენა გვერდზე დაწოლა და დასვენება საუკეთესოა როგორც თქვენი, ისე ბავშვის სისხლის მიმოქცევისთვის.') WHERE id = 'f9782520-1096-410b-87b6-a06b825d2aa4';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის კაპილარული სისხლძარღვები ჩამოყალიბებას იწყებს. ბავშვის დანახვა რომ შეგეძლოთ, მისი თხელი კანის ქვეშ წარმოქმნილ სისხლძარღვებს საკმაოდ ადვილად გაარჩევდით. ეს სისხლძარღვები თავიდან ფეხის თითების წვერებამდე ყველა ორგანოსა და ქსოვილს აღწევს.;;;
მთელ სხეულში ქსელის სახით განლაგებული კაპილარების საერთო სიგრძემ, მათი ბოლოების ერთმანეთთან შეერთების შემთხვევაში, შესაძლოა 40 კილომეტრს გადააჭარბოს. ვინაიდან კაპილარებს სისხლძარღვებს შორის ყველაზე დიდი საერთო ზედაპირი აქვს, მათში სისხლის ნაკადის სიჩქარეც ყველაზე დაბალია.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი თმა ფერს იძენს! 🎨 აქამდე ჩემი თმა სრულიად თეთრი იყო, ახლა კი გენეტიკური კოდის შესაბამისად შეფერილობას იწყებს. შავი, ქერა, ყავისფერი... ნეტავ რა ფერის მექნება? იქნებ თქვენის მსგავსი, ან იქნებ მამასავით. ესეც სიურპრიზია!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'სიმინდი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობათა დაახლოებით 10% ნაადრევი მშობიარობით სრულდება. ამიტომ მნიშვნელოვანია, იცოდეთ, როგორ განასხვაოთ ნამდვილი მშობიარობის ნიშნები ცრუ მშობიარობის ნიშნებისგან.;;;
მშობიარობის დაწყების ნიშნები შეიძლება იყოს მუდმივი ან რეგულარული ინტერვალებით წარმოქმნილი ტკივილი, რომელიც ჩვეულებრივ წელის არეში იწყება, ხშირი და რიტმული შეკუმშვების შეგრძნება, მუცლის ქვედა ნაწილში ჭვალის მსგავსი ტკივილი, დიარეა და გულისრევა, საშოსა და სწორი ნაწლავის არეში ზეწოლის შეგრძნება, ვაგინალური გამონადენის რაოდენობის მკვეთრი მატება და სისხლდენა.;;;
ცრუ მშობიარობის შეკუმშვები რეგულარული ინტერვალებით არ ვითარდება. სხეულის მდგომარეობის შეცვლის ან მოძრაობისას ისინი ხშირად ქრება. ნამდვილი მშობიარობის შეკუმშვების დროს კი სხეულის მდგომარეობის შეცვლა და მოძრაობა ტკივილს არ ამსუბუქებს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ხელების დაბუჟების შესამცირებლად ისინი ხშირად შეანჯღრიეთ. ძილის დროს ეცადეთ, ხელები მოხრილი არ გქონდეთ. თუ კომპიუტერთან მუშაობთ, ხშირად შეისვენეთ. მშობიარობის შემდეგ ეს სიმპტომები გაივლის.') WHERE id = '5496d151-ca1f-41e0-a2f7-53fb1cdf1218';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'წოვის რეფლექსი, რომლის დროსაც ბავშვი პირის ირგვლივ და ლოყებზე შეხებისას პირს აღებს, ამ ეტაპზე უკვე საკმაოდ გაძლიერებულია. სიცოცხლის გასაგრძელებლად ბავშვს დედის რძის მიღების უნარი სჭირდება. ამიტომ ბავშვი წოვის რეფლექსის საშუალებით იკვებება ისე, რომ ამის სწავლება არავისგან სჭირდება. ბავშვმა წოვის რეფლექსი შეიძლება გამოიყენოს არა მხოლოდ საკვების მისაღებად, არამედ იმისთვისაც, რომ თავი უსაფრთხოდ იგრძნოს.;;;
თითქმის ყველა ბავშვი ძლიერი წოვის რეფლექსით იბადება. ბავშვებში ამ რეფლექსის არარსებობა შესაძლოა ძალიან სერიოზულ მიზეზებზე მიუთითებდეს. ვინაიდან წოვის რეფლექსი შეიძლება გააქროს სამშობიარო ტრავმამ, თავის ტვინის ჟანგბადის დეფიციტმა, ტვინის ღეროს დარღვევებმა, ნერვული სისტემის პრობლემებმა და ისეთმა მძიმე ინფექციებმა, როგორიცაა მენინგიტი, აუცილებელია ამ ბავშვებზე ყურადღებით დაკვირვება.'), baby_message_ka = COALESCE(baby_message_ka, 'როცა მეშინია, ვკრთები! 😯 ჩემი რეფლექსები ძალიან გამძაფრებულია. მოულოდნელი ხმის გაგონებისას მთელი სხეულით ვკრთები. ამას "შეკრთომის რეფლექსს" უწოდებენ. თქვენც შეიძლება იგრძნოთ მუცელში უეცარი ბიძგი. როცა შემეშინდება, მუცელზე ხელი მომისვით და მშვიდად მელაპარაკეთ — მაშინვე დავმშვიდდები.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'სიმინდი'), body_changes_ka = COALESCE(body_changes_ka, 'თუ საშარდე გზების ინფექცია არ იმკურნალება და პროგრესირებს, მან შესაძლოა ნაადრევი მშობიარობა გამოიწვიოს. საშარდე გზების ინფექციის უმნიშვნელოვანესი ნიშნებია შარდვის დროს წვა და ხშირი შარდვა. თუმცა, ინფიცირებული უბნის მდებარეობის მიხედვით, ინფექცია შეიძლება ყოველგვარი სიმპტომის გარეშეც პროგრესირებდეს. საშარდე გზების ინფექციას, ჩვეულებრივ, ანტიბიოტიკებით მკურნალობენ და მკურნალობის დაწყებიდან მალევე ანთება შემცირებას იწყებს. თუმცა საშარდე გზების განმეორებითმა ინფექციებმა შესაძლოა ანტიბიოტიკების უფრო მაღალი დოზებით მკურნალობა მოითხოვოს.;;;
თუ საშარდე გზების ინფექცია გაქვთ, დიდი რაოდენობით წყლის დალევა ორგანიზმიდან ბაქტერიების გამოდევნას უწყობს ხელს. ამიტომ დღეში სულ მცირე 2 ლიტრი სითხის მიღებით შეგიძლიათ ხელი შეუშალოთ ბაქტერიების გამრავლებასა და ინფექციის პროგრესირებას. გამოჯანმრთელების დასაჩქარებლად შესაძლოა სასარგებლო იყოს შესაბამისი მცენარეული ჩაის მიღებაც.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ფეხებზე ზეწოლის შესამცირებლად დღის განმავლობაში ხშირად შეიცვალეთ სხეულის მდგომარეობა და, შეძლებისდაგვარად, დაისვენეთ გულის დონეზე მაღლა აწეული ფეხებით. ეს შეშუპების თავიდან აცილებაშიც დაგეხმარებათ. მაგნიუმით მდიდარი საკვები კუნთების კრუნჩხვებს ამცირებს. ამ საღამოს მშვიდ გარემოში მოუყევით თქვენს ბავშვს იმ პირველი გასეირნების შესახებ, რომელიც მომავალში ერთად გექნებათ.') WHERE id = '6533fb18-848f-4cc6-b4c7-bf0dc1cff401';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'საშვილოსნოში ყოფნისას ბავშვის ტვინი იმაზე მეტ ნეირონს წარმოქმნის, ვიდრე საჭიროა. დაბადების შემდეგ კი გამოუყენებელი და სტიმულაციის გარეშე დარჩენილი ნეირონები პროცესის შედეგად ქრება, რომელსაც „გასხვლა“ ეწოდება.;;;
ტვინში არსებული 100 მილიარდი ნეირონიდან თითოეული ათასობით სხვა ნეირონთან ქმნის სპეციალურ საკონტაქტო წერტილებს. ორი-სამი წლის ასაკში ამ კავშირების რაოდენობა დაახლოებით 15.000-ს აღწევს. ტვინი, სუნთქვისა და გულისცემის მსგავსი სასიცოცხლო პროცესების გარდა, აზროვნების, დამახსოვრებისა და მეტყველების მსგავს უმაღლეს ფუნქციებსაც არეგულირებს.;;;
ყველა განსხვავებული ზედაპირი, რომელსაც თქვენი ბავშვი ეხება, ყოველი სუნი, რომელსაც შეიგრძნობს, და ყოველი ხმა, რომელიც ესმის, ამ ნერვული კავშირების ჩამოყალიბებას უწყობს ხელს. ამ კავშირების გაძლიერება და შენარჩუნება კი ამ სტიმულების რეგულარულ გამეორებაზეა დამოკიდებული.'), baby_message_ka = COALESCE(baby_message_ka, 'გამარჯობა, დედიკო! მე ტკბილი წიწაკის ზომის ვარ. ჩემი ნერვები ვითარდება. სპეციალური ნივთიერება, სახელად „მიელინი“, ჩემს ნერვებს გარს ეხვევა. მისი წყალობით ჩემი ტვინიდან სხეულისკენ გაგზავნილი სიგნალები უფრო სწრაფად მიაღწევს დანიშნულების ადგილს. მე ყოველდღე უფრო ჭკვიანი ვხდები!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ტკბილი წიწაკა'), body_changes_ka = COALESCE(body_changes_ka, 'თქვენი ორსულობა უკვე გარეგნულადაც შესამჩნევია. მთელი ორსულობის განმავლობაში საშვილოსნო იზრდება, რათა ბავშვისთვის, პლაცენტისა და სანაყოფე წყლებისთვის საკმარისი ადგილი უზრუნველყოს, ხოლო ორსულობის ბოლოს მისი წონა დაახლოებით 1100 გრამს აღწევს. ეს საშვილოსნოს ნორმალურ წონაზე თითქმის 20-ჯერ მეტია. მოცულობის მხრივ კი მშობიარობის მოახლოებისას მისი ტევადობა დაახლოებით 5 ლიტრს აღწევს და ჩვეულებრივ მოცულობას 500-1000-ჯერ აღემატება. ეს ზრდა საშვილოსნოს შემადგენელი გლუვი კუნთოვანი უჯრედების რაოდენობის კი არა, მათი ზომის მატების ხარჯზე ხდება.;;;
ორსულობის პირველ თვეებში საშვილოსნო მსხლისებრ ფორმას ინარჩუნებს, თუმცა მე-12 კვირისთვის უკვე სფეროს ფორმას იღებს და მენჯის ძვლებს სცდება. ამ კვირის შემდეგ საშვილოსნო ისეთ ზომას აღწევს, რომ მისი შეგრძნება წინ, ბოქვენის ძვლის ზემოთ, უკვე შესაძლებელია. მომდევნო კვირებში კი მუცლის ღრუში წინსვლისთვის ოვალური ფორმით ზემოთ იზრდება. ზრდის გაგრძელებასთან ერთად ის მუცლის წინა კედელს ეყრდნობა, ნაწლავებს გვერდებისა და ზემოთკენ გადაადგილებს და ღვიძლამდე აღწევს.'), daily_tip_ka = COALESCE(daily_tip_ka, '18-კვირიანი გზა მცირე გასეირნებით აღნიშნეთ! წელის ტკივილის შესამცირებლად ეცადეთ, აუცილებლად სწორად იჯდეთ და კომფორტული ფეხსაცმელი ატაროთ. ძილისას აუცილებლად მარცხენა გვერდზე დაწექით — ეს დადებითად მოქმედებს როგორც ბავშვისკენ სისხლის მიმოქცევაზე, ისე თქვენი თირკმელების მუშაობაზე. არ დაგავიწყდეთ ბევრი სითხისა და კალციუმის მიღება (რძე, იოგურტი, ნუში).') WHERE id = 'b73aa0c0-fb01-4c2d-abb0-69a88e7c97e4';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის წონის ასეთი სწრაფი მატების მთავარი მიზეზებია კუნთოვანი და ძვლოვანი მასის განვითარება, ახალი ცხიმოვანი ქსოვილის წარმოქმნა და ორგანოების ზრდა. მოძრაობისას განვითარებული ხელებისა და ფეხების კუნთები უფრო ძლიერ მოძრაობებს განაპირობებს, ეს მოძრაობები კი, თავის მხრივ, კუნთების შემდგომ განვითარებას უწყობს ხელს — ასე იქმნება უწყვეტი ციკლი. ცხიმოვანი ქსოვილის მატებასთან ერთად ბავშვის ლოყები მრგვალდება. ამის წყალობით მისი სახის ნაკვთები თანდათან უფრო მკაფიოდ ყალიბდება. დეტალური ულტრაბგერითი გამოკვლევისას, თუ ბავშვი ხელსაყრელ პოზაშია, შესაძლოა ისიც კი დაინახოთ, ვის ჰგავს. 😊;;;
თქვენი ბავშვის სმენა უკვე საკმაოდ მგრძნობიარეა და მას დაბალი სიხშირის ბგერების გაგონებაც კი შეუძლია. ის თქვენს ხმას სხვა ხმებისგან ძალიან ადვილად არჩევს. თქვენი ხმის გაგონებისას მისი გულისცემა ჩქარდება, თავს უსაფრთხოდ გრძნობს და შესაძლოა ძლიერი მოძრაობითაც კი გიპასუხოთ, თითქოს გიჩვენებთ, რომ თქვენი ხმა გაიგონა.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი სახე უკვე მზადაა! 👶 დედიკო, ახლა რომ დაგენახე, ზუსტად გეცოდინებოდა, როგორი ვიქნები დაბადებისას. ჩემი სახის ნაკვთები, ცხვირი, ტუჩები — ყველაფერი ჩამოყალიბებულია. უბრალოდ ჯერ კიდევ ცოტა გამხდარი ვარ. ვის ვგავარ? შენ თუ მამას?'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'სიმინდი'), body_changes_ka = COALESCE(body_changes_ka, 'ამ ეტაპამდე 5500 გრამიდან 8500 გრამამდე უნდა გქონდეთ მომატებული. თუ ფიქრობთ, რომ ამ მაჩვენებელზე მეტი წონა მოიმატეთ, ყურადღების გამოჩენა ხელს შეუწყობს როგორც თქვენთვის, ისე თქვენი ბავშვისთვის შესაძლო პრობლემების თავიდან აცილებას.;;;
ნორმაზე მეტმა წონის მატებამ შეიძლება ორსულობის არაჯანსაღად მიმდინარეობას შეუწყოს ხელი და ორსულთა ჰიპერტენზიისა და გესტაციური დიაბეტის მსგავსი დაავადებების განვითარების რისკი გაზარდოს. გარდა ამისა, ეს ზედმეტი წონა შეიძლება მშობიარობის შემდეგ რთულად დასაკლებ, ხანგრძლივად შენარჩუნებულ კილოგრამებად დაგრჩეთ.;;;
თუ ორსულობამდე არც ჭარბი წონა გქონდათ და არც ძალიან გამხდარი იყავით, პირველ ტრიმესტრში ბავშვისთვის დამატებითი კალორიების მიღება არ გჭირდებათ. მეორე ტრიმესტრში კი საკმარისია, ყოველდღიურ კალორიულობას დამატებით 300 კალორია შემატოთ. ორსულობის ბოლო ტრიმესტრში ეს გაზრდილი მოთხოვნილება დაახლოებით 450 კალორიამდე ადის. ეს დღეში დამატებით ორი-სამი ულუფა ხილის, 2 ჭიქა დაბალცხიმიანი რძის, 1 დიდი ჯამი იოგურტის, 60 გრამი ნუშის ან 45 გრამი კარაქის ეკვივალენტურია.'), daily_tip_ka = COALESCE(daily_tip_ka, 'თვალები დაასვენეთ. თუ კომპიუტერთან დიდხანს მუშაობთ, ხშირად შეისვენეთ. „ხელოვნური ცრემლის“ წვეთები (ბუნებრივი შემადგენლობით) თვალის სიმშრალის შემსუბუქებაში დაგეხმარებათ.') WHERE id = '64f0cdbb-7db6-482f-be9f-92435bab2ca8';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის გემოს შეგრძნება უკვე საკმაოდ კარგად არის განვითარებული. გემოს აღქმა ენაზე არსებული რეცეპტორების მეშვეობით ხდება. რეცეპტორებად წოდებული გემოვნების კვირტები პაპილებად წოდებულ სტრუქტურებში მდებარეობს. პაპილები ენის ზედაპირზე განლაგებული უსწორმასწორო პატარა ამობურცულობებია.'), baby_message_ka = COALESCE(baby_message_ka, '🌽 მე სიმინდის ზომის ვარ! ეს კვირა ძალიან მნიშვნელოვანია, დედიკო. ექიმები ამბობენ, რომ ახლა უკვე „სიცოცხლისუნარიანად“ ვითვლები. ანუ ახლა რომ დავიბადო, თანამედროვე მედიცინის დახმარებით გადარჩენის შანსი მაქვს (მაგრამ ჯერ ძალიან ადრეა, აქ დარჩენა მინდა!). ეს ძალიან მნიშვნელოვანი ეტაპია!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'სიმინდი'), body_changes_ka = COALESCE(body_changes_ka, 'სწრაფად მზარდი მუცლის, ხშირი შარდვისა და სუნთქვის გაძნელების გამო შესაძლოა ძილის პრობლემები დაგწყებოდათ. ამასთან, ზედიზედ გატარებულმა უძილო ღამეებმა შეიძლება თავი თანდათან უფრო დაღლილად გაგრძნობინოთ.;;;
ამ პერიოდში ტუალეტში ხშირად სიარულის საჭიროება უძილობის ერთ-ერთი მთავარი მიზეზია. პროგესტერონის დონის მატება და საშვილოსნოს ზრდა შარდის ბუშტზე ზეწოლას აძლიერებს, რაც მოშარდვის გახშირებას იწვევს. გარდა ამისა, უძილობის მიზეზი შეიძლება გახდეს ისეთი ჩივილებიც, როგორიცაა შეშუპება, მოუსვენარი ფეხების სინდრომი, გულძმარვა და საჭმლის მონელების პრობლემები.;;;
ვახშმის ადრე მიღება, ცხიმიანი და ცხარე საკვებისგან თავის შეკავება, ძილის წინ თბილი შხაპის მიღება და რძის დალევა უფრო მშვიდად დაძინებაში დაგეხმარებათ. ხშირი შარდვის შესამცირებლად მისაღები წყლის უდიდესი ნაწილი დღის განმავლობაში დალიეთ და ეცადეთ, საღამოს ბევრი წყალი არ მიიღოთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'სხეულის ტემპერატურის მატებამ შესაძლოა წყურვილი გაგიძლიეროთ, ამიტომ წყლის რეგულარულად დალევა ჩვევად აქციეთ. ნეკნების ტკივილის შესამსუბუქებლად ხელები მაღლა ასწიეთ და ღრმად ჩაისუნთქეთ — ეს ამ არეს გაფართოებაში დაგეხმარებათ. თუ წელის არეში სიმძიმეს გრძნობთ, უპირატესობა მიანიჭეთ არც ისე რბილ საწოლზე ძილს. დღეს ზედმეტად ნუ გადაიღლებით — ცოტაოდენი წაიკითხეთ და დაისვენეთ.') WHERE id = '88964348-70ed-4f53-a6a4-d8d7da7286ff';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'სიცოცხლისუნარიანობის ზღვარს მიღწეული თქვენი ბავშვის ზურგის ტვინი, რომელიც ყველა ნერვულ მოძრაობას აკონტროლებს, საკმაოდ განვითარებულია და ჩამოყალიბებას განაგრძობს.;;;
ზურგის ტვინის სტრუქტურაში გარეთა შრე თეთრი ნივთიერებისგან, შიგნითა კი რუხი ნივთიერებისგან შედგება. ზურგის ტვინის გარედან გარშემომყოფი თეთრი ნივთიერება მიელინის გარსით დაფარული ნერვებისგან შედგება, ხოლო რუხი ნივთიერება — ნერვული უჯრედებისგან, რომლებსაც მიელინის გარსი არ აქვთ. ზურგის ტვინის ერთ-ერთი უმნიშვნელოვანესი ფუნქცია მოგრძო ტვინიდან მომავალი რეფლექსების მართვა და თავის ტვინიდან წამოსული ნებითი მოძრაობების შესრულების უზრუნველყოფაა. ხერხემლის სვეტში სულ 33 მალისგან შედგება. დარტყმებისა და ტრავმებისგან ზურგის ტვინის დასაცავად მალებს შორის მოთავსებულია ნივთიერება, რომელსაც თავ-ზურგტვინის სითხე ეწოდება.'), baby_message_ka = COALESCE(baby_message_ka, 'მე ყვავილოვანი კომბოსტოს ზომის ვარ! ახლა სწრაფად ვიმატებ წონას. ჩემს კანზე ნაოჭები მცირდება, ლოყები კი მევსება. უკვე საყვარელ ბავშვს ვგავარ. ჩემი თმის ფერი და სტრუქტურაც უკვე განსაზღვრულია.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ყვავილოვანი კომბოსტო'), body_changes_ka = COALESCE(body_changes_ka, 'არ დაგავიწყდეთ სისხლისა და შარდის ანალიზების რეგულარულად ჩატარება. ყოველთვიური სისხლის ანალიზები ხელს უწყობს ისეთი პრობლემების თავიდან აცილებას, როგორებიცაა რკინის შესაძლო დეფიციტი, მანამდე გამოუვლენელი და ორსულობის დროს გააქტიურებული ფარისებრი ჯირკვლის დაავადებები, შეუმჩნეველი სისხლის შეუთავსებლობა, ტოქსოპლაზმოზისა და წითურას მსგავსი ინფექციები, ჰეპატიტი და ფარული საშარდე გზების ინფექციები.;;;
ფარისებრი ჯირკვლის გამოუვლენელი დაავადებები პირდაპირ მოქმედებს თქვენს მეტაბოლიზმზე და, შესაბამისად, შეიძლება ბავშვის განვითარებაზეც უარყოფითად აისახოს. ორსულობის პირველი 12 კვირის განმავლობაში ბავშვის ფარისებრი ჯირკვალი ჯერ სრულად არ არის განვითარებული და ჰორმონებს ვერ გამოიმუშავებს, ამიტომ თქვენ მიერ გამომუშავებული ჰორმონების ნაწილი ბავშვს გადაეცემა. 12 კვირის შემდეგ და განსაკუთრებით ორსულობის მესამე ტრიმესტრში, პლაცენტის მიერ გამოყოფილი ზოგიერთი ჰორმონის გამო, TSH-ის დონე თანდათან იმატებს.;;;
ორსულობის დროს გამოვლენილი ფარული საშარდე გზების ინფექციები ადრეულ ვადაზე მუცლის მოშლის ერთ-ერთი ყველაზე გავრცელებული მიზეზია. ამიტომ შარდის საერთო ანალიზის რეგულარულად ჩატარება აუცილებელია.'), daily_tip_ka = COALESCE(daily_tip_ka, 'წელის ტკივილის შესამცირებლად დიდხანს ნუ დარჩებით ერთსა და იმავე პოზაში და უპირატესობა მიანიჭეთ ორთოპედიულ, კომფორტულ ფეხსაცმელს. თუ მუცლის არეში ქავილი ან დაჭიმულობა გაქვთ, არ დაგავიწყდეთ დამატენიანებელი ზეთების გამოყენება. დალიეთ ბევრი წყალი და გაზარდეთ რაციონში ბოჭკოვანი საკვების რაოდენობა, რათა საჭმლის მომნელებელი სისტემა განიტვირთოს. დღეს მიეცით საკუთარ თავს ჩვეულებრივზე მეტი დასვენების უფლება.') WHERE id = '3d485358-4a99-4889-8e24-ba3824e8665d';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ტვინის სწრაფ განვითარებასთან ერთად ყალიბდება რთული შრეები — ტვინის გარსები, რომლებიც მას ყველა მხრიდან აკრავს და იცავს. სამი შრისგან შემდგარი ეს გარსები თავის ქალასთან ერთად მტკიცე "ჯავშნის" როლს ასრულებს და ტვინს გარეგანი ზემოქმედებისგან იცავს. ეს დამცავი სისტემა ზურგის ტვინის მიდამომდე გრძელდება და ცენტრალური ნერვული სისტემის ყველა ნაწილს იცავს. თქვენი ბავშვის ტვინში ორი ძირითადი სტრუქტურა ვითარდება:;;;
რუხი ნივთიერება: ნაწილი, რომელშიც ნერვული უჯრედებია თავმოყრილი და რომლის წარმოქმნაშიც ტვინის გარსები მონაწილეობს.;;;
თეთრი ნივთიერება: მიელინის გარსით დაფარული გრძელი ნერვული ბოჭკოები, რომლებიც ნერვული სისტემის ნაწილებს შორის კავშირს უზრუნველყოფს.;;;
ყველაზე საინტერესო კი თავის ტვინის ქერქია. მიუხედავად იმისა, რომ მისი სისქე მხოლოდ 3 mm-ია, ტვინის ნერვული უჯრედების სამი მეოთხედი სწორედ აქ მდებარეობს. ამდენი უჯრედის ასეთ მცირე სივრცეში მოსათავსებლად თავის ტვინის ქერქს ღრმა ღარებით დაფარული, დანაოჭებული სტრუქტურა აქვს.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი კაპილარები სისხლით ივსება! 🩸 ჩემი კანის ქვეშ ათასობით წვრილი სისხლძარღვი წარმოიქმნება და სისხლით ივსება. სწორედ ეს აძლევს ჩემს კანს ლამაზ ვარდისფერ შეფერილობას. ჩემი სისხლის მიმოქცევა იმდენად ძლიერია, რომ გული მთელ სხეულს ჟანგბადით ამარაგებს. სიცოცხლით სავსე ვარ, დედიკო!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ყვავილოვანი კომბოსტო'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის პერიოდში კანის მოვლას განსაკუთრებული ყურადღებით უნდა მოეკიდოთ. ორსულობის პირველ და ბოლო ტრიმესტრებში კანის ბუნებრივი ცხიმის — სებუმის — გამოყოფა იმატებს, ამიტომ აკნესადმი მიდრეკილება შეიძლება იმ ქალებსაც კი გაუჩნდეთ, რომლებსაც ჩვეულებრივ ეს პრობლემა არ აქვთ. ამ პერიოდში კანი ქიმიური ნივთიერებებისგან თავისუფალი, ორგანული და უსაფრთხო გამწმენდი საშუალებებით უნდა გაიწმინდოთ. ამასთანავე, დაიცავით კანი მზისგან და რეგულარულად დაიტენიანეთ ორსულობისთვის შესაფერისი შემადგენლობის მქონე დამატენიანებელი საშუალებებით.;;;
გარდა ამისა, სოკოვანი ინფექციების თავიდან ასაცილებლად შხაპის შემდეგ კარგად გაიმშრალეთ ყურის შიდა და უკანა ნაწილები, კისერი, იღლიები, მკერდებს შორის და მათ ქვეშ არსებული ადგილები, ჭიპის ღრმული, საზარდულის მიდამო და ფეხის თითებს შორის სივრცეები. უპირატესობა მიანიჭეთ ბამბის შემცველ საცვლებსა და წინდებს.'), daily_tip_ka = COALESCE(daily_tip_ka, '25-კვირიანი გზის წარმატებით გავლის აღსანიშნავად დღეს სასიამოვნო გარემო შეუქმენით საკუთარ თავს. ფეხების შეშუპების შესამცირებლად, გაშლისას მათ ქვეშ ბალიში მოათავსეთ. დალიეთ ბევრი წყალი და ამასთანავე ოდნავ შეამცირეთ მარილის მიღება. თუ ჯერ არ გაგიკეთებიათ, ექიმთან ერთად დაგეგმეთ გლუკოზით დატვირთვის ტესტი. ხვალ ახალ, 26-ე კვირას ვიწყებთ!') WHERE id = '2ee2955f-80d8-4cff-afab-c01bdb172368';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'გახსნილი ნესტოების წყალობით თქვენი ბავშვი პერიოდულად ჩასუნთქვა-ამოსუნთქვას ავარჯიშებს. ეს სავარჯიშო მოძრაობები სასუნთქი სისტემის განვითარებას უწყობს ხელს. სასუნთქი სისტემა თანმიმდევრულად შედგება ცხვირის, ხახის, ხორხის, სასულესა და ფილტვებისგან. ცხვირი ჰაერის მიღებას უზრუნველყოფს. მის შიდა ზედაპირზე არსებული ბუსუსოვანი სტრუქტურები და ლორწოვანი ეპითელიუმი ცხვირის ღრუს ტენიანობას ინარჩუნებს, რაც ორგანიზმს ინფექციებისგან იცავს. ხახა მიღებულ ჰაერს სასულეში ატარებს, ხოლო სასულე, რომელსაც "ტრაქეას" უწოდებენ, ჰაერს ფილტვებისკენ მიმართავს. სასულის შიგნით არსებული მოციმციმე ეპითელური ქსოვილის მიერ გამომუშავებული ლორწოს (მუკუსის) მეშვეობით ჰაერი გავლისას ტენიანდება, ფილტვები კი ინფექციებისგან არის დაცული.'), baby_message_ka = COALESCE(baby_message_ka, 'მე ხელს მიზანმიმართულად ვიყენებ! 🖐️ დედიკო, უკვე უბრალოდ შემთხვევით მოძრაობებს აღარ ვაკეთებ. მე ვირჩევ, რომელ ხელს უფრო ხშირად გამოვიყენებ. ანუ უკვე განსაზღვრულია, ცაცია ვიქნები თუ მემარჯვენე. თითებს ვამოძრავებ და ჭიპლარს ვეჭიდები.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ყვავილოვანი კომბოსტო'), body_changes_ka = COALESCE(body_changes_ka, 'ამ კვირისთვის თქვენს ორგანიზმში სისხლის საერთო მოცულობა დაახლოებით 25%-ით არის გაზრდილი. ბავშვის სისხლზე გაზრდილი მოთხოვნილების დასაკმაყოფილებლად აუცილებელია საშვილოსნოსკენ მიმავალი სისხლის რაოდენობის მატება. ორსულობის ბოლო კვირებში საშვილოსნოსკენ სისხლის ნაკადმა შეიძლება წუთში 1 ლიტრს მიაღწიოს. სისხლის მოცულობის ზრდის კიდევ ერთი მიზეზი მშობიარობის დროს სისხლის მოსალოდნელი დანაკარგია. ვაგინალური მშობიარობისას იკარგება 500-750 ml სისხლი, ხოლო საკეისრო კვეთის დროს ამ რაოდენობამ შეიძლება 1000 ml-ს მიაღწიოს. მშობიარობისას გაკეთებული ჭრილობებისა და მშობიარობის შემდგომი სისხლდენის გათვალისწინებით, ორგანიზმი სისხლის ასეთი მნიშვნელოვანი დანაკარგისთვის მზად უნდა იყოს.;;;
თუმცა, სისხლის მოცულობის მატების მიუხედავად, კვირების მატებასთან ერთად გადიდებული საშვილოსნო, განსაკუთრებით ზურგზე წოლისას, გულში დაბრუნებული სისხლის რაოდენობას ამცირებს. ამიტომ მარჯვენა ან მარცხენა გვერდზე წოლა უკვე ძალიან მნიშვნელოვანია როგორც თქვენი, ისე თქვენი ბავშვის ჯანმრთელობისთვის.'), daily_tip_ka = COALESCE(daily_tip_ka, 'თუ ქუთუთოებზე ან ფეხებზე უეცარ და ძლიერ შეშუპებას შეამჩნევთ, აუცილებლად აცნობეთ ექიმს (არტერიული წნევის შესამოწმებლად). ქოშინის შესამცირებლად შეეცადეთ გამართულად იჯდეთ და მსუბუქი სუნთქვითი ვარჯიშები შეასრულოთ. შეამცირეთ საკვებში მარილის რაოდენობა, თუმცა წყლის მიღება სტაბილურად განაგრძეთ. დღეს მოუყევით ბავშვს მისი მომავალი ოთახის ან სათამაშოების შესახებ.') WHERE id = 'd74fd8bf-8b0d-4ea8-8d39-905a3d36166e';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ფილტვებში არსებული ალვეოლები განვითარებას განაგრძობს. ალვეოლები ფილტვებში განლაგებული ურიცხვი ბრონქიოლის ბოლოებში არსებული, ყურძნის მტევნის მსგავსი ჰაერის პარკუჭებია. სწორედ აქ მიმდინარეობს აირთა ცვლა — ჟანგბადის სისხლში გადასვლა და ნახშირორჟანგის გამოდევნა. ისინი ასევე ძალიან თხელი გარსით არის დაფარული. ალვეოლებში ჰაერსა და კაპილარულ სისხლძარღვებში არსებულ სისხლს შორის ბარიერის საერთო სისქე მხოლოდ 4 მიკრომეტრია. ეს სისქე ერთი ერითროციტის რადიუსის ტოლია. ბარიერის უკიდურესი სითხელე უზრუნველყოფს, რომ ორივე მიმართულებით მიმდინარე აირთა ცვლა ძალიან სწრაფი და ეფექტური იყოს. გარდა ამისა, ჩასუნთქვისა და ამოსუნთქვის დროს ალვეოლები იხსნება და იხურება. ისინი დაფარულია ნივთიერებით, რომელსაც სურფაქტანტი ეწოდება და რომელიც ალვეოლებში ჰაერის პარკუჭების გახსნა-დახურვას უწყობს ხელს. ამ ნივთიერების წყალობით ამოსუნთქვისას პარკუჭები ბოლომდე არ იჩუტება და ფილტვებში ზედაპირული დაჭიმულობა რეგულირდება.'), baby_message_ka = COALESCE(baby_message_ka, 'თქვენს სურნელს ვგრძნობ! 👃 ამნიონური სითხის სუნი იმის მიხედვით იცვლება, თუ რას მიირთმევთ და როგორია გარემო. ჩემი ყნოსვა იმდენად განვითარებულია, რომ ამ ცვლილებებს ვგრძნობ. როცა დავიბადები, თქვენს სურნელს ათასობით ადამიანის შორისაც ამოვიცნობ. დედის სურნელი — მსოფლიოში ყველაზე მშვენიერი არომატია.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ყვავილოვანი კომბოსტო'), body_changes_ka = COALESCE(body_changes_ka, 'თუ ორსულობის პერიოდში მაღალი არტერიული წნევა გაქვთ, ამის შესახებ აუცილებლად უნდა აცნობოთ თქვენს ექიმს.;;;
მაღალი არტერიული წნევის დროს პლაცენტისკენ სისხლის ნაკადი ნელდება. ეს კი ნიშნავს, რომ ბავშვმა შესაძლოა მისთვის საჭირო ჟანგბადი და საკვები ნივთიერებები ვერ მიიღოს. შედეგად, საშვილოსნოში ბავშვის განვითარება შეიძლება შეფერხდეს. არტერიული წნევის მომატების მიზეზებს შორის შეიძლება იყოს ორსულობამდე არსებული ჰიპერტენზია, 35 წლის ან მეტი ასაკი, ჭარბი წონა, მრავალნაყოფიანი ორსულობა და იმუნური სისტემის დარღვევები.;;;
თუ მაღალ არტერიულ წნევას თან ახლავს ძლიერი ტკივილი, წონის სწრაფი მატება, ხელებისა და სახის შეშუპება ან მხედველობის დაბინდვა, დაუყოვნებლივ უნდა მიმართოთ ექიმს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'კუჭის გადავსების შეგრძნების შესამცირებლად დიდი ულუფების ნაცვლად დღეში 5-6-ჯერ, მცირე ულუფებით იკვებეთ. წელის დატვირთვის შესამსუბუქებლად ჯდომისას გამოიყენეთ ზურგის საყრდენი ბალიშები და გამართულად იჯექით. შეკრულობის თავიდან ასაცილებლად რაციონში გაზარდეთ უმი ბოსტნეულისა და ხილის რაოდენობა. დღეს საღამოს ფეხები ოდნავ მაღლა შემოაწყვეთ და მშვიდი მუსიკის ფონზე დაისვენეთ.') WHERE id = 'ed58011e-092e-41ea-a45c-df149cb7fc4b';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენს ბავშვს უკვე შეუძლია საშვილოსნოში თვალების გახელა! ქუთუთოებმა, რომლებიც ამ ეტაპამდე დახურული იყო, უკვე შეიძინა გახსნის უნარი. ქუთუთოები მნიშვნელოვანი დამცავი სისტემაა: ისინი თვალს გარეგანი ზემოქმედებისგან იცავს, ცრემლის თანაბრად განაწილებით გამოშრობას უშლის ხელს და შემომავალი სინათლის რაოდენობას არეგულირებს.;;;
ქუთუთოების რამდენიმე საინტერესო თავისებურება: სპეციალური კუნთის წყალობით ზედა ქუთუთო ქვედასთან შედარებით უფრო მოძრავია. ზედა და ქვედა ქუთუთოების კუნთები საპირისპიროდ მოქმედებს, რაც თვალების სრულად დახუჭვას უზრუნველყოფს. ქუთუთოები მოძრაობს როგორც ნებაყოფლობით, ისე რეფლექსურად. თვალის ხამხამის რეფლექსი ცრემლს თვალის ზედაპირზე ანაწილებს და მის ნორმალურ ფუნქციონირებას უზრუნველყოფს.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი ცხიმოვანი შრე იზრდება! 🧈 სხეულზე ნაოჭები ნელ-ნელა მისწორდება, რადგან მათ ქვეშ ცხიმი გროვდება. ახლა უფრო გლუვი და რბილი ვჩანვარ. ეს ცხიმოვანი შრე სითბოს შემინარჩუნებს. როცა ხელში ამიყვანთ, ძვლიანი კი არა, "ფუმფულა" ვიქნები. თქვენი რძით კიდევ უფრო გავიზრდები.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ყვავილოვანი კომბოსტო'), body_changes_ka = COALESCE(body_changes_ka, 'ამ კვირისთვის გლუკოზის დატვირთვის ტესტი უკვე ჩატარებული უნდა გქონდეთ. თუ შედეგები ზღვრულ მაჩვენებლებზე მაღალია, შესაძლოა გესტაციური დიაბეტის დიაგნოზი დაგისვეს.;;;
ორსულობის დროს ორგანიზმს მეტი ინსულინი სჭირდება. თუმცა ჰორმონულმა ცვლილებებმა შესაძლოა უჯრედების ინსულინის მიმართ მგრძნობელობა შეამციროს. ჩვეულებრივ, სისხლში შაქრის დონის მატებისას კუჭქვეშა ჯირკვალი საპასუხოდ მეტ ინსულინს გამოყოფს. მაგრამ როდესაც კუჭქვეშა ჯირკვალი სისხლში შაქრის დონის დასაქვეითებლად საკმარის ინსულინს ვერ გამოიმუშავებს, ვითარდება მდგომარეობა, რომელსაც გლუკოზისადმი ტოლერანტობის დარღვევა ეწოდება. თუ ეს ორსულობის დროს ხდება, მას გესტაციური დიაბეტი ეწოდება.;;;
გესტაციური დიაბეტის მქონე ქალებში სისხლში არსებული ჭარბი გლუკოზა პლაცენტის გავლით ბავშვს გადაეცემა, რამაც შეიძლება ბავშვის ჭარბი წონის მატება გამოიწვიოს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'შეშუპების შესამცირებლად დღის განმავლობაში ბევრი წყლის დალევა არ დაგავიწყდეთ. ფეხის კრუნჩხვების დროს ძილის წინ მსუბუქი მასაჟი ან თბილი შხაპი შეიძლება სასარგებლო იყოს. დღეს ცოტა დრო გაატარეთ თქვენს ბავშვთან და სამომავლო გეგმებზე ესაუბრეთ; ის თქვენს ხმაში მღელვარებასა და სიყვარულს მაშინვე გრძნობს.') WHERE id = 'e581817d-cd7b-4e6d-a51b-e85acf339c0a';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის თვალში ბადურის შრეების ფორმირება დასრულებულია. თვალის ერთ-ერთი ყველაზე მნიშვნელოვანი ნაწილი ბადურაა. ბადურა თხელი შრეა, რომელიც თვალის კაკლის უკანა ნაწილს ფარავს. მას ბადურა შიგნით არსებული სისხლძარღვების ქსელის მსგავსი აგებულების გამო ეწოდება. ეს შრე თვალის მთელ შიდა კედელს ფარავს. იგი ტვინიდან გამომავალი სისხლძარღვებისა და ნერვებისგან შედგება. ბადურის იმ ნაწილში, რომელიც თვალის კაკლის შიგნითაა მიმართული, სინათლისა და ფერის მიმართ მგრძნობიარე მილიონობით უჯრედია. ეს უჯრედები თვალის წინა ნაწილიდან შემოსულ სინათლის სიგნალებს იღებს, ტვინისთვის აღქმად ელექტრულ სიგნალებად გარდაქმნის და მხედველობის ნერვს გადასცემს. მხედველობის ნერვი ამ სიგნალებს ტვინს გადასცემს, რის შედეგადაც ტვინი გამოსახულებას აღიქვამს. მხედველობის ნერვი არხის მსგავსი სისტემის გავლით ტვინის იმ უბნისკენ მიემართება, რომელიც მხედველობას აკონტროლებს. ადგილს, საიდანაც მხედველობის ნერვი გამოდის, მხედველობის დისკი ან პაპილა ეწოდება. ბადურის ცენტრში მდებარე მხედველობის დისკში სინათლისადმი მგრძნობიარე უჯრედები არ არის, ამიტომ ის სინათლეს ვერ აღიქვამს და ამ ადგილს "ბრმა ლაქა" ეწოდება.'), baby_message_ka = COALESCE(baby_message_ka, 'თვალების გასახელად მზად ვარ! 👁️ ჩემს ქუთუთოებს შორის შემაერთებელი ხაზი უკვე გაყოფას იწყებს. ძალიან მალე, შესაძლოა რამდენიმე დღეში, თვალებს გავახელ! მიუხედავად იმისა, რომ სიბნელეში ვარ, მაინც მინდა გავიხედო. ჩემი წამწამები მზად არის თვალების დასაცავად. ერთი სული მაქვს, როდის დაგინახავთ, დედიკო.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ყვავილოვანი კომბოსტო'), body_changes_ka = COALESCE(body_changes_ka, 'ალბათ უკვე შეამჩნიეთ, რომ თქვენი თმა უფრო ბზინვარე და ხშირი გახდა. ამასთანავე, ორსულობამდელ პერიოდთან შედარებით სხეულზე შესაძლოა მეტი თმა გაგეზარდოთ. ჰორმონულ ცვლილებებთან დაკავშირებული ჭარბთმიანობა, როგორც წესი, ორსულობის მეორე ტრიმესტრში იწყება და ხშირ შემთხვევაში მშობიარობიდან მალევე ქრება.;;;
თუ ორსულობის დროს ჭარბთმიანობა გაწუხებთ, უპირატესობა უნდა მიანიჭოთ სამართებელს, ეპილატორს ან ცვილით ეპილაციას. ეს მეთოდები თქვენს ბავშვს არანაირ ზიანს არ აყენებს. თუმცა უნდა გაითვალისწინოთ, რომ ორსულობის დროს კანი უფრო მგრძნობიარე ხდება, ამიტომ შესაძლოა გაწითლდეს ან გაღიზიანდეს, რაც ინფექციის რისკს ზრდის. გარდა ამისა, ორსულობის პერიოდში თმის მოსაშორებელი კრემები არ უნდა გამოიყენოთ. ამის მიზეზია მათ შემადგენლობაში არსებული ისეთი ძლიერი ქიმიური ნივთიერებები, როგორებიცაა ბარიუმის სულფატი და კალციუმის თიოგლიკოლატი, რომლებმაც შესაძლოა თქვენს ბავშვს ზიანი მიაყენოს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'კეგელის ვარჯიშები (მენჯის ფსკერის კუნთების დაჭიმვა და მოდუნება) ყოველდღიურ რეჟიმში ჩართეთ. ამ კუნთების გაძლიერება შარდის შეუკავებლობის თავიდან აცილებასა და მშობიარობის გამარტივებას უწყობს ხელს. ყოველდღიური ჰიგიენური საფენების გამოყენება უფრო კომფორტულად გაგრძნობინებთ თავს.') WHERE id = 'ca71a802-8315-4430-831a-1c24d93987c8';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის წარბებმა და წამწამებმა საკმაოდ შესამჩნევი ფორმა მიიღო. წარბები და წამწამები თვალებს უცხო სხეულებისგან დამცავ ბუნებრივ ბარიერად ემსახურება. წამწამები სხეულის სხვა თმებისგან განსხვავებული აგებულებისაა: მათ თმის ღერის ამწევი კუნთი არ აქვთ და, ბევრი სხვა თმისგან განსხვავებით, ზოგიერთი ჰორმონის ზემოქმედებას არ ექვემდებარება. წარბები კი წარბზედა ძვლების გასწვრივ განლაგებული, რკალისებრი ფორმის თმებია. მიუხედავად იმისა, რომ წარბის თმის ფოლიკულებს სხეულის სხვა ნაწილებში არსებულ თმის ფოლიკულებთან ერთნაირი ძირითადი აგებულება აქვს, მათი ზრდის ფაზები სხვა თმის ფოლიკულებთან შედარებით საკმაოდ სწრაფია.;;;
წარბები თვალებს ოფლისგან იცავს და ჩრდილს ქმნის. სახის გამომეტყველებისთვისაც ძალიან მნიშვნელოვანი წარბები წამწამებთან, ლოყის ძვლებთან, თმის ზრდის ხაზსა და ცხვირთან ერთად თვალებს გარს აკრავს და ამგვარად ადამიანის გარეგნობას ესთეტიკურ იერს სძენს.;;;
მცირე რაოდენობით წყალთან ერთად, ეს სტრუქტურები მდიდარია ნახშირწყლებით, შარდოვანათი, შარდმჟავით, თავისუფალი ამინომჟავებით, ფოსფოლიპიდებით, ქოლესტერინით, ცხიმოვანი მჟავებითა და უმნიშვნელოვანესი სამშენებლო მასალით — კერატინით. სხვა სიტყვებით რომ ვთქვათ, ისინი ძირითადად კერატინისგან შედგება, რომელიც 18 ამინომჟავას შეიცავს და კანის ქვედა შრეში განლაგებული კერატინოციტების მიერ წარმოიქმნება.'), baby_message_ka = COALESCE(baby_message_ka, 'მე შენს სტრესს ვიზიარებ. 😔 დედიკო, როცა დაძაბული ხარ, შენს სისხლში არსებული კორტიზოლი ჩემამდეც აღწევს. მეც ვღელავ და ჩემი მოძრაობები იცვლება. მაგრამ როცა იცინი და ბედნიერი ხარ, მეც ვმშვიდდები. გთხოვ, თავს გაუფრთხილდი. ჩვენ ერთი გუნდი ვართ — შენი გრძნობები ჩემი გრძნობებიცაა.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ყვავილოვანი კომბოსტო'), body_changes_ka = COALESCE(body_changes_ka, 'ექიმის მიერ ულტრაბგერითი გამოკვლევის საფუძველზე განსაზღვრული თქვენი ბავშვის გესტაციური ასაკი შეიძლება ზუსტად არ ემთხვეოდეს ბოლო მენსტრუაციის თარიღის მიხედვით გამოთვლილ ვადას. ასეთ შემთხვევაში არ უნდა ინერვიულოთ.;;;
თუ ექიმის მეთვალყურეობის ქვეშ ჩატარებული ულტრაბგერითი შემოწმებებისას ბავშვის ზრდა მოსალოდნელ მაჩვენებელს ჩამორჩება, შესაძლოა ნაყოფის ზრდის შეფერხება ივარაუდონ. ზრდის შეფერხების მქონე ბავშვების დიდ ნაწილში ამის მიზეზი მშობლებისგან მემკვიდრეობით მიღებული გენებია. თუ დედაც და მამაც გენეტიკურად წვრილი აღნაგობის არიან, მოსალოდნელი არ არის, რომ ბავშვი საშვილოსნოში დიდი ზომის იყოს. განვითარების ასეთი განსხვავება ორი კვირით წინ ან ორი კვირით უკან ნორმად მიიჩნევა და გენეტიკური ფაქტორების გარდა სხვა ეჭვს არ იწვევს. თუ განსხვავება 2 კვირაზე მეტია, შესაძლოა საჭირო გახდეს დეტალური ულტრასონოგრაფია, მაღალი რისკის ორსულობის სპეციალისტის კონსულტაცია და ბავშვისკენ მიმავალი სისხლის ნაკადის შემოწმება. ცნობილია, რომ ბავშვებში გამოვლენილი ზრდის შეფერხების 75% კონსტიტუციური ხასიათისაა. გარდა ამისა, ზრდის შეფერხება შეიძლება გამოიწვიოს ბავშვისკენ მიმავალი სისხლის ნაკადის შემცირებამ, პლაცენტის ნაადრევმა დაბერებამ და სანაყოფე წყლების შემცირებამ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'გულძმარვის შესამცირებლად ჭამისთანავე ნუ დაწვებით, ხოლო ძილის დროს თავი ბალიშით ოდნავ მაღლა აიწიეთ. წელის ტკივილის შესამსუბუქებლად რეგულარულად შეასრულეთ მსუბუქი გაჭიმვის ვარჯიშები. თქვენ უკვე 1 kq-იან სასწაულს ატარებთ, ამიტომ მძიმე ტვირთის აწევას აუცილებლად მოერიდეთ. დღეს საღამოს მუცელზე მოეფერეთ და თქვენს ბავშვს ესაუბრეთ — ის თქვენს შეხებას გრძნობს!') WHERE id = '7b482622-6ce3-4e23-a975-62440aec9dc6';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ნერვული სისტემა და მასთან დაკავშირებული თითოეული კუნთი უკვე იმდენად განვითარებულია, რომ გარე გამღიზიანებლებზე გააზრებული რეაქციის გამოვლენა შეუძლია. ქცევა შინაგან და გარეგან ზემოქმედებაზე გაცემულ გაცნობიერებულ რეაქციას ნიშნავს. მთავარი ფაქტორი, რომელიც ქცევას უბრალო მოძრაობისგან განასხვავებს, ისაა, რომ ქცევა გარკვეულ ზემოქმედებაზე გაცნობიერებული პასუხია.;;;
გაცნობიერებულ ქცევას თავისი მიზეზი და აუცილებლად გარკვეული მიზანიც აქვს. მოძრაობისგან განსხვავებით, გაცნობიერებული ქცევა მისი გამომვლენის ნებასა და პირად მოტივებს ასახავს.;;;
ფიზიოლოგიური თვალსაზრისით კი ეს არის ენერგიის ნაკადი, რომელსაც სხეულისკენ შინაგანი და გარეგანი ფაქტორები მიმართავს. განვითარებული ნერვული სისტემის წყალობით სხეული ამ ნაკადს აღიქვამს, განმარტავს და უკუკავშირის სახით გარემოსა და გამღიზიანებლებთან შესაგუებლად იყენებს.;;;
ქცევის საფუძველს გამღიზიანებელსა და მის საპასუხოდ გამოვლენილ ქცევას შორის შესაბამისობა ქმნის. ეს შესაბამისობა ორგანიზმს გარემოსთან წონასწორობის მდგომარეობის შენარჩუნებაში ეხმარება.;;;
ეს წონასწორობა შეიძლება გამოიხატოს იმით, რომ როცა თქვენ იცინით, თქვენი ბავშვიც იღიმის, ტკივილისას ტუჩებს კუმავს, ხოლო შიმშილისას რძეს წოვს.'), baby_message_ka = COALESCE(baby_message_ka, 'თვალები გავახილე! 👀 დედიკო, დღეს ჩემთვის რევოლუციური დღეა. აქამდე ერთმანეთზე შეწებებული ჩემი ქუთუთოები გაიყო და პირველად გავახილე თვალები. ჯერჯერობით ყველაფერი ბუნდოვანია, მაგრამ თვალების დახამხამება შემიძლია. მიუხედავად იმისა, რომ ირგვლივ ბნელა, ყურებას ვსწავლობ. კიდევ ერთი ნაბიჯით მოგიახლოვდი, რომ დაგინახო!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ყვავილოვანი კომბოსტო'), body_changes_ka = COALESCE(body_changes_ka, '„ბრექსტონ-ჰიქსის“ შეკუმშვები (ცრუ მშობიარობის ტკივილები) შეიძლება უფრო ხშირად გამოვლინდეს. ნუ შეგაშინებთ, თუ მუცელი ქვასავით გაგიმაგრდებათ. ასე საშვილოსნოს კუნთი „ვარჯიშობს“. თუ ეს შეკუმშვები პოზის შეცვლის ან წყლის დალევის შემდეგ გაივლის, ისინი ცრუა. ნამდვილი მშობიარობის შეკუმშვები თანდათან ძლიერდება და არ წყდება.;;;
შესაძლოა ნეკნების ტკივილიც დაიწყოს. საშვილოსნო იმდენად მაღლაა აწეული, რომ უკვე ნეკნების რკალის გაფართოებას იწყებს. ბავშვის თავი ან ფეხები შეიძლება თქვენს ნეკნებს ეხებოდეს. ზოგჯერ ღრმად ჩასუნთქვაც შეიძლება გაგიჭირდეთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'იცოდეთ პრეეკლამფსიის ნიშნები: სახისა და ხელების უეცარი შეშუპება, ძლიერი თავის ტკივილი, თვალწინ „სინათლის გაელვება“ ან ნეკნების ქვეშ ტკივილი. ამ ნიშნებიდან რომელიმეს გამოვლენის შემთხვევაში დაუყოვნებლივ მიმართეთ ექიმს.') WHERE id = '664b492c-1968-495f-9380-1ec985579ba8';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენს ბავშვში ცხიმოვანი ქსოვილის წარმოქმნის დაჩქარება ხელს უწყობს კანქვეშა ქსოვილის განვითარებას და, შესაბამისად, წონის სწრაფ მატებას. წარმოქმნილი ცხიმი დაბადების მომენტიდანვე ბავშვს სიცივისგან დამცავ ბარიერადაც ემსახურება.;;;
საშვილოსნოში განვითარების სრულ ვადას მიღწეული ბავშვების დაბადების წონა 2500 qram-დან 4000 qram-მდე მერყეობს. ეს მაჩვენებელი ბევრ ფაქტორზეა დამოკიდებული, რომელთაგან ერთ-ერთი ყველაზე ცნობილი სქესია. გოგო და ბიჭ ბავშვებს შორის გენეტიკური განსხვავებები არსებობს — ბიჭებს გოგოებთან შედარებით მეტი ცხიმოვანი უჯრედი აქვთ.;;;
არსებობს მრავალი მიზეზი, რის გამოც ბავშვის წონა საშვილოსნოში საშუალოზე ნაკლები ან მეტი შეიძლება იყოს. საშუალოზე ნაკლები წონის მქონე ბავშვების მნიშვნელოვან ნაწილში მიზეზი გენეტიკური ფაქტორებია. გარდა ამისა, ეს პრობლემა შეიძლება გამოიწვიოს ორსულობის დროს გადატანილმა ზოგიერთმა დაავადებამ და არასწორმა კვებამ. თუ საშუალოზე მაღალი წონის მქონე ბავშვის ჭარბ წონასთან ერთად სანაყოფე წყლების სიჭარბეც აღინიშნება, პირველ რიგში გესტაციურ დიაბეტზე ჩნდება ეჭვი. ამასთან, ბავშვის საშუალოზე მაღალი წონა შეიძლება გენეტიკურმა და ნივთიერებათა ცვლის თავისებურებებმაც გამოიწვიოს.'), baby_message_ka = COALESCE(baby_message_ka, 'წამწამები მეზრდება! 👁️ ახლა, როცა თვალები გავახილე, მათი დაცვაა საჭირო. გრძელი, აბრეშუმივით რბილი წამწამები მაქვს. როცა თვალებში ჩამხედავ, ჩემი წამწამებით მოიხიბლები. წარბებიც უკვე სრულად ჩამომიყალიბდა. ახლა პატარა თოჯინას ვგავარ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ყვავილოვანი კომბოსტო'), body_changes_ka = COALESCE(body_changes_ka, 'ამ პერიოდში ჰორმონული ბალანსის ცვლილების გამო თქვენი ვაგინალური ფლორაც იცვლება. ამიტომ ორსულობის დროს ორგანიზმი ვაგინალური სოკოვანი ინფექციის მიმართ უფრო მიდრეკილი ხდება. განსაკუთრებით მაშინ, თუ მუცლის მოშლის რისკი გაქვთ და ამის გამო ვაგინალურ სანთლებს ან კრემს იყენებთ, სოკოვანი ინფექცია შეიძლება უფრო ხშირად განვითარდეს. ვაგინალური სოკოვანი ინფექცია შეიძლება გამოვლინდეს სასქესო ორგანოების მიდამოში წვითა და ქავილით, უხვი თეთრი გამონადენით, ხშირი შარდვითა და სქესობრივი კავშირის დროს ტკივილით. მიუხედავად იმისა, რომ სიმპტომები ადამიანებში განსხვავებულია, სოკოვანი ინფექციისთვის დამახასიათებელი გამონადენი ხშირად თეთრი ან კრემისფერია, კრემივით სქელი, ხაჭოს ან ყველის ნამცეცების მსგავსი მარცვლოვანი სტრუქტურისა და მომჟავო სუნის მქონე.'), daily_tip_ka = COALESCE(daily_tip_ka, '26-ე კვირის დასრულება საკუთარი თავის განებივრებით აღნიშნეთ! წელის ტკივილის შესამცირებლად ჯდომისას აუცილებლად გამოიყენეთ ბალიში, რომელიც ზურგს სათანადოდ დაგიჭერთ. თუ ჯერ არ გაგიკეთებიათ, გლუკოზის დატვირთვის ტესტის შესახებ ბოლო დეტალები ექიმთან დააზუსტეთ. ღამით მარცხენა გვერდზე წოლა როგორც თქვენი, ისე ბავშვის სისხლის მიმოქცევისთვის საუკეთესო პოზაა.') WHERE id = '3c253a83-3ac7-475e-8987-d27fab00a076';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის სასუნთქი, საჭმლის მომნელებელი, ნერვული და იმუნური სისტემები განვითარებას განაგრძობს. იმუნური სისტემა ორგანიზმის დამცავი სისტემაა, რომელიც მას ინფექციის გამომწვევი მიკროორგანიზმების — ვირუსების, ბაქტერიების, სოკოებისა და პარაზიტების — მავნე ზემოქმედებისგან იცავს.;;;
იმუნური სისტემის შემადგენელი უჯრედები, ქსოვილები და ორგანოები შეთანხმებულად და ძალიან ეფექტურად თანამშრომლობენ. იმუნური სისტემის ფუნქციონირება ორ ძირითად ნაწილად იყოფა: თანდაყოლილ და შეძენილ იმუნურ სისტემებად. თანდაყოლილი იმუნური სისტემა ორგანიზმში ბუნებრივად არსებული სისტემაა, რომელიც ინფექციის გამომწვევ მიკრობებს ორგანიზმში პირველად მოხვედრისთანავე ხვდება, ამოიცნობს და შემდეგ მათ განადგურებას ცდილობს. შეძენილი იმუნური სისტემა კი ორგანიზმისთვის საზიანო მიკრობთან შეხვედრის შემდეგ, გარკვეული მოსამზადებელი პერიოდის შედეგად აქტიურდება. ის მავნე ორგანიზმის საწინააღმდეგო დამცავ სტრუქტურებს წარმოქმნის და იმუნური მეხსიერება აქვს. მის ძირითად ელემენტებს T და B ლიმფოციტები შეადგენს.'), baby_message_ka = COALESCE(baby_message_ka, 'დედიკო, მე-3 ტრიმესტრი კარს მოგვადგა! უკვე „მძიმე წონით“ კატეგორიაში გადავდივარ. ადგილი მევიწროვება, ამიტომ ჩემი მოძრაობები შეიძლება უფრო ძლიერი გახდეს. თუ ნეკნებზე გეხები, მაპატიე, უბრალოდ ვიჭიმები.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ყვავილოვანი კომბოსტო'), body_changes_ka = COALESCE(body_changes_ka, 'რადგან ამ კვირებში ორსულობის ტოქსიკოზი ხშირად გვხვდება, ყურადღებით უნდა იყოთ და არტერიული წნევა გაიზომოთ. ორსულობის ტოქსიკოზი, რომელსაც პრეეკლამფსია ეწოდება, ორსულობის მე-20 კვირის შემდეგ არტერიული წნევის ვერცხლისწყლის სვეტის 140/90 მმ-ზე მეტად მომატებითა და შარდში ცილის აღმოჩენით ვლინდება. ამ მდგომარეობებს ხშირად შეშუპებაც ახლავს.;;;
ორსულობის ტოქსიკოზის განვითარების მექანიზმი შეიძლება სისხლძარღვთა სისტემის დარღვევად დახასიათდეს. პრობლემის საფუძველია საშვილოსნოს შიგნითა შრის მომმარაგებელი წვრილი და დაკლაკნილი არტერიების ზედმეტად შევიწროება, რის შედეგადაც პლაცენტა ბავშვს საკმარისი რაოდენობის საკვები ნივთიერებებით ვეღარ ამარაგებს.;;;
პრეეკლამფსია ორსულობათა დაახლოებით 5%-დან 7%-მდე შემთხვევაში შეიძლება გამოვლინდეს. წონის უეცარი მატების, შეშუპების, სისუსტის, ცნობიერების დაბინდვის, მუცლის არეში ტკივილისა და ბავშვის მოძრაობების შემცირების შემთხვევაში დაუყოვნებლივ უნდა მიმართოთ უახლოეს სამედიცინო დაწესებულებას.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ძილის დროს ფეხებს შორის და მუცლის ქვეშ ბალიშის მოთავსება წელის ტკივილს ამცირებს. მარცხენა გვერდზე წოლა ბავშვისკენ სისხლის ნაკადს ზრდის და თქვენი თირკმელების მუშაობას ამარტივებს.') WHERE id = '1d4c4310-3e73-4b60-b4c5-883dd87bf1e3';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'კეთილი იყოს თქვენი მობრძანება მეორე ტრიმესტრის ბოლო კვირაში! დრო რა სწრაფად გადის, არა? თქვენი ბავშვის სიგრძე უკვე არა თავიდან კუდუსუნამდე მანძილით, არამედ ბარძაყის ძვლის სიგრძის 7-ზე გამრავლებით განისაზღვრება.;;;
მესამე ტრიმესტრის დაწყებამდე ცოტა ხნით ადრე, ექიმთან გამოკვლევისას შეიძლება გაირკვეს, რომ თქვენი ბავშვი მშობიარობისთვის თავით ქვემოთ მდებარე პოზიციაშია. ეს სრულიად ნორმალურია. ბოლო კვირებთან შედარებით ბავშვს ჯერ კიდევ მეტი სივრცე აქვს სამოძრაოდ, ამიტომ პოზიციის შეცვლა ადვილად შეუძლია. გარდა ამისა, ბავშვის პირის ღრუში არსებული მრავალი გემოვნების კვირტის წყალობით, თქვენ მიერ მიღებული საკვების გემო ამნიონური სითხის მეშვეობით მასაც აღწევს და გემოების გარჩევის შესაძლებლობას აძლევს.;;;
ამ ეტაპზე თქვენი ბავშვის ენის ზედაპირზე უფრო მეტი გემოვნების კვირტია, ვიდრე ზრდასრულ ადამიანს აქვს. ამის წყალობით ბავშვი ამ გემოებს არა მხოლოდ არჩევს, არამედ მათზე რეაგირებაც შეუძლია. განსაკუთრებით ცხარე და ძალიან მწარე საკვებზე შეიძლება სლოკინით რეაგირებდეს.'), baby_message_ka = COALESCE(baby_message_ka, 'მე სიზმრებს ვხედავ! 💤 მეცნიერებმა ჩემი ტვინი შეისწავლეს და აღმოაჩინეს, რომ „REM ძილის“ ფაზაში ვარ. ანუ, მიუხედავად იმისა, რომ თვალები დახუჭული მაქვს, მაინც ვოცნებობ. ნეტავ სიზმარში რას ვხედავ? შენს ხმას? თუ იმ გემრიელ შოკოლადს, რომელიც შეჭამე? მეც შენსავით მეოცნებე ვარ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ყვავილოვანი კომბოსტო'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის 28-ე კვირიდან თქვენს ორგანიზმში არსებული მარაგების დიდი ნაწილი ბავშვს გადაეცემა. ამიტომ კალციუმით, მაგნიუმითა და A, D, E და K ვიტამინებით მდიდარი საკვების მიღება ძალიან მნიშვნელოვანია, რათა თქვენს ორგანიზმში მიმდინარე პროცესები არ შენელდეს.;;;
თუ ორსულობისას საკმარისი რაოდენობის კალციუმს არ მიიღებთ, ბავშვის განვითარებისთვის საჭირო კალციუმი თქვენი ძვლებიდან შეივსება. ამან შეიძლება კალციუმის დეფიციტი გამოიწვიოს და მომავალში ოსტეოპოროზის, ანუ ძვლოვანი ქსოვილის განლევის, განვითარებას შეუწყოს ხელი. რძე, იოგურტი და ყველი კალციუმით ყველაზე მდიდარი პროდუქტებია. მათ გარდა, კალციუმის მნიშვნელოვან რაოდენობას შეიცავს გარგრის ჩირი, ნიგოზი, თხილი, ნუში, კალმახი, მუქი მწვანე ფოთლოვანი ბოსტნეული და პარკოსნები. ყოველდღიურად მისაღებ ერთ ჭიქა რძეში 250 მგ კალციუმია. ერთი ნაჭერი თეთრი ყველი, სახეობის მიხედვით, 100 მგ-ს, ერთი მუჭა უმი თხილეული 50 მგ-ს, ხოლო ერთი მუჭა ქიშმიში 30 მგ კალციუმს შეიცავს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'წელის ტკივილის შესამცირებლად ჩაიცვით დაბალქუსლიანი, კომფორტული ფეხსაცმელი და ჯდომისას ზურგი აუცილებლად მიაყრდენით. ცხვირის სიმშრალის თავიდან ასაცილებლად ოთახში ტენიანობის სათანადო დონე შეინარჩუნეთ. დღეს უფრო მეტი ესაუბრეთ თქვენს ბავშვს ან ზღაპარი წაუკითხეთ; მომავალში მას თქვენი ხმის ჟღერადობა ემახსოვრება. დალიეთ ბევრი წყალი და რაციონში ბოჭკოვანი საკვები აუცილებლად შეინარჩუნეთ.') WHERE id = '1533383b-1c83-483c-ad7a-9958fe297dd1';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის წონის სწრაფი მატება იმით არის განპირობებული, რომ მის ორგანიზმში გასაოცარი სისწრაფით წარმოიქმნება ყავისფერი ცხიმოვანი უჯრედები. ყავისფერი ცხიმოვანი უჯრედები ორგანიზმში ქოლესტერინის გარკვეულ ნაწილს ინახავს და, მათში არსებული მრავალი მიტოქონდრიის წყალობით, სითბოსაც გამოიმუშავებს. რადგან ყავისფერი ცხიმოვანი უჯრედები თქვენი ბავშვის სხეულის ტემპერატურის შენარჩუნებას უზრუნველყოფს, ლანუგოს ბუსუსები, რომლებიც ამ ეტაპამდე მას სითბოს უნარჩუნებდა, თანდათან ცვენას იწყებს. ლანუგოს ბუსუსების ცვენის ეტაპი თითოეული ბავშვისთვის განსხვავებულია. ამას განვითარება და მეტაბოლური პროცესები განსაზღვრავს. ჩამოცვენილი ლანუგოს ბუსუსები ერევა ამნიონურ სითხეში, რომელშიც თქვენი ბავშვი იმყოფება, შემდეგ კი ბავშვი ამ სითხეს ყლაპავს. გადაყლაპულ ამნიონურ სითხეში არსებული ლანუგოს ბუსუსები ბავშვის ნაწლავებში გროვდება და თავს იყრის მეკონიუმში, რომელიც „პირველი განავლის“ სახელითაა ცნობილი. ამასთანავე, მის სხეულში სწრაფად მზარდი ყავისფერი ცხიმოვანი უჯრედების რაოდენობის წყალობით კანქვეშა შრე სწრაფად ვითარდება და ივსება, რის გამოც კანის ნაოჭები მცირდება და კანი უფრო გლუვი და დაჭიმული ხდება. ამასთან, ამ ეტაპამდე გამჭვირვალე კანი და მის ქვეშ ხილული კაპილარული სისხლძარღვები უკვე აღარ ჩანს.'), baby_message_ka = COALESCE(baby_message_ka, 'სლოკინი ამიტყდა! 🤭 მუცელში რიტმულ „ტკაც-ტკაც-ტკაცს“ გრძნობ? ეს ჩემი სლოკინია! როცა ამნიონურ სითხეს ვყლაპავ, დიაფრაგმა მეღიზიანება და სლოკინი მეწყება. შეიძლება ეს უცნაურად მოგეჩვენოს, მაგრამ ჩემთვის ეს ფილტვების გამაძლიერებელი ვარჯიშია. ნუ გეშინია, არ ვიხრჩობი!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ყვავილოვანი კომბოსტო'), body_changes_ka = COALESCE(body_changes_ka, 'მალე მეორე ტრიმესტრს დაასრულებთ. ამ ეტაპის, რომელსაც ორსულობის ოქროს პერიოდს ან თაფლობის თვეს უწოდებენ, დასრულება ნიშნავს, რომ პირველ ტრიმესტრში განცდილი ზოგიერთი ჩივილი შეიძლება დაბრუნდეს.;;;
რადგან თქვენი ბავშვი საკმაოდ მაღლა ავიდა, საშვილოსნოს ზეწოლის შედეგად თქვენი ორგანოები მდებარეობას იცვლის. კუჭი ერთ-ერთი ორგანოა, რომელზეც ეს მდგომარეობა ყველაზე მეტად მოქმედებს. ჩვეულებრივზე მაღლა აწეულ კუჭში, განსაკუთრებით მძიმე საკვების მიღებისას, წნევა იმატებს, რამაც შეიძლება ღებინება და გულძმარვა გამოიწვიოს. ამასთან, რადგან ნაწლავები გვერდზეა გადაწეული, შეიძლება შენელდეს ნაწლავების მოქმედება და აღინიშნოს მუცლის შებერილობა და შეკრულობა. ასევე, ბავშვის ზრდასთან ერთად საშვილოსნო კვლავ იწყებს შარდის ბუშტზე ზეწოლას, რის გამოც შეიძლება ისევ ხშირად მოგიწიოთ ტუალეტში სიარული. შარდის ბუშტზე ზეწოლა მის მოცულობას ამცირებს, ამიტომ შარდვის სიხშირე შეიძლება გაიზარდოს, ხოლო შარდის ნაკადის სიჩქარე შემცირდეს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'დღეს მოიმზადეთ ერთი ფინჯანი მცენარეული ჩაი (ექიმთან კონსულტაციის შემდეგ) და მშვიდ გარემოში დააკვირდით თქვენი ბავშვის მოძრაობებს.') WHERE id = '0a949afb-87f2-4780-b137-5c4298637904';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამ ეტაპზე თქვენი ბავშვის წონის გარკვეულ ნაწილს ყავისფერი ცხიმოვანი უჯრედები შეადგენს. ჩვეულებრივ უჯრედებსა და ცხიმოვან უჯრედებთან შედარებით, ყავისფერი ცხიმოვანი უჯრედები აგებულებაში ძალიან დიდი რაოდენობით მიტოქონდრიებს შეიცავს. მიტოქონდრიების — უჯრედის ენერგიის წარმომქმნელი ნაწილების — რაოდენობა შეიძლება უჯრედის ენერგეტიკული მოთხოვნილების მიხედვით იცვლებოდეს. განსაკუთრებით ბევრი მიტოქონდრია შეიძლება ჰქონდეს უჯრედებს, რომლებსაც დიდი რაოდენობით ენერგია სჭირდება, მაგალითად, კუნთოვან და ნერვულ უჯრედებს. მაგალითად, ღვიძლის უჯრედებში, რომელიც ერთ-ერთი ყველაზე მაღალი ენერგეტიკული მოთხოვნილების მქონე ორგანოა, მათი რაოდენობა დაახლოებით 2500-ს შეადგენს. მიტოქონდრია ყველა იმ ეუკარიოტულ უჯრედში გვხვდება, რომელსაც ჟანგბადით სუნთქვა შეუძლია. ამიტომ ერითროციტებში, რომლებსაც სისხლით გადაადგილების გამო ენერგია არ სჭირდება, მიტოქონდრიები არ გვხვდება.'), baby_message_ka = COALESCE(baby_message_ka, 'იცით, რა არის „Lightning Crotch“? ⚡ ზოგჯერ, როცა ქვემოთ გირტყამთ ფეხს ან თავს ვატრიალებ, შეიძლება საზარდულის მიდამოში უეცარი, ელექტროშოკის მსგავსი ტკივილი იგრძნოთ. ამას ინგლისურად „Lightning Crotch“ (ელვისებური ტკივილი) ეწოდება. ეს იმიტომ ხდება, რომ რომელიმე ნერვს ვეხები. მაპატიეთ, რომ გატკინეთ — უბრალოდ, აქ ძალიან ცოტა ადგილი მაქვს!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ბროკოლი'), body_changes_ka = COALESCE(body_changes_ka, 'თუ თქვენი ბავშვი დროდადრო ძალიან აქტიურია ან მისი მოძრაობები ნელდება, არ უნდა ინერვიულოთ. მიუხედავად იმისა, რომ მოძრაობები გარკვეულ რეჟიმში ექცევა, მათ ინტენსივობას ყოველთვის ერთნაირად ვერ იგრძნობთ. ამის ყველაზე გავრცელებული მიზეზი ბავშვის იმჟამინდელი მდებარეობაა. თუ ბავშვმა მშობიარობისთვის საჭირო პოზიცია დაიკავა და თავით ქვემოთ იმყოფება, მან შეიძლება კუჭსა და ფილტვებზე მეტი ზეწოლა მოახდინოს, რის გამოც სუნთქვა გაგიჭირდებათ. ამასთან, ნეკნებისკენ მიმართული დარტყმები შეიძლება საკმაოდ მტკივნეული იყოს. ხოლო თუ ბავშვი დუნდულებით ან ფეხებით ქვემოთ მდებარეობს (მენჯით წინამდებარეობა), შესაძლოა სწორ ნაწლავზე ზეწოლის შეგრძნება გამოიწვიოს და შარდის ბუშტსაც მეტი დატვირთვა შეუქმნას.;;;
ასევე, ბავშვები მუდმივად არ მოძრაობენ. გახსოვდეთ, რომ ამ ეტაპზე თქვენი ბავშვი დღე-ღამეში თითქმის 18-20 საათს ძილში ატარებს. ნორმალურია, თუ თქვენი მოძრაობისას ბავშვი ნაკლებად აქტიურია, ხოლო დასვენების დროს საკმაოდ აქტიურდება. თუმცა, თუ უჩვეულო სიმშვიდესა და უმოძრაობას შეამჩნევთ და ბავშვი თქვენთვის ჩვეული სიხშირით აღარ მოძრაობს, ექიმს უნდა დაუკავშირდეთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'თუ საზარდულის ტკივილი გაქვთ, ფეხები ძალიან ფართოდ არ გაშალოთ. ავტომობილში ჩაჯდომისას ჯერ სავარძელზე დაჯექით, შემდეგ კი ორივე ფეხი ერთად შეიტანეთ სალონში. აუცილებლად მოერიდეთ მძიმე ნივთების აწევას.') WHERE id = 'e505d439-55d1-41af-8277-5a18a75a724e';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენს ბავშვს უკვე შეუძლია თვალების გახელა და დახუჭვა. ამის წყალობით ის განვითარების იმ დონეს აღწევს, როცა დღისა და ღამის გარჩევა შეუძლია. მიუხედავად იმისა, რომ საშვილოსნოს კედელი ბარიერის როლს ასრულებს და გარეგან გამღიზიანებლებს, როგორიცაა სინათლე და ხმა, საშვილოსნოს ღრუში შეღწევაში უშლის ხელს, ბავშვის ზრდასთან ერთად ეს კედელი იჭიმება და შედარებით თხელი ხდება. ამ ეტაპზე, თუ მუცელთან ძლიერ სინათლის წყაროს მიიტანთ, ბავშვმა შეიძლება მასზე რეაგირება მოახდინოს და თავი სინათლის წყაროსკენ მიაბრუნოს. ასეთი რეაქცია ასევე შესაძლებელი ხდება თვალის განვითარებული რქოვანას და მხედველობის ნერვის წყალობით.;;;
გარდა ამისა, ბავშვი თქვენს ხმაზე რეაგირებს და მამის ხმის სხვა ხმებისგან გარჩევაც შეუძლია. ქალებისა და ბავშვების ხმები კაცების ხმებთან შედარებით უფრო მაღალი და წვრილია, ამიტომ ისინი საშვილოსნოს კედელში უფრო ადვილად აღწევს და ბავშვიც მათზე მეტად რეაგირებს. უეცარი და ძლიერი ხმების გაგონებისას კი შეიძლება შეკრთეს და ძლიერად დაგარტყათ ფეხები.'), baby_message_ka = COALESCE(baby_message_ka, '⚖️ რაც უფრო ვიმატებ წონაში, მით უფრო მძიმე ვხდები თქვენთვისაც. ვიცი, წელი გტკივათ. მაგრამ იფიქრეთ იმაზე, რამდენად ჯანმრთელი და ძლიერი ვხდები. ცხიმის ფენა სითბოს შემინარჩუნებს. როცა დავიბადები, თქვენს მკლავებს შევავსებ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ბროკოლი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის შემდგომ კვირებში ჰორმონული ცვლილებების გამო მომატებული და უფრო თხელი გამონადენი შეიძლება სანაყოფე წყლების დაღვრაში აგერიოთ. სანაყოფე გარსის გახეთქვისას სითხე, როგორც წესი, დიდი რაოდენობით გამოიყოფა და ფეხებზე უხვად ჩამოედინება. თუმცა ზოგიერთ შემთხვევაში სანაყოფე გარსი გარკვეული მიზეზების გამო გვერდით ან ზედა ნაწილში შეიძლება გაიხვრიტოს. შედეგად სანაყოფე წყლები შეიძლება მცირე ნაკადის ან წვეთვის სახით გამოვიდეს.;;;
თუ ეჭვობთ, რომ სანაყოფე წყლები დაგეღვათ, მიმართეთ საავადმყოფოს. მარტივი ტესტით შესაძლებელია დადგინდეს, გამოყოფილი სითხე სანაყოფე წყალია თუ ვაგინალური გამონადენი.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ქოშინის შესამცირებლად ეცადეთ, გამართულად იჯდეთ, მხრები უკან გასწიოთ და გულმკერდი გახსნათ. კალციუმის საჭიროების დასაკმაყოფილებლად დღის განმავლობაში უპირატესობა მიანიჭეთ რძის პროდუქტებს ან მწვანეფოთლოვან ბოსტნეულს. თუ მუცელი გექავებათ, კანი ბუნებრივი ზეთებით დაიტენიანეთ. დღეს ცოტა დამშვიდდით და თქვენს ბავშვთან ერთად მომავალ ბედნიერ დღეებზე იოცნებეთ.') WHERE id = 'e2245d19-3163-447c-8f3b-d37ca7523b57';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენ შეხვედით ორსულობის 27-ე და 32-ე კვირებს შორის პერიოდში, როდესაც ბავშვი მთელი ორსულობის განმავლობაში ყველაზე აქტიურია. ამასთან, ამ კვირებიდან ბავშვის მოძრაობები უკვე რეგულარული ხდება. ეს ნიშნავს, რომ მისი სიფხიზლის ყოველ საათში სულ მცირე 10 მოძრაობა უნდა იგრძნოთ. ბავშვი ყველაზე აქტიური ღამითაა, როდესაც ამნიონური სითხე არ მოძრაობს. დღის განმავლობაში თქვენი მოძრაობების შედეგად ამნიონური სითხე ირხევა, რაც ბავშვს დაძინებაში ეხმარება. ანუ, ბავშვმა შეიძლება უკვე ძილიც დაგიფრთხოთ. 😊;;;
ამ ეტაპზე ბავშვის მოძრაობებს ასე ძლიერად და ხშირად უმთავრესად იმიტომ გრძნობთ, რომ ის უკვე საკმაოდ გაიზარდა, მის ირგვლივ კი ჯერ კიდევ საკმარისი ამნიონური სითხეა თავისუფლად მოძრაობისთვის.;;;
კვირების მატებასთან ერთად ბავშვი სანაყოფე გარსში შარდის სახით უფრო ნაკლებ სითხეს გამოყოფს, ვიდრე ამნიონურ სითხეს ყლაპავს. შედეგად, მის გარშემო არსებული სითხის რაოდენობა თანდათან მცირდება. სითხის მოცულობის შემცირება აუცილებელი პროცესია, რადგან ზრდასთან ერთად ბავშვს სულ უფრო მეტი სივრცე სჭირდება.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი რეჟიმი მაქვს! 📅 დედიკო, შეგიმჩნევიათ? ჩვეულებრივ, ერთსა და იმავე საათებში ვიღვიძებ და ვიძინებ. მაგალითად, როცა საღამოს წამოწვებით, მე ვიღვიძებ. დილაობით კი მშვიდად ვარ. ჩემი ბიოლოგიური საათი უკვე ამუშავდა. დაბადების შემდეგაც გარკვეული ხნით ასეთი ვიქნები (ღამის ფრინველი ვიქნები!).'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ბროკოლი'), body_changes_ka = COALESCE(body_changes_ka, 'პროგესტერონის ჰორმონის გავლენით კუჭისა და საყლაპავის შეერთების ადგილას კუნთის მოდუნებამაც შეიძლება გულძმარვა გამოიწვიოს. ორსულობის დროს უნდა მოერიდოთ საკვებს, რომელიც გულძმარვას აძლიერებს. რადგან დახრის მსგავსი მოძრაობებიც ამ პრობლემას ამწვავებს, არ უნდა შეასრულოთ მძიმე საოჯახო საქმეები ან სხვა საქმიანობა, რომელიც დახრას მოითხოვს. სწრაფად ჭამის ნაცვლად საკვები ნელა მიირთვით და მოერიდეთ მჟავე, გაზიან და კოფეინის შემცველ სასმელებს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'დილით უზმოზე ერთი ჭიქა თბილი წყლის დალევა ან ჩირის, მაგალითად, გარგრის ჩირის ჭამა ნაწლავების მუშაობას ააქტიურებს. ტუალეტში გასვლის სურვილი არასოდეს გადადოთ.') WHERE id = '45b37fad-6e16-4ec4-9e5c-d3eea98a5a6d';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'დაახლოებით 24-ე კვირიდან თქვენი ბავშვი სიცოცხლისუნარიანობის ზღვარს აღწევს, ხოლო ამ კვირაში ნაადრევად დაბადების შემთხვევაშიც კი მისი გადარჩენის შანსი 90%-ზე მეტი იქნება. ამის უმთავრესი მიზეზი ის არის, რომ ფილტვები უკვე მნიშვნელოვანი რაოდენობით სურფაქტანტს გამოიმუშავებს. ეს ნივთიერება ალვეოლებში სითხის ზედაპირულ დაჭიმულობას ამცირებს და ხელს უშლის მათ ძლიერ შეწებებასა და ჩაფუშვას, რაც შეიძლება გარშემო არსებული სისხლძარღვების გაფართოებამ და იქ სისხლის დაგროვებამ გამოიწვიოს; ამგვარად, ის აფერხებს შეშუპებისა და სხვა ნივთიერებების დაგროვებას. აირთა ცვლის დროს ეს ნივთიერებები ბრონქებში ლორწოს რაოდენობას ზრდის და ზედაპირის სრიალს უზრუნველყოფს. მათი სტრუქტურა ცილებისა და ლიპიდების რთული ნარევისგან შედგება. გარდა ამისა, თქვენი ბავშვის შეხების, გემოს, სმენის, ყნოსვისა და მხედველობის შეგრძნებები უკვე სრულად ჩამოყალიბებულია.'), baby_message_ka = COALESCE(baby_message_ka, 'თქვენს ხმაზე ვრეაგირებ! 🎵 როცა მამა მუცელთან ახლოს მოდის და მელაპარაკება, ჩემი გულისცემა იცვლება. მისი ხმა ძალიან კარგად მესმის. უთხარით, რომ მელაპარაკოს. ოჯახის წევრების ხმებით ცნობას უკვე ვიწყებ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ბროკოლი'), body_changes_ka = COALESCE(body_changes_ka, 'მუცლის მნიშვნელოვნად გაზრდისა და ღამის საათებში თქვენი ბავშვის აქტიურობის გამო შესაძლოა ძილის პრობლემები შეგექმნათ. ამ პერიოდში ორსულობის ბალიშის შეძენა შეიძლება სასარგებლო იყოს. ორსულობის ბალიში ზურგსა და წელის არეს ეყრდნობა და ტკივილს ამცირებს, ასევე თირკმელების უკეთ მუშაობას უწყობს ხელს. ის სუნთქვასაც აადვილებს და ორსულობის დროს ხშირად განვითარებული ქოშინის შემცირებაში გეხმარებათ. ხელს უწყობს ბავშვის უკეთ კვებასა და ჟანგბადის მიღებას, ასევე ამცირებს ორსულობის პერიოდში საკმაოდ გავრცელებულ გულძმარვას. სისხლის მიმოქცევის გაუმჯობესების წყალობით ამცირებს კრუნჩხვებსა და, განსაკუთრებით, ფეხების შეშუპებას. ;;;
განსაკუთრებით ბოლო ტრიმესტრში, ჩვეულებრივ, მარცხენა გვერდზე წოლაა რეკომენდებული. ამის მიზეზი ის არის, რომ მარჯვენა მხარეს მდებარე ქვედა ღრუ ვენაზე ზეწოლამ შეიძლება სხეულის ქვედა ნაწილში ვენების გაფართოება და მასთან დაკავშირებული პრობლემები გამოიწვიოს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'დღეს 27-კვირიანი წარმატებული გზა დასვენებით აღნიშნეთ. ფეხების შეშუპების შესამცირებლად აკონტროლეთ მარილის მიღება და ფეხები შემაღლებულ მდგომარეობაში გქონდეთ დასვენებისას. მესამე ტრიმესტრის ენერგიულად დასაწყებად მოაწესრიგეთ ძილის რეჟიმი. ხვალიდან ჩვენს შეხვედრამდე კიდევ უფრო ცოტა დრო დარჩება!') WHERE id = '7654580f-12f8-4fea-93bd-20d5a4e92397';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის კუნთების ელასტიკურობა განვითარებას განაგრძობს. კუნთების ელასტიკურობის განვითარება დადებითად მოქმედებს ბავშვის ჩაჭიდების უნარზე და ძალიან მნიშვნელოვანია რეფლექსების ჩამოყალიბებისთვის.;;;
მოძრაობის სისტემის საფუძველს ჩონჩხთან მიმაგრებული კუნთები ქმნის. ადამიანის სხეულში დაახლოებით 650 კუნთია და მათი საერთო წონა საშუალოდ სხეულის მთლიანი წონის 40-50%-ს შეადგენს. კუნთები სამ ჯგუფად იყოფა: განივზოლიანი, გლუვი და გულის კუნთი. კუნთებს რამდენიმე სპეციფიკური თვისება აქვთ: აგზნებადობა, გამტარობა, შეკუმშვის უნარი, ელასტიკურობა და სიბლანტე.;;;
ნებისმიერი ცოცხალი ქსოვილის მსგავსად, კუნთებსაც აქვთ უნარი, მათზე მოქმედ გამღიზიანებელს უპასუხონ. კუნთები ამ გაღიზიანებას შეკუმშვით პასუხობენ. არსებობს შეკუმშვის ხუთი ტიპი: იზომეტრიული, კონცენტრული, ექსცენტრიკული, იზოკინეტიკური და ტეტანური შეკუმშვა.'), baby_message_ka = COALESCE(baby_message_ka, 'გამარჯობა, მე-3 ტრიმესტრო! 👋 დედიკო, ჩვენ დიდი ეტაპი დავასრულეთ. მეორე ტრიმესტრი სრულდება და ახლა მე-3 ტრიმესტრი იწყება. უკვე დიდი ბავშვი ვარ. ახლა ჩემი მთავარი საქმე წონის მომატება და დაბადებისთვის მომზადებაა. ვიცი, რომ დაიღალეთ, მაგრამ ცოტა დარჩა. ჩვენ შევხვდებით!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ბროკოლი'), body_changes_ka = COALESCE(body_changes_ka, 'მუცლის მნიშვნელოვნად გაზრდის გამო ტანსაცმელი შეიძლება აღარ გერგებოდეთ. განსაკუთრებით ბოლო ტრიმესტრში უნდა მოერიდოთ ტანსაცმელს, რომელიც მუცელზე გიჭერთ, რადგან ამან შეიძლება ბავშვი შეაწუხოს და სისხლის მიმოქცევა შეანელოს. ფეხებზე ძალიან მომდგარმა შარვალმაც შეიძლება ვენების ფუნქციონირებას ხელი შეუშალოს და ვარიკოზული ვენების განვითარებას შეუწყოს ხელი.;;;
კიდევ ერთი მნიშვნელოვანი საკითხია ორსულობის დროს მაღალქუსლიანი ფეხსაცმლის ტარება. ფეხშიშველი დგომისას სხეულის წონის 50% ქუსლებზე ნაწილდება, ხოლო 50% — ფეხის წინა ნაწილზე, რაც წონასწორობას უზრუნველყოფს. მაღალქუსლიანი ფეხსაცმლის ტარებისას ეს თანაფარდობა დაახლოებით 10% და 90% ხდება, რაც წონასწორობის სერიოზულ დარღვევას იწვევს. ორსულობისას მზარდი საშვილოსნოს გამო სხეულის სიმძიმის ცენტრი ისედაც იცვლება, ამიტომ მაღალქუსლიანი ფეხსაცმლის ტარებამ შეიძლება წონასწორობა დაგაკარგვინოთ და სერიოზული ტრავმები გამოიწვიოს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ახლა, როცა მესამე ტრიმესტრი დაიწყეთ, საუკეთესო დროა, ექიმთან განიხილოთ "რეზუს (Rh) შეუთავსებლობა" (თუ თქვენი სისხლის ჯგუფი უარყოფითია) და გლუკოზის დატვირთვის ტესტის შედეგები. წელის ტკივილის შესამცირებლად შეგიძლიათ ორსულობის მხარდამჭერი ქამარი გამოიყენოთ. დღის განმავლობაში დაიწყეთ ბავშვის მოძრაობების დათვლა; ჩვეულებრივ, 2 საათის განმავლობაში 10 მოძრაობა ნორმად მიიჩნევა.') WHERE id = 'efc08af4-0ca2-4af8-832f-852d08704ce8';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამ კვირიდან ორსულობის 7-ე თვეში გადადიხართ. ამავდროულად, ორსულობის ბოლო სამ თვეში, რომელსაც ბოლო ტრიმესტრსაც უწოდებენ, თქვენი ბავშვი უკვე იმდენად განვითარებული იქნება, რომ საშვილოსნოს გარეთ სიცოცხლეს შეძლებს. ამ ეტაპზე შესაძლო ნაადრევი მშობიარობის შემთხვევაში ბავშვის გადარჩენის შანსი 80%-ზე მეტია. ფილტვები განვითარებას სრულად 37-ე კვირაში დაასრულებს, თუმცა ამ კვირაში ნაადრევი მშობიარობის შემთხვევაშიც ისინი უკვე იმდენად განვითარებულია, რომ ახალშობილთა ინტენსიური თერაპიის განყოფილებაში სათანადო დახმარებით ბავშვმა სუნთქვა შეძლოს. ამის მთავარი მიზეზი ის არის, რომ სურფაქტანტის მნიშვნელოვანი ნაწილი უკვე გამომუშავებულია.;;;
ამ კვირიდან ექიმმა შეიძლება ბავშვის მოძრაობების დათვლა გთხოვოთ. დათვლის დაწყებისას გახსოვდეთ, რომ ბავშვს ძილისა და სიფხიზლის პერიოდები აქვს და დღის დიდ ნაწილს ძილში ატარებს. კუნთების გაზრდილი ძალისა და სხეულის მასის წყალობით, მისი სიფხიზლისას თითოეულ მოძრაობას იგრძნობთ. ბავშვის მოძრაობების დასათვლელად უნდა შეარჩიოთ დროის მონაკვეთი, როდესაც ის ღვიძავს და აქტიურია. მშვიდ გარემოში მარცხენა გვერდზე დაწექით და თითოეული მოძრაობა ჩაინიშნეთ.'), baby_message_ka = COALESCE(baby_message_ka, 'გამარჯობა, დედიკო! ჩვენ დიდ წარმატებას მივაღწიეთ. ორსულობის ბოლო ეტაპზე გადავედით. ახლა ჩემთვის მთავარი წონის მომატება და დაბადებისთვის მომზადებაა. აქ ადგილი სულ უფრო მცირდება, მაგრამ მე უფრო ვძლიერდები. ძლიერად გირტყამთ ფეხს და გეუბნებით: "გილოცავთ!"'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'დიდი ბადრიჯანი'), body_changes_ka = COALESCE(body_changes_ka, 'ამ კვირებში თქვენს ბავშვს განსაკუთრებით სჭირდება კალციუმი. თუ დღის განმავლობაში საკვებიდან საკმარის კალციუმს ვერ მიიღებთ, ეს მოთხოვნილება თქვენს ძვლებში არსებული მარაგის ხარჯზე დაკმაყოფილდება.;;;
რკინა მონაწილეობს როგორც თქვენი, ისე ბავშვის სისხლის წითელი უჯრედების წარმოქმნაში. თუ საკვებითა და ექიმის მიერ დანიშნული დანამატებით რკინის საჭიროება საკმარისად არ დაკმაყოფილდება, ბავშვი საკუთარ სისხლის უჯრედებს მაინც წარმოქმნის, თუმცა თქვენ შესაძლოა ანემია განგივითარდეთ.;;;
რკინასა და კალციუმთან ერთად, მესამე ტრიმესტრში ერთ-ერთი უმნიშვნელოვანესი საჭიროება Omega-3 ცხიმოვანი მჟავებია, რომლებსაც ბავშვი ამ კვირებში ტვინის ქსოვილის დაჩქარებული განვითარებისთვის დიდი რაოდენობით იყენებს. Omega-3 გვხვდება მცენარეულ წყაროებში, როგორიცაა სოია და ნიგოზი, თუმცა ყველაზე დიდი რაოდენობით თევზშია. ამიტომ ორსულობის პერიოდში სასარგებლოა თევზის მოხმარების გაზრდა.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ამ პერიოდის აღსანიშნავად პარტნიორთან ერთად მოაწყვეთ პატარა ვახშამი ან, თუ "Baby Shower"-ს გეგმავთ, სია შეადგინეთ. დააჯილდოეთ საკუთარი თავი — თქვენ დიდ საქმეს აკეთებთ!') WHERE id = '96a22ed0-5e13-4094-87c4-74d0da4a58fc';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამ კვირაში ექიმის შემოწმებისას შეიძლება გაირკვეს, რომ თქვენი ბავშვი მშობიარობისთვის თავის წინამდებარეობაში ან მენჯით წინამდებარეობაშია. არც ერთ შემთხვევაში შეშფოთების საფუძველი არ არსებობს. ორსულობის 34-ე კვირამდე ყველა ბავშვს აქვს საკმარისი რაოდენობის ამნიონური სითხე, რათა საშვილოსნოში თავისუფლად იმოძრაოს და მდებარეობა შეიცვალოს. ბავშვის ზრდასთან ერთად მისი თავი სხეულთან შედარებით მძიმდება და მიზიდულობის ძალის გავლენით ის თავს ქვემოთ მიმართავს. ვაგინალური მშობიარობა ყველაზე მარტივად ამ მდებარეობაში მიმდინარეობს. ამგვარად, ბავშვები ბუნებრივი მშობიარობის დროს გამოსაძევებლად მზად არიან.;;;
ორსულობის 32-34-ე კვირებისთვის ბავშვების დაახლოებით 70-80% უკვე იკავებს მშობიარობისთვის თავის წინამდებარეობას. 37-ე კვირისთვის კი ეს მაჩვენებელი 95%-მდე იზრდება. ზოგ შემთხვევაში ბავშვი შეიძლება განსხვავებულად, მაგალითად, მენჯით წინამდებარეობაში მოთავსდეს. ასეთ სიტუაციაში ექიმი საავადმყოფოში მეთვალყურეობას გააძლიერებს და საჭიროების შემთხვევაში მშობიარობა საკეისრო კვეთით ჩატარდება. გარკვეული პერიოდის შემდეგ ბავშვის მშობიარობისთვის საჭირო მდებარეობაში ჩაუდგომლობის მიზეზებს შორის შეიძლება იყოს ამნიონური სითხის ჭარბი რაოდენობა, პლაცენტის ისეთი მდებარეობა, როდესაც ის საშვილოსნოს ყელს ფარავს, საშვილოსნოს ფორმის ანომალიები და ვიწრო მენჯი.'), baby_message_ka = COALESCE(baby_message_ka, 'მე უკვე ძილის რეჟიმი მაქვს! 🌙 შემთხვევით დროს აღარ მძინავს. ძილისა და სიფხიზლის განსაზღვრული საათები მაქვს. ჩვეულებრივ, როცა შენ ისვენებ, მე ვიღვიძებ. ძილის დროს კი "REM ძილი" (თვალების სწრაფი მოძრაობა) მაქვს. ესე იგი, სიზმრებს ვხედავ! იქნებ სიზმარში შენც გხედავ...'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'დიდი ბადრიჯანი'), body_changes_ka = COALESCE(body_changes_ka, 'ამ პერიოდში ფიზიკური დაღლილობა შეიძლება კვლავ დაბრუნდეს. თქვენი მუცელი მნიშვნელოვნად გაიზარდა, რაც მოძრაობასა და კომფორტულად ძილს ართულებს. თუ თქვენი სისხლის ჯგუფის რეზუს-ფაქტორი უარყოფითია (-), ხოლო თქვენი პარტნიორის — დადებითი (+), ამ კვირაში ექიმს უნდა გაესაუბროთ "Rhogam"-ის (ანტირეზუს იმუნოგლობულინის) ინიექციის გაკეთების შესახებ (რეზუს-კონფლიქტის პროფილაქტიკისთვის).'), daily_tip_ka = COALESCE(daily_tip_ka, 'ძილის წინ ნუ მიირთმევთ მძიმე საკვებს და მოერიდეთ ეკრანებს (ტელეფონი, TV). თბილი შხაპი და ერთი ჭიქა თბილი რძე ჩაძინებაში დაგეხმარებათ.') WHERE id = '65a58c5e-3cca-4355-b7cb-eb0f566d682e';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამ ეტაპზე თქვენი ბავშვის წონა შეიძლება იყოს როგორც 850 გრამი, ისე 1000 გრამზე მეტიც. თუ ბავშვის წონა საშუალოზე ნაკლები ან მეტია, არ უნდა ინერვიულოთ. გახსოვდეთ, რომ ყველა ბავშვი ერთნაირი წონით არ იბადება და ჯანმრთელი ახალშობილის წონა შეიძლება 2500-4000 გრამის ფარგლებში მერყეობდეს. ახლა, როცა მესამე ტრიმესტრში შედიხართ, თქვენი ბავშვის წონის ძირითადი მატება სწორედ ამ ეტაპის შემდეგ დაიწყება.;;;
მესამე ტრიმესტრში ბავშვები კვირაში საშუალოდ 250 გრამს იმატებენ. თუ ჯანმრთელობის პრობლემა არ არსებობს, ბავშვი წონის მატებას მაშინაც განაგრძობს, როდესაც მშობიარობა გვიანდება. თუ თქვენთან ან ბავშვთან დაკავშირებული პრობლემა არსებობს, წონის მატების ტემპი შეიძლება შენელდეს ან შეჩერდეს. დროულად დაბადებული ბავშვისთვის 2500-4000 გრამი დაბადების ნორმალურ წონად ითვლება. ბავშვები ხშირად 3000-3500 გრამის წონით იბადებიან. გოგო და ბიჭ ბავშვებს შორის საშუალო წონის სხვაობა შეიძლება დაახლოებით 10 პროცენტი იყოს.;;;
გარდა ამისა, გენეტიკური ფაქტორები ბავშვის დაბადების წონის განმსაზღვრელი ერთ-ერთი უმნიშვნელოვანესი ფაქტორია. ბავშვის მდგომარეობის მხოლოდ წონის მიხედვით შეფასება არასწორია. მიუხედავად იმისა, რომ ჯანსაღად იკვებებით, ბავშვთან დაკავშირებულმა პრობლემებმა, ქრონიკულმა დაავადებებმა, სიგარეტის მოხმარებამ და გენეტიკურმა ფაქტორებმა შეიძლება დაბადების დაბალი წონა გამოიწვიოს.'), baby_message_ka = COALESCE(baby_message_ka, 'თვალებს ვახამხამებ! 😉 დედიკო, უკვე შემიძლია თვალების გახელა და დახუჭვა. თუ შენს მუცელს მკვეთრი სინათლე დაეცემა, სახეს ვაბრუნებ ან თვალებს ვახამხამებ. ჩემი მხედველობა ჯერ სრულად განვითარებული არ არის, მაგრამ სინათლესა და სიბნელეს შესანიშნავად ვარჩევ. ერთი სული მაქვს, როდის დავინახავ სამყაროს.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'დიდი ბადრიჯანი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის დროს სისხლში პროგესტერონის დონის მატების გამო მენჯის მიდამო, მუცლის ღრუს იოგები და კუნთები იწელება და უფრო ელასტიკური ხდება. ეს ცვლილება ხელს უწყობს მზარდი საშვილოსნოს დაჭერასა და სტაბილიზაციას. ორსულობის დასასრულისკენ ხერხემლის ზედა ნაწილი ოდნავ უკან იხრება, რათა საშვილოსნოს მიერ სხვა ორგანოებზე შექმნილი წნევა შეამციროს. მენჯის შემადგენელი სახსრები უფრო მოქნილი ხდება და მშობიარობისთვის მზადებას იწყებს. ყველა ეს ცვლილება ორგანიზმში მომატებული და გარდაქმნილი ორსულობის ჰორმონების, მათ შორის ესტროგენისა და პროგესტერონის, ზემოქმედებით ხდება.'), daily_tip_ka = COALESCE(daily_tip_ka, 'წელის ტკივილის შესამსუბუქებლად სცადეთ იოგის მოძრაობა "კატა-ძროხა" (Cat-Cow) — დადექით ოთხზე და მონაცვლეობით მოხარეთ და გამართეთ ზურგი. ეს ხერხემალზე ზეწოლას ამცირებს და ბავშვს უფრო კომფორტულ მდებარეობაში გადასვლაში ეხმარება.') WHERE id = 'd388c035-3ae4-451c-bcce-e8ae700cd74b';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამ ეტაპზე თქვენი ბავშვი შეიძლება სხვადასხვა მდებარეობაში იყოს. ბავშვისთვის საუკეთესო მდებარეობად მიიჩნევა "წინა" მდებარეობა, როდესაც მისი სახე თქვენი ზურგისკენაა მიმართული, და "თავით წინამდებარეობა", როდესაც თავი ქვემოთ აქვს. ამ მდებარეობის იდეალურად მიჩნევას რამდენიმე მიზეზი აქვს. ასე ბავშვი ადვილად ერგება თქვენი მენჯის მოხრილობას. მშობიარობის დროს ეს მდებარეობა ბავშვს საშუალებას აძლევს, ზურგით შემობრუნდეს და ნიკაპი მკერდზე მიაბჯინოს. ამასთან, თავის თხემი საშვილოსნოს ყელზე ზეწოლას ახდენს და ხელს უწყობს ჭინთვებისთვის საჭირო ჰორმონების გამომუშავებას. ჭინთვების ეტაპზე ეს ბავშვს სწორი კუთხის დაკავებასა და თავის სამშობიარო არხში მარტივად გავლაში ეხმარება. ამის წყალობით შეიძლება იმშობიაროთ ხელოვნურად გამოწვეული ჭინთვებისა და საკეისრო კვეთის გარეშე. მშობიარობა უფრო სწრაფად და მარტივად ჩაივლის, ნაკლებ ტკივილს იგრძნობთ და უფრო მალე შეძლებთ მოდუნებას. ორსულობის ბოლო კვირებამდე ბავშვი შეიძლება ჯერ კიდევ არ იყოს მშობიარობისთვის საჭირო მდებარეობაში. ამ ეტაპზეც კი შესაძლებელია, რომ ის თავისით შემოტრიალდეს. ზოგ შემთხვევაში ბავშვი მშობიარობის დაწყების მომენტშიც კი ტრიალდება.'), baby_message_ka = COALESCE(baby_message_ka, 'სუნთქვაში ვვარჯიშობ! 🌬️ რა თქმა უნდა, აქ ჯერ ჰაერი არ არის, მაგრამ გულმკერდს ზემოთ-ქვემოთ ვამოძრავებ და ამნიონურ სითხეს ფილტვებში ვისრუტავ. ეს ვარჯიშები ჩემს დიაფრაგმას აძლიერებს. ზოგჯერ ამ დროს სლოკინი მეწყება. გრძნობ იმ რიტმულ ბიძგებს? ეს ჩემი ვარჯიშია.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'დიდი ბადრიჯანი'), body_changes_ka = COALESCE(body_changes_ka, 'ნაწლავების მუშაობის დარღვევა და ყაბზობა ორსულობის განმავლობაში ყველაზე გავრცელებულ პრობლემებს შორისაა. ამ პერიოდში ორსულობის ჰორმონის, პროგესტერონის, მომატებული დონე საჭმლის მომნელებელი ტრაქტის კუნთების მოდუნებას იწვევს. შედეგად, ნაწილობრივ მონელებული საკვები, რომელსაც ქიმუსი ეწოდება, ნაწლავებში უფრო ნელა გადაადგილდება.;;;
ამასთან, მზარდი საშვილოსნო მუცლის ღრუში მსხვილი ნაწლავის სხვადასხვა ნაწილზე ზეწოლას ახდენს და საკვების ნარჩენების გადაადგილებას აფერხებს. შედეგად ვითარდება ყაბზობა.;;;
თუ ყაბზობა ერთ კვირაზე მეტხანს გრძელდება, პრობლემის გახანგრძლივების თავიდან ასაცილებლად აუცილებლად მიმართეთ ექიმს. ხანგრძლივად უმკურნალოდ დატოვებულმა ყაბზობამ შეიძლება მრავალი პრობლემა, უპირველესად კი ჰემოროი, გამოიწვიოს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ჭამის შემდეგ დაუყოვნებლივ ნუ დაწვებით — სულ მცირე 1 საათის განმავლობაში ვერტიკალურ მდგომარეობაში დარჩით. მაღალი ბალიშით ძილი კუჭის მჟავის უკან ამოსვლას შეუშლის ხელს. მოერიდეთ სოდიანი წყლის დალევას (მარილის შემცველობის გამო შეშუპებას იწვევს).') WHERE id = 'b00d6682-7d24-499f-8007-e3d98626d47b';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ტვინის უჯრედები ყოველ წამს მილიონობით ნეირონის წარმოქმნას განაგრძობს. ტვინის უჯრედები საოცარი სისწრაფით მრავლდება, ხოლო ტვინის მოცულობა ამისთვის საკმარისი არ არის, ამიტომ მის სტრუქტურაში ნაოჭები იწყებს ფორმირებას. ბავშვის უკვე განვითარებული გრძნობის ორგანოების დახმარებით, სწავლის პროცესთან ერთად, ამ დანაოჭებული სტრუქტურების ჩამოყალიბებაც ჩქარდება. ტვინის ზედაპირის ღარებითა და ხვეულებით დაფარული სტრუქტურა მას საშუალებას აძლევს, საკუთარ თავზე და შიგნით დამატებითი სივრცე შექმნას და უფრო მეტი ფუნქცია შეასრულოს. ამ ხვეულების წყალობით, ადამიანის ტვინის ზედაპირის ფართობი თავის ქალის შიგნით მოქცეული სივრციდან გვერდიგვერდ გაშლილი ორი გაზეთის გვერდის ფართობამდე იზრდება.'), baby_message_ka = COALESCE(baby_message_ka, 'მე გცნობ! 🎤 დედიკო, შენი ხმა ჩემთვის ყველაზე ახლობელია. კვლევები აჩვენებს, რომ შენი ხმის გაგონებისას ჩემი გულისცემა მშვიდდება. უკვე ვსწავლობ შენს ინტონაციასა და საუბრის მანერას. როცა დავიბადები, ჩემს დასამშვიდებლად მხოლოდ შენი საუბარიც საკმარისი იქნება.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'დიდი ბადრიჯანი'), body_changes_ka = COALESCE(body_changes_ka, 'ამ კვირებში შესაძლოა სარძევე ჯირკვლების სადინარებში დაგროვილი რძის მცირე ნაწილი გამოიყოს. ძუძუსთავების ნებისმიერი სახით სტიმულაციამ შეიძლება გაზარდოს რძის გამოყოფა და, ამავე დროს, დააჩქაროს ჰორმონ ოქსიტოცინის გამოყოფა, რამაც საშვილოსნოს შეკუმშვები შეიძლება გამოიწვიოს. ამიტომ იმის შესამოწმებლად, გამოიყოფა თუ არა რძე, ძუძუსთავები არასდროს მოიჭიროთ. ჩვეულებრივ პირობებში სარძევე ჯირკვლებიდან რძის გამოყოფა ნაადრევ მშობიარობასთან დაკავშირებული არ არის, თუმცა ძუძუსთავების სტიმულაციისას საშვილოსნოს კუნთებმა შეიძლება შეკუმშვა დაიწყოს, რაც ნაადრევი მშობიარობის მიზეზი შეიძლება გახდეს. ჰორმონი პროლაქტინი ასევე თრგუნავს ოვულაციას, ამიტომ მეძუძურ დედებს გარკვეული პერიოდის განმავლობაში ოვულაცია არ აქვთ. ეს ჰორმონი ხელს უშლის კვერცხუჯრედების მომწიფებასა და განვითარებას, რის გამოც მშობიარობის შემდეგ გარკვეული ხნის განმავლობაში მენსტრუაცია არ აღინიშნება. ზოგ ქალს მენსტრუალური ციკლი 6 თვის განმავლობაში უწესრიგდება, თუმცა მისი 2 წლამდე არარსებობაც ნორმად მიიჩნევა.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ამ საღამოს საკუთარ თავს ცოტა დრო დაუთმეთ და ბავშვს უამბეთ პირველი მოგზაურობის შესახებ, რომელშიც მომავალში ერთად გაემგზავრებით.') WHERE id = '4ca04882-bd78-4264-985d-0684e463329f';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ტვინის ტალღები უკვე ჩამოყალიბებულია. ბოლო წლებში ჩატარებული კვლევების თანახმად, ელექტრული იმპულსებით მოქმედი ტვინი და მის მიერ წარმოქმნილი ელექტრული ტალღები ჯერ კიდევ დედის საშვილოსნოში იწყებს ფორმირებას. ტვინი წარმოქმნის ბეტა, ალფა, თეტა და დელტა ტალღებს, რომლებიც ჰერცით (Hz) გამოისახება. ჰერცი წამში ციკლების რაოდენობას აღნიშნავს. როდესაც ტვინი ბეტა მდგომარეობაშია, სხეულს ღვიძავს. ეს ყოველდღიურ ცხოვრებაში ყველაზე ხშირად გამოყენებული გონებრივი მდგომარეობაა და მოიცავს ფიქრს, საუბარს, გადაწყვეტილების მიღებას, პრობლემის გადაჭრას, დაგეგმვასა და მოქმედების დაწყებას. დღის განმავლობაში, როდესაც თვალებს ხუჭავთ და სხეულს ადუნებთ, ტვინი ბეტა სიხშირიდან ალფა სიხშირეზე გადადის. ამ მდგომარეობას მსუბუქ ჰიპნოზს უწოდებენ; ამ დროს ცნობიერი გონების კონტროლი მცირდება, შემოქმედებითობა კი იზრდება. დელტა გონებრივი მდგომარეობა ჩვენთვის ნაცნობი ძილის რეჟიმია. ის ქვეცნობიერად კი არა, ცნობიერების მიღმა მიმდინარეობს. როდესაც გონება დელტა ტალღების სიხშირეზე მუშაობს, სხეული უკვე დასვენებისა და აღდგენის ეტაპზეა. ძილი ყველა ადამიანს სჭირდება, რადგან ძილის დროს სხეული აღდგება, ნერვული სისტემა კი ისვენებს.'), baby_message_ka = COALESCE(baby_message_ka, '28 კვირა სრულდება! 👋 ოფიციალურად მე-7 თვეში გადავდივართ. ჩემი სივრცე თანდათან ვიწროვდება, ამიტომ ახლა უკვე ჩემს „ცურვას“ კი არა, იდაყვებისა და მუხლების კონკრეტულ ბიძგებს გრძნობ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'დიდი ბადრიჯანი'), body_changes_ka = COALESCE(body_changes_ka, 'ამ ეტაპზე ჰორმონებისა და ორგანოების ნაწილობრივი გადაადგილების გამო თქვენს საჭმლის მომნელებელ სისტემაში მნიშვნელოვანი ცვლილებები ხდება. კუჭის სარქვლის მოდუნების შედეგად კუჭის მჟავა შესაძლოა საყლაპავში გადავიდეს და გულძმარვა გამოიწვიოს. ამიტომ ჭამის დასრულებისთანავე დაწოლას უნდა მოერიდოთ. გაზიანი სასმელებით, ცხარე კერძებითა და ცხიმიანი შემწვარი საკვებით კუჭის ზედმეტად გადავსებამ შესაძლოა გულძმარვა კიდევ უფრო გააძლიეროს. საყლაპავს მჟავისგან დამცავი მექანიზმი არ აქვს და ხშირმა გულძმარვამ ამ მიდამოში შესაძლოა მუდმივი ცვლილებები გამოიწვიოს. ამიტომ თქვენი ჯანმრთელობისთვის ძალიან მნიშვნელოვანია, ყურადღება მიაქციოთ კვების რეჟიმს და ხშირად, მცირე ულუფებით იკვებოთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'დღეს დააჯილდოეთ საკუთარი თავი იმისთვის, რომ ეს 28-კვირიანი გზა წარმატებით გაიარეთ, და დაისვენეთ. ფეხების შეშუპების შესამცირებლად აკონტროლეთ მარილის მიღება და დასვენებისას ფეხები მაღლა შემოაწყვეთ. თუ ჯერ არ დაგიწყიათ, ბავშვისთვის საჭირო პირველი ნივთების სიის შედგენას შეუდექით. ხვალიდან 29-ე კვირას ვიწყებთ — ახალ ეტაპს, რომელიც ჩვენს შეხვედრას კიდევ ერთი ნაბიჯით გვაახლოებს!') WHERE id = 'bfd55361-27a4-4f83-b42f-472543bccd24';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ახლა, როდესაც მესამე ტრიმესტრში გადადიხართ, თქვენი ბავშვი კვირაში დაახლოებით 150-200 გრამს მოიმატებს. წონის მატების მიზეზი ცხიმოვანი ქსოვილის სწრაფი წარმოქმნაა. ცხიმოვანი უჯრედების რაოდენობის ზრდასთან ერთად ბავშვის კანი დანაოჭებულ იერს კარგავს. ამ კვირაში ბავშვის სანაყოფე გარსიც უკვე სრულად არის განვითარებული. თქვენ შედიხართ პერიოდში, როდესაც გარე სამყაროსთვის მომზადებული ბავშვის ტვინი და თავის ქალა სწრაფად ვითარდება. განვითარებული გრძნობის ორგანოებისა და ტვინის იმ უბნების მომწიფების წყალობით, რომლებიც მათ მართავს, ბავშვი გარედან მიღებული სტიმულების მეშვეობით სწავლას უკვე იწყებს. რადგან ამ ცოდნის შესანახად ტვინში გარკვეული მოცულობაა საჭირო, სივრცის დასაზოგად მის სტრუქტურაში ხვეულები იწყებს ფორმირებას. დაბადებისთანავე თქვენი ბავშვი სწრაფად დაიწყებს სწავლასა და მიღებული ინფორმაციის მეხსიერებაში გადატანას. მის ტვინში საჭიროებაზე მილიარდობით მეტი უჯრედია; მათი ნაწილი ე.წ. ნაწილობრივი გასხვლის პროცესით განადგურდება და ახალი ცოდნისთვის სივრცეს გაათავისუფლებს.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი ძვლები მყარდება! 🦴 დედიკო, ახლა შენგან ძალიან ბევრი კალციუმი მჭირდება. ჩემი ძვლები სწრაფად მყარდება. ყოველდღიურად დაახლოებით 250 მგ კალციუმს ვაგროვებ. თუ საკმარის რძეს არ დალევ, ამ კალციუმს შენი კბილებიდან და ძვლებიდან „მოვიპარავ“. თავს გაუფრთხილდი, ყველი მიირთვი!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'კომბოსტო'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის განმავლობაში მნიშვნელოვანი ცვლილებები არა მხოლოდ თქვენს სხეულში, არამედ ტვინის ბიოქიმიაშიც ხდება. ამ ცვლილებების გამო, განსაკუთრებით თუ ემოციურად მგრძნობიარე ხართ, შესაძლოა დეპრესიისკენ მიდრეკილება გამოგივლინდეთ. დეპრესია, ჩვეულებრივ, მშობიარობის შემდეგ ძლიერდება, თუმცა ზოგჯერ მისი პირველი ნიშნები ჯერ კიდევ ორსულობის პერიოდში ჩნდება. დეპრესიის ნიშნებია მუდმივი გაღიზიანება, საკუთარი თავის უღირსად ან დამნაშავედ აღქმა, მადისა და კვების დარღვევები, ტკივილები, რომლებიც მკურნალობას არ ექვემდებარება, იმ საქმიანობებით სიამოვნების ვეღარ მიღება, რომლებიც ადრე გაბედნიერებდათ, თქვენთვის საინტერესო მოვლენების მიმართ ინტერესის შემცირება, ძილის სერიოზული დარღვევები, ყურადღების მოკრებისა და კონცენტრაციის გაძნელება. ამ პერიოდში მნიშვნელოვანია, მიიღოთ მხარდაჭერა პარტნიორისა და ოჯახის წევრებისგან, ყურადღება დადებით მოვლენებზე გაამახვილოთ და ეცადოთ, გონება თქვენთვის მტკივნეული საკითხებით არ გადატვირთოთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'განსაკუთრებული ყურადღება მიაქციეთ კალციუმის მიღებას (რძე, იოგურტი, ყველი), რადგან ამ პერიოდში ბავშვი თქვენგან კალციუმს სწრაფად „იპარავს“. წელის ტკივილის შესამცირებლად ჯდომისას აუცილებლად გამოიყენეთ ბალიშები, რომლებიც ზურგს საყრდენს შეუქმნის. თუ ჯერ არ დაგიწყიათ, ახლა შესანიშნავი დროა ბავშვის ჩანთისთვის საჭირო ნივთების სიის შესადგენად. დღეს ბავშვთან ერთად მშვიდი მუსიკის ფონზე დაისვენეთ.') WHERE id = '124477a3-06f6-44dd-a276-41487168c5e0';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'მიმიკური კუნთები სრულად განვითარებულია. ნაყოფს შეუძლია გაიღიმოს, სახე მოეღუშოს და ენა გამოყოს. თირკმელზედა ჯირკვლები ჰორმონ „ესტრიოლს“ გამოიმუშავებენ. ეს ჰორმონი დედის ორგანიზმში რძის გამომუშავებას ასტიმულირებს.;;;
გაძვალების პროცესი პიკს აღწევს. ნაყოფის ჩონჩხი მყარდება. თავის ტვინში თერმორეგულაციის ცენტრი იწყებს მუშაობას. ბავშვს უკვე შეუძლია სხეულის ტემპერატურის ნაწილობრივ რეგულირება და ნაკლებად არის დამოკიდებული ამნიონური სითხის ტემპერატურაზე.'), baby_message_ka = COALESCE(baby_message_ka, 'მე ვიღიმი! 😊 ულტრაბგერითი გამოკვლევისას ექიმები ხშირად ხედავენ, როგორ ვიღიმით. ეს, ჩვეულებრივ, ძილის დროს ხდება. იქნებ ანგელოზებს ვხედავ? თუ უბრალოდ სახის კუნთებს ვავარჯიშებ? რაც არ უნდა იყოს მიზეზი, მე ბედნიერი ვარ. შენც გაიღიმე, დედიკო!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'კომბოსტო'), body_changes_ka = COALESCE(body_changes_ka, 'პლაცენტა თქვენი ბავშვის დაბადებამდე საკუთარ თავზე იღებს როგორც ფილტვების, ისე თირკმელებისა და ღვიძლის ფუნქციებს. ვინაიდან ბავშვის ფილტვებს ჯერ კიდევ არ შეუძლიათ თავიანთი ფუნქციის შესრულება, ამ საქმეს პლაცენტა ასრულებს. პლაცენტა ჭიპლარის სისხლძარღვებიდან მიღებულ სისხლს თქვენი ორგანიზმიდან მიღებული ჟანგბადით ამდიდრებს და ჭიპლარის მეშვეობით კვლავ თქვენს ბავშვს უგზავნის. ამავე გზით, ბავშვის ორგანიზმში წარმოქმნილი ყველა ნარჩენი ნივთიერება, ნაცვლად იმისა, რომ თირკმლებისა და ღვიძლის მეშვეობით გამოიყოს, პლაცენტაში, იქიდან კი თქვენს სისხლის მიმოქცევის სისტემაში გადადის და ორგანიზმიდან გამოიდევნება. ასეთი სასიცოცხლოდ მნიშვნელოვანი ფუნქციის მქონე პლაცენტაში წარმოქმნილმა ნებისმიერმა პრობლემამ, როგორიცაა კალციფიკაცია, ნაადრევი დაბერება ან სისხლის მიმოქცევის დარღვევა, შეიძლება ბავშვის არასაკმარისი კვება გამოიწვიოს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'სტრიების საწინააღმდეგო კრემები რეგულარულად გამოიყენეთ. თუმცა გახსოვდეთ, რომ სტრიების გაჩენა უფრო მეტად გენეტიკაზეა დამოკიდებული. ქავილის შესამცირებლად მიიღეთ გრილი შხაპი და მოერიდეთ სინთეტიკურ ტანსაცმელს.') WHERE id = '82410eeb-db13-46e1-be5e-f6446cc033ef';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ეს კვირები თქვენი ბავშვის ამნიონური სითხის მოცულობის ზრდის ბოლო პერიოდია. მომდევნო რამდენიმე კვირის განმავლობაში ამნიონური სითხის რაოდენობა აღარ მოიმატებს და მშობიარობამდე სტაბილური დარჩება. ამნიონური სითხე სტერილური სითხეა, რომელიც თქვენს ბავშვს გარეგანი გარემოს ზემოქმედებისგან იცავს. ბავშვი ამ სითხეს ყლაპავს, ამასთან, ის ფილტვებიდან და კანიდან შეიწოვება და სისხლში გადადის. შემცირებული სითხე ბავშვის მიერ შარდის გამოყოფით კვლავ ივსება. სითხე შეიცავს როგორც ბავშვის სხეულის ბიოქიმიის ამსახველ ნივთიერებებს, ისე მისი კანიდან მოცილებულ უჯრედებს, ვერნიქსსა და ლანუგოს თმას.;;;
ამნიონური სითხე ხელს უწყობს თქვენი ბავშვის ზრდასა და განვითარებას. ის მონაწილეობს თავის ტვინის განვითარებაში. იცავს ბავშვს ისეთი გარეგანი გამღიზიანებლებისგან, როგორებიცაა ხმა, დარტყმა, სინათლე და წნევა. მონაწილეობს სხეულის ტემპერატურის რეგულირებასა და მის სტაბილურ შენარჩუნებაში. ხელს უწყობს გრძნობის ორგანოების განვითარებას. მნიშვნელოვან როლს ასრულებს მრავალი ორგანოთა სისტემის, განსაკუთრებით კუნთოვანი და ნერვული სისტემების განვითარებაში.;;;
ამნიონური სითხის ძირითადი წყარო თქვენი ბავშვის თირკმლებია. ბავშვის თირკმლების მიერ გამოყოფილი შარდი ამნიონურ სითხეს ქმნის. ბავშვი ამ სითხეს ყლაპავს და ის კვლავ სისხლის მიმოქცევის სისტემაში გადადის. სისხლის მიმოქცევაში გადასული სითხე თირკმლებში ხელახლა იფილტრება და შარდის სახით კვლავ ამნიონურ სითხეს უერთდება. ეს ციკლი უწყვეტად მეორდება.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი კბილები დამალულია! 🦷 დედიკო, ჩემი ღრძილების ქვეშ სარძევე კბილების ჩანასახები უკვე მზადაა. მათ ქვემოთ მუდმივი კბილების ჩანასახებიც კი არის. მე უკბილოდ დავიბადები, მაგრამ ყველაფერი მზად მაქვს. ბუნება ძალიან საინტერესოა, არა? მომავლისთვის მარაგს ვაგროვებთ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'კომბოსტო'), body_changes_ka = COALESCE(body_changes_ka, 'თუ საკეისრო კვეთის აუცილებლობა არ არსებობს, თქვენი მშობიარობის მეთოდი ჯერ კიდევ ზუსტად განსაზღვრული არ არის. ბოლო ტრიმესტრში გადასვლასთან ერთად მშობიარობის მეთოდზე ფიქრი უნდა დაიწყოთ. მშობიარობის სახეებია: ბუნებრივი მშობიარობა, საკეისრო კვეთა, ეპიდურული ანესთეზიით მშობიარობა და წყალში მშობიარობა.;;;
ვაგინალური მშობიარობისას, რომელსაც ბუნებრივ მშობიარობასაც უწოდებენ, პროცესი საკმაოდ ხანგრძლივია. ვაგინალური მშობიარობისთვის საშვილოსნოს ყელი 10 სმ-მდე უნდა გაიხსნას. პირველ 4 სმ-ს ლატენტური ფაზა ეწოდება და საშვილოსნოს ყელის 4 სმ-მდე გახსნას ზოგჯერ 2 კვირაც კი შეიძლება დასჭირდეს. 4 სმ-დან 10 სმ-მდე გახსნის პერიოდი კი საშუალოდ 4-დან 12 საათამდე გრძელდება, რის შემდეგაც საშვილოსნოს ყელი სრულად არის გახსნილი.;;;
თუ ბავშვი მენჯით წინ მდებარეობს, ზედმეტად დიდია, მისი თავი სამშობიარო არხში ვერ თავსდება, აქვს გულისცემის დარღვევები ან პლაცენტა ფარავს საშვილოსნოს ყელს, ასევე, თუ თქვენ გაქვთ HPV ინფექცია, პრეეკლამფსია, ჭარბი წონა ან ვიწრო მენჯი, ბუნებრივი მშობიარობა ვერ ჩატარდება და აუცილებელი ხდება საკეისრო კვეთა.'), daily_tip_ka = COALESCE(daily_tip_ka, 'შარდის ბუშტის სრულად დასაცლელად ტუალეტში ჯდომისას ოდნავ წინ გადაიხარეთ. ეს შარდის ბუშტის სრულ დაცლას უწყობს ხელს და ინფექციის რისკს ამცირებს.') WHERE id = '98a97832-2773-43d8-bf72-e6458dfbc947';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის სეკრეციული ჯირკვლები განვითარებას აგრძელებს. ორგანიზმში ორი ტიპის სეკრეციული ჯირკვალია: შინაგანი და გარეგანი სეკრეციის ჯირკვლები. გარეგანი სეკრეციის ჯირკვლები თავიანთ გამონაყოფს სპეციალურ სადინრებში გამოყოფენ, ხოლო შინაგანი სეკრეციის ჯირკვლები — უშუალოდ სისხლში. სისხლით გადატანილი ჰორმონები კაპილარების მეშვეობით ყველა უჯრედამდე აღწევს.;;;
ერთ-ერთი ასეთი ჯირკვალია ჰიპოფიზი, რომელიც წინა ტვინის ქვედა ნაწილში მდებარეობს და მრავალ ჰორმონს გამოიმუშავებს. ეს ჰორმონები უზრუნველყოფს თქვენი ბავშვის ზრდას, განვითარებასა და სასქესო ჰორმონების ჩამოყალიბებას. ჰიპოფიზის მიერ გამომუშავებული ჰორმონები გავლენას ახდენს სპერმატოზოიდების წარმოქმნაზე, თუ ბავშვი ბიჭია, და კვერცხუჯრედების ჩამოყალიბებაზე, თუ ბავშვი გოგოა; ასევე არეგულირებს ორგანიზმის წყლის ბალანსსა და არტერიულ წნევას. ფარისებრი ჯირკვალი თავისი ჰორმონებით ნივთიერებათა ცვლის სიჩქარეს არეგულირებს და ბავშვის ზრდის პერიოდში გაძვალების პროცესს აჩქარებს. გარდა ამისა, ის უჯრედების მიერ ჟანგბადის გამოყენებას არეგულირებს. თირკმელზედა ჯირკვლები კი მონაწილეობს ადრენალინის გამოყოფაში, რათა ორგანიზმი შესაძლო საფრთხეებისგან დაიცვას, და არეგულირებს ორგანიზმის მინერალურ ბალანსს. შერეული სეკრეციის ჯირკვალი — პანკრეასი — გამოყოფს ინსულინს, გლუკაგონსა და საჭმლის მომნელებელ ფერმენტებს და უზრუნველყოფს სისხლში შაქრის დონის რეგულირებას.'), baby_message_ka = COALESCE(baby_message_ka, '200 დღე! 🎉 დედიკო, დაუჯერებელია! ჩვენ უკვე 200 დღეა ერთად ვართ. მე დიდი გოგრის ზომის ვარ. ახლა ძალიან ძლიერი ვარ. ჩემმა ბიძგებმა შეიძლება ზოგჯერ გატკინოს, მაგრამ იცოდე, რომ უბრალოდ ჩემს ძალას ვამოწმებ. ჩვენს შეხვედრამდე ცოტა დარჩა!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'დიდი გოგრა'), body_changes_ka = COALESCE(body_changes_ka, 'დაახლოებით ორი თვის განმავლობაში თქვენი ექიმი ჩაატარებს მენჯის ძვლების გაზომვას, რომელიც მენჯის გამოკვლევის სახელითაა ცნობილი. ამ გაზომვის მიზანია, თუ გეგმური საკეისრო კვეთა არ არის გათვალისწინებული, შემოწმდეს, შეესაბამება თუ არა მენჯის ზომები ვაგინალურ მშობიარობას. თუ მენჯის ზედა ნაწილში შევიწროების მსგავსი სტრუქტურული თავისებურებები გამოვლინდა, შევიწროების ხარისხის მიხედვით, შესაძლოა უპირატესობა მშობიარობის სხვა მეთოდებს მიენიჭოს.;;;
მენჯი დაახლოებით 10 სმ დიამეტრის არხია, რომელიც გარშემორტყმულია კუნთებითა და შემაერთებელი ქსოვილით. ეს არის გზა, რომელსაც თქვენი ბავშვი გაივლის და ამქვეყნად მოევლინება. აგებულებით ეს არხი შიგნიდან სწორი კი არა, უსწორმასწოროა. მის გასავლელად ბავშვს მშობიარობის დროს გარკვეული პოზიციების მიღება სჭირდება. საშვილოსნოს შეკუმშვები ამ პროცესში ბავშვისთვის როგორც მამოძრავებელი ძალა, ისე მიმართულების მიმცემია.;;;
ბავშვი თავს ჰორიზონტალურად ათავსებს მენჯის ძვლების ზედა საზღვრებით შექმნილ არხის შესასვლელში; არხის შუაში ჩასვლისას თავს 90 გრადუსით აბრუნებს და სახით თქვენკენ ტრიალდება, ხოლო არხის ბოლოს იმავე პოზიციაში თავი გარეთ გამოდის. თავის გამოსვლის შემდეგ, მხრებმაც რომ შეძლონ სამშობიარო არხში შესვლა, ბავშვი თავს თქვენი ერთ-ერთი ფეხის შიდა მხარისკენ აბრუნებს. მოტრიალების დასრულების შემდეგ სხეულის დარჩენილი ნაწილის გამოსვლით მშობიარობა სრულდება.'), daily_tip_ka = COALESCE(daily_tip_ka, 'მე-200 დღე აღნიშნეთ — საკუთარ თავს პატარა საჩუქარი გაუკეთეთ ან დასვენებისთვის დრო გამოყავით. წელის ტკივილის შესამცირებლად ჯდომისას ფეხების ქვეშ პატარა სკამი დაიდგით. ძილისას კვლავ მარცხენა გვერდზე დაწექით და მუხლებს შორის ბალიში მოათავსეთ; ეს სისხლის მიმოქცევას გააუმჯობესებს. თუ ჯერ არ დაგიწყიათ, კარგი დროა ბავშვის ოთახის მომზადებისა და სამშობიარო ჩანთის სიის დასასრულებლად.') WHERE id = 'dc4e8ae4-b5e0-48d5-8713-248744b76ec6';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის მუდმივი კბილების ჩანასახებს კბილის კვირტებში განვითარება უკვე დასრულებული აქვთ. სარძევე კბილები, რომლებიც ბავშვს დაბადებიდან გარკვეული დროის შემდეგ ამოუვა და რომლებსაც გარკვეული პერიოდის განმავლობაში გამოიყენებს, ძალიან მნიშვნელოვან როლს ასრულებს მუდმივი კბილების სწორად და ჯანსაღად ამოსვლაში. ბავშვის კბილები პირველად 5-8 თვის ასაკში იწყებს ღრძილების ზედაპირზე გამოჩენას. პირველი, როგორც წესი, ქვედა წინა საჭრელი კბილები ამოდის. ისინი ჩვეულებრივ ბავშვის 6 თვის ასაკიდან ამოსვლას იწყებს. ამის შემდეგ, დაახლოებით მე-8 თვიდან, ზედა საჭრელი კბილები ამოდის. მათ გვერდითი საჭრელი და საღეჭი კბილები მოჰყვება. ბოლოს უკანა საღეჭი კბილები ჩნდება. სარძევე კბილები ცვივა, როდესაც ქვემოდან ამომავალი მუდმივი კბილები მათზე ზეწოლას იწყებს. ეს ზეწოლა კბილის ფესვის თანდათანობით დაშლას და საბოლოოდ კბილის ამოვარდნას იწვევს. ბავშვის ზრდის ტემპის მიხედვით, მუდმივი კბილები 6-7 წლის ასაკში იწყებს ამოსვლას. „სიბრძნის კბილების“ ამოსვლით სრულდება მუდმივი კბილების ფორმირება, რომელთა საერთო რაოდენობა 32-ია.'), baby_message_ka = COALESCE(baby_message_ka, 'კალციუმი მჭირდება! 🥛 ჩემი ძვლები სწრაფად მტკიცდება. ახლა ყოველდღე შენი სისხლიდან დაახლოებით 250 მილიგრამ კალციუმს ვიღებ. ეს აუცილებელია, რომ ჩემი ჩონჩხი ძლიერი იყოს. თუ რძეს არ დალევ, ამ კალციუმს შენი კბილებისა და ძვლებისგან „ვისესხებ“. თავს გაუფრთხილდი, დედიკო!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'დიდი გოგრა'), body_changes_ka = COALESCE(body_changes_ka, 'ალბათ უკვე შეამჩნიეთ ცვლილებები თქვენს თმაზე. ის უფრო ხშირი და მბზინვარე ჩანს და საკმაოდ სწრაფად იზრდება. ამის მიზეზია ორსულობის პერიოდში გამოყოფილი ჰორმონები და, რაც მთავარია, სისხლში ესტროგენის ძალიან მაღალი დონე. ბავშვის დაბადების შემდეგ ესტროგენის გამომუშავება მკვეთრად მცირდება და სისხლში მის ნორმალურ დონემდე დაქვეითებასთან ერთად თმის ზრდაც მნიშვნელოვნად ნელდება. ამ დროს თმის ფოლიკულები ერთდროულად გადადის ცვენის ფაზაში და თმა 2-3 თვის განმავლობაში იწყებს ცვენას. ცვენის ეს ფაზა 6 თვის განმავლობაში სრულდება, რის შემდეგაც დაკარგული თმა თანდათან კვლავ იზრდება.'), daily_tip_ka = COALESCE(daily_tip_ka, 'დღის განმავლობაში დააკვირდით ბავშვის მოძრაობებს; თუ მათ მკვეთრ შემცირებას შეამჩნევთ, მიმართეთ თქვენს ექიმს. დღეს ცოტათი დაისვენეთ და თავი საყვარელი საქმიანობით გაიხარეთ.') WHERE id = '64fd7099-afb5-4134-9918-3acc90ed702e';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ტვინში მდებარე ეპიფიზი ამ კვირიდან ფუნქციონირებას იწყებს. ეპიფიზი ტვინის უკანა ნაწილში მდებარე, ოსპის მარცვლის ზომის ჯირკვალია, რომელიც ბავშვის ორგანიზმში მელატონინის გამოყოფას არეგულირებს და მის ბალანსს უზრუნველყოფს. ეს ორგანო ასევე ორგანიზმის ბიოლოგიური საათის რეგულირებაში მონაწილეობს. შესაბამისად, ის ჩართულია მრავალ ფუნქციაში, მათ შორის ძილის რეჟიმის, დაძინებისა და გაღვიძების მართვაში. ეპიფიზის მიერ გამოყოფილი ჰორმონი მელატონინი სქესობრივი მომწიფების დაწყებაში, სქესობრივ განვითარებასა და რეპროდუქციულ უნარზე ზემოქმედებაში მონაწილეობს. ის ორგანიზმის ბიოლოგიურ საათსა და რიტმს არეგულირებს, ხელს უწყობს უჯრედების განახლებას, იცავს თვალის ბადურას და ორგანიზმში სიმსივნის საწინააღმდეგო ფუნქციას ასრულებს. ბოლო წლებში ჩატარებული კვლევებით დადგინდა, რომ ეპიფიზი, როგორც წესი, ბნელ გარემოში აქტიურდება. სწორედ ამიტომ, ბნელ ადგილას გარკვეული ხნის გატარების შემდეგ სხეულში სიმძიმესა და ძილიანობას ვგრძნობთ. ეპიფიზი განსაკუთრებით ეფექტიანად ბნელ გარემოში მუშაობს. გარდა ამისა, ეს ჯირკვალი ზრდის პროცესშიც აქტიურად მონაწილეობს და განსაკუთრებით მოზარდობის პერიოდში მის მიერ გამოყოფილი ჰორმონები სასქესო ჯირკვლების ნაადრევ განვითარებას უშლის ხელს.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემს ტემპერატურას ვარეგულირებ! 🌡️ ადრე მთლიანად შენი სხეულის ტემპერატურაზე ვიყავი დამოკიდებული. ახლა კი ჩემი ტვინისა და ცხიმოვანი შრის წყალობით საკუთარი სხეულის ტემპერატურის რეგულირებას ვიწყებ. უკვე პატარა ღუმელივით ვარ. ვემზადები, რომ დაბადებისას არ შემცივდეს.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'დიდი გოგრა'), body_changes_ka = COALESCE(body_changes_ka, 'მრავალნაყოფიან ორსულობასთან დაკავშირებული ყველაზე დიდი პრობლემა ნაადრევი მშობიარობაა. ნაყოფების რაოდენობის ზრდასთან ერთად ორსულობის ხანგრძლივობა და თითოეული ბავშვის დაბადების წონა მცირდება. ტყუპების შემთხვევაში ორსულობის საშუალო ხანგრძლივობა დაახლოებით 37 კვირაა, სამეულის შემთხვევაში კი — 35 კვირა. საშვილოსნოში გატარებული ყოველი დამატებითი კვირა ხელს უწყობს ბავშვის ორგანოებისა და სისტემების მომწიფებას და მისი დაბადების წონის მატებას. მრავალნაყოფიანი ორსულობის დროს მიზანია ორსულობის შეძლებისდაგვარად გახანგრძლივება, რათა ნაადრევი მშობიარობა თავიდან იქნეს აცილებული. ამის საუკეთესო გზა წოლითი რეჟიმია. შესაძლოა, მთელი ორსულობის განმავლობაში ჩვეული აქტივობების გაგრძელება ვერ შეძლოთ. შეიძლება საჭირო გახდეს ექიმის მიერ რეკომენდებული წოლითი რეჟიმის დაცვა.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ღამით ძილის ხარისხის გასაუმჯობესებლად დაწექით მარცხენა გვერდზე და ფეხებს შორის ბალიში მოათავსეთ; ეს წელის არეში ზეწოლას შეამცირებს. მუცლის ქავილის შესამსუბუქებლად გამოიყენეთ ბუნებრივი შემადგენლობის დამატენიანებელი საშუალებები. ყურადღება მიაქციეთ კალციუმისა და რკინის მიღებას, რადგან თქვენი ბავშვის ძვლები ახლა გამაგრების ყველაზე სწრაფ ეტაპზეა. დღეს ზედმეტად ნუ გადაიღლებით.') WHERE id = '2a9f34ac-1247-4ead-b172-d62294531480';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ზრდასთან ერთად საშვილოსნოში მისი მოძრაობისთვის განკუთვნილი სივრცე თანდათან ვიწროვდება. ამიტომ ის ხელებსა და ფეხებს სხეულისკენ კრავს და ჩვენთვის ნაცნობ „ფეტალურ პოზას“ (ემბრიონის პოზას) იღებს. ეს ჭკვიანური პოზა არა მხოლოდ სივრცეს ზოგავს, არამედ სხეულის ტემპერატურის შენარჩუნებასაც უწყობს ხელს. ამ ეტაპზე თქვენი ბავშვის ტვინი მომწიფების გასაოცარ დონეს აღწევს. მისი ტვინის ცენტრები უკვე სწავლობს დაბადების შემდგომი ცხოვრებისთვის ყველაზე მნიშვნელოვანი ფუნქციების — სუნთქვისა და სხეულის ტემპერატურის — მართვას. სუნთქვის ცენტრი რიტმულ მოძრაობებს არეგულირებს და ფილტვებს სუნთქვისთვის ამზადებს, ჰიპოთალამუსი კი ბავშვის შინაგანი ტემპერატურის სტაბილურად შესანარჩუნებლად „თერმოსტატის“ ფუნქციას ასრულებს. ეს იმაზე მიუთითებს, თუ რამდენად სრულყოფილად არის მომზადებული ბავშვის ტვინი საშვილოსნოს გარეთ სიცოცხლისთვის.'), baby_message_ka = COALESCE(baby_message_ka, 'თავს ქვემოთ ვაბრუნებ? ⬇️ შესაძლოა, ნელ-ნელა მშობიარობის პოზისთვის მზადება დავიწყო. ჯერ ძალიან მოძრავი ვარ და ხშირად ვტრიალდები, მაგრამ რადგან თავი მიმძიმდება, მიზიდულობის ძალა ქვემოთ მქაჩავს. თუ ჯერ კიდევ არ ვარ თავით ქვემოთ, არ ინერვიულო, ჯერ კიდევ ბევრი დრო მაქვს!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'დიდი გოგრა'), body_changes_ka = COALESCE(body_changes_ka, 'შესაძლოა, საზარდულის არეში ზეწოლა ან ტკივილი იგრძნოთ. ბავშვის ზრდასთან და ქვემოთ გადაადგილებასთან ერთად მენჯის ძვლებსა და შარდის ბუშტზე ზეწოლა იმატებს. შესაძლოა, ტუალეტში ხშირად წასვლის საჭიროება კვლავ გაგიჩნდეთ. ასევე შეიძლება განვითარდეს „სიმფიზიტი“ (მენჯის ძვლების დაშორებით გამოწვეული ტკივილი).;;;
შესაძლოა, წამოხურება იგრძნოთ. თქვენი ნივთიერებათა ცვლა ბავშვის საჭიროებების გამო 20% უფრო სწრაფად მიმდინარეობს, რაც დამატებით სითბოს წარმოქმნის. შესაძლოა, მუდმივად გცხელოდეთ, მაშინაც კი, როცა გარშემო სხვებს სცივათ. ოფლიანობაც იმატებს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'გულძმარვის შესამცირებლად მიირთვით მცირე ულუფებით, მაგრამ ხშირად და ჭამის შემდეგ დაუყოვნებლივ ნუ დაწვებით. ძილისას მარცხენა გვერდზე წოლა ხელს შეუწყობს როგორც თქვენს მონელებას, ისე ბავშვის სისხლის მიმოქცევას. წელის ტკივილის შესამსუბუქებლად მიიღეთ თბილი შხაპი ან შეასრულეთ მსუბუქი გაჭიმვის ვარჯიშები. დღეს ცოტა დრო დაუთმეთ საკუთარ თავს და დაფიქრდით იმ ოთახის ან კუთხის დეტალებზე, რომელსაც თქვენი ბავშვისთვის ამზადებთ.') WHERE id = '46d5df45-3974-471b-a1a7-d53afb295423';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის კანის ყოველ კვადრატულ სანტიმეტრზე დაახლოებით 110 საოფლე ჯირკვალი, 15 ცხიმოვანი ჯირკვალი და ტემპერატურისადმი მგრძნობიარე 3000-მდე უჯრედია. კანქვეშ წარმოქმნილი ამ საოფლე ჯირკვლების მიერ განხორციელებული ოფლიანობა სრულიად უნებლიე პროცესია და ნივთიერებათა ცვლის ბუნებრივ ფუნქციას წარმოადგენს. მისი დანიშნულებაა სხეულის ტემპერატურის სტაბილურად შენარჩუნება და გამომყოფი სისტემის მუშაობის ხელშეწყობა. თქვენი ბავშვის სხეულში წარმოქმნილი ამ ჯირკვლების დაახლოებით ნახევარი ისეთი საოფლე ჯირკვლებია, რომლებიც უსუნო და გამჭვირვალე სითხეს გამოყოფენ. გამჭვირვალე ოფლის გამომყოფი ჯირკვლების უმეტესობა ტერფებზე, ხელებსა და სახის არეშია განლაგებული. სქელი კონსისტენციისა და სუნის მქონე ოფლის გამომყოფი ჯირკვლები კი გარკვეულ ადგილებში, მაგალითად, იღლიებსა და გენიტალიების მიდამოში გვხვდება. მიუხედავად იმისა, რომ იღლიის მიდამოში გამჭვირვალე და სქელი ოფლის გამომყოფი ჯირკვლების რაოდენობა თანაბარია, სხეულის სხვა ნაწილებში გამჭვირვალე ოფლის გამომყოფი ჯირკვლები ათჯერ მეტია. ოფლიანობის მთავარი ფუნქცია სხეულის ტემპერატურის რეგულირებაა. გამჭვირვალე ოფლის გამომყოფი ჯირკვლებიდან გამოყოფილი სითხე ორთქლდება და სხეულის გაგრილებას უწყობს ხელს. სხეულის ტემპერატურას თავის ტვინის ჰიპოთალამუსში მდებარე თერმორეგულაციის ცენტრი აკონტროლებს. ეს პროცესი გამჭვირვალე ოფლის გამომყოფი ჯირკვლებიდან ოფლის გამოყოფისა და კანში სისხლის მიმოქცევის რეგულირების გზით ხორციელდება.'), baby_message_ka = COALESCE(baby_message_ka, 'მე სიზმრებს ვხედავ! 😴 დედიკო, ჩემი ტვინი იმდენად განვითარდა, რომ უკვე "REM ძილის" (თვალების სწრაფი მოძრაობის) ფაზაში გადავდივარ. ანუ მე უკვე ნამდვილად ვხედავ სიზმრებს! ნეტავ, რას ვხედავ სიზმარში? შენს ხმას თუ იმ გემრიელ ტორტს? დღის უმეტეს ნაწილს ძილში ვატარებ, მაგრამ როცა მღვიძავს, ძალიან აქტიური ვარ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'დიდი გოგრა'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის ამ პერიოდში შეიძლება წელისა და ზურგის ძლიერი ტკივილი გქონდეთ. ამის მიზეზია თქვენი სხეულის სიმძიმის ცენტრის ცვლილება, რაც ბავშვის შემცველი საშვილოსნოს ზემოთ გადაადგილებით არის გამოწვეული. ამის საუკეთესო გამოსავალია ვარჯიში, ორსულთა პილატესი და ორსულთა იოგა. ეს მეთოდები არა მხოლოდ ორსულობასთან დაკავშირებულ ტკივილსა და კრუნჩხვებს ამსუბუქებს, არამედ სხეულის არასწორ პოზასაც ასწორებს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'მოერიდეთ მძიმე საოჯახო საქმეებს. "ბუდის მოწყობის" ენერგია მსუბუქ საქმეებს მოახმარეთ (ტანსაცმლის გარეცხვას, ოთახის მორთვას). ფარდების დაკიდება ან ავეჯის გადაადგილება კატეგორიულად აკრძალულია!') WHERE id = '2b574c8a-d0de-45f5-bd25-7b7b01e3d2fe';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ლანუგოს გარდა, თქვენი ბავშვის მუდმივი თმა თმის ფოლიკულებში უკვე იწყებს ფორმირებას. ამ მუდმივი თმის წყალობით ბავშვის სხეულს წყლისა და სითბოს ბალანსის შენარჩუნება შეუძლია. სხეულის გარკვეულ ნაწილებში არსებული ეს თმა თბოიზოლაციაზეც არის პასუხისმგებელი. თმის ფოლიკულებში მდებარე პატარა კუნთები სიცივეში იკუმშება, თმას ყალყზე აყენებს და ამ მიდამოში ენერგიას, შესაბამისად კი სითბოს წარმოქმნის. დაბადებისას თქვენი ბავშვის სხეულზე ჯერ კიდევ შეიძლება დარჩენილი იყოს ლანუგოს ნაწილი, მთელი სხეული კი თვალით თითქმის შეუმჩნეველი, ძალიან თხელი მუდმივი თმით იქნება დაფარული. ბავშვის ზრდასთან ერთად ეს თმაც სქელდება. ხელისგულების, ტერფებისა და ტუჩების გარდა, ადამიანის მთელი კანი თმით არის დაფარული. თუმცა უმეტეს ადგილას ეს თმა იმდენად თხელი და ღია ფერისაა, რომ არ ჩანს. თმის შავი, ყავისფერი, ქერა ან წითური შეფერილობა დამოკიდებულია პიგმენტებად წოდებული საღებავი ნივთიერებების არსებობაზე, რომლებიც თმის გარე შრის ქვეშ მდებარეობს. თუ ამ სხვადასხვა ფერის პიგმენტებიდან არცერთი არ არის, მათ ადგილს მრავალი ჰაერის ღრუ იკავებს, რომლებიც მთელ სინათლეს ირეკლავს, ამიტომ თმა თეთრად გამოიყურება.'), baby_message_ka = COALESCE(baby_message_ka, 'მე გხედავ (თითქმის)! 💡 თვალები ღია მაქვს და თუ მუცელზე კაშკაშა შუქს მიანათებ, თავს მისკენ ვაბრუნებ. სინათლის წყაროსთვის თვალის გაყოლა შემიძლია. მიუხედავად იმისა, რომ ჩემი სამყარო ბნელია, ზოგჯერ მუცლის კედელში შემოღწეულ მკრთალ სინათლის სხივებს ვხედავ. ჩემთვის ეს ნამდვილი სასწაულია!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'დიდი გოგრა'), body_changes_ka = COALESCE(body_changes_ka, 'მშობიარობამდე ცოტა დრო დარჩა. ამ ეტაპის შემდეგ, განსაკუთრებით მუცლის მნიშვნელოვნად გაზრდის გამო, შეიძლება გადაადგილებაც კი გაგიჭირდეთ. თუ ამ სირთულის გამო უმოძრაოდ ყოფნას აირჩევთ, თქვენი სხეული დასუსტდება და მშობიარობა გართულდება. ამიტომ ისე, რომ ზედმეტად არ დაიღალოთ, ხანმოკლე სეირნობა და ვარჯიში უნდა განაგრძოთ. ვარჯიში ფიზიკურად გაგაძლიერებთ და სხეულის მოქნილობასაც გაზრდის. ხელებისა და ფეხების კუნთები გაძლიერდება, კუნთები და შემაერთებელი ქსოვილის იოგები კი გაიჭიმება. ბარძაყებისა და მენჯის მიდამოს მოქნილობა კომფორტული მშობიარობისთვის მოგამზადებთ. კეგელის ვარჯიშებით მენჯის ფსკერის კუნთების გაძლიერება ორსულობის ბოლო თვეებისთვის, მშობიარობისა და მშობიარობის შემდგომი აღდგენის პერიოდისთვის მომზადებაში დაგეხმარებათ.;;;
კვლევების თანახმად, ქალები, რომლებიც მთელი ორსულობის განმავლობაში ვარჯიშობენ, მშობიარობამდე დაახლოებით 7 კილოგრამით ნაკლებ წონას იმატებენ. ვარჯიში განსაკუთრებით ორსულობის ბოლო პერიოდში გაძლიერებული ფეხების შეშუპებისა და შეშუპებითი სითხის დაგროვების თავიდან აცილებაში დაგეხმარებათ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ვარიკოზული წინდების ტარება სისხლის მიმოქცევას აუმჯობესებს და ფეხების ტკივილს ამცირებს. ყველაზე ეფექტურია მათი დილით, საწოლიდან ადგომამდე ჩაცმა.') WHERE id = '98b2e2a6-b569-4828-8904-245e5d1bc37e';